package com.lightbend.lagom.javadsl.api.deser;

import akka.util.ByteString;
import com.lightbend.lagom.javadsl.api.transport.MessageProtocol;
import com.lightbend.lagom.javadsl.api.transport.NotAcceptable;
import com.lightbend.lagom.javadsl.api.transport.UnsupportedMediaType;
import org.pcollections.PSequence;
import org.pcollections.TreePVector;

import java.util.List;
import java.util.Optional;

/**
 * Serializer for messages.
 *
 * A message serializer is effectively a factory for negotiating serializers/deserializers.  They are created by passing
 * the relevant protocol information to then decide on a serializer/deserializer to use.
 *
 * The returned serializers/deserializers may be invoked once for strict messages, or many times for streamed messages.
 *
 * This interface doesn't actually specify the wireformat that the serializer must serialize to, there are two sub
 * interfaces that do, they being {@link StrictMessageSerializer}, which serializes messages that are primarily in
 * memory, to and from {@link ByteString}, and {@link StreamedMessageSerializer}, which serializes streams of messages.
 * Note that all message serializers used by the framework must implement one of these two sub interfaces, the
 * framework does not know how to handle other serializer types.
 *
 * @param <MessageEntity> The message entity being serialized/deserialized.
 */
public interface MessageSerializer<MessageEntity, WireFormat> {

    /**
     * The message headers that will be accepted for response serialization.
     */
    default PSequence<MessageProtocol> acceptResponseProtocols() {
        return TreePVector.empty();
    }

    /**
     * Whether this serializer serializes values that are used or not.
     *
     * If false, it means this serializer is for an empty request/response, eg, they use the
     * {@link akka.NotUsed} type.
     *
     * @return Whether the values this serializer serializes are used.
     */
    default boolean isUsed() {
        return true;
    }

    /**
     * Whether this serializer is a streamed serializer or not.
     *
     * @return Whether this is a streamed serializer.
     */
    default boolean isStreamed() { return false; }

    /**
     * Get a serializer for a client request.
     *
     * Since a client is the initiator of the request, it simply returns the default serializer for the entity.
     *
     * @return A serializer for request messages.
     */
    NegotiatedSerializer<MessageEntity, WireFormat> serializerForRequest();

    /**
     * Get a deserializer for an entity described by the given request or response protocol.
     *
     * @param protocol The protocol of the message request or response associated with teh entity.
     * @return A deserializer for request/response messages.
     * @throws UnsupportedMediaType If the deserializer can't deserialize that protocol.
     */
    NegotiatedDeserializer<MessageEntity, WireFormat> deserializer(MessageProtocol protocol) throws UnsupportedMediaType;

    /**
     * Negotiate a serializer for the response, given the accepted message headers.
     *
     * @param acceptedMessageProtocols The accepted message headers is a list of message headers that will be accepted by
     *                               the client. Any empty values in a message protocol, including the list itself,
     *                               indicate that any format is acceptable.
     * @throws NotAcceptable If the serializer can't meet the requirements of any of the accept headers.
     */
    NegotiatedSerializer<MessageEntity, WireFormat> serializerForResponse(List<MessageProtocol> acceptedMessageProtocols) throws NotAcceptable;

    /**
     * A negotiated serializer.
     *
     * @param <MessageEntity> The type of entity that this serializer serializes.
     * @param <WireFormat> The wire format that this serializer serializes to.
     */
    interface NegotiatedSerializer<MessageEntity, WireFormat> {

        /**
         * Get the protocol associated with this entity.
         */
        default MessageProtocol protocol() {
            return new MessageProtocol(Optional.empty(), Optional.empty(), Optional.empty());
        }

        /**
         * Serialize the given message entity.
         *
         * @param messageEntity The entity to serialize.
         * @return The serialized entity.
         */
        WireFormat serialize(MessageEntity messageEntity) throws SerializationException;
    }

    /**
     * A negotiated deserializer.
     *
     * @param <MessageEntity> The type of entity that this serializer serializes.
     * @param <WireFormat> The wire format that this serializer serializes to.
     */
    interface NegotiatedDeserializer<MessageEntity, WireFormat> {

        /**
         * Deserialize the given wire format.
         *
         * @param wire The raw wire data.
         * @return The deserialized entity.
         */
        MessageEntity deserialize(WireFormat wire) throws DeserializationException;
    }
}

package org.minimalj.repository.query;

public enum FieldOperator {
	less("<"), greaterOrEqual(">="), lessOrEqual("<="), greater(">"), equal("="), notEqual("<>");

	private final String operatorAsString;

	private FieldOperator(String operatorAsString) {
		this.operatorAsString = operatorAsString;
	}

	public String getOperatorAsString() {
		return operatorAsString;
	}

	public boolean includesEqual() {
		return this == equal || this == lessOrEqual || this == greaterOrEqual;
	}

	public FieldOperator negate() {
		return FieldOperator.values()[this.ordinal() ^ 1];
	}
}

package net.mdh.enj.workout;

import org.junit.Test;
import org.junit.Before;
import org.junit.Assert;
import net.mdh.enj.exercise.Exercise;
import net.mdh.enj.resources.TestData;
import net.mdh.enj.resources.DbTestUtils;
import net.mdh.enj.resources.RollbackingDBUnitTest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class WorkoutRepositoryTest extends RollbackingDBUnitTest {

    private DbTestUtils utils;
    private WorkoutRepository workoutRepository;
    private static Exercise testExercise;

    public WorkoutRepositoryTest() {
        super();
        this.utils = new DbTestUtils(rollbackingDSFactory);
    }

    @Before
    public void beforeEach() {
        this.workoutRepository = new WorkoutRepository(rollbackingDSFactory);
        if (testExercise == null) {
            testExercise = new Exercise();
            testExercise.setName("foo");
            this.utils.insertExercise(testExercise);
        }
    }

    /**
     * Testaa, että selectAll hakee treenit tietokannasta relaatioineen (mappaa
     * treeniin myös siihen kuuluvat liikkeet (jos niitä on), ja liikkeisiin niihin
     * kuuluvat sarjat (jos niitä on)).
     */
    @Test
    public void selectAllSisältääLiikkeetJaSetit() {
        Workout w1 = this.insertWorkoutWithExerciseAndSet(this.newTimestamp() + 200);
        Workout w2 = this.insertWorkoutWithExerciseButNoSets(this.newTimestamp() + 300);
        Workout w3 = this.insertWorkoutWithoutExercisesOrSets(this.newTimestamp() + 400);
        //
        SearchFilters searchFilters = new SearchFilters();
        searchFilters.setUserId(TestData.TEST_USER_ID);
        searchFilters.setStartFrom(w1.getStart() - 1);
        List<Workout> results = this.workoutRepository.selectAll(searchFilters);
        Assert.assertEquals(3, results.size());
        Workout actualW1 = results.get(2);
        Workout actualW2 = results.get(1);
        Workout actualW3 = results.get(0);
        //
        Assert.assertEquals(w3.toString(), actualW3.toString());
        Assert.assertEquals(0, actualW3.getExercises().size());
        //
        Assert.assertEquals(w2.toString(), actualW2.toString());
        Assert.assertEquals(1, actualW2.getExercises().size());
        Assert.assertEquals(w2.getExercises().get(0).toString(),
            actualW2.getExercises().get(0).toString()
        );
        Assert.assertEquals(0, actualW2.getExercises().get(0).getSets().size());
        //
        Assert.assertEquals(w1.toString(), actualW1.toString());
        Assert.assertEquals(1, actualW1.getExercises().size());
        Assert.assertEquals(w1.getExercises().get(0).toString(),
            actualW1.getExercises().get(0).toString()
        );
        Assert.assertEquals(1, actualW1.getExercises().get(0).getSets().size());
        Assert.assertEquals(w1.getExercises().get(0).getSets().get(0).toString(),
            actualW1.getExercises().get(0).getSets().get(0).toString()
        );
    }

    private Workout insertWorkoutWithExerciseAndSet(long timeStamp) {
        // Treeni
        Workout workout = this.insertWorkout(timeStamp);
        // Treenille 1 liike
        Workout.Exercise we = this.insertWorkoutExercise(workout.getId(), 0);
        this.addExercisesToWorkout(workout, we);
        // Liikkeeelle yksi sarja
        Workout.Exercise.Set wes = this.insertWorkoutExercseSet(we.getId());
        this.addSetsToWorkoutExercise(we, wes);
        return workout;
    }

    private Workout insertWorkoutWithExerciseButNoSets(long timestamp) {
        // Treeni
        Workout workout = this.insertWorkout(timestamp);
        // Treenille 1 liike
        Workout.Exercise we = this.insertWorkoutExercise(workout.getId(), 1);
        this.addExercisesToWorkout(workout, we);
        return workout;
    }

    private Workout insertWorkoutWithoutExercisesOrSets(long timestamp) {
        return this.insertWorkout(timestamp);
    }

    private Workout insertWorkout(long timestamp) {
        Workout workout = new Workout();
        workout.setUserId(TestData.TEST_USER_ID);
        workout.setStart(timestamp);
        workout.setExercises(new ArrayList<>());
        this.utils.insertWorkout(workout);
        return workout;
    }

    private Workout.Exercise insertWorkoutExercise(String workoutId, int ordinal) {
        Workout.Exercise we = new Workout.Exercise();
        we.setOrdinal(ordinal);
        we.setWorkoutId(workoutId);
        we.setExerciseId(WorkoutRepositoryTest.testExercise.getId());
        we.setExerciseName(WorkoutRepositoryTest.testExercise.getName());
        we.setSets(new ArrayList<>());
        this.utils.insertWorkoutExercise(we);
        return we;
    }

    private void addExercisesToWorkout(Workout workout, Workout.Exercise... esx) {
        List<Workout.Exercise> wexs = new ArrayList<>();
        Collections.addAll(wexs, esx);
        workout.setExercises(wexs);
    }

    private Workout.Exercise.Set insertWorkoutExercseSet(String workoutExerciseId) {
        Workout.Exercise.Set wes = new Workout.Exercise.Set();
        wes.setWeight(100);
        wes.setReps(6);
        wes.setOrdinal(2);
        wes.setWorkoutExerciseId(workoutExerciseId);
        this.utils.insertWorkoutExerciseSet(wes);
        return  wes;
    }

    private void addSetsToWorkoutExercise(Workout.Exercise we, Workout.Exercise.Set... wes) {
        List<Workout.Exercise.Set> weSets = new ArrayList<>();
        Collections.addAll(weSets, wes);
        we.setSets(weSets);
    }

    private long newTimestamp() {
        return System.currentTimeMillis() / 1000L;
    }
}

