package de.infsec.tpl.modules;


import com.ibm.wala.classLoader.CallSiteReference;
import com.ibm.wala.classLoader.CodeScanner;
import com.ibm.wala.classLoader.IClass;
import com.ibm.wala.classLoader.IMethod;
import com.ibm.wala.ipa.cha.IClassHierarchy;
import com.ibm.wala.shrikeCT.InvalidClassFileException;
import de.infsec.tpl.utils.AndroidClassType;
import de.infsec.tpl.utils.MapUtils;
import de.infsec.tpl.utils.Utils;
import de.infsec.tpl.utils.WalaUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.util.*;


public class APIScanner {
    private static final Logger logger = LoggerFactory.getLogger(de.infsec.tpl.modules.APIScanner.class);

	public static Map<String, String> init(File apiFile) throws FileNotFoundException {
		// load api file
		return APIScanner.loadResource(apiFile);
	}


	/**
	 * Loads API definitions defined in the following format:
	 *   <api-signature>  ::  [comma-separated optional list of android permissions]
	 * Lines starting with '#' are considered comments.
	 * @param file  input {@link File}
	 * @return Mapping of <api-signatures> to list of required permissions
	 */
	private static Map<String, String> loadResource(final File file) throws FileNotFoundException {
		if (!file.exists() || !file.isFile())
			throw new FileNotFoundException("Could not load file: " + file.getName());

		// API -> list of required permissions
		Map<String, String> result = new HashMap<String, String>();

		try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
			String line;
			while ((line = reader.readLine()) != null) {
				if (line.isEmpty() || line.startsWith("#")) continue;

				String[] token = line.split("  ::  ");

				if (token.length > 2) {
					logger.debug("Skip invalid entry: " + line + "  (expected format: <api-signature>  ::  perm1, perm2, ..)");
					continue;
				} else if (token.length == 2) {
					result.put(token[0], token.length == 2? token[1] : "");
                }
			}
		} catch (Exception e) {
			logger.error(Utils.stacktrace2Str(e));
		}

//		for (String k: result.keySet()) {
//			logger.debug("Parse: " + k + "  -> " + result.get(k));
//		}

		return result;
	}


	/**
	 * Scan bytecode for APIs in terms of method signatures. Very fast as it does not require any graph structure
	 * @param cha
	 * @return  mapping of found APIs and their code location in terms of enclosing method signature
	 */
	public static Map<String, List<String>> scanBytecodeForApis(IClassHierarchy cha, Map<String, String> apiToPermissions) {
	    // api signature -> list of bytecode methods
        Map<String, List<String>> results = new HashMap<String, List<String>>();

		for (IClass clazz: cha) {
			if (WalaUtils.isAppClass(clazz)) {
//				logger.debug(Utils.INDENT + "- class: " + WalaUtils.simpleName(clazz));

				try {
					for (IMethod m: clazz.getDeclaredMethods()) {
						for (CallSiteReference csf: CodeScanner.getCallSites(m)) {
							String signature = prettyPrint(csf.getDeclaredTarget().getSignature());

							if (apiToPermissions.keySet().contains(signature)) {
								AndroidClassType type = WalaUtils.classifyClazz(clazz);
								String permissions = apiToPermissions.get(signature);
								MapUtils.addValue(results, signature, m.getSignature());
								logger.debug("  - Class (" + type.toString() + "): " + WalaUtils.simpleName(clazz) + "  api: " + signature +  (permissions.isEmpty()? "" : "  (" + permissions + ")"));
							}
						}
					}
				} catch (InvalidClassFileException e) {
					logger.error(Utils.stacktrace2Str(e));
				}
			}
		}

		logger.info("= Scan for sinks =");
		logger.info(Utils.INDENT + ">> Found " + results.size() + " sinks!");
		return results;
	}


	public static String prettyPrint(String methodSignature) {
		List<String> args = Utils.parseMethodArguments(methodSignature, true);

		return methodSignature.substring(0, methodSignature.indexOf('(') + 1) + Utils.join(args, ",") + ")"; //TODO + Utils.getReturnType(methodSignature, false);
	}
}

package com.tyagiabhinav.dialogflowchatlibrary.templates;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.os.Handler;
import android.os.Looper;
import android.text.Html;
import android.text.method.LinkMovementMethod;
import android.util.Log;
import android.widget.FrameLayout;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import com.google.cloud.dialogflow.v2.DetectIntentResponse;
import com.google.protobuf.Value;
import com.tyagiabhinav.dialogflowchatlibrary.R;
import com.tyagiabhinav.dialogflowchatlibrary.networkutil.TaskRunner;
import com.tyagiabhinav.dialogflowchatlibrary.templateutil.OnClickCallback;

import java.io.InputStream;
import java.util.List;
import java.util.Map;

public class CardMessageTemplate extends MessageLayoutTemplate {

    private static final String TAG = CardMessageTemplate.class.getSimpleName();

    public CardMessageTemplate(Context context, OnClickCallback callback, int type) {
        super(context, callback, type);
        setOnlyTextResponse(false);
    }

    @Override
    FrameLayout populateRichMessageContainer() {
        FrameLayout richMessageContainer = getRichMessageContainer();
        DetectIntentResponse response = getResponse();
        List<com.google.cloud.dialogflow.v2.Context> contextList = response.getQueryResult().getOutputContextsList();
        LinearLayout cardContainer = getVerticalContainer();

        final LinearLayout cardLayout = getCardLayout(null);
        LinearLayout btnLayout = getVerticalContainer();
        btnLayout.setFocusableInTouchMode(true);
        for (com.google.cloud.dialogflow.v2.Context context : contextList) {
            Map<String, Value> contextParam = context.getParameters().getFieldsMap();
            Map<String, Value> cardItems = (contextParam.get("cardItems") != null) ? contextParam.get("cardItems").getStructValue().getFieldsMap() : null;
            List<Value> buttonList = (contextParam.get("buttonItems") != null) ? contextParam.get("buttonItems").getListValue().getValuesList() : null;
            String align = context.getParameters().getFieldsMap().get("align").getStringValue();
            String sizeValue = context.getParameters().getFieldsMap().get("size").getStringValue();
            String eventName = context.getParameters().getFieldsMap().get("eventToCall").getStringValue();

            if (cardItems != null) {
                final String imgUrl = (cardItems.get("imgUrl") != null) ? cardItems.get("imgUrl").getStringValue() : null;
                String title = (cardItems.get("title") != null) ? cardItems.get("title").getStringValue() : null;
                String description = (cardItems.get("description") != null) ? cardItems.get("description").getStringValue() : null;
                TextView titleView = cardLayout.findViewById(R.id.title);
                TextView descriptionView = cardLayout.findViewById(R.id.description);
                titleView.setMovementMethod(LinkMovementMethod.getInstance());
                if (title != null) {
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N) {
                        titleView.setText(Html.fromHtml(title, Html.FROM_HTML_MODE_LEGACY));
                    } else {
                        titleView.setText(Html.fromHtml(title));
                    }
                } else {
                    titleView.setVisibility(GONE);
                }

                if (description != null) {
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N) {
                        descriptionView.setText(Html.fromHtml(description, Html.FROM_HTML_MODE_LEGACY));
                    } else {
                        descriptionView.setText(Html.fromHtml(description));
                    }
                } else {
                    descriptionView.setVisibility(GONE);
                }

                Runnable downloadImage = new Runnable() {
                    @Override
                    public void run() {
                        Bitmap bmp = null;
                        try {
                            InputStream in = new java.net.URL(imgUrl).openStream();
                            bmp = BitmapFactory.decodeStream(in);
                        } catch (Exception e) {
                            Log.e("Image download error", e.getMessage());
                            e.printStackTrace();
                        }
                        final Bitmap finalBmp = bmp;
                        new Handler(Looper.getMainLooper()).post(new Runnable() {
                            @Override
                            public void run() {
                                if (finalBmp != null) {
                                    ((ImageView) cardLayout.findViewById(R.id.img)).setImageBitmap(finalBmp);
                                } else {
                                    ((ImageView) cardLayout.findViewById(R.id.img)).setImageResource(R.drawable.error_image);
                                }
                            }
                        });
                    }
                };
                new TaskRunner().executeTask(downloadImage);
            }

            if (align.equalsIgnoreCase("horizontal") || align.equalsIgnoreCase("h")) {
                btnLayout = getHorizontalContainer();
            }

            if (buttonList != null) {
                for (Value item : buttonList) {
                    btnLayout.addView(getBtn("button", item.getStructValue().getFieldsMap(), sizeValue, eventName));
                }
            }
        }
        Log.d(TAG, "populateRichMessageContainer: btn layout count: " + btnLayout.getChildCount());

        cardContainer.addView(cardLayout);
        cardContainer.addView(btnLayout);
        richMessageContainer.addView(cardContainer);

        return richMessageContainer;
    }


}

package com.blinkfox.stalker.output;

import com.blinkfox.minitable.MiniTable;
import com.blinkfox.stalker.config.Options;
import com.blinkfox.stalker.kit.StrKit;
import com.blinkfox.stalker.result.MeasureResult;
import java.util.Arrays;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * 在控制台输出结果的实现类.
 *
 * <p>控制台输出的结果示例如下：</p>
 * +----------------------------------------------------------------------------------------------------------------+
 * |                     threads: 1000, concurrens: 100, warmups:5, runs: 5, printErrorLog: false                   |
 * +-----------+-------+---------+---------+---------+---------+---------+----------+---------+---------------------+
 * |   Costs   | Total | Success | Failure |   Sum   |   Avg   |   Min   |   Max    | StdDev  | 95% LowerConfidence |
 * +-----------+-------+---------+---------+---------+---------+---------+----------+---------+---------------------+
 * | 397.15 ms | 5000  |  4968   |   32    | 23.44 s | 4.72 ms | 2.01 ms | 13.26 ms | 1.81 ms |       4.67 ms       |
 * +-----------+-------+---------+---------+---------+---------+---------+----------+---------+---------------------+
 *
 * @author blinkfox on 2019-01-11.
 * @since v1.0.0
 */
@Slf4j
public class OutputConsole implements MeasureOutput {

    /**
     * 表头数据的数组.
     */
    private static final List<String> HEADERS = Arrays.asList("", "Costs", "Total", "Success", "Failure", "Throughput",
            "Sum", "Avg", "Min", "Max", "StdDev", "95% LowerConfidence", "95% UpperConfidence");

    /**
     * 将测量的相关参数和统计结果等信息输出出来.
     *
     * @param options 测量的选项参数
     * @param measureResults 多个测量统计结果的不定集合
     */
    @Override
    public Object output(Options options, MeasureResult... measureResults) {
        // 渲染并打印结果.
        String result = this.getRenderResult(options, measureResults);
        log.warn("\n{}", result);
        return result;
    }

    /**
     * 获取最终需要渲染的结果.
     *
     * @param options 测量运行的相关选项参数
     * @param measureResults 多个测量统计结果的不定集合
     * @return 结果字符串
     */
    private String getRenderResult(Options options, MeasureResult... measureResults) {
        if (options == null || measureResults == null) {
            throw new IllegalArgumentException("options or measureResult is null.");
        }

        // 根据options的值, 拼接title.
        String title;
        if (options.getDuration() != null) {
            title = StrKit.join("duration: ", options.getDuration().toString(),
                    ", concurrens: ", options.getConcurrens(), ", warmups:", options.getWarmups(),
                    ", runs: ", options.getRuns(), ", printErrorLog: ", options.isPrintErrorLog());
        } else {
            title = StrKit.join("threads: ", options.getThreads(),
                    ", concurrens: ", options.getConcurrens(), ", warmups:", options.getWarmups(),
                    ", runs: ", options.getRuns(), ", printErrorLog: ", options.isPrintErrorLog());
        }
        String name = options.getName();
        title = StrKit.isEmpty(name) ? title : StrKit.join("name: ", name, ", ", title);

        // 拼接各个测量结果的字符串表头和内容.
        MiniTable table = new MiniTable(title).addHeaders(HEADERS);
        for (int i = 0, len = measureResults.length; i < len; i++) {
            MeasureResult result = measureResults[i];
            table.addDatas(i + 1, result.getEasyReadCosts(),
                    result.getTotal(), result.getSuccess(), result.getFailure(), result.getEasyReadThroughput(),
                    result.getEasyReadSum(), result.getEasyReadAvg(), result.getEasyReadMin(), result.getEasyReadMax(),
                    result.getEasyReadStdDev(), result.getEasyReadLowerConfidence(),
                    result.getEasyReadUpperConfidence());
        }
        return table.render();
    }

}

