/**
 * ID resolver for ZFIN genes.
 *
 * @author Fengyuan Hu
 */
public class ZfinIdentifiersResolverFactory extends IdResolverFactory
{
    protected static final Logger LOG = Logger.getLogger(ZfinIdentifiersResolverFactory.class);

    // data file path set in ~/.intermine/MINE.properties
    // e.g. resolver.zfin.file=/micklem/data/zfin-identifiers/current/identifiersForIntermine.txt
    private final String propKey = "resolver.file.rootpath";
    private final String resolverFileSymbo = "zfin";
    private final String taxonId = "7955";

    private static final String GENE_PATTERN = "ZDB-GENE";

    /**
     * Construct without SO term of the feature type.
     */
    public ZfinIdentifiersResolverFactory() {
        this.clsCol = this.defaultClsCol;
    }

    /**
     * Construct with SO term of the feature type.
     * @param clsName the feature type to resolve
     */
    public ZfinIdentifiersResolverFactory(String clsName) {
        this.clsCol = new HashSet<String>(Arrays.asList(new String[] {clsName}));
    }

    /**
     * Build an IdResolver from Entrez Gene gene_info file
     */
    @Override
    protected void createIdResolver() {
        if (resolver != null
                && resolver.hasTaxonAndClassName(taxonId, this.clsCol
                        .iterator().next())) {
            return;
        }
        if (resolver == null) {
            if (clsCol.size() > 1) {
                resolver = new IdResolver();
            } else {
                resolver = new IdResolver(clsCol.iterator().next());
            }
        }

        try {
            boolean isCachedIdResolverRestored = restoreFromFile();
            if (!isCachedIdResolverRestored || (isCachedIdResolverRestored
                    && !resolver.hasTaxonAndClassName(taxonId, this.clsCol.iterator().next()))) {
                String resolverFileRoot =
                        PropertiesUtil.getProperties().getProperty(propKey);

                if (StringUtils.isBlank(resolverFileRoot)) {
                    String message = "Resolver data file root path is not specified";
                    LOG.warn(message);
                    return;
                }

                LOG.info("Creating id resolver from data file and caching it.");
                String resolverFileName = resolverFileRoot.trim() + "/" + resolverFileSymbo;
                File f = new File(resolverFileName);
                if (f.exists()) {
                    createFromFile(f);
                    resolver.writeToFile(new File(idResolverCachedFileName));
                } else {
                    LOG.warn("Resolver file does not exist: " + resolverFileName);
                }
            } else {
                LOG.info("Using previously cached id resolver file: " + idResolverCachedFileName);
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Populate the ID resolver from a tab delimited file
     *
     * @param f the file
     * @throws IOException if we can't read from the file
     */
    protected void createFromFile(File f) throws IOException {
        // data is in format:
        // ZDBID ID1,ID2,ID3
        Iterator<?> lineIter = FormattedTextParser.
                parseTabDelimitedReader(new BufferedReader(new FileReader(f)));
        while (lineIter.hasNext()) {
            String[] line = (String[]) lineIter.next();

            if (line.length < 2 || line[0].startsWith("#") || !line[0].startsWith(GENE_PATTERN)) {
                continue;
            }

            String zfinId = line[0];
            String[] synonyms = StringUtil.split(line[1].trim(), ",");

            resolver.addMainIds(taxonId, zfinId, Collections.singleton(zfinId));
            resolver.addSynonyms(taxonId, zfinId, new HashSet<String>(Arrays.asList(synonyms)));
        }
    }
}

package com.craftinginterpreters.lox;

import com.craftinginterpreters.lox.expressions.*;
import com.craftinginterpreters.lox.statements.ExprStmt;
import com.craftinginterpreters.lox.statements.PrintStmt;
import com.craftinginterpreters.lox.statements.Stmt;

import java.util.ArrayList;
import java.util.List;
import static com.craftinginterpreters.lox.TokenType.*;

public class Parser {

    private final List<Token> tokens;
    private int current = 0;

    Parser(List<Token> tokens) {
        this.tokens = tokens;
    }

    /**
     * Given a set of token types, checks if the current token matches
     * ony of them. If that's the case, advances the current token and
     * returns true, otherwise returns false **without** advancing.
     */
    private boolean match(TokenType... types) {
        for (var type : types) {
            if (check(type)) {
                advance();
                return true;
            }
        }

        return false;
    }

    /**
     * Checks if current token is of the passed type. It doesn't advance counter.
     * (unless token list is exhausted, as in that case it'll always return false)
     */
    private boolean check(TokenType type) {
        if (isAtEnd()) return false;

        return peek().type == type;
    }

    /**
     * Increases the token counter by one, and returns
     * what was until right now the current token.
     */
    private Token advance() {
        if (!isAtEnd()) current++;
        return previous();
    }

    private boolean isAtEnd() {
        return peek().type == EOF;
    }

    /**
     * Returns current token without advancing counter
     */
    private Token peek() {
        return tokens.get(current);
    }

    /**
     * Returns previous token
     */
    private Token previous() {
        return tokens.get(current - 1);
    }

    private Stmt statement() {
        if (match(PRINT)) return printStatement();

        return expressionStatement();
    }

    private PrintStmt printStatement() {
        var expr = expression();
        consume(SEMICOLON, "Expected ';' at the end of print statement");
        return new PrintStmt(expr);
    }

    private ExprStmt expressionStatement() {
        var expr = expression();
        consume(SEMICOLON, "Expected ';' at the end of expression statement");
        return new ExprStmt(expr);
    }

    private Expr expression() {
        return commaExpression();
    }

    private Expr commaExpression() {
        var expr = equality();

        while (match(COMMA)) {
            expr = new Binary(expr, previous(), equality());
        }

        return expr;
    }

    private Expr equality() {
        var expr = comparison();

        while (match(BANG_EQUAL, EQUAL_EQUAL)) {
            // Left associative, therefore nest on the left side of the binary
            expr = new Binary(expr, previous(), comparison());
        }

        return expr;
    }

    private Expr comparison() {
        var expr = addition();

        while (match(GREATER, GREATER_EQUAL, LESS, LESS_EQUAL)) {
            expr = new Binary(expr, previous(), addition());
        }

        return expr;
    }

    private Expr addition() {
        var expr = multiplication();

        while (match(PLUS, MINUS)) {
            expr = new Binary(expr, previous(), addition());
        }

        return expr;
    }

    private Expr multiplication() {
        var expr = unary();

        while (match(SLASH, STAR)) {
            expr = new Binary(expr, previous(), addition());
        }

        return expr;
    }

    private Expr unary() {
        if (match(BANG, MINUS)) {
            return new Unary(previous(), unary());
        }

        return primary();
    }

    private Token consume(TokenType type, String errorMsg) {
        if (check(type)) return advance();

        throw error(peek(), errorMsg);
    }

    private ParseError error(Token token, String errorMsg) {
        Lox.error(token, errorMsg);
        return new ParseError();
    }

    private static class ParseError extends RuntimeException {}

    /**
     * To be used on syntax errors to avoid cascading thousands of errors.
     * Discard tokens until we hit a new statement, and keep going from there.
     *
     * Better approach than panicking and have the users fix one error after the other.
     */
    private void synchronize() {
        advance();

        while (!isAtEnd()) {
            if (previous().type == SEMICOLON) return;

            switch (peek().type) {
                case CLASS:
                case FUN:
                case VAR:
                case FOR:
                case IF:
                case WHILE:
                case PRINT:
                case RETURN:
                    return;
            }

            advance();
        }
    }

    private Expr primary() {
        if (match(TRUE)) return new Literal(true);
        if (match(FALSE)) return new Literal(false);
        if (match(NIL)) return new Literal(null);

        if (match(NUMBER, STRING)) return new Literal(previous().literal);

        if (match(LEFT_PAREN)) {
            var expr = expression();
            consume(RIGHT_PAREN, "Expect ')' after expression");
            return new Grouping(expr);
        }

        throw error(peek(), "Expression expected.");
    }

    List<Stmt> parse() {
        var statements = new ArrayList<Stmt>();

        while (!isAtEnd()) statements.add(statement());

        return statements;
    }
}

