/**
 * An argument for a command for the {@link SkbShell}.
 *
 * @author     Sven van der Meer &lt;vdmeer.sven@mykolab.com&gt;
 * @version    v0.2.0 build 170404 (04-Apr-17) for Java 1.8
 * @since      v0.0.8
 */
public interface SkbShellArgument extends HasDescription {

	/**
	 * Returns the key of a shell argument.
	 * @return shell argument key
	 */
	String getKey();

	/**
	 * Returns the type of a shell argument.
	 * @return shell argument type
	 */
	SkbShellArgumentType getType();

	/**
	 * Returns additional text for an auto-generated help for the argument.
	 * @return additional help text, null if none set
	 */
	default String addedHelp(){
		return null;
	}

	/**
	 * Optional flag for the argument.
	 * @return true if the argument is optional, false otherwise (default)
	 */
	boolean isOptional();

	/**
	 * Returns an allowed set of values of same type as {@link #getType()} refers to
	 * @return value set, null if non specified (which means any value is allowed)
	 */
	Object[] valueSet();

}

package com.github.chen0040.jrl.ttt.bots;

import com.github.chen0040.jrl.ttt.Board;
import com.github.chen0040.jrl.ttt.Move;
import com.github.chen0040.jrl.ttt.Position;
import com.github.chen0040.rl.learning.qlearn.QLearner;
import com.github.chen0040.rl.utils.IndexValue;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class QBot extends Bot {
    private final QLearner agent;

    public QBot(int color, Board board, QLearner learner) {
        super(color, board);
        this.agent = learner;
    }

    @Override
    public void act() {
        int state = getState();

        Set<Integer> possibleActions = getPossibleActions();
        List<Integer> possibleActionList = new ArrayList<>(possibleActions);

        int action = -1;
        if(!possibleActions.isEmpty()) {
            IndexValue iv = agent.selectAction(state, possibleActions);
            action = iv.getIndex();
            double value = iv.getValue();

            if(value <= 0){
                action = possibleActionList.get(random.nextInt(possibleActionList.size()));
            }

            Position pos = Position.fromInteger(board, action);


            board.move(pos, color);
        }

        if(action != -1) {
            int newState = getState();
            moves.add(new Move(state, action, newState, 0));
        }
    }

    @Override
    public void updateStrategy() {

        int winner = board.getWinner();
        int strategyColor = getStrategyColor(winner);

        double reward = REWARD[strategyColor];

        for(int i=moves.size()-1; i >=0; --i){
            Move move = moves.get(i);
            if(i >= moves.size()-2) {
                move.reward = reward;
            }
            agent.update(move.oldState, move.action, move.newState, move.reward);
        }

    }
}

