    private final Board board;
    private Player player1;
    private Player player2;

    private final ArrayList draws = new ArrayList<Draw>();
    private int round = 0;

    private EPlayer playersTurn;


    public Game(){
        gameId = UUID.randomUUID();
        SymmetricBoardGenerator gen = new SymmetricBoardGenerator();
        board = gen.generate();
        playersTurn = diceStartPlayer();

    }


    public boolean join(Player player){
        if(player1==null) {
            player1 = player;
            return true;
        }
        if(player2==null){
            player2 = player;
            return true;
        }
        return false;
    }


    public void play(Position fromPos, Position toPos){
        if(board.getWinner().isPresent()){
            return;
        }
        Piece piece = board.pieceAt(fromPos);
        // is it this players turn?
        if(piece.getOwner().equals(playersTurn)){
            // is it possible move??
            if(piece.canMoveTo(toPos)){
                board.perform(fromPos,toPos);
            }
        }
        endTurn();
    }


    private void endTurn(){
        //Check Win/Lose
        if(board.getWinner().isPresent()){
            // board.getWinner() wins
        }

        if(playersTurn.equals(EPlayer.P1)){
            playersTurn=EPlayer.P2;
        } else {
            playersTurn=EPlayer.P1;
        }
        board.computePossibleMoves();
        round++;
    }


    public UUID getGameId() {
        return gameId;
    }

    public Player getPlayer1() {
        return player1;
    }

    public Player getPlayer2() {
        return player2;
    }

    public Board getBoard() {
        return board;
    }

    public int getRound() {
        return round;
    }

    public EPlayer getPlayersTurn() {
        return playersTurn;
    }

    public Optional<Player> getWinner(){

        Optional<EPlayer> winner = board.getWinner();
        if(winner.isEmpty()){
            return Optional.empty();
        }
        if(winner.get()==EPlayer.P1){
            return Optional.of(player1);
        } else {
            return Optional.of(player2);
        }

    }

    private EPlayer diceStartPlayer(){
        if(Math.random()>=0.5){
            return EPlayer.P1;
        } else {
            return EPlayer.P2;
        }
    }
}

package me.synterxis.genesis;

import me.synterxis.genesis.impl.GenesisCrackerImpl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;

import java.net.Proxy;

public class GenesisCrackerBuilder {

    protected final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    protected Proxy proxy = Proxy.NO_PROXY;
    protected OkHttpClient.Builder builder = new OkHttpClient.Builder().proxy(proxy);
    protected OkHttpClient client = new OkHttpClient();

    public GenesisCrackerBuilder(Proxy proxy) {
        this.proxy = proxy;
        this.builder = new OkHttpClient.Builder().proxy(this.proxy);
        this.client = this.builder.build();
    }

    public GenesisCrackerBuilder() {
        this(Proxy.NO_PROXY);
    }

    public GenesisCrackerImpl build() {
        GenesisCrackerImpl genesisCracker = new GenesisCrackerImpl(this.builder, this.proxy);
        return genesisCracker;
    }
}

