package dev.galacticraft.impl.machine.storage.slot;

import dev.galacticraft.impl.machine.ModCount;
import net.fabricmc.fabric.api.transfer.v1.storage.StoragePreconditions;
import net.fabricmc.fabric.api.transfer.v1.storage.TransferVariant;
import net.fabricmc.fabric.api.transfer.v1.storage.base.ResourceAmount;
import net.fabricmc.fabric.api.transfer.v1.storage.base.SingleSlotStorage;
import net.fabricmc.fabric.api.transfer.v1.transaction.TransactionContext;
import net.fabricmc.fabric.api.transfer.v1.transaction.base.SnapshotParticipant;
import org.jetbrains.annotations.Contract;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.TestOnly;

public abstract class ResourceSlot<T, V extends TransferVariant<T>, S> extends SnapshotParticipant<ResourceAmount<V>>  implements SingleSlotStorage<V> {
    private final ModCount modCount = new ModCount();
    private final long capacity;
    private V variant = this.getBlankVariant();
    private long amount = 0;

    public ResourceSlot(long capacity) {
        this.capacity = capacity;
    }

    public int getModCount() {
        return this.modCount.getModCount();
    }

    public int getModCountUnsafe() {
        return this.modCount.getModCountUnsafe();
    }

    @TestOnly
    public void setStackUnsafe(@NotNull V variant, long amount, boolean markDirty) {
        StoragePreconditions.notNegative(amount);
        if (amount == 0) variant = this.getBlankVariant();
        else if (variant.isBlank()) amount = 0;
        this.variant = variant;
        this.amount = amount;
        if (markDirty) this.modCount.incrementUnsafe();
    }

    public void setStack(@NotNull V variant, long amount, @NotNull TransactionContext context) {
        StoragePreconditions.notNegative(amount);
        this.updateSnapshots(context);
        this.modCount.increment(context);
        if (amount == 0) variant = this.getBlankVariant();
        else if (variant.isBlank()) amount = 0;
        this.variant = variant;
        this.amount = amount;
    }

    public void setAmount(long amount, @NotNull TransactionContext context) {
        StoragePreconditions.notNegative(amount);
        if (this.variant.isBlank()) {
            if (amount != 0) {
                throw new IllegalArgumentException("Cannot set amount of blank variant");
            }
        }
        this.updateSnapshots(context);
        this.modCount.increment(context);
        if (amount == 0) {
            this.variant = this.getBlankVariant();
        }
        this.amount = amount;
    }

    public void extract(long amount, @NotNull TransactionContext context) {
        this.updateSnapshots(context);
        this.modCount.increment(context);
        this.amount -= amount;
        assert this.amount >= 0;
        if (this.amount == 0) {
            this.variant = this.getBlankVariant();
        }
    }

    protected abstract @NotNull V getBlankVariant();

    protected abstract long getVariantCapacity(@NotNull V variant);

    @Contract(pure = true)
    protected abstract @NotNull S getEmptyStack();

    @Contract(pure = true)
    protected abstract @NotNull S createStack(@NotNull V variant, long amount);

    public @NotNull S copyStack() {
        if (this.variant.isBlank() || this.amount == 0) return this.getEmptyStack();
        return this.createStack(this.variant, this.amount);
    }

    @Override
    public long insert(V variant, long maxAmount, @NotNull TransactionContext transaction) {
        StoragePreconditions.notBlankNotNegative(variant, maxAmount);

        if ((variant.equals(this.variant) || this.variant.isBlank())) {
            long insertedAmount = Math.min(maxAmount, Math.min(this.capacity, getCapacity(variant)) - this.amount);

            if (insertedAmount > 0) {
                updateSnapshots(transaction);

                if (this.variant.isBlank()) {
                    this.variant = variant;
                    this.amount = insertedAmount;
                } else {
                    this.amount += insertedAmount;
                }
            }

            return insertedAmount;
        }

        return 0;
    }

    @Override
    public long extract(V variant, long amount, @NotNull TransactionContext context) {
        StoragePreconditions.notBlankNotNegative(variant, amount);

        if (variant.equals(this.variant)) {
            long extractedAmount = Math.min(amount, this.amount);

            if (extractedAmount > 0) {
                updateSnapshots(context);
                this.amount -= extractedAmount;

                if (this.amount == 0) {
                    this.variant = getBlankVariant();
                }
            }

            return extractedAmount;
        }

        return 0;
    }

    @Override
    public boolean isResourceBlank() {
        return this.variant.isBlank();
    }

    @Override
    public @NotNull V getResource() {
        return this.variant;
    }

    @Override
    public long getAmount() {
        return this.amount;
    }

    @Override
    public long getCapacity() {
        return this.getCapacity(this.variant);
    }

    public long getCapacity(V variant) {
        return Math.min(this.getVariantCapacity(variant), this.capacity);
    }

    @Override
    protected ResourceAmount<V> createSnapshot() {
        return new ResourceAmount<>(this.variant, this.amount);
    }

    @Override
    protected void readSnapshot(@NotNull ResourceAmount<V> snapshot) {
        this.variant = snapshot.resource();
        this.amount = snapshot.amount();
    }
}

package com.edge.xshtsk.listner.taskListener.before;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpSession;

import org.activiti.engine.delegate.DelegateTask;
import org.activiti.engine.delegate.TaskListener;
import org.apache.ibatis.type.Alias;
import org.springframework.context.ApplicationContext;
import org.springframework.web.context.ContextLoader;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import com.edge.admin.processDefinition.entity.SYS_WorkFlow_Operation;
import com.edge.admin.processDefinition.service.inter.OpeantionService;
import com.edge.admin.user.entity.ERP_User;
import com.edge.admin.user.service.inter.ERP_UserService;
import com.edge.currency.processView.entity.Sys_WorkFlow_Lcjs;
import com.edge.currency.processView.service.inter.WorkFlowLcjsService;

/**
 * 领导审核操作之前,用于设置该节点的任务办理人
 * 
 * @author NingCG
 *
 */
@Alias("xshtsk_ldshBefore")
public class LdshBefore implements TaskListener {

	public void notify(DelegateTask delegateTask) {
		Date beginTime = new Date();
		// 获取Session
		HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.getRequestAttributes())
				.getRequest();
		HttpSession session = request.getSession();
		// 获取当前登录系统的用户
		ERP_User user = (ERP_User) session.getAttribute("user");
		List<String> userNames = new ArrayList<String>();
		ApplicationContext ac = ContextLoader.getCurrentWebApplicationContext();
		String processDefinitionId = delegateTask.getProcessDefinitionId();
		System.out.println(processDefinitionId);
		// 获取 OpeantionService
		OpeantionService opeantionService = (OpeantionService) ac.getBean("opeantionServiceImpl");
		// 获取ERP_UserService
		ERP_UserService erp_UserService = (ERP_UserService) ac.getBean("ERP_UserServiceImpl");
		WorkFlowLcjsService lcjsService = (WorkFlowLcjsService) ac.getBean("workFlowLcjsServiceImpl");
		// 获取当前流程下的所有操作集合
		List<SYS_WorkFlow_Operation> list = opeantionService.queryOperationByProId(processDefinitionId);
		List<ERP_User> userList = null;
		// 遍历该集合
		for (SYS_WorkFlow_Operation l : list) {
			// 若操作集合中的节点主键与当前任务节点的主键一致则设置该节点的办理人
			if (delegateTask.getTaskDefinitionKey().equals(l.getS_Id())) {
				// 根据岗位主键获得用户候选组集合
				userList = erp_UserService.queryUserByPost(l.getPost_Id());
				break;
			}
		}
		for (ERP_User u : userList) {
			// 设置下一节点拥有该角色的用户进行办理
			delegateTask.addCandidateUser(String.valueOf(u.getUserId()));
			userNames.add(u.getUserName());
		}
		try {
			this.saveLcjs(delegateTask.getName(), userNames.toString(), beginTime,
					delegateTask.getExecution().getBusinessKey(), lcjsService);
		} catch (Exception e) {
			e.printStackTrace();
		}

	}

	// 新增流程检视数据
	private void saveLcjs(String taskName, String userNames, Date beginTime, String objId,
			WorkFlowLcjsService lcjsService) throws Exception {
		SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:dd");
		// 设置流程检视数据
		Sys_WorkFlow_Lcjs lcjs = new Sys_WorkFlow_Lcjs();
		// 设置当前节点名称
		lcjs.setNodeName(taskName);
		// 设置当前节点办理人名称
		lcjs.setProcessingUsers(userNames);
		lcjs.setNodeInfo(null);
		lcjs.setBeginTime(sdf.format(beginTime));
		lcjs.setEndTime("未完成");
		lcjs.setObjDm(objId);
		lcjsService.saveLcjs(lcjs);
	}

}

package cn.edu.buaa.crypto.encryption.abe.kpabe.hw14.serparams;

import cn.edu.buaa.crypto.utils.PairingUtils;
import it.unisa.dia.gas.jpbc.Element;
import it.unisa.dia.gas.jpbc.Pairing;
import it.unisa.dia.gas.jpbc.PairingParameters;
import it.unisa.dia.gas.plaf.jpbc.pairing.PairingFactory;

import java.util.Arrays;
import java.util.Map;

/**
 * Created by Weiran Liu on 17/1/2.
 *
 * Hohenberger-Waters-14 CPA-secure OO-KP-ABE ciphertext parameter.
 */
public class KPABEHW14CiphertextSerParameter extends KPABEHW14HeaderSerParameter {
    private transient Element C;
    private final byte[] byteArrayC;

    public KPABEHW14CiphertextSerParameter(
            PairingParameters pairingParameters, Element C, Element C0,
            Map<String, Element> C1s, Map<String, Element> C2s, Map<String, Element> C3s) {
        super(pairingParameters, C0, C1s, C2s, C3s);
        this.C = C.getImmutable();
        this.byteArrayC = this.C.toBytes();
    }

    public Element getC() { return this.C.duplicate(); }

    @Override
    public boolean equals(Object anObject) {
        if (this == anObject) {
            return true;
        }
        if (anObject instanceof KPABEHW14CiphertextSerParameter) {
            KPABEHW14CiphertextSerParameter that = (KPABEHW14CiphertextSerParameter) anObject;
            return PairingUtils.isEqualElement(this.C, that.C)
                    && Arrays.equals(this.byteArrayC, that.byteArrayC)
                    && super.equals(anObject);
        }
        return false;
    }

    private void readObject(java.io.ObjectInputStream objectInputStream)
            throws java.io.IOException, ClassNotFoundException {
        objectInputStream.defaultReadObject();
        Pairing pairing = PairingFactory.getPairing(this.getParameters());
        this.C = pairing.getGT().newElementFromBytes(this.byteArrayC);
    }
}

