package com.hazelcast.cache.impl.operation;

import com.hazelcast.cache.impl.CacheDataSerializerHook;
import com.hazelcast.cache.impl.record.CacheRecord;
import com.hazelcast.internal.nio.IOUtil;
import com.hazelcast.nio.ObjectDataInput;
import com.hazelcast.nio.ObjectDataOutput;
import com.hazelcast.internal.serialization.Data;
import com.hazelcast.spi.impl.operationservice.BackupAwareOperation;
import com.hazelcast.spi.impl.operationservice.Operation;
import com.hazelcast.spi.impl.operationservice.MutatingOperation;

import javax.cache.expiry.ExpiryPolicy;
import java.io.IOException;
import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import static com.hazelcast.internal.util.MapUtil.createHashMap;

public class CachePutAllOperation extends CacheOperation
        implements BackupAwareOperation, MutableOperation, MutatingOperation {

    private List<Map.Entry<Data, Data>> entries;
    private ExpiryPolicy expiryPolicy;
    private int completionId;

    private transient Map<Data, CacheRecord> backupRecords;

    public CachePutAllOperation() {
    }

    public CachePutAllOperation(String cacheNameWithPrefix, List<Map.Entry<Data, Data>> entries, ExpiryPolicy expiryPolicy,
                                int completionId) {
        super(cacheNameWithPrefix);
        this.entries = entries;
        this.expiryPolicy = expiryPolicy;
        this.completionId = completionId;
    }

    @Override
    public int getCompletionId() {
        return completionId;
    }

    @Override
    public void setCompletionId(int completionId) {
        this.completionId = completionId;
    }

    @Override
    public void run() throws Exception {
        UUID callerUuid = getCallerUuid();
        backupRecords = createHashMap(entries.size());

        for (Map.Entry<Data, Data> entry : entries) {
            Data key = entry.getKey();
            Data value = entry.getValue();

            CacheRecord backupRecord = recordStore.put(key, value, expiryPolicy, callerUuid, completionId);

            // backupRecord may be null (eg expired on put)
            if (backupRecord != null) {
                backupRecords.put(key, backupRecord);
                publishWanUpdate(key, backupRecord);
            }
        }
    }

    @Override
    public boolean shouldBackup() {
        return !backupRecords.isEmpty();
    }

    @Override
    public Operation getBackupOperation() {
        return new CachePutAllBackupOperation(name, backupRecords);
    }

    @Override
    public int getClassId() {
        return CacheDataSerializerHook.PUT_ALL;
    }

    @Override
    protected void writeInternal(ObjectDataOutput out) throws IOException {
        super.writeInternal(out);
        out.writeObject(expiryPolicy);
        out.writeInt(completionId);
        out.writeInt(entries.size());
        for (Map.Entry<Data, Data> entry : entries) {
            IOUtil.writeData(out, entry.getKey());
            IOUtil.writeData(out, entry.getValue());
        }
    }

    @Override
    protected void readInternal(ObjectDataInput in) throws IOException {
        super.readInternal(in);
        expiryPolicy = in.readObject();
        completionId = in.readInt();
        int size = in.readInt();
        entries = new ArrayList<Map.Entry<Data, Data>>(size);
        for (int i = 0; i < size; i++) {
            Data key = IOUtil.readData(in);
            Data value = IOUtil.readData(in);
            entries.add(new AbstractMap.SimpleImmutableEntry<Data, Data>(key, value));
        }
    }

}

package ue06_plf03;

import java.util.Locale;

/**
 *
 * @author raphael
 */
abstract public class Component {
    private final String id;
    private final double value;
    private double voltage;
    private double current;

    public Component (String id, double value) {
        /*if(value < 0){
            throw new IllegalArgumentException("Invalid parameter value");
        }
        if(id != "L" || id != "C" || id != "R"){
            throw new IllegalArgumentException("Invalid parameter id");
        }*/
        this.id = id;
        this.value = value;
    }

    public String getId () {
        return id;
    }

    public double getValue () {
        return value;
    }

    public double getVoltage () {
        return voltage;
    }

    public double getCurrent () {
        return current;
    }

    public void setVoltage (double voltage) {
        this.voltage = voltage;
    }

    public void setCurrent (double current) {
        this.current = current;
    }

    public double power(){
        return current * voltage;
    }

    public String formattedValue(){
        return value + unit();
    }

    public String formattedValue(Locale locale){
        double mul;
        String preUnit;

        if (value < 1E-9) {
            mul = 1E-12; preUnit = "p"; // pico
        } else if (value < 1E-6) {
            mul = 1E-9; preUnit = "n"; // nano
        } else if (value < 1E-3) {
            mul = 1E-6; preUnit = "µ"; // micro
        } else if (value < 1) {
            mul = 1E-3; preUnit = "m"; // milli
        } else if (value < 1E3) {
            mul = 1; preUnit = "";
        } else if (value < 1E6) {
            mul = 1E3; preUnit = "k"; // kilo
        } else if (value < 1E9) {
            mul = 1E6; preUnit = "M"; // kilo            
        } else {
            mul = 1E9; preUnit = "G"; // giga
        }

        String rv = String.format(locale, "%.3f", value / mul);
        if (rv.endsWith(".00")) {
            rv = rv.substring(0, rv.length() - 3) + preUnit + unit();
        } else if (rv.endsWith("0")) {
            rv = rv.substring(0, rv.length() - 1)  + preUnit + unit();
        } else {
            rv = rv  + preUnit + unit();
        }
        return rv;
    }

    @Override
    public String toString () {
        final StringBuilder sb = new StringBuilder();
        sb.append(getClass().getSimpleName());
        sb.append(" {").append("\"id\":\"").append(id).append("\"");
        sb.append(",").append("\"value\":").append(value);
        sb.append(",").append("\"voltage\":").append(voltage);
        sb.append(",").append("\"current\":").append(current);
        sb.append("}");
        return sb.toString();
    }

    abstract public String unit();

    abstract public double energy();
}

