package com.netflix.spinnaker.orca.clouddriver.tasks.providers.gce;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.common.collect.ImmutableMap;
import com.netflix.spinnaker.orca.clouddriver.OortService;
import com.netflix.spinnaker.orca.clouddriver.tasks.image.ImageTagger;
import com.netflix.spinnaker.orca.clouddriver.utils.CloudProviderAware;
import com.netflix.spinnaker.orca.pipeline.model.Stage;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;

import static java.lang.String.format;

@Component
public class GoogleImageTagger extends ImageTagger implements CloudProviderAware {
  private static final Set<String> BUILT_IN_TAGS = new HashSet<>(Arrays.asList("appversion", "build_host"));

  @Autowired
  public GoogleImageTagger(OortService oortService, ObjectMapper objectMapper) {
    super(oortService, objectMapper);
  }

  @Override
  public ImageTagger.OperationContext getOperationContext(Stage stage) {
    StageData stageData = stage.mapTo(StageData.class);

    Collection<MatchedImage> matchedImages = findImages(stageData.imageNames, stageData.consideredStages, stage, MatchedImage.class);

    stageData.imageNames = matchedImages.stream()
      .map(matchedImage -> matchedImage.imageName)
      .collect(Collectors.toSet());

    // Built-in tags are not updatable
    Map<String, String> tags = stageData.tags.entrySet().stream()
      .filter(entry -> !BUILT_IN_TAGS.contains(entry.getKey()))
      .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

    List<Image> targetImages = new ArrayList<>();
    Map<String, Object> originalTags = new HashMap<>();
    List<Map<String, Map>> operations = new ArrayList<>();

    for (MatchedImage matchedImage : matchedImages) {
      Image targetImage = new Image(
        matchedImage.imageName,
        getCredentials(stage),
        null,
        tags
      );
      targetImages.add(targetImage);

      log.info(format("Tagging '%s' with '%s' (executionId: %s)", targetImage.imageName, targetImage.tags, stage.getExecution().getId()));

      // Update the tags on the image
      operations.add(
        ImmutableMap.<String, Map>builder()
          .put(OPERATION, ImmutableMap.builder()
            .put("imageName", targetImage.imageName)
            .put("tags", targetImage.tags)
            .put("credentials", targetImage.account)
            .build()
          ).build()
      );

      originalTags.put(matchedImage.imageName, matchedImage.tags);
    }

    Map<String, Object> extraOutput = objectMapper.convertValue(stageData, Map.class);
    extraOutput.put("targets", targetImages);
    extraOutput.put("originalTags", originalTags);

    return new ImageTagger.OperationContext(operations, extraOutput);
  }

  /**
   * Return true iff the tags on the current machine image match the desired.
   */
  @Override
  public boolean areImagesTagged(Collection<Image> targetImages, Collection<String> consideredStageRefIds, Stage stage) {
    Collection<MatchedImage> matchedImages = findImages(
      targetImages.stream().map(targetImage -> targetImage.imageName).collect(Collectors.toSet()),
      consideredStageRefIds,
      stage,
      MatchedImage.class
    );

    AtomicBoolean isUpserted = new AtomicBoolean(true);

    for (Image targetImage : targetImages) {
      MatchedImage matchedImage = matchedImages.stream()
        .filter(m -> m.imageName.equals(targetImage.imageName))
        .findFirst()
        .orElse(null);

      if (matchedImage == null) {
        isUpserted.set(false);
      } else {
        targetImage.tags.entrySet().forEach(entry -> {
          // assert tag equality
          isUpserted.set(isUpserted.get() && entry.getValue().equals(matchedImage.tags.get(entry.getKey())));
        });
      }
    }

    return isUpserted.get();
  }

  @Override
  public String getCloudProvider() {
    return "gce";
  }

  static class StageData {
    public Set<String> imageNames;
    public Map<String, String> tags = new HashMap<>();
    public Set<String> consideredStages = new HashSet<>();
  }

  private static class MatchedImage {
    public String account;
    public String imageName;
    public Map<String, String> tags = new HashMap<>();
  }
}

package moe.gensoukyo.mcgproject.common.feature.elevator;

import moe.gensoukyo.mcgproject.common.tileentity.AbstractTileEntity;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.math.BlockPos;

import javax.annotation.Nonnull;

public class TileElevator extends AbstractTileEntity {

    private boolean hasUp = false;
    private BlockPos upCtl = BlockPos.ORIGIN;

    private boolean hasDown = false;
    private BlockPos downCtl = BlockPos.ORIGIN;

    @Override
    public void fromNBT(NBTTagCompound tag) {
        hasUp = tag.hasKey("upCtl");
        if (hasUp) {
            NBTTagCompound pos = tag.getCompoundTag("upCtl");
            upCtl = new BlockPos(
                    pos.getInteger("x"),
                    pos.getInteger("y"),
                    pos.getInteger("z")
            );
        }
        hasDown = tag.hasKey("downCtl");
        if (hasDown) {
            NBTTagCompound pos = tag.getCompoundTag("downCtl");
            downCtl = new BlockPos(
                    pos.getInteger("x"),
                    pos.getInteger("y"),
                    pos.getInteger("z")
            );
        }
    }

    @Nonnull
    @Override
    public NBTTagCompound toNBT(NBTTagCompound tag) {
        if (hasUp) {
            NBTTagCompound pos = new NBTTagCompound();
            pos.setInteger("x", upCtl.getX());
            pos.setInteger("y", upCtl.getY());
            pos.setInteger("z", upCtl.getZ());
            tag.setTag("upCtl", pos);
        }
        if (hasDown) {
            NBTTagCompound pos = new NBTTagCompound();
            pos.setInteger("x", downCtl.getX());
            pos.setInteger("y", downCtl.getY());
            pos.setInteger("z", downCtl.getZ());
            tag.setTag("downCtl", pos);
        }

        return tag;
    }

    public void setUpCtl(BlockPos pos) {
        hasUp = pos != null;
        upCtl = pos;
    }

    public void setDownCtl(BlockPos pos) {
        hasDown = pos != null;
        downCtl = pos;
    }

    public boolean hasUpCtl() {
        return hasUp;
    }

    public boolean hasDownCtl() {
        return hasDown;
    }

    public boolean upCrl() {
        if (hasUp)
            return world.isBlockPowered(upCtl);
        return false;
    }

    public boolean downCrl() {
        if (hasDown)
            return world.isBlockPowered(downCtl);
        return false;
    }

}

package openmods.utils;

import com.google.common.base.MoreObjects;
import java.util.UUID;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.Vec3d;
import net.minecraft.util.math.Vec3i;
import net.minecraftforge.common.util.Constants;

public class NbtUtils {

	private static final String KEY = "K";
	private static final String VALUE = "V";

	private static final String TAG_Z = "Z";
	private static final String TAG_Y = "Y";
	private static final String TAG_X = "X";

	public static boolean hasCoordinates(NBTTagCompound tag) {
		return tag.hasKey(TAG_X, Constants.NBT.TAG_ANY_NUMERIC) &&
				tag.hasKey(TAG_Y, Constants.NBT.TAG_ANY_NUMERIC) &&
				tag.hasKey(TAG_Z, Constants.NBT.TAG_ANY_NUMERIC);
	}

	public static NBTTagCompound store(NBTTagCompound tag, int x, int y, int z) {
		tag.setInteger(TAG_X, x);
		tag.setInteger(TAG_Y, y);
		tag.setInteger(TAG_Z, z);
		return tag;
	}

	public static NBTTagCompound store(int x, int y, int z) {
		return store(new NBTTagCompound(), x, y, z);
	}

	public static NBTTagCompound store(NBTTagCompound tag, double x, double y, double z) {
		tag.setDouble(TAG_X, x);
		tag.setDouble(TAG_Y, y);
		tag.setDouble(TAG_Z, z);
		return tag;
	}

	public static NBTTagCompound store(double x, double y, double z) {
		return store(new NBTTagCompound(), x, y, z);
	}

	public static NBTTagCompound store(NBTTagCompound tag, Vec3i coords) {
		return store(tag, coords.getX(), coords.getY(), coords.getZ());
	}

	public static NBTTagCompound store(Vec3i coords) {
		return store(new NBTTagCompound(), coords.getX(), coords.getY(), coords.getZ());
	}

	public static NBTTagCompound store(NBTTagCompound tag, Coord coords) {
		return store(tag, coords.x, coords.y, coords.z);
	}

	public static NBTTagCompound store(Coord coords) {
		return store(new NBTTagCompound(), coords.x, coords.y, coords.z);
	}

	public static NBTTagCompound store(NBTTagCompound tag, BlockPos coords) {
		return store(tag, coords.getX(), coords.getY(), coords.getZ());
	}

	public static NBTTagCompound store(BlockPos coords) {
		return store(new NBTTagCompound(), coords.getX(), coords.getY(), coords.getZ());
	}

	public static NBTTagCompound store(NBTTagCompound tag, UUID uuid) {
		tag.setLong("UUIDMost", uuid.getMostSignificantBits());
		tag.setLong("UUIDLeast", uuid.getLeastSignificantBits());
		return tag;
	}

	public static NBTTagCompound store(UUID uuid) {
		return store(new NBTTagCompound(), uuid);
	}

	public static NBTTagCompound store(Vec3d vec) {
		return store(vec.x, vec.y, vec.z);
	}

	public static NBTTagCompound store(NBTTagCompound tag, ResourceLocation location) {
		tag.setString(KEY, location.getResourceDomain());
		tag.setString(VALUE, location.getResourcePath());
		return tag;
	}

	public static NBTTagCompound store(ResourceLocation location) {
		return store(new NBTTagCompound(), location);
	}

	public static Coord readCoord(NBTTagCompound tag) {
		final int x = tag.getInteger(TAG_X);
		final int y = tag.getInteger(TAG_Y);
		final int z = tag.getInteger(TAG_Z);
		return new Coord(x, y, z);
	}

	public static BlockPos readBlockPos(NBTTagCompound tag) {
		final int x = tag.getInteger(TAG_X);
		final int y = tag.getInteger(TAG_Y);
		final int z = tag.getInteger(TAG_Z);
		return new BlockPos(x, y, z);
	}

	public static Vec3d readVec(NBTTagCompound tag) {
		final double x = tag.getDouble(TAG_X);
		final double y = tag.getDouble(TAG_Y);
		final double z = tag.getDouble(TAG_Z);
		return new Vec3d(x, y, z);
	}

	public static UUID readUuid(NBTTagCompound tag) {
		final long most = tag.getLong("UUIDMost");
		final long least = tag.getLong("UUIDLeast");
		return new UUID(most, least);
	}

	public static ResourceLocation readResourceLocation(final NBTTagCompound entry) {
		final String domain = entry.getString(KEY);
		final String path = entry.getString(VALUE);
		final ResourceLocation blockLocation = new ResourceLocation(domain, path);
		return blockLocation;
	}

	public static <T extends Enum<T>> T readEnum(NBTTagCompound tag, String name, Class<T> cls) {
		if (tag.hasKey(name, Constants.NBT.TAG_ANY_NUMERIC)) {
			int ordinal = tag.getInteger(name);
			return EnumUtils.fromOrdinal(cls, ordinal);
		}

		return null;
	}

	@SuppressWarnings("unchecked")
	public static <T extends Enum<T>> T readEnum(NBTTagCompound tag, String name, T defaultValue) {
		return MoreObjects.firstNonNull(readEnum(tag, name, (Class<T>)defaultValue.getClass()), defaultValue);
	}
}

