package org.oddjob.arooa.convert.convertlets;

import org.junit.Test;

import java.math.BigDecimal;

import org.junit.Assert;

import org.oddjob.arooa.convert.ConversionFailedException;
import org.oddjob.arooa.convert.ConversionPath;
import org.oddjob.arooa.convert.DefaultConversionRegistry;

public class FloatConvertletsTest extends Assert {

   @Test
	public void testNumberToFloat() throws ConversionFailedException {
		DefaultConversionRegistry registry = new DefaultConversionRegistry();
		new FloatConvertlets().registerWith(registry);
		
		ConversionPath<Number, Float> path = registry.findConversion(
				Number.class, Float.class);
		
		Float result = path.convert(new BigDecimal(42.24), null);
		
		assertEquals(42.24, result, 0.001);  
	}
	
   @Test
	public void testStringToFloat() throws ConversionFailedException {
		DefaultConversionRegistry registry = new DefaultConversionRegistry();
		new FloatConvertlets().registerWith(registry);
		
		ConversionPath<String, Float> path = registry.findConversion(
				String.class, Float.class);
		
		Float result = path.convert("42.24", null);
		
		assertEquals(42.24, result, 0.001);  
	}
	
}

package pl.dominik.cmms.service.security;

import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import pl.dominik.cmms.entity.security.Role;
import pl.dominik.cmms.entity.security.User;
import pl.dominik.cmms.repository.security.RoleRepository;
import pl.dominik.cmms.repository.security.UserRepository;

import java.util.Arrays;
import java.util.HashSet;

@Service
public class AdminServiceImpl implements AdminService {

    private final UserRepository userRepository;
    private final RoleRepository roleRepository;
    private final BCryptPasswordEncoder passwordEncoder;

    public AdminServiceImpl(UserRepository userRepository,
                            RoleRepository roleRepository, BCryptPasswordEncoder passwordEncoder) {
        this.passwordEncoder = passwordEncoder;
        this.userRepository = userRepository;
        this.roleRepository = roleRepository;
    }

    @Override
    public User findByUserName(String username) {
        return userRepository.findByUsername(username);
    }

    @Override
    public void saveUser(User user) {
        user.setPassword(passwordEncoder.encode(user.getPassword()));
        user.setEnabled(1);
        Role userRole = roleRepository.findByName("ROLE_ADMIN");
        user.setRoles(new HashSet<Role>(Arrays.asList(userRole)));
        userRepository.save(user);
    }
}

package mil.nga.giat.mage.sdk.datastore.observation;

import android.net.Uri;
import android.support.annotation.NonNull;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.j256.ormlite.field.DataType;
import com.j256.ormlite.field.DatabaseField;
import com.j256.ormlite.field.ForeignCollectionField;
import com.j256.ormlite.table.DatabaseTable;

import org.apache.commons.lang3.builder.CompareToBuilder;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;

import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Date;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

import mil.nga.giat.mage.sdk.Temporal;
import mil.nga.giat.mage.sdk.datastore.user.Event;
import mil.nga.giat.mage.sdk.utils.GeometryUtility;
import mil.nga.wkb.geom.Geometry;
import mil.nga.wkb.geom.Point;
import mil.nga.wkb.util.GeometryUtils;

@DatabaseTable(tableName = "observations")
public class Observation implements Comparable<Observation>, Temporal {

    // name _id needed for cursor adapters
    @DatabaseField(generatedId = true)
    private Long _id;

    @DatabaseField(unique = true, columnName = "remote_id")
    private String remoteId;

    @DatabaseField(unique = true, columnName = "url")
    private String url;

	/**
	 * This is really the remote id!
	 */
	@DatabaseField(columnName = "user_id", canBeNull = false)
	private String userId = "-1";

    @DatabaseField(columnName = "device_id")
    private String deviceId;

    /**
     * This is the time the server created or updated the observation.  It can also be a local time, if no time from the server is given.
     */
    @DatabaseField(canBeNull = false, columnName = "last_modified", dataType = DataType.DATE_LONG)
    private Date lastModified = null;

    /**
     * This is the time the observation was made/reported at.
     */
    @DatabaseField(canBeNull = false, dataType = DataType.DATE_LONG)
    private Date timestamp = new Date(0);

    @DatabaseField(canBeNull = false)
    private boolean dirty = Boolean.TRUE;

    @DatabaseField(canBeNull = false)
    private State state = State.ACTIVE;

	@DatabaseField(columnName = "geometry", canBeNull = false, dataType = DataType.BYTE_ARRAY)
    private byte[] geometryBytes;

    @DatabaseField
    private String provider;

    @DatabaseField
    private Float accuracy;

    @DatabaseField
    private String locationDelta;

    @DatabaseField(canBeNull = false, foreign = true, foreignAutoRefresh = true)
    private Event event;

    @ForeignCollectionField(eager = true)
    private Collection<ObservationForm> forms = new ArrayList<>();

    @ForeignCollectionField(eager = true)
    private Collection<Attachment> attachments = new ArrayList<>();

    @DatabaseField(canBeNull = true, foreign = true, foreignAutoRefresh = true, foreignAutoCreate = true)
    private ObservationImportant important;

    @DatabaseField(persisterClass = ObservationErrorClassPersister.class, columnName = "error")
    private ObservationError error;

    @ForeignCollectionField(eager = true)
    private Collection<ObservationFavorite> favorites = new ArrayList<>();

    public Observation() {
        // ORMLite needs a no-arg constructor
    }

    public Observation(Geometry geometry, Collection<ObservationForm> forms, Collection<Attachment> attachments, Date timestamp, Event event) {
        this(null, null, geometry, forms, attachments, timestamp, event);
        this.dirty = true;
    }

    public Observation(String remoteId, Date lastModified, Geometry geometry, Collection<ObservationForm> forms, Collection<Attachment> attachments, Date timestamp, Event event) {
        super();
        this.remoteId = remoteId;
        this.lastModified = lastModified;
        this.geometryBytes = GeometryUtility.toGeometryBytes(geometry);
        this.forms = forms;
        this.attachments = attachments;
        this.dirty = false;
        this.timestamp = timestamp;
        this.event = event;
    }

    public Long getId() {
        return _id;
    }

    public void setId(Long id) {
        this._id = id;
    }

    public String getRemoteId() {
        return remoteId;
    }

    public void setRemoteId(String remoteId) {
        this.remoteId = remoteId;
    }

    public String getUrl() {
        return url;
    }

    public void setUrl(String url) {
        this.url = url;
    }

    public String getUserId() {
        return userId;
    }

    public void setUserId(String userId) {
        this.userId = userId;
    }

    public String getDeviceId() {
        return deviceId;
    }

    public void setDeviceId(String deviceId) {
        this.deviceId = deviceId;
    }

    public State getState() {
        return state;
    }

    public void setState(State state) {
        this.state = state;
    }

	public byte[] getGeometryBytes() {
		return geometryBytes;
	}

	public void setGeometryBytes(byte[] geometryBytes) {
		this.geometryBytes = geometryBytes;
	}

    public Geometry getGeometry() {
        return GeometryUtility.toGeometry(getGeometryBytes());
    }

    public void setGeometry(Geometry geometry) {
        this.geometryBytes = GeometryUtility.toGeometryBytes(geometry);
    }

    public String getProvider() {
        return provider;
    }

    public void setProvider(String provider) {
        this.provider = provider;
    }

    public Float getAccuracy() {
        return accuracy;
    }

    public void setAccuracy(Float accuracy) {
        this.accuracy = accuracy;
    }

    public String getLocationDelta() {
        return locationDelta;
    }

    public void setLocationDelta(String locationDelta) {
        this.locationDelta = locationDelta;
    }

    public Event getEvent() {
        return event;
    }

    public void setEvent(Event event) {
        this.event = event;
    }

    public ObservationError getError() {
        return error;
    }

    public void setError(ObservationError error) {
        this.error = error;
    }

    public Date getLastModified() {
        return lastModified;
    }

    public void setLastModified(Date lastModified) {
        this.lastModified = lastModified;
    }

    public boolean isDirty() {
        return dirty;
    }

    public void setDirty(boolean dirty) {
        this.dirty = dirty;
    }

    public Collection<ObservationForm> getForms() {
        return forms;
    }

    public void setForms(Collection<ObservationForm> forms) {
        this.forms = forms;
    }

    public void addForms(Collection<ObservationForm> forms) {

        Map<Long, ObservationForm> newFormsMap = new HashMap<Long, ObservationForm>();
        for (ObservationForm form : forms) {
            form.setObservation(this);
            newFormsMap.put(form.getFormId(), form);
        }

        Map<Long, ObservationForm> oldFormsMap = getFormsMap();

        oldFormsMap.putAll(newFormsMap);
        this.forms = oldFormsMap.values();
    }

    public Collection<Attachment> getAttachments() {
        return attachments;
    }

    public void setAttachments(Collection<Attachment> attachments) {
        this.attachments = attachments;
    }

    public ObservationImportant getImportant() {
        return important;
    }

    public void setImportant(ObservationImportant important) {
        this.important = important;
    }

    public Collection<ObservationFavorite> getFavorites() {
        return favorites;
    }

    public void setFavorites(Collection<ObservationFavorite> favorites) {
        this.favorites = favorites;
    }

    /**
     * A convenience method used for returning an Observation's properties in a
     * more useful data-structure.
     *
     * @return
     */
    public final Map<Long, ObservationForm> getFormsMap() {
        Map<Long, ObservationForm> formsMap = new HashMap<>();
        for (ObservationForm form : forms) {
            formsMap.put(form.getFormId(), form);
        }

        return formsMap;
    }

    /**
     * A convenience method used for returning an Observation's favorites in a
     * more useful data-structure.
     *
     * Map key is the userId who favorited the observation.
     *
     * @return
     */
    public final Map<String, ObservationFavorite> getFavoritesMap() {
        Map<String, ObservationFavorite> favoritesMap = new HashMap<>();
        for (ObservationFavorite favorite : favorites) {
            favoritesMap.put(favorite.getUserId(), favorite);
        }

        return favoritesMap;
    }

    public Uri getGoogleMapsUri() {
        DecimalFormat latLngFormat = new DecimalFormat("###.#####");
        String uriString = "http://maps.google.com/maps";

        Geometry geometry = getGeometry();
        Point point = GeometryUtils.getCentroid(geometry);
        uriString += String.format("?daddr=%1$s,%2$s",  latLngFormat.format(point.getY()), latLngFormat.format(point.getX()));

        return Uri.parse(uriString);
    }

    @Override
    public String toString() {
        return ToStringBuilder.reflectionToString(this);
    }

    @Override
    public int compareTo(@NonNull Observation another) {
        return new CompareToBuilder().append(this._id, another._id).append(this.remoteId, another.remoteId).toComparison();
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + ((_id == null) ? 0 : _id.hashCode());
        result = prime * result + ((remoteId == null) ? 0 : remoteId.hashCode());
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
            return true;
        if (obj == null)
            return false;
        if (getClass() != obj.getClass())
            return false;
        Observation other = (Observation) obj;
        return new EqualsBuilder().append(_id, other._id).append(remoteId, other.remoteId).isEquals();
    }

	@Override
	public Date getTimestamp() {
		return timestamp;
	}

	public void setTimestamp(Date timestamp) {
		this.timestamp = timestamp;
	}

	public ObservationProperty getPrimaryField() {
        return getField("primaryField");
    }

    public ObservationProperty getSecondaryField() {
        return getField("variantField");
    }

    public ObservationProperty getField(String name) {
        ObservationProperty field = null;
        Collection<ObservationForm> forms = getForms();
        if (forms != null && forms.size() > 0) {
            ObservationForm form = forms.iterator().next();
            JsonObject eventForm = getEventForm(form.getFormId());
            if (eventForm != null) {
                JsonElement fieldName = eventForm.get(name);
                if (fieldName != null && !fieldName.isJsonNull()) {
                    field = form.getPropertiesMap().get(fieldName.getAsString());
                }

            }
        }

        return field;
    }

    public JsonElement getStyle() {
        JsonElement style = null;
        Collection<ObservationForm> forms = getForms();
        if (forms != null && forms.size() > 0) {
            ObservationForm form = forms.iterator().next();
            JsonObject eventForm = getEventForm(form.getFormId());
            if (eventForm != null) {
                style = eventForm.get("style");
            }
        }

        return style;
    }

    private JsonObject getEventForm(Long formId) {
        Iterator<JsonElement> iterator = event.getForms().iterator();
        while (iterator.hasNext()) {
            JsonObject formJson = (JsonObject) iterator.next();
            Long id = formJson.get("id").getAsLong();
            if (id.equals(formId)) {
                return formJson;
            }
        }

        return null;
    }

    public boolean hasValidationError() {
        ObservationError observationError = getError();
        return observationError != null && observationError.getStatusCode() != null;
    }

    public String errorMessage() {
        String message = "";
        ObservationError observationError = getError();
        if (observationError != null) {
            message = observationError.getMessage() != null ? observationError.getMessage() : observationError.getDescription();
        }

        return message;
    }

}

package org.hubotek.service;

import java.io.Serializable;
import java.lang.reflect.ParameterizedType;
import java.util.Arrays;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Named;

import org.hubotek.service.orm.PersistenceService;
import org.nanotek.Base;

import com.google.common.base.Optional;
import com.querydsl.core.types.Expression;
import com.querydsl.core.types.QMap;
import com.querydsl.core.types.dsl.EntityPathBase;
import com.querydsl.jpa.impl.JPAQueryFactory;

/**
 * http://stackoverflow.com/questions/3403909/get-generic-type-of-class-at-runtime
 * @author JoseCanova
 *
 * @param <T>
 * @param <K>
 */
public abstract class DataBaseService<T extends Base<K> , K extends Serializable> implements Service {

	private JPAQueryFactory  qf;

	public static final Integer DEFAULT_MAX_RECORDS = 100;

	@Inject @Named("persistenceService")
	protected PersistenceService persistenceService;

	public void deleteAll (){ 
		persistenceService.delete(getPersistentClass());
	}

	public  T findById(K id)
	{ 
		return persistenceService.find(getPersistentClass(), id);
	}

	public List<Map<Expression<?>,?>> applyMapProjection(EntityPathBase<T> entityPathBase ,QMap projection , Integer offset , Integer limit)
	{ 
		return qf.select(projection).from(entityPathBase).offset(Optional.fromNullable(offset).or(0)).limit(Optional.fromNullable(limit).or(DEFAULT_MAX_RECORDS)).fetch();
	}

	public List<T> findByRange(Integer offset , Integer limit)
	{ 
		return findByRange(getPersistentClass() , offset , limit);
	}


	public List<T> findByRange(Class<T> clazz , Integer offset , Integer limit)
	{ 
		return   persistenceService.<T>createQuery("Select r from " + clazz.getSimpleName() + " r order by r.id desc" , clazz).setFirstResult(Optional.fromNullable(offset).or(0)).setMaxResults(Optional.fromNullable(limit).or(DEFAULT_MAX_RECORDS)).getResultList();
	}

	private List<?> getTypeArguments()
	{ 
		return Arrays.asList(((ParameterizedType)getClass().getGenericSuperclass()).getActualTypeArguments());
	}

	@SuppressWarnings("unchecked")
	public Class<T> getPersistentClass()
	{ 
		return (Class<T>)getTypeArguments().get(0);
	}

}

package firemerald.mechanimation.api.crafting.casting;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;

import firemerald.mechanimation.api.crafting.FluidOrGasStack;
import firemerald.mechanimation.api.crafting.IRecipes;
import net.minecraft.util.ResourceLocation;

public class CastingRecipes implements ICastingRecipes
{
	private static final Map<EnumCastingType, List<ICastingRecipes>> PROVIDERS = new HashMap<>();

	static
	{
		for (EnumCastingType type : EnumCastingType.values()) PROVIDERS.put(type, new ArrayList<>());
	}

	public static void registerRecipes(EnumCastingType type, ICastingRecipes recipes)
	{
		PROVIDERS.get(type).add(recipes);
	}

	public static void unregisterRecipes(EnumCastingType type, ICastingRecipes recipes)
	{
		PROVIDERS.get(type).remove(recipes);
	}

	public static ICastingRecipe getRecipe(EnumCastingType type, FluidOrGasStack stack)
	{
		return PROVIDERS.get(type).stream().map(recipes -> recipes.getResult(stack)).filter(result -> result != null).findFirst().orElse(null);
	}

	public static List<ICastingRecipe> getRecipes(EnumCastingType type)
	{
		return PROVIDERS.get(type).stream().flatMap(recipes -> recipes.getAllResults().stream()).collect(Collectors.toList());
	}

	public static boolean isCraftable(EnumCastingType type, FluidOrGasStack stack)
	{
		return getRecipes(type).parallelStream().anyMatch(recipe -> recipe.isInputValid(stack));
	}

	public static boolean isCraftable(ICastingRecipe result)
	{
		return result != null && result.getOutput() != null && !result.getOutput().isEmpty();
	}

	private static final Map<EnumCastingType, CastingRecipes> INSTANCES = new HashMap<>();

	static
	{
		for (EnumCastingType type : EnumCastingType.values()) INSTANCES.put(type, new CastingRecipes(type));
	}

	public static void registerRecipe(EnumCastingType type, ResourceLocation name, ICastingRecipe recipe)
	{
		CastingRecipes instance = INSTANCES.get(type);
		if (!instance.disabled.contains(name)) instance.recipes.put(name, recipe);
	}

	public static ICastingRecipe getRecipe(EnumCastingType type, ResourceLocation name)
	{
		return INSTANCES.get(type).recipes.get(name);
	}

	public static boolean hasRecipe(EnumCastingType type, ResourceLocation name)
	{
		return INSTANCES.get(type).recipes.containsKey(name);
	}

	public static void removeRecipe(EnumCastingType type, ResourceLocation name)
	{
		INSTANCES.get(type).recipes.remove(name);
	}

	public static void removeRecipe(EnumCastingType type, ICastingRecipe recipe)
	{
		Map<ResourceLocation, ICastingRecipe> recipes = INSTANCES.get(type).recipes;
		recipes.entrySet().parallelStream().filter(entry -> entry.getValue() == recipe).map((Function<Entry<ResourceLocation, ICastingRecipe>, Object>) Entry::getKey).collect(Collectors.toList()).forEach(recipes::remove);
	}

	public static void removeRecipe(EnumCastingType type, ResourceLocation name, ICastingRecipe recipe)
	{
		Map<ResourceLocation, ICastingRecipe> recipes = INSTANCES.get(type).recipes;
		if (recipes.get(name) == recipe) recipes.remove(name);
	}

	public static void disableRecipe(ResourceLocation name)
	{
		INSTANCES.values().forEach(instance -> {
			instance.recipes.remove(name);
			instance.disabled.add(name);
		});
	}

	public static void initRecipes()
	{
		PROVIDERS.values().stream().flatMap(List::stream).forEach(IRecipes::init);
	}

	private final Map<ResourceLocation, ICastingRecipe> recipes = new LinkedHashMap<>();
	private final Set<ResourceLocation> disabled = new HashSet<>();

	private CastingRecipes(EnumCastingType type)
	{
		registerRecipes(type, this);
	}

	@Override
	public void init()
	{
		recipes.clear();
		disabled.clear();
	}

	@Override
	public ICastingRecipe getResult(FluidOrGasStack stack)
	{
		return recipes.values().stream().filter(recipe -> recipe.isInputValid(stack)).findFirst().orElse(null);
	}

	@Override
	public Collection<ICastingRecipe> getAllResults()
	{
		return recipes.values();
	}
}

