package org.caffinitas.ohc.linked;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;

import org.caffinitas.ohc.Eviction;

/**
 * On-heap test-only counterpart of {@link OffHeapLinkedMap} for {@link CheckOHCacheImpl}.
 */
final class CheckSegment {
    private final Map<HeapKeyBuffer, byte[]> map;
    private final LinkedList<HeapKeyBuffer> lru = new LinkedList<>();
    private final AtomicLong freeCapacity;
    private final Eviction eviction;

    long hitCount;
    long missCount;
    long putAddCount;
    long putReplaceCount;
    long removeCount;
    long evictedEntries;

    public CheckSegment(int initialCapacity, float loadFactor, AtomicLong freeCapacity, Eviction eviction) {
        this.map = new HashMap<>(initialCapacity, loadFactor);
        this.freeCapacity = freeCapacity;
        this.eviction = eviction;
    }

    synchronized void clear() {
        for (Map.Entry<HeapKeyBuffer, byte[]> entry : map.entrySet()) {
            freeCapacity.addAndGet(sizeOf(entry.getKey(), entry.getValue()));
        }
        map.clear();
        lru.clear();
    }

    synchronized byte[] get(HeapKeyBuffer keyBuffer) {
        byte[] r = map.get(keyBuffer);
        if (r == null) {
            missCount++;
            return null;
        }

        lru.remove(keyBuffer);
        lru.addFirst(keyBuffer);
        hitCount++;

        return r;
    }

    synchronized boolean put(HeapKeyBuffer keyBuffer, byte[] data, boolean ifAbsent, byte[] old) {
        long sz = sizeOf(keyBuffer, data);
        while (freeCapacity.get() < sz) {
            if (!evictOne()) {
                remove(keyBuffer);
                return false;
            }
        }

        byte[] existing = map.get(keyBuffer);
        if (ifAbsent || old != null) {
            if (ifAbsent && existing != null) {
                return false;
            }
            if (old != null && existing != null && !Arrays.equals(old, existing)) {
                return false;
            }
        }

        map.put(keyBuffer, data);
        lru.remove(keyBuffer);
        lru.addFirst(keyBuffer);

        if (existing != null) {
            freeCapacity.addAndGet(sizeOf(keyBuffer, existing));
            putReplaceCount++;
        } else {
            putAddCount++;
        }

        freeCapacity.addAndGet(-sz);

        return true;
    }

    synchronized boolean remove(HeapKeyBuffer keyBuffer) {
        byte[] old = map.remove(keyBuffer);
        if (old != null) {
            boolean r = lru.remove(keyBuffer);
            removeCount++;
            freeCapacity.addAndGet(sizeOf(keyBuffer, old));
            return r;
        }
        return false;
    }

    synchronized long size() {
        return map.size();
    }

    synchronized Iterator<HeapKeyBuffer> hotN(int n) {
        List<HeapKeyBuffer> lst = new ArrayList<>(n);
        for (Iterator<HeapKeyBuffer> iter = lru.iterator(); iter.hasNext() && n-- > 0;) {
            lst.add(iter.next());
        }
        return lst.iterator();
    }

    synchronized Iterator<HeapKeyBuffer> keyIterator() {
        return new ArrayList<>(lru).iterator();
    }

    //

    private boolean evictOne() {
        if (eviction == Eviction.NONE) {
            return false;
        }

        HeapKeyBuffer last = lru.pollLast();
        if (last == null) {
            return false;
        }
        byte[] old = map.remove(last);
        freeCapacity.addAndGet(sizeOf(last, old));
        evictedEntries++;
        return true;
    }

    static long sizeOf(HeapKeyBuffer key, byte[] value) {
        // calculate the same value as the original impl would do
        return Util.ENTRY_OFF_DATA + Util.roundUpTo8(key.size()) + value.length;
    }

    void resetStatistics() {
        evictedEntries = 0L;
        hitCount = 0L;
        missCount = 0L;
        putAddCount = 0L;
        putReplaceCount = 0L;
        removeCount = 0L;
    }

}

package com.linkedin.parseq;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import com.linkedin.parseq.Cancellable;


/**
 * A wrapper around a delayed executor that provides better behavior for
 * cancellation. If a task is cancelled (or run), we forget the reference to
 * that task. Without this indirection it is possible that the underlying
 * scheduled executor will hold a reference to the task - even if it has been
 * cancelled - thus keeping a path to the task from a GC root.
 *
 * @author Chris Pettitt
 */
/* package private */ class IndirectDelayedExecutor implements DelayedExecutor {
  private final DelayedExecutor _executor;

  public IndirectDelayedExecutor(final DelayedExecutor executor) {
    _executor = executor;
  }

  @Override
  public Cancellable schedule(final long delay, final TimeUnit unit, final Runnable command) {
    final IndirectRunnable indirectRunnable = new IndirectRunnable(command);
    final Cancellable cancellable = _executor.schedule(delay, unit, indirectRunnable);
    return new IndirectCancellable(cancellable, indirectRunnable);
  }

  private static class IndirectRunnable implements Runnable {
    private AtomicReference<Runnable> _commandRef;

    public IndirectRunnable(final Runnable command) {
      _commandRef = new AtomicReference<Runnable>(command);
    }

    @Override
    public void run() {
      final Runnable runnable = _commandRef.get();
      if (runnable != null && _commandRef.compareAndSet(runnable, null)) {
        runnable.run();
      }
    }

    public boolean cancel() {
      final Runnable runnable = _commandRef.get();
      return (runnable != null && _commandRef.compareAndSet(runnable, null));
    }
  }

  private static class IndirectCancellable implements Cancellable {
    private final Cancellable _cancellable;
    private final IndirectRunnable _runnable;

    private IndirectCancellable(final Cancellable cancellable, final IndirectRunnable runnable) {
      _cancellable = cancellable;
      _runnable = runnable;
    }

    @Override
    public boolean cancel(final Exception reason) {
      return _runnable.cancel() && _cancellable.cancel(reason);
    }
  }
}

