        CopyOnWriteArrayList<Task> newTaskList = new CopyOnWriteArrayList<>();
        Integer taskNum = taskList.size();
        for (int j = 0; j < taskNum; j++) {
            if (taskList == null || taskList.size() == 0) {
                break;
            }
            for (int i = 0; i < userList.size(); i++) {
                if (taskList == null || taskList.size() == 0) {
