        }
        for (int i = 0; i < size; i++) {
            if (i % 3 == 0) {
                assertNull(test.getIfPresent(new BadHash(i)));
            } else {
                assertEquals(i, test.getIfPresent(new BadHash(i)).intValue());
            }
        }
        for (int i = 0; i < size; i++) {
