import com.google.spanner.admin.database.v1.UpdateDatabaseDdlMetadata;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class PgPartitionedDmlSampleIT extends SampleTestBase {

  @Test
  public void testPgPartitionedDml() throws Exception {
    final String databaseId = idGenerator.generateDatabaseId();
    databaseAdminClient
        .createDatabase(
            databaseAdminClient
                .newDatabaseBuilder(DatabaseId.of(projectId, instanceId, databaseId))
                .setDialect(Dialect.POSTGRESQL)
                .build(),
            Collections.emptyList())
        .get();
    final OperationFuture<Void, UpdateDatabaseDdlMetadata> updateOperation =
        databaseAdminClient.updateDatabaseDdl(
            instanceId,
            databaseId,
            Collections.singleton(
                "CREATE TABLE users ("
                    + "  user_id   bigint NOT NULL PRIMARY KEY,"
                    + "  user_name varchar(1024),"
                    + "  active    boolean"
                    + ")"),
            null);
    updateOperation.get();
    DatabaseClient client =
        spanner.getDatabaseClient(DatabaseId.of(projectId, instanceId, databaseId));
    client.write(
        Arrays.asList(
            Mutation.newInsertBuilder("users")
                .set("user_id")
                .to(1L)
                .set("user_name")
                .to("user1")
                .set("active")
                .to(false)
                .build(),
            Mutation.newInsertBuilder("users")
                .set("user_id")
                .to(2L)
                .set("user_name")
                .to("user2")
                .set("active")
                .to(false)
                .build(),
            Mutation.newInsertBuilder("users")
                .set("user_id")
                .to(3L)
                .set("user_name")
                .to("user3")
                .set("active")
                .to(true)
                .build()));

    final String out =
        SampleRunner.runSample(
            () -> PgPartitionedDmlSample.partitionedDml(projectId, instanceId, databaseId));

    assertTrue(out.contains("Deleted at least 2 inactive users"));
  }
}

