			control.setY(start.getY()+1);
		}
		if(control.getY()>=end.getY()){
			control.setY(end.getY()-1);
		}*/

		double y1 = dEnd.getY();
		double x1 = dEnd.getX();
		double y2 = control.getY();
		double x2 = control.getX();
		double y3 = dStart.getY();
