 */
public class Logger {

  private final Log log;

  Logger(Log log) {
    this.log = log;
  }

  public void error(Supplier<String> s, Throwable e) {
    log.error(s.get(), e);
  }

  public void error(Supplier<String> s) {
    log.error(s.get());
  }

  public void warn(Supplier<String> s) {
