package com.twilio.sms2fa.application.util;

import com.twilio.sms2fa.domain.exception.DomainException;
import org.slf4j.Logger;

import javax.persistence.PersistenceException;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.validation.ConstraintViolationException;
import java.io.IOException;

import static com.twilio.sms2fa.application.util.ValidationUtil.extractMessage;
import static org.slf4j.LoggerFactory.getLogger;

public final class ServletUtil {

    private static final Logger LOG = getLogger(ServletUtil.class);

    private ServletUtil() { }

    public static void handleException(
            final Exception e,
            final HttpServletRequest request,
            final HttpServletResponse response,
            final String forwardToJsp) throws ServletException, IOException {
        if (e instanceof DomainException) {
            DomainException de = (DomainException) e;
            handle(request, response, forwardToJsp, de.getMessage());
        } else if (e instanceof ConstraintViolationException) {
            ConstraintViolationException cve = (ConstraintViolationException) e;
            handle(request, response, forwardToJsp, extractMessage(cve));
        } else if (e instanceof PersistenceException) {
            PersistenceException pe = (PersistenceException) e;
            if (pe.getMessage().contains(
                    "UNIQUE constraint failed: USER.EMAIL")) {
                handle(request, response, forwardToJsp,
                        "User with this e-mail already exists");
            } else {
                handle(request, response, forwardToJsp, e.getMessage());
            }
        } else {
            LOG.error("Cannot handle this exception: %s", e.getMessage(), e);
            throw new RuntimeException(e);
        }
    }

    private static void handle(
            final HttpServletRequest request,
            final HttpServletResponse response,
            final String forwardToJsp,
            final String message)
            throws ServletException, IOException {
        request.setAttribute("errorMessage", message);
        request.getRequestDispatcher(forwardToJsp).forward(request, response);
    }

}

package gui;//: gui/MessageBoxes.java
// Demonstrates JOptionPane.
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import static net.mindview.util.SwingConsole.*;

public class MessageBoxes extends JFrame {
  private JButton[] b = {
    new JButton("Alert"), new JButton("Yes/No"),
    new JButton("Color"), new JButton("Input"),
    new JButton("3 Vals")
  };
  private JTextField txt = new JTextField(15);
  private ActionListener al = new ActionListener() {
    public void actionPerformed(ActionEvent e) {
      String id = ((JButton)e.getSource()).getText();
      if(id.equals("Alert"))
        JOptionPane.showMessageDialog(null,
          "There's a bug on you!", "Hey!",
          JOptionPane.ERROR_MESSAGE);
      else if(id.equals("Yes/No"))
        JOptionPane.showConfirmDialog(null,
          "or no", "choose yes",
          JOptionPane.YES_NO_OPTION);
      else if(id.equals("Color")) {
        Object[] options = { "Red", "Green" };
        int sel = JOptionPane.showOptionDialog(
          null, "Choose a Color!", "Warning",
          JOptionPane.DEFAULT_OPTION,
          JOptionPane.WARNING_MESSAGE, null,
          options, options[0]);
        if(sel != JOptionPane.CLOSED_OPTION)
          txt.setText("Color Selected: " + options[sel]);
      } else if(id.equals("Input")) {
        String val = JOptionPane.showInputDialog(
            "How many fingers do you see?");
        txt.setText(val);
      } else if(id.equals("3 Vals")) {
        Object[] selections = {"First", "Second", "Third"};
        Object val = JOptionPane.showInputDialog(
          null, "Choose one", "Input",
          JOptionPane.INFORMATION_MESSAGE,
          null, selections, selections[0]);
        if(val != null)
          txt.setText(val.toString());
      }
    }
  };
  public MessageBoxes() {
    setLayout(new FlowLayout());
    for(int i = 0; i < b.length; i++) {
      b[i].addActionListener(al);
      add(b[i]);
    }
    add(txt);
  }
  public static void main(String[] args) {
    run(new MessageBoxes(), 200, 200);
  }
} ///:~

package uk.ac.ebi.gxa.statistics;

import com.google.common.base.Strings;

import javax.annotation.Nonnull;
import java.io.ObjectStreamException;
import java.io.Serializable;

import static com.google.common.base.Strings.isNullOrEmpty;
import static uk.ac.ebi.gxa.utils.EscapeUtil.encode;

/**
 * Serializable representation of ef-efv for the purpose of ConciseSet storage.
 * This class also represents ef-efvs at bit index query time.
 * <p/>
 */
public class EfvAttribute extends EfAttribute implements Serializable {
    private static final String EF_EFV_SEP = "_";
    private static final long serialVersionUID = -4674735573391531209L;

    private final String efv;
    private transient String value;

    /**
     * Constructor used for ef-efv tuple stored in bit index
     *
     * @param ef  an experiment factor name
     * @param efv an experiment factor value
     */
    public EfvAttribute(@Nonnull final String ef, @Nonnull final String efv) {
        super(ef);
        this.efv = efv;
        this.value = encodePair(ef, efv);
    }

    public String getEfv() {
        return efv;
    }

    @Override
    public String getValue() {
        return value;
    }

    private static String encodePair(@Nonnull final String ef, @Nonnull final String efv) {
        return !Strings.isNullOrEmpty(ef) && !Strings.isNullOrEmpty(efv) ? ef + EF_EFV_SEP + efv : null;
    }

    /**
     * Restores the transient fields on deserialization
     *
     * @return <code>this</code>
     * @throws ObjectStreamException in case of I/O errors during deserialization
     */
    private Object readResolve() throws ObjectStreamException {
        this.value = encodePair(getEf(), efv);
        return this;
    }
}

