		ENTITY result = null;
		final Optional<ENTITY> entity = this.repo.findById(id);
		if(entity.isPresent()) {
			result = entity.get();
		}
		return result;
	}
	public List<ENTITY> getAll(){
		return this.repo.findAll();
	}
	public void deleteById(Integer id) {
		this.repo.deleteById(id);
	}
}

