    /**
     * @return Cache configurations.
     */
    private List<CacheConfiguration<Integer, Integer>> cacheConfigurations() {
        List<CacheConfiguration<Integer, Integer>> ccfgs = new ArrayList<>();

        ccfgs.add(cacheConfiguration(REPLICATED, FULL_SYNC, 0));

        ccfgs.add(cacheConfiguration(PARTITIONED, FULL_SYNC, 0));
        ccfgs.add(cacheConfiguration(PARTITIONED, FULL_SYNC, 1));
        ccfgs.add(cacheConfiguration(PARTITIONED, FULL_SYNC, 2));

        return ccfgs;
    }

    /**
     * @param cacheMode Cache mode.
     * @param syncMode Write synchronization mode.
     * @param backups Number of backups.
     * @return Cache configuration.
     */
    private CacheConfiguration<Integer, Integer> cacheConfiguration(
        CacheMode cacheMode,
        CacheWriteSynchronizationMode syncMode,
        int backups) {
        CacheConfiguration<Integer, Integer> ccfg = new CacheConfiguration<>(DEFAULT_CACHE_NAME);

        ccfg.setCacheMode(cacheMode);
        ccfg.setAtomicityMode(TRANSACTIONAL);
        ccfg.setWriteSynchronizationMode(syncMode);

        if (cacheMode == PARTITIONED)
            ccfg.setBackups(backups);

        return ccfg;
    }

    /**
     * @throws Exception If failed.
     */
    @Test
    public void testTxConflictGetAndPutIfAbsent() throws Exception {
        Ignite ignite0 = ignite(0);

        final IgniteTransactions txs = ignite0.transactions();

        for (CacheConfiguration<Integer, Integer> ccfg : cacheConfigurations()) {
            try {
                IgniteCache<Integer, Integer> cache = ignite0.createCache(ccfg);

                ThreadLocalRandom rnd = ThreadLocalRandom.current();

                for (int i = 0; i < 10; i++) {
                    Integer key = rnd.nextInt(10_000);

                    cache.put(key, 2);

                    for (TransactionConcurrency concurrency : TransactionConcurrency.values()) {
                        for (TransactionIsolation isolation : TransactionIsolation.values()) {
                            if (MvccFeatureChecker.forcedMvcc() && !MvccFeatureChecker.isSupported(concurrency, isolation))
                                continue;

                            try (Transaction tx = txs.txStart(concurrency, isolation)) {
                                Object old = cache.getAndPutIfAbsent(key, 3);

                                assertEquals(2, old);

                                Object val = cache.get(key);

                                assertEquals(2, val);

                                tx.commit();
                            }

                            assertEquals((Integer)2, cache.get(key));
                        }
                    }
                }
            }
            finally {
                ignite0.destroyCache(ccfg.getName());
            }
        }
    }
}

package com.vc.hard;

import java.util.*;

//TLE: Work on fixing it

class L1187 {
    HashMap<String, Integer> memo = new HashMap<>();

    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for(int i = 0; i < arr2.length; i++) map.put(arr2[i], map.getOrDefault(arr2[i], 0) + 1);

        int res = solve(0, Integer.MIN_VALUE, arr1, map);
        return res == Integer.MAX_VALUE ? -1 : res;
    }

    private int solve(int index1, int prev, int[] arr1, TreeMap<Integer, Integer> arr2) {
        if(index1 == arr1.length) return 0;

        String key = index1+" "+prev;
        if(memo.containsKey(key)) memo.get(key);

        //keep the current index
        int keep = Integer.MAX_VALUE;
        if(arr1[index1] > prev) {
            keep = solve(index1 + 1, arr1[index1], arr1, arr2);
        }

        //replace the current index
        int replace = Integer.MAX_VALUE;
        if(!arr2.isEmpty()) {
            Integer replaceElement = arr2.higherKey(prev);
            if(replaceElement != null) {
                arr2.put(replaceElement, arr2.get(replaceElement) - 1);
                if(arr2.get(replaceElement) == 0) arr2.remove(replaceElement);

                replace = solve(index1 + 1, replaceElement, arr1, arr2);
                if(replace != Integer.MAX_VALUE) replace++;

                arr2.put(replaceElement, arr2.getOrDefault(replaceElement, 0) + 1);
            }
        }

        int res = Math.min(keep, replace);
        memo.put(key, res);
        return res;
    }
}

