        docflowConfig.udtTypes.fields = docflowConfig.fieldTypes;
        docflowConfig.documents.put(docflowConfig.udtTypes.name.toUpperCase(), docflowConfig.udtTypes);
    }

    private static void recurrentProcessStructure(DocflowConfig docflowConfig, LinkedHashMap<String, Field> fields, Stack<String> path, Result result) {
        for (Field fldType : fields.values()) {
            if (fldType.udtType != null)
                recurrentProcessFieldType(docflowConfig, fldType, path, result);
            else if (fldType.type == BuiltInTypes.STRUCTURE || fldType.type == BuiltInTypes.SUBTABLE)
                recurrentProcessStructure(docflowConfig, ((FieldStructure) fldType).fields, path, result);
        }
    }

    private static void recurrentProcessFieldType(DocflowConfig docflowConfig, Field fldType, Stack<String> path, Result result) {

        final Field parentType = docflowConfig.fieldTypes.get(fldType.udtType.toUpperCase());
        if (parentType == null) {
            result.addMsg(YamlMessages.error_UDTypeHasUnknownType, fldType.name, fldType.udtType);
            fldType.type = BuiltInTypes.STRING; // Just to let process other fields
            return;
        }

        if (path.contains(parentType.name)) { // it's loop
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < path.size(); i++) {
                if (sb.length() > 0)
                    sb.append(",");
                sb.append(path.get(i));
            }
            result.addMsg(YamlMessages.error_UDTypeCyclingDependenciesWithTypes, fldType.name, sb.toString());
            fldType.type = BuiltInTypes.STRING; // Just to let process other fields
            return;
        }

        if (parentType.type == null) {
            path.push(fldType.name);
            recurrentProcessFieldType(docflowConfig, parentType, path, result);
            path.pop();
        } else if (parentType.type == BuiltInTypes.STRUCTURE || parentType.type == BuiltInTypes.SUBTABLE)
            recurrentProcessStructure(docflowConfig, ((FieldStructure) parentType).fields, path, result);

        // apply named enum type
        if (fldType.type == BuiltInTypes.ENUM) {
            if (fldType.udtType != null) {
                Field type = docflowConfig.fieldTypes.get(fldType.udtType.toUpperCase());
                if (type == null)
                    result.addMsg(YamlMessages.error_TypeHasUnknownType, type.name, type.udtType);
                else if (!(type instanceof FieldEnum))
                    result.addMsg(YamlMessages.error_TypeNotAnEnumType, type.name, type.udtType);
                else
                    type.mergeTo(fldType);
            } else {
                FieldEnum fieldEnum = (FieldEnum) fldType;
                fieldEnum.enumTypeName = "docflow.enums." + NamesUtil.turnFirstLetterInUpperCase(fldType.name);
            }
        }
        // apply named structure type
        else if (fldType.type == BuiltInTypes.STRUCTURE || fldType.type == BuiltInTypes.SUBTABLE) {
            if (fldType.udtType != null) {
                Field type = docflowConfig.fieldTypes.get(fldType.udtType.toUpperCase());
                if (type == null)
                    result.addMsg(YamlMessages.error_TypeHasUnknownType, type.name, type.udtType);
                else if (!(type instanceof FieldStructure))
                    result.addMsg(YamlMessages.error_TypeNotAStructureType, type.name, type.udtType);
                else
                    type.deepCopy().mergeTo(fldType);
            }
        } else
            // TODO: Check that not an enum, structure or refers are merged into simple field
            parentType.mergeTo(fldType);
    }
}

package com.arcrobotics.ftclib.controller;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class PIDInputOutputTest {
    private PIDController m_controller;

    @BeforeEach
    void setUp() {
        m_controller = new PIDController(0, 0, 0);
    }

    @Test
    void proportionalGainOutputTest() {
        m_controller.setP(4);

        assertEquals(-0.1, m_controller.calculate(0.025, 0), 1e-5);
    }

    @Test
    void integralGainOutputTest() {
        m_controller.setI(4);
        m_controller.setIntegrationBounds(-180,180);

        double out = 0;

        for (int i = 0; i < 5; i++) {
            out = m_controller.calculate(0.025, 0);
        }

        assertEquals(-0.5 * m_controller.getPeriod(), out, 1e-5);
    }

    @Test
    void derivativeGainOutputTest() {
        m_controller.setD(4);

        assertEquals(0, m_controller.calculate(0,0));

        assertEquals(m_controller.calculate(0.025, 0), -0.1 / m_controller.getPeriod(), 0.05);
    }
}

package dao;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

import javax.sql.DataSource;

import beans.Product;

public class ProductDao {
	private DataSource datasource;
	private Connection conn;
	private PreparedStatement pstmt;
	private ResultSet rs;

	public ProductDao(DataSource datasource) {
		this.datasource = datasource;
	}

	// 모든 상품을 리스트로 리턴
	public List<Product> findAll() {
		List<Product> prodList = new ArrayList<>();

		try {
			conn = datasource.getConnection();
			pstmt = conn.prepareStatement("select * from product");
			rs = pstmt.executeQuery();

			while (rs.next()) {
				Product product = new Product();
				product.setProdID(rs.getInt("prodID"));
				product.setFarmID(rs.getString("farmID"));
				product.setProdName(rs.getString("prodName"));
				product.setProdPrice(rs.getInt("prodPrice"));
				product.setProdImg(rs.getString("prodImg"));
				product.setProdInfo(rs.getString("prodInfo"));
				product.setProdID(rs.getInt("prodID"));

				prodList.add(product);
			}

		} catch (SQLException e) {
			System.out.println("농산품 전체 출력 SQL에러");
			e.printStackTrace();
		} finally {
			closeAll();
		}

		System.out.println("농산품 전체 출력 완료");
		return prodList;
	}

	public Product find(int prodId) {
		Product product = null;

		try {
			conn = datasource.getConnection();
			pstmt = conn.prepareStatement("select * from product where prodID=?");
			pstmt.setInt(1, prodId);
			rs = pstmt.executeQuery();

			while (rs.next()) {
				product = new Product();
				product.setProdID(rs.getInt("prodID"));
				product.setFarmID(rs.getString("farmID"));
				product.setFarmTel(rs.getString("farmTel"));
				product.setProdName(rs.getString("prodName"));
				product.setProdPrice(rs.getInt("prodPrice"));
				product.setProdImg(rs.getString("prodImg"));
				product.setProdInfo(rs.getString("prodInfo"));
				product.setProdID(rs.getInt("prodID"));
			}

		} catch (Exception e) {
			System.out.println("특정 농산품 출력 SQL에러");
			e.printStackTrace();
		} finally {
			closeAll();
		}
		System.out.println("특정 농산품 출력 완료");
		return product;
	}


    public boolean save(Product prod) {
		boolean rowAffected = false;

		try {
			conn = datasource.getConnection();
			pstmt = conn.prepareStatement("insert into product(farmID, prodName, prodPrice, farmTel, prodInfo) values(?,?,?,?,?)");
			pstmt.setString(1, prod.getFarmID());
			pstmt.setString(2, prod.getProdName());
			pstmt.setInt(3, prod.getProdPrice());
			pstmt.setString(4, prod.getFarmTel());
			pstmt.setString(5, prod.getProdInfo());

			rowAffected = pstmt.executeUpdate() > 0;

		} catch (SQLException e) {
			e.printStackTrace();
			System.out.println("SQL에러 - save");
		} finally {
			closeAll();
		}
		return rowAffected;
	}


	public boolean update(Product prod) {
		boolean rowAffected = false;

		try {
			conn = datasource.getConnection();
			pstmt = conn.prepareStatement("update product set farmID =?, farmTel =?, prodName =?, prodImg=?, prodPrice =?, prodInfo =? where prodID =? ");
			pstmt.setString(1, prod.getFarmID());
			pstmt.setString(2, prod.getFarmTel());
			pstmt.setString(3, prod.getProdName());
			pstmt.setString(4, prod.getProdImg());
			pstmt.setInt(5, prod.getProdPrice());
			pstmt.setString(6, prod.getProdInfo());
			pstmt.setInt(7, prod.getProdID());

			rowAffected = pstmt.executeUpdate() > 0;

		} catch (SQLException e) {
			e.printStackTrace();
			System.out.println("SQL에러 - save");
		} finally {
			closeAll();
		}
		return rowAffected;
	}


	public int findProdNum() {
		int num = 1;

		try {
			conn = datasource.getConnection();
			pstmt = conn.prepareStatement("select max(prodID) from product");
			rs = pstmt.executeQuery();

			if(rs.next()) {
				num = rs.getInt(1);
			}

			}catch (SQLException e) {
				e.printStackTrace();
				System.out.println("select SQL 에러");
			} finally { 
				closeAll();	
			}
		System.out.println(num);
		return num;
	}



	public boolean delete(int prodID) {
		boolean rowDeleted = false;

		try {
			conn = datasource.getConnection();
			pstmt = conn.prepareStatement(" DELETE FROM product WHERE prodID = ? ");
			pstmt.setInt(1, prodID);
			rowDeleted = pstmt.executeUpdate() > 0;

		} catch (SQLException e) {
			System.out.println("product 삭제 SQL 에러");
			return false;
		}finally {
			closeAll();
		}
		System.out.println("product 삭제성공!");

		return rowDeleted;
	}


	public void closeAll() {
		try {
			if (rs != null)
				rs.close();
			if (pstmt != null)
				pstmt.close();
			if (conn != null)
				conn.close();
		} catch (Exception e) {
			System.out.println("DB연결 닫는 과정에서 에러발생");
		}
	}

}

