import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Answers;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;

@FetcherTest
public class IsbnViaEbookDeFetcherTest extends AbstractIsbnFetcherTest {

    @BeforeEach
    public void setUp() {
        bibEntry = new BibEntry();
        bibEntry.setType(BiblatexEntryTypes.BOOK);
        bibEntry.setField("bibtexkey", "9780134685991");
        bibEntry.setField("title", "Effective Java");
        bibEntry.setField("publisher", "Addison Wesley");
        bibEntry.setField("year", "2018");
        bibEntry.setField("author", "Bloch, Joshua");
        bibEntry.setField("date", "2018-01-11");
        bibEntry.setField("ean", "9780134685991");
        bibEntry.setField("isbn", "0134685997");
        bibEntry.setField("url", "https://www.ebook.de/de/product/28983211/joshua_bloch_effective_java.html");

        fetcher = new IsbnViaEbookDeFetcher(mock(ImportFormatPreferences.class, Answers.RETURNS_DEEP_STUBS));
    }

    @Test
    @Override
    public void testName() {
        assertEquals("ISBN (ebook.de)", fetcher.getName());
    }

    @Test
    @Override
    public void testHelpPage() {
        assertEquals("ISBNtoBibTeX", fetcher.getHelpPage().get().getPageName());
    }

    @Test
    @Override
    public void searchByIdSuccessfulWithShortISBN() throws FetcherException {
        Optional<BibEntry> fetchedEntry = fetcher.performSearchById("0134685997");
        assertEquals(Optional.of(bibEntry), fetchedEntry);
    }

    @Test
    @Override
    public void searchByIdSuccessfulWithLongISBN() throws FetcherException {
        Optional<BibEntry> fetchedEntry = fetcher.performSearchById("9780134685991");
        assertEquals(Optional.of(bibEntry), fetchedEntry);
    }

    @Test
    @Override
    public void authorsAreCorrectlyFormatted() throws Exception {
        BibEntry bibEntry = new BibEntry();
        bibEntry.setType(BiblatexEntryTypes.BOOK);
        bibEntry.setField("bibtexkey", "9783662565094");
        bibEntry.setField("title", "Fundamentals of Business Process Management");
        bibEntry.setField("publisher", "Springer Berlin Heidelberg");
        bibEntry.setField("year", "2018");
        bibEntry.setField("author", "Dumas, Marlon and Rosa, Marcello La and Mendling, Jan and Reijers, Hajo A.");
        bibEntry.setField("date", "2018-03-23");
        bibEntry.setField("ean", "9783662565094");
        bibEntry.setField("url", "https://www.ebook.de/de/product/33399253/marlon_dumas_marcello_la_rosa_jan_mendling_hajo_a_reijers_fundamentals_of_business_process_management.html");

        Optional<BibEntry> fetchedEntry = fetcher.performSearchById("978-3-662-56509-4");
        assertEquals(Optional.of(bibEntry), fetchedEntry);
    }

    /**
     * This test searches for a valid ISBN. See https://www.amazon.de/dp/3728128155/?tag=jabref-21 However, this ISBN is
     * not available on ebook.de. The fetcher should return nothing rather than throwing an exeption.
     */
    @Test
    public void searchForValidButNotFoundISBN() throws Exception {
        Optional<BibEntry> fetchedEntry = fetcher.performSearchById("3728128155");
        assertEquals(Optional.empty(), fetchedEntry);
    }
}

package com.letv.core.utils;

import android.app.KeyguardManager;
import android.content.Context;
import android.os.PowerManager;
import android.util.DisplayMetrics;
import com.letv.core.BaseApplication;

public class ScreenInfoUtils {
    private static float mDensity;
    private static float mDensityDpi;
    private static int mHeight = 0;
    private static float mScaledDensity;
    private static int mWidth = 0;
    private static float mXdpi;
    private static float mYdpi;

    private static void getDisplayMetricsInfo(Context context) {
        DisplayMetrics dm = context.getResources().getDisplayMetrics();
        mWidth = dm.widthPixels;
        mHeight = dm.heightPixels;
        mXdpi = dm.xdpi;
        mYdpi = dm.ydpi;
        mDensity = dm.density;
        mDensityDpi = (float) dm.densityDpi;
        mScaledDensity = dm.scaledDensity;
    }

    public static int getWidth(Context context) {
        if (mWidth == 0) {
            getDisplayMetricsInfo(context);
        }
        return mWidth;
    }

    public int getHeight() {
        return mHeight;
    }

    public float getXdpi() {
        return mXdpi;
    }

    public float getYdpi() {
        return mYdpi;
    }

    public float getDensity() {
        return mDensity;
    }

    public float getDensityDpi() {
        return mDensityDpi;
    }

    public float getScaledDensity() {
        return mScaledDensity;
    }

    public static boolean reflectScreenState() {
        boolean isScreenOn = true;
        boolean flag = false;
        try {
            isScreenOn = ((PowerManager) BaseApplication.getInstance().getSystemService("power")).isScreenOn();
            flag = ((KeyguardManager) BaseApplication.getInstance().getSystemService("keyguard")).inKeyguardRestrictedInputMode();
        } catch (Exception e) {
            e.printStackTrace();
        }
        return isScreenOn && !flag;
    }
}

package com.otuadraw.util;

import javafx.scene.control.Alert;
import javafx.scene.control.ButtonBar;
import javafx.scene.control.ButtonType;

public class AlertUtil {

    public static boolean warn(String title, String header, String content, boolean neglectful){
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle(title);
        alert.setHeaderText(header);
        alert.setContentText(content);
        if(neglectful){
            ButtonType neglect = new ButtonType("忽略");
            ButtonType confirm = new ButtonType("取消",ButtonBar.ButtonData.CANCEL_CLOSE);
            alert.getButtonTypes().setAll(confirm, neglect);
            return neglect == alert.showAndWait().get();
        }else{
            alert.showAndWait();
        }
        return false;

    }
}

