package com.intellij.psi.impl.smartPointers;

import com.intellij.lang.LanguageUtil;
import com.intellij.openapi.application.ReadAction;
import com.intellij.openapi.util.Comparing;
import com.intellij.openapi.util.ProperTextRange;
import com.intellij.openapi.util.Segment;
import com.intellij.openapi.util.TextRange;
import com.intellij.psi.PsiAnchor;
import com.intellij.psi.PsiElement;
import com.intellij.psi.PsiFile;
import com.intellij.psi.impl.source.PsiFileWithStubSupport;
import com.intellij.psi.stubs.IStubElementType;
import com.intellij.psi.tree.IElementType;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

class AnchorElementInfo extends SelfElementInfo {
  private volatile long myStubElementTypeAndId; // stubId in the lower 32 bits; stubElementTypeIndex in the high 32 bits packed together for atomicity

  AnchorElementInfo(@NotNull PsiElement anchor, @NotNull PsiFile containingFile, Identikit.ByAnchor identikit) {
    super(ProperTextRange.create(anchor.getTextRange()), identikit, containingFile, false);
    myStubElementTypeAndId = pack(-1, null);
  }
  // will restore by stub index until file tree get loaded
  AnchorElementInfo(@NotNull PsiElement anchor,
                    @NotNull PsiFileWithStubSupport containingFile,
                    int stubId,
                    @NotNull IStubElementType stubElementType) {
    super(null,
          Identikit.fromTypes(anchor.getClass(), stubElementType, LanguageUtil.getRootLanguage(containingFile)),
          containingFile, false);
    myStubElementTypeAndId = pack(stubId, stubElementType);
    assert !(anchor instanceof PsiFile) : "FileElementInfo must be used for file: "+anchor;
  }

  private static long pack(int stubId, IStubElementType stubElementType) {
    short index = stubElementType == null ? 0 : stubElementType.getIndex();
    assert index >= 0 : "Unregistered token types not allowed here: " + stubElementType;
    return ((long)stubId) | ((long)index << 32);
  }

  private int getStubId() {
    return (int)myStubElementTypeAndId;
  }

  @Override
  @Nullable
  public PsiElement restoreElement(@NotNull SmartPointerManagerImpl manager) {
    long typeAndId = myStubElementTypeAndId;
    int stubId = (int)typeAndId;
    if (stubId != -1) {
      PsiFile file = restoreFile(manager);
      if (!(file instanceof PsiFileWithStubSupport)) return null;
      short index = (short)(typeAndId >> 32);
      IStubElementType stubElementType = (IStubElementType)IElementType.find(index);
      return PsiAnchor.restoreFromStubIndex((PsiFileWithStubSupport)file, stubId, stubElementType, false);
    }

    return super.restoreElement(manager);
  }

  @Override
  public boolean pointsToTheSameElementAs(@NotNull final SmartPointerElementInfo other,
                                          @NotNull SmartPointerManagerImpl manager) {
    if (other instanceof AnchorElementInfo) {
      if (!getVirtualFile().equals(other.getVirtualFile())) return false;

      long packed1 = myStubElementTypeAndId;
      long packed2 = ((AnchorElementInfo)other).myStubElementTypeAndId;

      if (packed1 != -1 && packed2 != -1) {
        return packed1 == packed2;
      }
      if (packed1 != -1 || packed2 != -1) {
        return ReadAction.compute(() -> Comparing.equal(restoreElement(manager), other.restoreElement(manager)));
      }
    }
    return super.pointsToTheSameElementAs(other, manager);
  }

  @Override
  public void fastenBelt(@NotNull SmartPointerManagerImpl manager) {
    if (getStubId() != -1) {
      switchToTree(manager);
    }
    super.fastenBelt(manager);
  }

  private void switchToTree(SmartPointerManagerImpl manager) {
    PsiElement element = restoreElement(manager);
    SmartPointerTracker tracker = manager.getTracker(getVirtualFile());
    if (element != null && tracker != null) {
      tracker.switchStubToAst(this, element);
    }
  }

  void switchToTreeRange(@NotNull PsiElement element) {
    switchToAnchor(element);
    myStubElementTypeAndId = pack(-1, null);
  }

  @Override
  public Segment getRange(@NotNull SmartPointerManagerImpl manager) {
    if (getStubId() != -1) {
      switchToTree(manager);
    }
    return super.getRange(manager);
  }

  @Nullable
  @Override
  public TextRange getPsiRange(@NotNull SmartPointerManagerImpl manager) {
    if (getStubId() != -1) {
      switchToTree(manager);
    }
    return super.getPsiRange(manager);
  }

  @Override
  public String toString() {
    return super.toString() + ",stubId=" + getStubId();
  }
}

package com.iampfac.bleach.test.rest.post;

import java.util.Arrays;
import java.util.List;

import org.hamcrest.Matchers;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit4.SpringJUnit4ClassRunner;
import org.springframework.test.context.web.WebAppConfiguration;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultMatcher;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import org.springframework.test.web.servlet.result.MockMvcResultMatchers;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

import com.iampfac.bleach.core.blog.Blog;
import com.iampfac.bleach.core.post.Post;
import com.iampfac.bleach.rest.post.PostController;
import com.iampfac.bleach.test.core.post.PostUnitTest;

@RunWith(SpringJUnit4ClassRunner.class)
@ContextConfiguration(classes = {
	PostControllerUnitTest.TestContext.class
})
@WebAppConfiguration
public class PostControllerUnitTest {

	@Configuration
	protected static class TestContext {

		@Bean
		public Blog blog() {
			return Mockito.mock(Blog.class);
		}

		@Bean
		public PostController postController(Blog blog) {
			return new PostController(blog);
		}

	}

	private MockMvc mvc;

	@Autowired
	private Blog blog;

	@Autowired
	private PostController controller;

	@Before
	public void setup() {
		mvc = MockMvcBuilders.standaloneSetup(controller).build();
	}

	@Test
	public void getPostsReturnsHttpOk() throws Exception {
		final MockHttpServletRequestBuilder request = MockMvcRequestBuilders.get("/posts");
		final ResultMatcher statusToBeOk = MockMvcResultMatchers.status()
				.isOk();

		mvc.perform(request).andExpect(statusToBeOk);
	}

	@Test
	public void getPostsReturnsJsonContent() throws Exception {
		final MockHttpServletRequestBuilder request = MockMvcRequestBuilders.get("/posts");
		final ResultMatcher contentToBeJson = MockMvcResultMatchers.content()
				.contentType("application/json;charset=UTF-8");

		mvc.perform(request).andExpect(contentToBeJson);
	}

	@Test
	public void getPostsReturnsArrayWithAllPostsData() throws Exception {
		final Post post1 = PostUnitTest.post();
		final Post post2 = PostUnitTest.post();
		final Post post3 = PostUnitTest.post();

		final int post1id = post1.getId().intValue();
		final int post2id = post2.getId().intValue();
		final int post3id = post3.getId().intValue();

		final List<Post> posts = Arrays.asList(post1, post2, post3);

		Mockito.when(blog.getPosts()).thenReturn(posts);

		final MockHttpServletRequestBuilder request = MockMvcRequestBuilders.get("/posts");
		final ResultMatcher contentToBeAnArray = MockMvcResultMatchers.jsonPath("$")
				.isArray();
		final ResultMatcher contentToHaveThreeItems = MockMvcResultMatchers.jsonPath("$", Matchers.hasSize(posts.size()));

		final ResultMatcher contentFirstToBePostOne = MockMvcResultMatchers.jsonPath("$[0].id")
				.value(post1id);
		final ResultMatcher contentSecondToBePostTwo = MockMvcResultMatchers.jsonPath("$[1].id")
				.value(post2id);
		final ResultMatcher contentThirdToBePostThree = MockMvcResultMatchers.jsonPath("$[2].id")
				.value(post3id);

		mvc.perform(request)
				.andExpect(contentToBeAnArray)
				.andExpect(contentToHaveThreeItems)
				.andExpect(contentFirstToBePostOne)
				.andExpect(contentSecondToBePostTwo)
				.andExpect(contentThirdToBePostThree);
	}
}

