package com.webank.runtime.boot;

import com.webank.runtime.configuration.AccessConfiguration;
import com.webank.runtime.configuration.ConfigurationWraper;
import com.webank.runtime.configuration.ProxyConfiguration;
import com.webank.runtime.constants.ProxyConstants;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.File;

public class ProxyStartup {

    public static Logger logger = LoggerFactory.getLogger(ProxyStartup.class);

    public static void main(String[] args) throws Exception {
        try{
            ConfigurationWraper configurationWraper =
                    new ConfigurationWraper(ProxyConstants.PROXY_CONF_HOME
                            + File.separator
                            + ProxyConstants.PROXY_CONF_FILE, false);
            ProxyConfiguration proxyConfiguration = new ProxyConfiguration(configurationWraper);
            proxyConfiguration.init();
            AccessConfiguration accessConfiguration = new AccessConfiguration(configurationWraper);
            accessConfiguration.init();
            ProxyServer server = new ProxyServer(proxyConfiguration, accessConfiguration);
            server.init();
            server.start();
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                try {
                    logger.info("proxy shutting down hook begin...");
                    long start = System.currentTimeMillis();
                    server.shutdown();
                    long end = System.currentTimeMillis();
                    logger.info("proxy shutdown cost {}ms", end - start);
                } catch (Exception e) {
                    logger.error("exception when shutdown...", e);
                }
            }));
        }catch (Throwable e){
            logger.error("Proxy start fail.", e);
            e.printStackTrace();
        }

    }
}

package parsley.commands.core;

import parsley.commands.Command;
import parsley.lexing.*;
import parsley.model.*;
import parsley.runtime.*;
import parsley.values.*;
import java.util.*;

public class CallCommand extends Command {
	protected String name;
	protected Stack parameters;
	protected Hashtable arguments;

	public CallCommand(Tokens tokens) {
		this();
		initWithTokens(tokens);
	}

	public CallCommand() {
		parameters = new Stack();
		arguments = new Hashtable();
	}

	public Command initWithTokens(Tokens tokens) {
		parameters.clear();
		arguments.clear();
		setName(tokens.nextToken());
		setParameters(tokens);
		return this;
	}

	protected void setName(String token) throws IllegalArgumentException {
		if (isName(token)) {
			name = new String(token);
		} else {
			throw new IllegalArgumentException(token);
		}
	}

	protected void setParameters(Tokens tokens) {
		String previous = null, current = null;
		while (tokens.hasMoreTokens()) {
			current = tokens.nextToken();
			if (isParameter(current)) {
				setParameter(current);
			} else if (isParameter(previous)) {
				setArgument(previous, current);
			} else {
				throw new IllegalArgumentException(current);
			}
			previous = current;
		}
	}

	protected void setParameter(String token) throws IllegalArgumentException {
		if (isParameter(token)) {
			parameters.push(new Parameter(token));
		} else {
			throw new IllegalArgumentException(token);
		}
	}

	protected void setArgument(String parameter, String argument) {
		arguments.put(new Parameter(parameter), argument);
	}

	private Value valueForToken(Context context, String token) {
		if (isSymbol(token)) {
			return context.localValueForSymbol(symbolForToken(token));
		} else if (isNumber(token)) {
			return numberValueForToken(token);
		} else if (isString(token)) {
			return stringValueForToken(token);
		} else if (isBoolean(token)) {
			return booleanValueForToken(token);
		} else {
			throw new IllegalStateException(token);
		}
	}

	public Signature signature() {
		return new Signature(name, parameters);
	}

	public void execute(Context context) throws Exception {
		Enumeration enumeration = arguments.keys();
		Table table = Table.newTable();

		while (enumeration.hasMoreElements()) {
			Parameter parameter = (Parameter) enumeration.nextElement();
			table.save(symbolForParameter(parameter), valueForToken(context, (String) arguments.get(parameter))); 
		}

		context.onProcedureCall(signature(), table);
	}
}

package wang.leal.ahel.http.api.annotation;

import static java.lang.annotation.ElementType.METHOD;
import static java.lang.annotation.RetentionPolicy.RUNTIME;

import java.lang.annotation.Documented;
import java.lang.annotation.Retention;
import java.lang.annotation.Target;

/**
 * Adds headers literally supplied in the {@code value}.
 *
 * <pre><code>
 * &#64;Headers("Cache-Control: max-age=640000")
 * &#64;GET
 * ...
 *
 * &#64;Headers({
 *   "X-Foo: Bar",
 *   "X-Ping: Pong"
 * })
 * &#64;GET
 * ...
 * </code></pre>
 *
 * <strong>Note:</strong> Headers do not overwrite each other. All headers with the same name will
 * be included in the request.
 *
 * @see Header
 * @see HeaderMap
 */
@Documented
@Target(METHOD)
@Retention(RUNTIME)
public @interface Headers {
  String[] value();
}

package com.unascribed.fabrication.mixin.c_tweaks.alt_absorption_sound;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

import com.unascribed.fabrication.interfaces.DidJustAbsorp;
import com.unascribed.fabrication.support.EligibleIf;
import com.unascribed.fabrication.support.MixinConfigPlugin;

import net.minecraft.entity.Entity;
import net.minecraft.server.world.ServerWorld;

@Mixin(ServerWorld.class)
@EligibleIf(configEnabled="*.alt_absorption_sound")
public class MixinServerWorld {

	@Inject(at=@At("HEAD"), method="sendEntityStatus(Lnet/minecraft/entity/Entity;B)V", cancellable=true)
	public void sendEntityStatus(Entity entity, byte status, CallbackInfo ci) {
		if (MixinConfigPlugin.isEnabled("*.alt_absorption_sound")) {
			if (status == 2 || status == 33 || status == 36 || status == 37 || status == 44) {
				if (entity instanceof DidJustAbsorp && ((DidJustAbsorp)entity).fabrication$didJustAbsorp()) {
					ci.cancel();
				}
			}
		}
	}

}

