import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectWriter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.Serializable;


public class OofRequest implements Serializable {

    private static final long serialVersionUID = -1541132882892163132L;
    private static final Logger logger = LoggerFactory.getLogger(OofRequest.class);


    @JsonProperty("requestInfo")
    private RequestInfo requestInformation;

    @JsonProperty("serviceInfo")
    private ServiceInfo serviceInformation;

    @JsonProperty("placementInfo")
    private PlacementInfo placementInformation;

    @JsonProperty("licenseInfo")
    private LicenseInfo licenseInformation;


    public RequestInfo getRequestInformation() {
        return requestInformation;
    }

    public void setRequestInformation(RequestInfo requestInformation) {
        this.requestInformation = requestInformation;
    }

    public ServiceInfo getServiceInformation() {
        return serviceInformation;
    }

    public void setServiceInformation(ServiceInfo serviceInformation) {
        this.serviceInformation = serviceInformation;
    }

    public PlacementInfo getPlacementInformation() {
        return placementInformation;
    }

    public void setPlacementInformation(PlacementInfo placementInformation) {
        this.placementInformation = placementInformation;
    }

    public LicenseInfo getLicenseInformation() {
        return licenseInformation;
    }

    public void setLicenseInformation(LicenseInfo licenseInformation) {
        this.licenseInformation = licenseInformation;
    }


    @JsonInclude(Include.NON_NULL)
    public String toJsonString() {
        String json = "";
        ObjectMapper mapper = new ObjectMapper();
        mapper.setSerializationInclusion(Include.NON_NULL);
        ObjectWriter ow = mapper.writer().withDefaultPrettyPrinter();
        try {
            json = ow.writeValueAsString(this);
        } catch (Exception e) {
            logger.error("Unable to convert oofRequest to string", e);
        }
        return json.replaceAll("\\\\", "");
    }


}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import javax.swing.JOptionPane;

	/**
	 * This class has utility methods used by the Blockchain logic.
	 */

public class BlockchainUtil {
	/**
	* This method produces an SHA-256 hash of the string input.
	* @param sOriginal
	* @return
	*/
		public static synchronized String generateHash(String sOriginal){
			try {
				MessageDigest digest = MessageDigest.getInstance("SHA-256");
				byte[] btEncodedhash = digest.digest(sOriginal.getBytes(StandardCharsets.UTF_8));
				StringBuilder sb = new StringBuilder();
				for (int i = 0; i < btEncodedhash.length; i++) {
					sb.append(Integer.toString((btEncodedhash[i] & 0xff) + 0x100, 16).substring(1));
				}

				return sb.toString();

			} catch (Exception ex) {

				System.out.println("Error generating hash: " + ex.getMessage());

				return null;

			}

		}
/**
* This method can either use Scanner or JOptionPane approaches to get user input.
* @param sQuestion
* @return
*/

	public String promptUser(String sQuestion){
        String sAnswer = JOptionPane.showInputDialog(sQuestion);
        return sAnswer;
    }

/**
* This method allows user to avoid extra typing and efficient code, especially if this class variable is one letter
* such as u, thus:
* u.p("hello");
* @param sMessage
*/

	public void p(String sMessage){

		System.out.println(sMessage);

	}

	/**
	 * This is used by any thread that needs to sleep to allow updating of static variables or to alleviate
	 * CPU usage on continuous looping.
	 * @param lMillis
	 */

	public void sleep(long lMillis){

		try{
			Thread.sleep(lMillis);
		}
		catch(Exception ex){

			// do nothing.

		}

	}

}

