package com.github.tomakehurst.wiremock.stubbing;

import com.github.tomakehurst.wiremock.common.LocalNotifier;
import com.github.tomakehurst.wiremock.common.Notifier;
import com.github.tomakehurst.wiremock.http.Request;
import com.github.tomakehurst.wiremock.http.RequestMethod;
import com.github.tomakehurst.wiremock.matching.RequestPattern;
import com.github.tomakehurst.wiremock.matching.ValuePattern;
import com.google.common.collect.ImmutableMap;
import org.jmock.Expectations;
import org.jmock.Mockery;
import org.jmock.integration.junit4.JMock;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;

import java.util.Map;

import static com.github.tomakehurst.wiremock.http.RequestMethod.*;
import static com.github.tomakehurst.wiremock.matching.ValuePattern.equalTo;
import static com.github.tomakehurst.wiremock.testsupport.MockRequestBuilder.aRequest;
import static com.google.common.collect.Maps.newHashMap;
import static java.util.Arrays.asList;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

@RunWith(JMock.class)
public class RequestPatternTest {

	private Mockery context;
	private Map<String, ValuePattern> headerPatterns;
	private Notifier notifier;

	@Before
	public void init() {
		context = new Mockery();
		headerPatterns = newHashMap();
		notifier = context.mock(Notifier.class);
		LocalNotifier.set(notifier);
	}

	@After
	public void cleanUp() {
	    LocalNotifier.set(null);
	}

	@Test
	public void matchesOnExactMethodAndUrl() {
		RequestPattern requestPattern = new RequestPattern(RequestMethod.POST, "/some/resource/path");
		Request request = aRequest(context)
			.withUrl("/some/resource/path")
			.withMethod(POST)
			.build();
		assertTrue(requestPattern.isMatchedBy(request));
	}

	@Test
	public void shouldNotMatchWhenMethodIsCorrectButUrlIsWrong() {
		RequestPattern requestPattern = new RequestPattern(RequestMethod.POST, "/some/resource/path");
		Request request = aRequest(context)
			.withUrl("/wrong/path")
			.withMethod(POST)
			.build();
		assertFalse(requestPattern.isMatchedBy(request));
	}

	@Test
	public void shouldMatchWhenSpecifiedHeadersArePresent() {
		headerPatterns.put("Accept", equalTo("text/plain"));
		headerPatterns.put("Content-Type", equalTo("application/json"));
		RequestPattern requestPattern = new RequestPattern(RequestMethod.GET, "/header/dependent/resource", headerPatterns);

		Request request = aRequest(context)
			.withUrl("/header/dependent/resource")
			.withMethod(GET)
			.withHeader("Accept", "text/plain")
			.withHeader("Content-Type", "application/json")
			.build();

		assertTrue(requestPattern.isMatchedBy(request));
	}

	@Test
	public void shouldNotMatchWhenASpecifiedHeaderIsAbsent() {
	    ignoringNotifier();

		headerPatterns.put("Accept", equalTo("text/plain"));
		headerPatterns.put("Content-Type", equalTo("application/json"));
		RequestPattern requestPattern = new RequestPattern(RequestMethod.GET, "/header/dependent/resource", headerPatterns);

		Request request = aRequest(context)
			.withUrl("/header/dependent/resource")
			.withMethod(GET)
			.withHeader("Accept", "text/plain")
			.build();

		assertFalse(requestPattern.isMatchedBy(request));
	}

	@Test
	public void shouldNotMatchWhenASpecifiedHeaderHasAnIncorrectValue() {
	    ignoringNotifier();

		headerPatterns.put("Accept", equalTo("text/plain"));
		headerPatterns.put("Content-Type", equalTo("application/json"));
		RequestPattern requestPattern = new RequestPattern(RequestMethod.GET, "/header/dependent/resource", headerPatterns);

		Request request = aRequest(context)
			.withUrl("/header/dependent/resource")
			.withMethod(GET)
			.withHeader("Accept", "text/plain")
			.withHeader("Content-Type", "text/xml")
			.build();

		assertFalse(requestPattern.isMatchedBy(request));
	}

    @Test
    public void shouldMatchHeaderWithMultipleValues() {
        ignoringNotifier();

        RequestPattern requestPattern1 = new RequestPattern(RequestMethod.GET,
                "/multi/header",
                ImmutableMap.of("X-Multi", equalTo("one")));
        RequestPattern requestPattern2 = new RequestPattern(RequestMethod.GET,
                "/multi/header",
                ImmutableMap.of("X-Multi", equalTo("two")));

        Request request = aRequest(context)
                .withUrl("/multi/header")
                .withMethod(GET)
                .withHeader("X-Multi", "one")
                .withHeader("X-Multi", "two")
                .build();

        assertTrue("Request should match request pattern with header X-Multi:one", requestPattern1.isMatchedBy(request));
        assertTrue("Request should match request pattern with header X-Multi:two", requestPattern2.isMatchedBy(request));
    }

	@Test
	public void shouldMatchUrlPatternWithRegexes() {
		RequestPattern requestPattern = new RequestPattern(RequestMethod.GET);
		requestPattern.setUrlPattern("/resource/(.*?)/subresource");

		Request request = aRequest(context)
			.withUrl("/resource/1234-abcd/subresource")
			.withMethod(GET)
			.build();

		assertTrue(requestPattern.isMatchedBy(request));
	}

	@Test
	public void shouldNotMatchUrlWhenUsingRegexButCandidateIsNotMatch() {
		RequestPattern requestPattern = new RequestPattern(RequestMethod.GET);
		requestPattern.setUrlPattern("/resource/([A-Z]+?)/subresource");

		Request request = aRequest(context)
			.withUrl("/resource/12340987/subresource")
			.withMethod(GET)
			.build();

		assertFalse(requestPattern.isMatchedBy(request));
	}

	@Test(expected=IllegalStateException.class)
	public void shouldNotPermitBothUrlAndUrlPattern() {
		RequestPattern requestPattern = new RequestPattern();
		requestPattern.setUrlPattern("/(.*?");
		requestPattern.setUrl("/some/url");

		requestPattern.isMatchedBy(aRequest(context).build());
	}

	private static final String XML_SAMPLE =
		"<document>							\n" +
		"	<important>Value</important>	\n" +
		"</document>		  				";

	@Test
	public void shouldMatchOnBodyPattern() {
		RequestPattern requestPattern = new RequestPattern(GET, "/with/body");
		requestPattern.setBodyPatterns(asList(ValuePattern.matches(".*<important>Value</important>.*")));

		Request request = aRequest(context)
			.withUrl("/with/body")
			.withMethod(GET)
			.withBody(XML_SAMPLE)
			.build();

		assertTrue(requestPattern.isMatchedBy(request));
	}

	@Test
	public void shouldNotMatchWhenBodyDoesNotMatchPattern() {
        ignoringNotifier();

        RequestPattern requestPattern = new RequestPattern(GET, "/with/body");
		requestPattern.setBodyPatterns(asList(ValuePattern.matches(".*<important>Value</important>.*")));

		Request request = aRequest(context)
			.withUrl("/with/body")
			.withMethod(GET)
			.withBody("<important>Wrong value</important>")
			.build();

		assertFalse(requestPattern.isMatchedBy(request));
	}

    @Test
	public void shouldMatchAnyMethod() {
		RequestPattern requestPattern = new RequestPattern(ANY, "/any/method");

		for (RequestMethod method: RequestMethod.values()) {
			context = new Mockery();
			Request request = aRequest(context)
				.withUrl("/any/method")
				.withMethod(method)
				.build();
			assertTrue("Method in request pattern is ANY so any method should match", requestPattern.isMatchedBy(request));
		}
	}

    @Test
    public void supportsMatchingOnAbsentHeader() {
        ignoringNotifier();

        RequestPattern requestPattern = new RequestPattern(GET, "/without/header");
        requestPattern.addHeader("X-My-Header", ValuePattern.absent());
        Request request = aRequest(context)
                .withUrl("/without/header")
                .withMethod(GET)
                .withHeader("X-Another-Header", "value")
                .build();

        assertTrue("Request is not a match for the request pattern", requestPattern.isMatchedBy(request));
    }

    @Test
    public void shouldFailMatchWhenRequiredAbsentHeaderIsPresent() {
        ignoringNotifier();

        RequestPattern requestPattern = new RequestPattern(GET, "/without/header/fail");
        requestPattern.addHeader("X-My-Header", ValuePattern.absent());
        Request request = aRequest(context)
                .withUrl("/without/header/fail")
                .withMethod(GET)
                .withHeader("X-My-Header", "value")
                .build();

        assertFalse("Request is a match for the request pattern and should not be", requestPattern.isMatchedBy(request));
    }

    @Test
	public void shouldLogMessageIndicatingFailedMethodMatch() {
		context.checking(new Expectations() {{
			one(notifier).info("URL /for/logging is match, but method GET is not");
		}});

		RequestPattern requestPattern = new RequestPattern(POST, "/for/logging");

		Request request = aRequest(context)
			.withUrl("/for/logging")
			.withMethod(GET)
			.build();

		requestPattern.isMatchedBy(request);
	}

	@Test
	public void shouldLogMessageIndicatingFailedHeaderMatch() {
		context.checking(new Expectations() {{
			one(notifier).info("URL /for/logging is match, but header Content-Type is not. For a match, value should equal text/xml");
		}});

		RequestPattern requestPattern = new RequestPattern(POST, "/for/logging");
		ValuePattern headerPattern = new ValuePattern();
		headerPattern.setEqualTo("text/xml");
		requestPattern.addHeader("Content-Type", headerPattern);

		Request request = aRequest(context)
			.withUrl("/for/logging")
			.withMethod(POST)
			.withHeader("Content-Type", "text/plain")
			.build();

		requestPattern.isMatchedBy(request);
	}

	@Test
	public void shouldLogMessageIndicatingFailedBodyMatch() {
		context.checking(new Expectations() {{
			one(notifier).info("URL /for/logging is match, but body is not: Actual Content");
		}});

		RequestPattern requestPattern = new RequestPattern(POST, "/for/logging");
		requestPattern.setBodyPatterns(asList(ValuePattern.matches("Expected content")));

		Request request = aRequest(context)
			.withUrl("/for/logging")
			.withMethod(POST)
			.withBody("Actual Content")
			.build();

		requestPattern.isMatchedBy(request);
	}

    private void ignoringNotifier() {
        context.checking(new Expectations() {{
            ignoring(notifier);
        }});
    }

}

package com.corochann.androidtvapptutorial.data;

import android.content.AsyncTaskLoader;
import android.content.Context;
import android.util.Log;

import com.corochann.androidtvapptutorial.model.Movie;

import org.json.JSONException;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;

/**
 * Loader class which prepares Movie class data
 */
public class VideoItemLoader extends AsyncTaskLoader<LinkedHashMap<String, List<Movie>>> {

    private static final String TAG = VideoItemLoader.class.getSimpleName();
    LinkedHashMap<String, List<Movie>> mData;

    public VideoItemLoader(Context context) {
        super(context);
    }

    @Override
    public LinkedHashMap<String, List<Movie>> loadInBackground() {
        Log.d(TAG, "loadInBackground");

        /*
         * Executed in background thread.
         * Prepare data here, it may take long time (Database access, URL connection, etc).
         * return value is used in onLoadFinished() method in Activity/Fragment's LoaderCallbacks.
         */
        //LinkedHashMap<String, List<Movie>> videoLists = prepareData();
        LinkedHashMap<String, List<Movie>> videoLists = null;
        try {
            videoLists = VideoProvider.buildMedia(getContext());
        } catch (JSONException e) {
            Log.e(TAG, "buildMedia failed", e);
            //cancelLoad();
        }
        return videoLists;
    }

    @Override
    public void deliverResult(LinkedHashMap<String, List<Movie>> data) {
        Log.d(TAG, "deliverResult");

        LinkedHashMap<String, List<Movie>> oldData = mData;
        mData = data;

        if(isStarted()){
            Log.d(TAG, "isStarted true");
            super.deliverResult(data);
        }

        if(oldData != null && oldData != data) {
            releaseResources(oldData);
        }
    }

    private void releaseResources(LinkedHashMap<String, List<Movie>> data) {
        Log.d(TAG, "releaseResources");
        // For a simple List, there is nothing to do. For something like a Cursor, we
        // would close it in this method. All resources associated with the Loader
        // should be released here.
        data = null;
    }

    @Override
    protected void onStartLoading() {
        Log.d(TAG, "onStartLoading");
        if (mData != null) {
            Log.d(TAG, "mData remaining");
            deliverResult(mData);
        } else {
            Log.d(TAG, "mData is null, forceLoad");
            forceLoad();
        }
        //super.onStartLoading();

    }

    @Override
    protected void onStopLoading() {
        Log.d(TAG, "onStopLoading");
        //super.onStopLoading();
        cancelLoad();
    }

    @Override
    protected void onReset() {
        Log.d(TAG, "onReset");
        super.onReset();
    }

    @Override
    public void onCanceled(LinkedHashMap<String, List<Movie>> data) {
        Log.d(TAG, "onCanceled");
        super.onCanceled(data);
    }

    @Override
    protected boolean onCancelLoad() {
        return super.onCancelLoad();
    }

    private LinkedHashMap<String, List<Movie>> prepareData() {
        LinkedHashMap<String, List<Movie>> videoLists = new LinkedHashMap<>();
        List<Movie> videoList = MovieProvider.getMovieItems();
        videoLists.put("category 1", videoList);
        videoLists.put("category 2", videoList);
        videoLists.put("category 3", videoList);
        return videoLists;
    }
}

package de.arthurpicht.meta.cli.MetaDir;

import de.arthurpicht.cli.option.OptionParserResult;
import de.arthurpicht.meta.Const;
import de.arthurpicht.meta.cli.Meta;
import de.arthurpicht.meta.exception.MetaRuntimeException;
import de.arthurpicht.meta.helper.FilesHelper;
import de.arthurpicht.utils.core.strings.Strings;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class MetaDirBuilder {

    public static MetaDir obtain(OptionParserResult optionParserResultGlobal) {

        MetaDir metaDir = obtainMetaDir(optionParserResultGlobal);
        assertExistenceOfMetaDir(metaDir);
        assertContainsMetaConf(metaDir);
        return metaDir;
    }

    private static MetaDir obtainMetaDir(OptionParserResult optionParserResultGlobal) {
        String metaDirString;
        MetaDirSpecifier metaDirSpecifier;
        if (optionParserResultGlobal.hasOption(Meta.OPTION_META_DIR)) {
            metaDirString = optionParserResultGlobal.getValue(Meta.OPTION_META_DIR);
            metaDirSpecifier = MetaDirSpecifier.CLI;
        } else if (Strings.isSpecified(System.getenv(Const.META_DIR__ENV_VAR))) {
            metaDirString = System.getenv(Const.META_DIR__ENV_VAR);
            metaDirSpecifier = MetaDirSpecifier.ENV_VAR;
        } else {
            metaDirString = FilesHelper.getWorkingDir().toString();
            metaDirSpecifier = MetaDirSpecifier.WORKING_DIR;
        }

        Path metaDir = Paths.get(metaDirString).normalize();
        return new MetaDir(metaDir, metaDirSpecifier);
    }

    private static void assertExistenceOfMetaDir(MetaDir metaDir) {
        if (!Files.exists(metaDir.asPath()) || !Files.isDirectory(metaDir.asPath()))
            throw new MetaRuntimeException("Meta directory as specified by " + metaDir.getSpecifier().getText() + " not found: [" + metaDir.asPath() + "].");
    }

    private static void assertContainsMetaConf(MetaDir metaDir) {
        Path metaConf = metaDir.asPath().resolve(Const.META_CONF__FILE_NAME);
        if (!Files.exists(metaConf) || !Files.isRegularFile(metaConf))
            throw new MetaRuntimeException("No " + Const.META_CONF__FILE_NAME + " [" + metaConf.toAbsolutePath() + "] found.");
    }

}

