import texas.hold.em.domain.Deck;
import texas.hold.em.domain.Hand;
import texas.hold.em.domain.rule.Rule;

public class BestHandProcessor {

  private final List<Rule> rules = new ArrayList<>();

  public BestHandProcessor(List<Rule> rules) {
    this.rules.clear();
    this.rules.addAll(rules);
  }

  public Hand pickBestHand(Deck deck) {
    for (Rule rule : rules) {
      Hand hand = rule.pick(deck);
      if (hand != null)
        return hand;
    }
    return null;
  }
}

package com.simibubi.create.foundation.command;

import com.mojang.brigadier.Command;
import com.mojang.brigadier.builder.ArgumentBuilder;
import com.simibubi.create.foundation.networking.AllPackets;

import net.minecraft.command.CommandSource;
import net.minecraft.command.Commands;
import net.minecraft.entity.player.ServerPlayerEntity;
import net.minecraftforge.fml.network.PacketDistributor;

public class FabulousWarningCommand {

	public static ArgumentBuilder<CommandSource, ?> register() {
		return Commands.literal("dismissFabulousWarning")
			.requires(AllCommands.sourceIsPlayer)
			.executes(ctx -> {
				ServerPlayerEntity player = ctx.getSource()
					.asPlayer();

				AllPackets.channel.send(PacketDistributor.PLAYER.with(() -> player),
					new ConfigureConfigPacket(ConfigureConfigPacket.Actions.fabulousWarning.name(), ""));

				return Command.SINGLE_SUCCESS;
			});

	}
}

