package androidx.camera.camera2.impl.compat.params;

import static com.google.common.truth.Truth.assertThat;

import android.graphics.ImageFormat;
import android.hardware.camera2.params.InputConfiguration;
import android.os.Build;

import androidx.test.filters.SmallTest;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.internal.DoNotInstrument;

@SmallTest
@RunWith(RobolectricTestRunner.class)
@DoNotInstrument
@Config(minSdk = Build.VERSION_CODES.LOLLIPOP)
public final class InputConfigurationCompatTest {

    private static final int WIDTH = 1024;
    private static final int HEIGHT = 768;
    private static final int FORMAT = ImageFormat.YUV_420_888;

    @Test
    public void canCreateInputConfigurationCompat() {
        InputConfigurationCompat compat = new InputConfigurationCompat(WIDTH, HEIGHT, FORMAT);

        assertThat(compat.getWidth()).isEqualTo(WIDTH);
        assertThat(compat.getHeight()).isEqualTo(HEIGHT);
        assertThat(compat.getFormat()).isEqualTo(FORMAT);
    }

    @Test
    @Config(minSdk = Build.VERSION_CODES.M)
    public void canWrapInputConfiguration() {
        InputConfiguration inputConfig = new InputConfiguration(WIDTH, HEIGHT, FORMAT);
        InputConfigurationCompat compat = InputConfigurationCompat.wrap(inputConfig);

        assertThat(compat).isNotNull();
        assertThat(compat.unwrap()).isSameInstanceAs(inputConfig);
    }

    @Test
    public void canCompare() {
        InputConfigurationCompat compat1 = new InputConfigurationCompat(WIDTH, HEIGHT, FORMAT);
        InputConfigurationCompat compat2 = new InputConfigurationCompat(WIDTH, HEIGHT, FORMAT);

        // Swap width and height
        // noinspection SuspiciousNameCombination
        InputConfigurationCompat compat3 = new InputConfigurationCompat(HEIGHT, WIDTH, FORMAT);

        assertThat(compat1).isEqualTo(compat1);
        assertThat(compat1).isEqualTo(compat2);
        assertThat(compat1).isNotEqualTo(compat3);

        assertThat(compat1.hashCode()).isEqualTo(compat1.hashCode());
        assertThat(compat1.hashCode()).isEqualTo(compat2.hashCode());
        assertThat(compat1.hashCode()).isNotEqualTo(compat3.hashCode());
    }

    @Test
    @Config(minSdk = Build.VERSION_CODES.M)
    public void baseImplHashCodeMatchesFramework() {
        InputConfigurationCompat.InputConfigurationCompatBaseImpl baseImpl =
                new InputConfigurationCompat.InputConfigurationCompatBaseImpl(WIDTH, HEIGHT,
                        FORMAT);

        InputConfiguration config = new InputConfiguration(WIDTH, HEIGHT, FORMAT);

        assertThat(baseImpl.hashCode()).isEqualTo(config.hashCode());
    }

    @Test
    @Config(minSdk = Build.VERSION_CODES.M)
    public void baseImplToStringMatchesFramework() {
        InputConfigurationCompat.InputConfigurationCompatBaseImpl baseImpl =
                new InputConfigurationCompat.InputConfigurationCompatBaseImpl(WIDTH, HEIGHT,
                        FORMAT);

        InputConfiguration config = new InputConfiguration(WIDTH, HEIGHT, FORMAT);

        assertThat(baseImpl.toString()).isEqualTo(config.toString());
    }
}

package ok;

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.net.HttpURLConnection;
import java.net.URL;

import java.util.HashMap;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import ok.Controllers.SecondaryController;

public class AccountsHandler {
	
	private HashMap<String, Account> accs = new HashMap<>();
	private HashMap<Integer, Account> accsByType = new HashMap<>();
 	private boolean offline = false;
	private boolean initialized = false;
	
	public void addAccount(Account acc) throws IOException {
		this.accs.put(acc.getIBAN(), acc);
		this.accsByType.put(acc.getType(), acc);
		if(this.isInitialized() == true) {
			this.updateRemote(acc);
		}
	}
	
	public int withdraw(double sum, int accType) {
		try {
			if(sum <= 0 || (sum % 10) != 0) {
				return -1;
			}
			if(this.getAccountByType(accType).getBalance() < sum) {
				return 0;
			}
			this.getAccountByType(accType).setBalance(this.getAccountByType(accType).getBalance() - sum);
			this.updateRemote(this.getAccountByType(accType));
			System.out.println("Withdrew " + sum + ". New balance: " + this.getAccountByType(accType).getBalance());
			return 1;
		}catch(java.lang.NumberFormatException | IOException e) {
			System.out.println("Something went wrong...");
		}
		return -1;
	}
	
	public int deposit(double sum, int accType) {
		try {
			if(sum <= 0 || (sum % 10) != 0) {
				return -1;
			}
			if(sum > 900000) {
				return 0;
			}
			this.getAccountByType(accType).setBalance(this.getAccountByType(accType).getBalance() + sum);
			this.updateRemote(this.getAccountByType(accType));
			System.out.println("Deposited " + sum + ". New balance: " + this.getAccountByType(accType).getBalance());
			return 1;
		}catch(java.lang.NumberFormatException | IOException e) {
			System.out.println("Something went wrong...");
		}
		return -1;
	}
	
	
	public int sendMoney(double sum, String IBANSender, String IBAN) throws IOException {
		Account sender = this.getAccountByIBAN(IBANSender);
		Account receiver = this.getRemoteAcc(IBAN);
		if(this.withdraw(sum, sender.getType()) == 1) {
			/* Check to see if account is ours, so that local data can be updated. */
			if(this.getAccounts().containsKey(receiver.getIBAN())) {
				this.getAccountByIBAN(receiver.getIBAN()).setBalance(receiver.getBalance() + sum);
			}
			receiver.setBalance(receiver.getBalance() + sum);
			this.updateRemote(receiver);
			SecondaryController.updateBalance();
			return 1;
		}
		return 0;
	}
	
	
	public void updateRemote(Account a) throws IOException {
		try {
			JSONObject ns = new JSONObject();
			ns.put("IBAN", a.getIBAN());
			ns.put("type", a.getType());
			ns.put("accID", a.getAccID());
			ns.put("currency", a.getCurrency());
			ns.put("balance", a.getBalance());
			ns.put("userid", ClientHandler.getClient().getAccID());
			String strrr = "http://alexbam.me/api/update_bank.php";
			URL url = new URL(strrr);
	        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
	        conn.setDoOutput(true);
	        conn.setRequestMethod("POST");
			conn.setRequestProperty("User-Agent", "Mozilla/5.0");
	        OutputStream os = conn.getOutputStream();
	        os.write(("account=" + ns.toString()).getBytes());
	        os.flush();
	        
	        if (conn.getResponseCode() != 200) {
	        	System.out.println("Could not process request: " + conn.getResponseCode());
	        }else {
		        BufferedReader br = new BufferedReader(new InputStreamReader((conn.getInputStream())));
	
		        String output;
		        while ((output = br.readLine()) != null) {
		        	try{ 
			        	JSONObject out = new JSONObject(output);
			        	switch(out.getString("result")) {
			        	case "OK": System.out.println("Info for IBAN " + a.getIBAN() + " successfully updated."); break;
			        	case "NEW_OK": System.out.println("Account " + a.getIBAN() + " successfully added to database."); break;
			        	case "NOT_OK": System.out.println("Account " + a.getIBAN() + " could not be added. Error: " + out.getString("error_msg")); break;
			        	default: System.out.println("Something went wrong... " + output);
		        	}
		        	}catch(JSONException e) {
		        		System.out.println(output);
		        	}
		            //System.out.println(output);
		        }
	        }
	        conn.disconnect();

	      } catch (IOException e) {
	    	  e.printStackTrace();
	      } 
	}
	
	public HashMap<String, Account> getAccounts(){
		return this.accs;
	}
		
	public void init() throws JSONException, IOException {
		 String s = "http://alexbam.me/api/accounts.php?userid=" + ClientHandler.getClient().getAccID();
		 URL url = new URL(s);
		 HttpURLConnection conn = (HttpURLConnection) url.openConnection();
		 conn.setRequestProperty("User-Agent", "Mozilla/5.0");
		 String str = new String();
		 String inputLine;
		 JSONObject obj = null;
		 // read from the URL
		 try(BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()))){
			 while ((inputLine = in.readLine()) != null) {
	            str += inputLine;
			 }
			 in.close();
			 obj = new JSONObject(str);
		 }catch(java.io.IOException e) {
			 this.offline = true;
			 System.out.println("An error has occured while reading students from remote server. Now in [OFFLINE] mode.");
			 try(BufferedReader cacheReader = new BufferedReader(new FileReader("accs.txt"))) {
				 String line = cacheReader.readLine();
				 if(line != null) {
					 obj = new JSONObject(line); 
				 }
			 }catch(java.io.FileNotFoundException ee) {
				 ee.printStackTrace();
			 }
			// e.printStackTrace();
		 }

		 if(!obj.isEmpty() && obj.getString("result").equals("OK")){			
			 JSONArray arr = obj.getJSONArray("accounts");
			 for(int i = 0; i < arr.length(); i++) {
				 Long accID = 0L;
				 try { accID = Long.valueOf(arr.getJSONObject(i).getString("accID")); }catch(java.lang.NumberFormatException ee) { accID = 0L; }
				 Account acc = new Account(arr.getJSONObject(i).getString("IBAN"), arr.getJSONObject(i).getInt("type"), accID, arr.getJSONObject(i).getString("currency"));
				 
				 this.addAccount(acc);
				 this.getAccountByIBAN(acc.getIBAN()).setBalance(arr.getJSONObject(i).getDouble("balance"));
			 }
			 try (PrintWriter out = new PrintWriter("accs.txt", "UTF-8")) {
				 out.println(obj);
			 }catch(java.io.FileNotFoundException e) {
				 e.printStackTrace();
			 }
			 System.out.println("Done initializing. " + arr.length() + " accounts were added" + ((this.offline == true) ? " from cache" : "")  + ".");
			 this.initialized = true;
		 }else {
			 System.out.println("An error has occured: " + obj.getString("error_msg"));
		 }
	}
	
	public Account getRemoteAcc(String IBAN) throws IOException {
		 String s = "http://alexbam.me/api/accounts.php?iban=" + IBAN;
		 URL url = new URL(s);
		 HttpURLConnection conn = (HttpURLConnection) url.openConnection();
		 conn.setRequestProperty("User-Agent", "Mozilla/5.0");
		 String str = new String();
		 String inputLine;
		 JSONObject obj = null;
		 // read from the URL
		 try(BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()))){
			 while ((inputLine = in.readLine()) != null) {
	            str += inputLine;
			 }
			 in.close();
			 obj = new JSONObject(str);
		 }catch(java.io.IOException e) {
			 
		 }

		 if(!obj.isEmpty() && obj.getString("result").equals("OK")){			
			 JSONArray arr = obj.getJSONArray("accounts");
			 Long accID = 0L;
			 try { accID = Long.valueOf(arr.getJSONObject(0).getString("accID")); }catch(java.lang.NumberFormatException ee) { accID = 0L; }
			 Account acc = new Account(arr.getJSONObject(0).getString("IBAN"), arr.getJSONObject(0).getInt("type"), accID, arr.getJSONObject(0).getString("currency"));
			 acc.setBalance(arr.getJSONObject(0).getDouble("balance"));
			 System.out.println(acc.getIBAN());
			 return acc;
		 }else {
			 System.out.println("An error has occured: " + obj.getString("error_msg"));
		 }
		return null;
	}
	
	public Account getAccountByIBAN(String IBAN) {
		return this.accs.get(IBAN);
	}
	
	public Account getAccountByType(int type) {
		return this.accsByType.get(type);
	}
	
	public boolean isInitialized() {
		return (initialized == true) ? true : false;
	}
	
}

