package de.siphalor.bouncylife.mixin;

import de.siphalor.bouncylife.BouncyLife;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.EquipmentSlot;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.damage.DamageSource;
import net.minecraft.item.ItemStack;
import net.minecraft.util.collection.DefaultedList;
import net.minecraft.world.World;
import org.spongepowered.asm.mixin.Final;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

@Mixin(LivingEntity.class)
public abstract class MixinLivingEntity extends Entity {
	@Shadow public abstract Iterable<ItemStack> getArmorItems();

	@Shadow @Final private DefaultedList<ItemStack> equippedArmor;

	public MixinLivingEntity(EntityType<?> entityType_1, World world_1) {
		super(entityType_1, world_1);
	}

	private float bouncylife$damageAmount = 0.0F;

	@Inject(method = "handleFallDamage", at = @At("HEAD"), cancellable = true)
	public void handleFallDamage(float float_1, float float_2, CallbackInfoReturnable<Boolean> callbackInfo) {
        for(ItemStack stack : getArmorItems()) {
        	if(stack.getItem() == BouncyLife.shoes) {
        		callbackInfo.setReturnValue(super.handleFallDamage(float_1, float_2));
        		return;
			}
		}
	}

	@Inject(method = "applyDamage", at = @At("HEAD"))
	public void onApplyDamageHead(DamageSource damageSource, float amount, CallbackInfo callbackInfo) {
		bouncylife$damageAmount = amount;
	}

	@Inject(method = "applyDamage", at = @At(value = "TAIL", target = "Lnet/minecraft/entity/LivingEntity;getHealth()F"))
	public void onApplyDamageTail(DamageSource damageSource, float amount, CallbackInfo callbackInfo) {
		BouncyLife.applySlimeThorns(this, damageSource, bouncylife$damageAmount, amount);
	}

	@Inject(method = "damage", at = @At("HEAD"), cancellable = true)
	public void damage(DamageSource damageSource, float amount, CallbackInfoReturnable<Boolean> callbackInfoReturnable) {
        if(!world.isClient()) {
        	if(damageSource == DamageSource.FLY_INTO_WALL) {
        		if(BouncyLife.isSlimeArmor(equippedArmor.get(EquipmentSlot.HEAD.getEntitySlotId()))) {
					callbackInfoReturnable.setReturnValue(false);
				}
			}
		}
	}
}

package com.ibm.ml.mp.others;
import com.ibm.ml.ilog.Credentials;
import com.ibm.ml.ilog.Connector;
import com.typesafe.config.ConfigFactory;
import ilog.concert.IloException;
import ilog.concert.IloNumVar;
import ilog.concert.IloLinearNumExpr;
import ilog.cplex.WmlCplex;
import ilog.cplex.IloCplex;

/** FixNet.java - Use logical constraints to avoid numerical trouble in a
 *               fixed charge network flow problem.
 *
 *  Find a minimum cost flow in a fixed charge network flow problem.
 *  The network is as follows:
 * <pre>
 *       1 -- 3 ---> demand = 1,000,000
 *      / \  /       
 *     /   \/        
 *    0    /\        
 *     \  /  \       
 *      \/    \      
 *       2 -- 4 ---> demand = 1
 * </pre>
 *  A fixed charge of one is incurred for every edge with non-zero flow,
 *  with the exception of edge <1,4>, which has a fixed charge of ten.
 *  The cost per unit of flow on an edge is zero, with the exception of
 *  edge <2,4>, where the cost per unit of flow is five.
 */

public final class FixNet {

   // Define origin and destination nodes for each edge, as well as
   // unit costs and fixed costs for transporting flow on each edge.
   // Note that by defining a fixed cost of 0 for each arc you just
   // get a regular min-cost flow problem.
   private static final int[] orig = new int[]{0,0,1,1,2,2};
   private static final int[] dest = new int[]{1,2,3,4,3,4};
   private static final double[] unitcost = new double[]{0,0,0,0,0,5};
   private static final double[] fixedcost = new double[]{1,1,1,10,1,1};

   // Define demand (supply) at each node.
   private static final double[] demand = new double[]{-1000001, 0, 0, 1000000, 1};

   public static void main(String[] args) {
      try (IloCplex cplex = new WmlCplex(
              Credentials.getCredentials(ConfigFactory.parseResources("wml.public.conf").resolve()),
              Connector.Runtime.DO_12_10,
              Connector.TShirtSize.M,
              1)) {
         // Create the variables.
         // x variables are continuous variables in [0, infinity[,
         // f variables are binary variables.
         IloNumVar[] x = cplex.numVarArray(orig.length, 0.0, Double.POSITIVE_INFINITY);
         for (int i = 0; i < x.length; ++i)
            x[i].setName(String.format("x%d%d", orig[i], dest[i]));
         IloNumVar[] f = cplex.boolVarArray(orig.length);
         for (int i = 0; i < f.length; ++i)
            x[i].setName(String.format("f%d%d", orig[i], dest[i]));

         // Create objective function.
         cplex.addMinimize(cplex.sum(cplex.scalProd(unitcost, x),
                                     cplex.scalProd(fixedcost, f)));

         // Create constraints.
         // There is one constraint for each node. The constraint for a node i
         // states that the flow leaving i and the flow entering i must differ
         // by at least the demand for i.
         for (int i = 0; i < demand.length; ++i) {
            IloLinearNumExpr sum = cplex.linearNumExpr();
            for (int j = 0; j < orig.length; ++j) {
               if ( orig[j] == i )
                  sum.addTerm(-1.0, x[j]);
               if ( dest[j] == i)
                  sum.addTerm(+1.0, x[j]);
            }
            cplex.addGe(sum, demand[i]);
         }

         // Add logical constraints that require x[i]==0 if f[i] is 0.
         for (int i = 0; i < orig.length; ++i)
            cplex.add(cplex.ifThen(cplex.eq(f[i], 0.0), cplex.eq(x[i], 0.0)));

         // Solve the problem.
         cplex.solve();

         // Write solution value and objective to the screen.
         System.out.println("Solution status: " + cplex.getStatus());
         System.out.println("Solution value  = " + cplex.getObjValue());
         System.out.println("Solution vector:");
         for (IloNumVar v : x)
            System.out.println(String.format("%10s: %15.6f", v.getName(), cplex.getValue(v)));
         for (IloNumVar v : f)
            System.out.println(String.format("%10s: %15.6f", v.getName(), cplex.getValue(v)));

      }
      catch (IloException e){
         System.out.println("Error "+e.getMessage());
      }
   }
}

package cc.bukkit.database;

import java.io.File;
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.LinkedList;

public class SQLiteCore implements DatabaseCore {
	private Connection connection;
	private File dbFile;
	private volatile Thread watcher;
	private volatile LinkedList<BufferStatement> queue = new LinkedList<BufferStatement>();

	public SQLiteCore(File dbFile) {
		this.dbFile = dbFile;
	}

	/**
	 * Gets the database connection for executing queries on.
	 * 
	 * @return The database connection
	 */
	public Connection getConnection() {
		try {
			// If we have a current connection, fetch it
			if (this.connection != null && !this.connection.isClosed()) {
				return this.connection;
			}
		} catch (SQLException e) {
			e.printStackTrace();
		}
		if (this.dbFile.exists()) {
			// So we need a new connection
			try {
				Class.forName("org.sqlite.JDBC");
				this.connection = DriverManager.getConnection("jdbc:sqlite:" + this.dbFile);
				return this.connection;
			} catch (ClassNotFoundException e) {
				e.printStackTrace();
				return null;
			} catch (SQLException e) {
				e.printStackTrace();
				return null;
			}
		} else {
			// So we need a new file too.
			try {
				// Create the file
				this.dbFile.createNewFile();
				// Now we won't need a new file, just a connection.
				// This will return that new connection.
				return this.getConnection();
			} catch (IOException e) {
				e.printStackTrace();
				return null;
			}
		}
	}

	@Override
	public void queue(BufferStatement bs) {
		synchronized (queue) {
			queue.add(bs);
		}
		if (watcher == null || !watcher.isAlive()) {
			startWatcher();
		}
	}

	@Override
	public void flush() {
		while (queue.isEmpty() == false) {
			BufferStatement bs;
			synchronized (queue) {
				bs = queue.removeFirst();
			}
			synchronized (dbFile) {
				try {
					PreparedStatement ps = bs.prepareStatement(getConnection());
					ps.execute();
					ps.close();
				} catch (SQLException e) {
					e.printStackTrace();

				}
			}
		}
	}

	@Override
	public void close() {
		flush();
	}

	private void startWatcher() {
		watcher = new Thread() {
			@Override
			public void run() {
				try {
					Thread.sleep(30000);
				} catch (InterruptedException e) {
				}
				flush();
			}
		};
		watcher.start();
	}
}

package gov.samhsa.c2s.pcm.service.audit;

import gov.samhsa.c2s.pcm.service.audit.domain.ActivityHistory;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.util.Assert;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.text.SimpleDateFormat;
import java.util.Date;

public class ActivityHistoryRowMapper implements RowMapper<ActivityHistory> {

    private static final String ACTIVITY_ID = "activity_id";
    private static final String REVISION_ID = "revision_id";
    private static final String TIMESTAMP = "timestamp";
    private static final String USERNAME = "username";
    private static final String REC_TYPE = "rec_type";
    private static final String TYPE = "type";

    @Override
    public ActivityHistory mapRow(ResultSet rs, int rowNum) throws SQLException {
        ActivityHistory activityHistory = new ActivityHistory();

        activityHistory.setId(rs.getLong(ACTIVITY_ID));
        activityHistory.setRevisionid(rs.getLong(REVISION_ID));
        activityHistory.setChangedDateTime(convertTimestampToDateTime(rs.getLong(TIMESTAMP)));
        activityHistory.setChangedBy(rs.getString(USERNAME));
        activityHistory.setRecType(rs.getString(REC_TYPE));
        activityHistory.setType(rs.getString(TYPE));

        return activityHistory;
    }

    private String convertTimestampToDateTime(Long revtstmp) {
        Assert.isTrue(revtstmp > 0, "The value must be greater than zero");
        return new SimpleDateFormat("MM/dd/yyyy HH:mm:ss").format(new Date(revtstmp));
    }
}

