package net.voldrich.graal.async.api;

import lombok.extern.slf4j.Slf4j;
import reactor.core.publisher.Mono;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;

@Slf4j
public class MockedHttpClient {
    private final Map<String, ScriptMockedHttpResponse> urlToResponseMap = new HashMap<>();

    public void addResponse(String url, ScriptMockedHttpResponse response) {
        this.urlToResponseMap.put(url, response);
    }

    public Mono<ScriptMockedHttpResponse> get(String url) {
        ScriptMockedHttpResponse response = urlToResponseMap.get(url);
        if (response == null) {
            throw new RuntimeException("404 NOT FOUND");
        }
        return Mono.delay(Duration.ofMillis(response.responseTimeoutMs))
                .thenReturn(response)
                .doOnSubscribe(subscription -> log.trace("Request {} started", url))
                .doOnSuccess(result -> log.trace("Request {} finished", url));
    }
}

package com.lty.config.exception;

import com.lty.entity.system.Result;
import com.lty.config.util.ResultUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseBody;

import javax.servlet.http.HttpServletRequest;

/**
 * Created by Administrator on 2018/5/14.
 * 统一处理异常
 *      在controller层 throws Exception
 */
@ControllerAdvice
public class ExceptionHandle {

    private final Logger logger = LoggerFactory.getLogger(ExceptionHandle.class);


    @ExceptionHandler(value = Exception.class)
    @ResponseBody
    public Result defaultErrorHandler(HttpServletRequest req, Exception e) throws Exception{
        if(e instanceof MyException){
            MyException myException = (MyException)e;
            logger.info(myException.getMessage());
            if(myException.getData()==null||"".equals(myException.getData())){
                myException.setData(myException.getMessage());
            }
            return ResultUtil.requestFailed(myException.getData(),myException.getMessage(),myException.getCode());
        }
        logger.error(e.getMessage()+"(异常)",e);  //这里必须是logger.error(str1,str2),需要在
        e.printStackTrace();
        return ResultUtil.requestFailed(e.getMessage());
    }


}

package de.codecentric.reedelk.platform.services.scriptengine.evaluator.function;

import de.codecentric.reedelk.runtime.api.commons.ScriptUtils;
import de.codecentric.reedelk.runtime.api.script.dynamicvalue.DynamicValue;

import java.util.List;

import static java.util.Arrays.asList;

public class FunctionDefinitionBuilderDefault implements FunctionDefinitionBuilder<DynamicValue<?>> {

    private final String template;

    private FunctionDefinitionBuilderDefault(List<String> functionArgumentNames) {
        String joinedArgs = String.join(", ", functionArgumentNames);
        template = "def %s(" + joinedArgs + ") {\n" +
                "  %s\n" +
                "}";
    }

    public static FunctionDefinitionBuilder<DynamicValue<?>> from(String ...functionArgumentNames) {
        return new FunctionDefinitionBuilderDefault(asList(functionArgumentNames));
    }

    public static final FunctionDefinitionBuilder<DynamicValue<?>> CONTEXT_AND_ERROR =
            FunctionDefinitionBuilderDefault.from("context", "error");

    public static final FunctionDefinitionBuilder<DynamicValue<?>> CONTEXT_AND_MESSAGE =
            FunctionDefinitionBuilderDefault.from("context", "message");

    @Override
    public String apply(DynamicValue<?> dynamicValue) {
        String functionBody = ScriptUtils.unwrap(dynamicValue.body());
        return String.format(template, dynamicValue.functionName(), functionBody);
    }
}

