package com.eliotlash.molang.expressions;

import com.eliotlash.mclib.math.Variable;
import com.eliotlash.molang.MolangParser;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.StringJoiner;

public class MolangMultiStatement extends MolangExpression
{
	public List<MolangExpression> expressions = new ArrayList<MolangExpression>();
	public Map<String, Variable> locals = new HashMap<String, Variable>();

	public MolangMultiStatement(MolangParser context)
	{
		super(context);
	}

	@Override
	public double get()
	{
		double value = 0;

		for (MolangExpression expression : this.expressions)
		{
			value = expression.get();
		}

		return value;
	}

	@Override
	public String toString()
	{
		StringJoiner builder = new StringJoiner("; ");

		for (MolangExpression expression : this.expressions)
		{
			builder.add(expression.toString());

			if (expression instanceof MolangValue && ((MolangValue) expression).returns)
			{
				break;
			}
		}

		return builder.toString();
	}
}

package de.codecentric.reedelk.runtime.api.component;

import de.codecentric.reedelk.runtime.api.message.Message;

public abstract class AbstractInbound implements Inbound, InboundEventListener {

    private InboundEventListener listener;

    @Override
    public void onEvent(Message message) {
        if (listener == null) {
            throw new IllegalStateException("Event listener was not registered!");
        }
        listener.onEvent(message);
    }

    @Override
    public void onEvent(Message message, OnResult onResult) {
        if (listener == null) {
            throw new IllegalStateException("Event listener was not registered!");
        }
        listener.onEvent(message, onResult);
    }

    @Override
    public void addEventListener(InboundEventListener listener) {
        this.listener = listener;
    }

    @Override
    public void removeEventListener() {
        this.listener = null;
    }
}

