                RegistryKeyProperty rkp = (RegistryKeyProperty) event.getNewValue();
                conditionalRouteBranch.setTargetSequence(rkp);
            } else {
                conditionalRouteBranch.setTargetSequence(EsbFactoryImpl.eINSTANCE.createRegistryKeyProperty());
            }
