package com.ning.billing.analytics.model;

import java.util.UUID;

import org.testng.Assert;
import org.testng.annotations.Test;

import com.ning.billing.analytics.AnalyticsTestSuiteNoDB;

public class TestBusinessInvoiceTag extends AnalyticsTestSuiteNoDB {

    @Test(groups = "fast")
    public void testEquals() throws Exception {
        final UUID invoiceId = UUID.randomUUID();
        final String name = UUID.randomUUID().toString();
        final BusinessInvoiceTagModelDao invoiceTag = new BusinessInvoiceTagModelDao(invoiceId, name);
        Assert.assertSame(invoiceTag, invoiceTag);
        Assert.assertEquals(invoiceTag, invoiceTag);
        Assert.assertTrue(invoiceTag.equals(invoiceTag));
        Assert.assertEquals(invoiceTag.getInvoiceId(), invoiceId);
        Assert.assertEquals(invoiceTag.getName(), name);

        final BusinessInvoiceTagModelDao otherInvoiceTag = new BusinessInvoiceTagModelDao(UUID.randomUUID(), UUID.randomUUID().toString());
        Assert.assertFalse(invoiceTag.equals(otherInvoiceTag));
    }
}

package main.controllers;

import main.entities.User;
import main.entities.UserRole;
import main.models.binding.UserLoginBindingModel;
import main.models.binding.UserRegisterBindingModel;
import main.repositories.UserRepository;
import org.softuni.broccolina.solet.HttpSoletRequest;
import org.softuni.javache.http.HttpSession;
import org.softuni.javache.http.HttpSessionImpl;
import org.softuni.summermvc.api.Controller;
import org.softuni.summermvc.api.GetMapping;
import org.softuni.summermvc.api.PostMapping;

@Controller
public class UserController {
    private UserRepository userRepository;

    public UserController() { this.userRepository = new UserRepository(); }

    @GetMapping(route = "/login")
    public String login(HttpSoletRequest request) {
        if(request.getSession() != null) {
            return "redirect:/home";
        }

        return "template:login";
    }

    @PostMapping(route = "/login")
    public String loginConfirm(HttpSoletRequest request, UserLoginBindingModel userLoginBindingModel) {
        if(request.getSession() != null) {
            return "redirect:/home";
        }

        User user = this.userRepository.findByUsername(userLoginBindingModel.getUsername());

        if(user == null || !user.getPassword().equals(userLoginBindingModel.getPassword())) {
            return "redirect:/login";
        }

        request.setSession(new HttpSessionImpl());

        request.getSession().addAttribute("user-id", user.getId());
        request.getSession().addAttribute("username", user.getUsername());
        request.getSession().addAttribute("role", user.getUserRole().toString());

        return "redirect:/home";
    }

    @GetMapping(route = "/register")
    public String register() {
        return "template:register";
    }

    @PostMapping(route = "/register")
    public String registerConfirm(UserRegisterBindingModel userRegisterBindingModel) {
        if(!userRegisterBindingModel.getPassword().equals(userRegisterBindingModel.getConfirmPassword())) {
            return "redirect:/register";
        }

        User user = new User();

        user.setUsername(userRegisterBindingModel.getUsername());
        user.setPassword(userRegisterBindingModel.getPassword());
        user.setUserRole(UserRole.USER);

        this.userRepository.saveUser(user);

        return "redirect:/login";
    }

    @GetMapping(route = "/logout")
    public String logout(HttpSoletRequest request) {
        if(request.getSession() == null) {
            return "redirect:/login";
        }

        request.getSession().invalidate();

        return "redirect:/";
    }
}

