    @Override
    public void onClick(View v) {
        switch (v.getId()) {
            case R.id.btn_auto_change:
                mIsAuto = mcheckbtn.isChecked();
                break;
            case R.id.btn_confirm:
                setMapResult();
                break;
            case R.id.btn_change_map:
                mcheckbtn.setChecked(false);
                mIsAuto = false;
                if (mIsAmapDisplay) {
                    changeToGoogleMapView();
                } else {
                    changeToAmapView();
                }
                break;
