    private void changeToAmapView() {
        if (googlemap != null) {
            zoom = googlemap.getCameraPosition().zoom;
            latitude = googlemap.getCameraPosition().target.latitude;
            longitude = googlemap.getCameraPosition().target.longitude;
        }
        mapbtn.setText("To 谷歌地图");
        mAmapView = new TextureMapView(this, new AMapOptions()
                .camera(new com.amap.api.maps.model.CameraPosition(new LatLng(latitude, longitude), zoom, 0, 0)));
        mAmapView.onCreate(null);
        mAmapView.onResume();
        mContainerLayout.addView(mAmapView, mParams);

        mGoogleMapView.animate().alpha(0f).setDuration(500).setListener(new AnimatorListenerAdapter() {
            @Override
            public void onAnimationEnd(Animator animation) {
                mGoogleMapView.setVisibility(View.GONE);
                mContainerLayout.removeView(mGoogleMapView);
                if (mGoogleMapView != null) {
                    mGoogleMapView.onDestroy();
                }
            }
        });
        //AMap amap = mAmapView.getMap();
        amap = mAmapView.getMap();
        amap.setOnCameraChangeListener(this);
        amap.setOnMapClickListener(this);
        mIsAmapDisplay = true;
    }

    private Handler handler = new Handler() {
        public void handleMessage(Message message) {
            mAmapView.setVisibility(View.GONE);
            mContainerLayout.removeView(mAmapView);
            if (mAmapView != null) {
                mAmapView.onDestroy();
            }
        }
    };

    private void changeToGoogleMapView() {
        zoom = mAmapView.getMap().getCameraPosition().zoom;
        latitude = mAmapView.getMap().getCameraPosition().target.latitude;
        longitude = mAmapView.getMap().getCameraPosition().target.longitude;

        mapbtn.setText("To 高德地图");
        mIsAmapDisplay = false;
        mGoogleMapView = new com.google.android.gms.maps.MapView(this, new GoogleMapOptions()
                .camera(new com.google.android.gms.maps.model
                        .CameraPosition(new com.google.android.gms.maps.model.LatLng(latitude, longitude), zoom, 0, 0)));
        mGoogleMapView.onCreate(null);
        mGoogleMapView.onResume();
        mContainerLayout.addView(mGoogleMapView, mParams);
        mGoogleMapView.getMapAsync(this);
        handler.sendEmptyMessageDelayed(0, 500);
    }

    @Override
    public void onCameraChange(com.amap.api.maps.model.CameraPosition cameraPosition) {

    }

    @Override
    public void onCameraChangeFinish(com.amap.api.maps.model.CameraPosition cameraPosition) {
        longitude = cameraPosition.target.longitude;
        latitude = cameraPosition.target.latitude;
        zoom = cameraPosition.zoom;
        if (!isInArea(latitude, longitude) && mIsAmapDisplay && mIsAuto) {
            changeToGoogleMapView();
        }
    }

    private boolean isInArea(double latitude, double longtitude) {
        if ((latitude > 3.837031) && (latitude < 53.563624)
                && (longtitude < 135.095670) && (longtitude > 73.502355)) {
            return true;
        }
        return false;
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (mAmapView != null) {
            mAmapView.onResume();
        }
        if (mGoogleMapView != null) {
            try {
                mGoogleMapView.onResume();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    @Override
    protected void onPause() {
        super.onPause();
        if (mAmapView != null) {
            mAmapView.onPause();
        }
        if (mGoogleMapView != null) {
            try {
                mGoogleMapView.onPause();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        if (mAmapView != null) {
            mAmapView.onSaveInstanceState(outState);
        }
        if (mGoogleMapView != null) {
            try {
                mGoogleMapView.onSaveInstanceState(outState);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }


    @Override
    protected void onDestroy() {
        super.onDestroy();
        destroyLocation();
        if (mAmapView != null) {
            mAmapView.onDestroy();
        }
        if (mGoogleMapView != null) {
            try {
                mGoogleMapView.onDestroy();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    @Override
    public void onMapReady(GoogleMap googleMap) {
        this.googlemap = googleMap;
        if (googlemap != null) {
            googlemap.setOnCameraMoveListener(this);
        }
        addGoogleMarker();
        googlemap.setOnMapClickListener(new GoogleMap.OnMapClickListener() {
            @Override
            public void onMapClick(com.google.android.gms.maps.model.LatLng latLng) {
                longitude = latLng.longitude;
                latitude = latLng.latitude;
                getGooglePosition(latLng);
            }
        });
        UiSettings uiSettings = googlemap.getUiSettings();
        uiSettings.setAllGesturesEnabled(true);
        uiSettings.setMapToolbarEnabled(true);
        uiSettings.setZoomControlsEnabled(true);
        //uiSettings.setCompassEnabled(true);
    }

    private void getGooglePosition(com.google.android.gms.maps.model.LatLng latLng) {
        ApiUtil.init().getGooglePostion(latLng, new MyCallBack() {
            public void onSuccess(String result) {
                formatAddress = result;
                LogUtils.debug(TAG,"Google formatAddress ="+formatAddress);
                setCurrentPositionInfo();
                addGoogleMarker();
            }
        });
    }

    private void addGoogleMarker() {
        com.google.android.gms.maps.model.LatLng location = new com.google.android.gms.maps.model.LatLng(latitude, longitude);
        googlemap.addMarker(new com.google.android.gms.maps.model.MarkerOptions().position(location).title("当前坐标："+longitude+","+latitude));
        googlemap.moveCamera(com.google.android.gms.maps.CameraUpdateFactory.newLatLng(location));
    }


    @Override
    public void onCameraMove() {
        CameraPosition cameraPosition=googlemap.getCameraPosition();
        longitude = cameraPosition.target.longitude;
        latitude = cameraPosition.target.latitude;
        zoom = cameraPosition.zoom;
        if (isInArea(latitude, longitude) && !mIsAmapDisplay && mIsAuto) {
            changeToAmapView();
        }
    }

    @Override
    public void onLocationChanged(AMapLocation aMapLocation) {
        if (aMapLocation != null
                && aMapLocation.getErrorCode() == 0) {
            //longitude = aMapLocation.getLongitude();
            //latitude = aMapLocation.getLatitude();
            if (!aMapLocation.getCountry().equals("中国")){
                changeToGoogleMapView();
            } else {
                amap.moveCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(latitude,longitude), 15));
            }
            //Toast.makeText(context,aMapLocation.getCountry(),Toast.LENGTH_LONG).show();
            mIsAuto = false;
            mcheckbtn.setChecked(false);
            //setCurrentPositionInfo();
        } else {
            String errText = "定位失败," + aMapLocation.getErrorCode() + ": " + aMapLocation.getErrorInfo();
            LogUtils.debug("AmapErr", errText);
            Toast.makeText(context, errText, Toast.LENGTH_LONG).show();
        }
    }

    private void stopLocation(){
        // 停止定位
        mlocationClient.stopLocation();
    }

    private void destroyLocation(){
        if (null != mlocationClient) {
            /**
             * 如果AMapLocationClient是在当前Activity实例化的，
             * 在Activity的onDestroy中一定要执行AMapLocationClient的onDestroy
             */
            mlocationClient.onDestroy();
            mlocationClient = null;
            mlocationClient = null;
        }
    }

    @Override
    public void onCheckedChanged(CompoundButton buttonView, boolean isChecked) {
        if (buttonView.getId()==R.id.btn_auto_change) {
            mIsAuto = isChecked;
        }
    }
}

package com.yumore.image.widget;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.util.AttributeSet;
import android.view.MotionEvent;
import android.view.View;

import com.yumore.imagelibrary.R;


/**
 * 裁剪遮罩视图
 * Created by cain.huang on 2017/12/28.
 */

public class CropCoverView extends View {

    private static final String TAG = "ImageCropView";
    private final float mLastX = 0;
    private final float mLastY = 0;
    private int mMeasuredWidth;
    private int mMeasuredHeight;
    private Paint mPaint;
    private int mStrokeWidth;
    // 边角长度
    private int mCornerLength;
    private float mMarginLeft;
    private float mMarginRight;
    private float mMarginTop;
    private float mMarginBottom;
    private int mStrokeWidthNew;
    // 按下坐标
    private float mTouchX;
    private float mTouchY;
    private boolean mTouchLeft;     // 左边触摸标志
    private boolean mTouchRight;    // 右边触摸标志
    private boolean mTouchTop;      // 上边触摸标志
    private boolean mTouchBottom;   // 下边触摸标志
    private boolean mMoving;        // 拖拽模式

    // 上下左右四个坐标
    private float mLeft;
    private float mRight;
    private float mTop;
    private float mBottom;

    // 是否可以自由改变
    private boolean mEnableChangeSize = true;

    // 长宽比，如果小于0，则表示不受长宽比限制
    private float mRatio = -1.0f;

    public CropCoverView(Context context, AttributeSet attrs, int defStyleAttr) {
        super(context, attrs, defStyleAttr);
        init();
    }

    public CropCoverView(Context context, AttributeSet attrs) {
        super(context, attrs);
        init();
    }

    public CropCoverView(Context context) {
        super(context);
        init();
    }

    private void init() {
        mStrokeWidth = (int) getResources().getDimension(R.dimen.dp3);
        mStrokeWidthNew = (int) getResources().getDimension(R.dimen.dp1);

        mPaint = new Paint();
        mPaint.setAntiAlias(true);
        mPaint.setColor(Color.WHITE);
        mPaint.setStyle(Paint.Style.STROKE);
    }

    public void setEnableChangedSize(boolean enableChangedSize) {
        mEnableChangeSize = enableChangedSize;
    }

    public void setRatio(float ratio) {
        mRatio = ratio;
    }

    @Override
    public boolean onTouchEvent(MotionEvent event) {
        if (!mEnableChangeSize) {
            return true;
        }
        switch (event.getAction()) {
            case MotionEvent.ACTION_DOWN:

                mTouchX = event.getX();
                mTouchY = event.getY();

                // 手指触摸的是左边还是右边
                if (Math.abs(mLeft - mTouchX) < mCornerLength) {
                    mTouchLeft = true;
                } else if (Math.abs(mRight - mTouchX) < mCornerLength) {
                    mTouchRight = true;
                }
                // 手指触摸是上边还是下边
                if (Math.abs(mTop - mTouchY) < mCornerLength) {
                    mTouchTop = true;
                } else if (Math.abs(mBottom - mTouchY) < mCornerLength) {
                    mTouchBottom = true;
                }
                // 如果手指范围没有在任何边界位置, 那么我们就认为用户是想拖拽框体
                if (!mTouchLeft && !mTouchTop && !mTouchRight && !mTouchBottom) {
                    mMoving = true;
                }
                break;
            case MotionEvent.ACTION_MOVE:
                float moveX = event.getX();
                float moveY = event.getY();
                // 得到手指移动距离
                float slideX = moveX - mTouchX + mLastX;
                float slideY = moveY - mTouchY + mLastY;

                // 判断是否是拖拽模式
                if (mMoving) {
                    mLeft += slideX;
                    mRight += slideX;
                    mTop += slideY;
                    mBottom += slideY;
                    // 同时改变left和right值, 达到左右移动的效果
                    if (mLeft < mMarginLeft || mRight > mMeasuredWidth - mMarginRight) { // 判断x轴的移动边界
                        mLeft -= slideX;
                        mRight -= slideX;
                    }
                    // 同时改变top和bottom值, 达到上下移动的效果
                    if (mTop < mMarginTop || mBottom > mMeasuredHeight - mMarginBottom) { // 判断y轴的移动边界
                        mTop -= slideY;
                        mBottom -= slideY;
                    }
                } else if (mEnableChangeSize) { // 更改边框大小模式
                    // 改变边框的宽度，左/右调整
                    if (mTouchLeft) {
                        mLeft += slideX;
                        if (mLeft < mMarginLeft) {
                            mLeft = mMarginLeft;
                        }
                        if (mLeft > mRight - mCornerLength * 2) {
                            mLeft = mRight - mCornerLength * 2;
                        }
                    } else if (mTouchRight) {
                        mRight += slideX;
                        if (mRight > mMeasuredWidth - mMarginRight) {
                            mRight = mMeasuredWidth - mMarginRight;
                        }
                        if (mRight < mLeft + mCornerLength * 2) {
                            mRight = mLeft + mCornerLength * 2;
                        }
                    }

                    // 按照比例top不变，计算bottom的位置
                    if (mRatio != -1) {
                        float width = mRight - mLeft;
                        float height = width / mRatio;
                        mBottom = mTop + height;
                        // 判断此时的Bottom是否超出了范围了
                        boolean needToAdjustHorizontal = false;
                        if (mBottom > mMeasuredHeight - mMarginBottom) {
                            mBottom = mMeasuredHeight - mMarginBottom;
                            needToAdjustHorizontal = true;
                        }
                        if (mBottom < mTop + mCornerLength * 2) {
                            mBottom = mTop + mCornerLength * 2;
                            needToAdjustHorizontal = true;
                        }
                        // 重新调整左右位置
                        if (needToAdjustHorizontal) {
                            height = mBottom - mTop;
                            width = height * mRatio;
                            if (mTouchLeft) {
                                mLeft = mRight - width;
                                // 判断是否超过左边margin的位置
                                if (mLeft < mMarginLeft) {
                                    mLeft = mMarginLeft;
                                    mRight = mLeft + width;
                                }
                            } else if (mTouchRight) {
                                mRight = mLeft + width;
                                // 判断是否超过右边margin的位置
                                if (mRight > mMeasuredWidth - mMarginRight) {
                                    mRight = mMeasuredWidth - mMarginRight;
                                    mLeft = mRight - width;
                                }

                            }
                        }
                    }

                    // 改变边框的高度，上/下调整
                    if (mTouchTop) {
                        mTop += slideY;
                        if (mTop < mMarginTop) {
                            mTop = mMarginTop;
                        }
                        if (mTop > mBottom - mCornerLength * 2) {
                            mTop = mBottom - mCornerLength * 2;
                        }
                    } else if (mTouchBottom) {
                        mBottom += slideY;
                        if (mBottom > mMeasuredHeight - mMarginBottom) {
                            mBottom = mMeasuredHeight - mMarginBottom;
                        }
                        if (mBottom < mTop + mCornerLength * 2) {
                            mBottom = mTop + mCornerLength * 2;
                        }
                    }
                    // 按照比例left不变，计算right的位置
                    if (mRatio != -1) {
                        float height = mBottom - mTop;
                        float width = height * mRatio;
                        mRight = mLeft + width;
                        // 判断right的位置是否超范围了
                        boolean needToAdjustVertical = false;
                        if (mRight > mMeasuredWidth - mMarginRight) {
                            mRight = mMeasuredWidth - mMarginRight;
                            needToAdjustVertical = true;
                        }
                        if (mRight < mLeft + mCornerLength * 2) {
                            mRight = mLeft + mCornerLength * 2;
                            needToAdjustVertical = true;
                        }
                        // 重新调整上下位置
                        if (needToAdjustVertical) {
                            width = mRight - mLeft;
                            height = width / mRatio;
                            if (mTouchTop) {
                                mTop = mBottom - height;
                                // 判断top是否超过顶部margin位置
                                if (mTop < mMarginTop) {
                                    mTop = mMarginTop;
                                    mBottom = mTop + height;
                                }
                            } else if (mTouchBottom) {
                                mBottom = mTop + height;
                                // 判断bottom是否超过底部margin位置
                                if (mBottom > mMeasuredHeight - mMarginBottom) {
                                    mBottom = mMeasuredHeight - mMarginBottom;
                                    mTop = mBottom - height;
                                }
                            }
                        }
                    }

                }
                // 实时触发onDraw()方法
                invalidate();

                mTouchX = moveX;
                mTouchY = moveY;
                break;

            case MotionEvent.ACTION_CANCEL:
            case MotionEvent.ACTION_UP:
                mTouchLeft = false;
                mTouchRight = false;
                mTouchTop = false;
                mTouchBottom = false;
                mMoving = false;
                break;
        }
        return true;
    }

    /**
     * 得到裁剪区域的margin值
     */
    public float[] getCutArea() {
        float[] arr = new float[4];
        arr[0] = mLeft - mMarginLeft;
        arr[1] = mTop - mMarginTop;
        arr[2] = mRight - mMarginLeft;
        arr[3] = mBottom - mMarginTop;
        return arr;
    }

    /**
     * 获取裁剪宽度
     *
     * @return
     */
    public int getRectWidth() {
        return (int) (mMeasuredWidth - mMarginLeft - mMarginRight);
    }

    /**
     * 获取裁剪高度
     *
     * @return
     */
    public int getRectHeight() {
        return (int) (mMeasuredHeight - mMarginTop - mMarginBottom);
    }

    @Override
    protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
        super.onMeasure(widthMeasureSpec, heightMeasureSpec);

        if (mMeasuredWidth == 0) {
            initParams();
        }
    }

    /**
     * 设置Margin
     *
     * @param left
     * @param top
     * @param right
     * @param bottom
     */
    public void setMargin(float left, float top, float right, float bottom) {
        mMarginLeft = left;
        mMarginTop = top;
        mMarginRight = right;
        mMarginBottom = bottom;
        initParams();
        invalidate();
    }

    /**
     * 设置layout位置
     *
     * @param left
     * @param top
     * @param right
     * @param bottom
     */
    public void setLayout(float left, float top, float right, float bottom) {
        mLeft = left;
        mRight = right;
        mTop = top;
        mBottom = bottom;
        invalidate();
    }

    /**
     * 初始化参数
     */
    private void initParams() {

        mMeasuredWidth = getMeasuredWidth();
        mMeasuredHeight = getMeasuredHeight();
        mCornerLength = mMeasuredWidth / 10;

        mLeft = mMarginLeft;
        mRight = mMeasuredWidth - mMarginRight;
        mTop = mMarginTop;
        mBottom = mMeasuredHeight - mMarginBottom;
    }

    @Override
    protected void onDraw(Canvas canvas) {

        // 宽度
        mPaint.setStrokeWidth(mStrokeWidthNew);
        // 绘制裁剪区域的矩形, 传入margin值来确定大小
        canvas.drawRect(mLeft, mTop, mRight, mBottom, mPaint);
        //绘制四条分割线和四个角
        drawLine(canvas, mLeft, mTop, mRight, mBottom);
    }

    /**
     * 绘制四条分割线和四个角
     */
    private void drawLine(Canvas canvas, float left, float top, float right, float bottom) {

        // 设置Stroke宽度
        mPaint.setStrokeWidth(1);
        // 绘制四条分割线
        float startX = (right - left) / 3 + left;
        float startY = top;
        float endX = (right - left) / 3 + left;
        float endY = bottom;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = (right - left) / 3 * 2 + left;
        startY = top;
        endX = (right - left) / 3 * 2 + left;
        endY = bottom;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = left;
        startY = (bottom - top) / 3 + top;
        endX = right;
        endY = (bottom - top) / 3 + top;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = left;
        startY = (bottom - top) / 3 * 2 + top;
        endX = right;
        endY = (bottom - top) / 3 * 2 + top;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        mPaint.setStrokeWidth(mStrokeWidth);
        // 绘制四个角
        startX = left - mStrokeWidth / 2;
        startY = top;
        endX = left + mCornerLength;
        endY = top;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = left;
        startY = top;
        endX = left;
        endY = top + mCornerLength;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = right + mStrokeWidth / 2;
        startY = top;
        endX = right - mCornerLength;
        endY = top;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = right;
        startY = top;
        endX = right;
        endY = top + mCornerLength;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = left;
        startY = bottom;
        endX = left;
        endY = bottom - mCornerLength;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = left - mStrokeWidth / 2;
        startY = bottom;
        endX = left + mCornerLength;
        endY = bottom;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = right + mStrokeWidth / 2;
        startY = bottom;
        endX = right - mCornerLength;
        endY = bottom;
        canvas.drawLine(startX, startY, endX, endY, mPaint);

        startX = right;
        startY = bottom;
        endX = right;
        endY = bottom - mCornerLength;
        canvas.drawLine(startX, startY, endX, endY, mPaint);
    }
}

package com.socketLabs.injectionApi.core.serialization;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.socketLabs.injectionApi.message.*;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Used by the Send function of the SocketLabsClient to generate an InjectionRequest for the Injection Api.
 */
public class InjectionRequestFactory{

    /**
     * Your SocketLabs server ID
     */
    private int serverId;

    /**
     * Your SocketLabs Injection API key
     */
    private String apiKey;

    /**
     * Jackson 2 class used for writing message to JSON
     */
    private ObjectMapper mapper = new ObjectMapper().setSerializationInclusion(JsonInclude.Include.NON_EMPTY);

    /**
     * Creates a new instance of the InjectionRequestFactory.
     * @param serverId Your SocketLabs server ID
     * @param apiKey Your SocketLabs Injection API key
     */
    public InjectionRequestFactory(int serverId, String apiKey) {
        this.serverId = serverId;
        this.apiKey = apiKey;
    }

    /**
     * Gets the server ID for the Injection Request Factory.
     * @return String
     */
    public int getServerId() {
        return serverId;
    }
    /**
     * Sets the server ID for the Injection Request Factory.
     * @param serverId String
     */
    public void setServerId(int serverId) {
        this.serverId = serverId;
    }

    /**
     * Gets the SocketLabs Injection API key for the Injection Request Factory.
     * @return String
     */
    public String getApiKey() {
        return apiKey;
    }
    /**
     * Sets the SocketLabs Injection API key for the Injection Request Factory.
     * @param apiKey String
     */
    public void setApiKey(String apiKey) {
        this.apiKey = apiKey;
    }

    /**
     * Generate the InjectionRequest for sending to the Injection Api.
     * @param bulkMessage A BulkMessage object to be sent
     * @return String
     * @throws IOException IOException
     */
    public String GenerateRequest(BulkMessage bulkMessage) throws IOException {
        List<MessageJson> messageJsons = new ArrayList<>();
        MessageJson messageJson = generateBaseMessage(bulkMessage);

        List<AddressJson> to = new ArrayList<>();

        to.add(new AddressJson("%%DeliveryAddress%%", "%%RecipientName%%"));

        messageJson.setTo(to);

        messageJson.setMergeData(populateMergeData(bulkMessage.getGlobalMergeData(), bulkMessage.getTo()));

        messageJsons.add(messageJson);

        return mapper.writeValueAsString(new InjectionRequest(this.serverId, this.apiKey, messageJsons));
    }

    /**
     * Generate the InjectionRequest for sending to the Injection Api.
     * @param basicMessage A BasicMessage object to be sent.
     * @return String
     * @throws IOException IOException
     */
    public String GenerateRequest(BasicMessage basicMessage) throws IOException {

        List<MessageJson> messageJsonList = new ArrayList<>();

        MessageJson messageJson = generateBaseMessage(basicMessage);

        messageJson.setTo(populateEmailList(basicMessage.getTo()));

        messageJson.setCc(populateEmailList(basicMessage.getCc()));

        messageJson.setBcc(populateEmailList(basicMessage.getBcc()));

        messageJsonList.add(messageJson);

        return GetAsJson(new InjectionRequest(this.serverId, this.apiKey, messageJsonList));
    }

    /**
     * Returns an InjectionRequest as JSON to be sent to the Injection API.
     * @param request InjectionRequest
     * @return String
     * @throws IOException IOException
     */
    private String GetAsJson(InjectionRequest request) throws IOException {
        return mapper.writeValueAsString(request);
    }

    /**
     * Converts MessageBase object to a MessageJson object
     * @param messageBase The base message to convert
     * @return MessageJson - JSON serializable representation of MessageBase
     */
    private MessageJson generateBaseMessage(MessageBase messageBase) {
        MessageJson messageJson = new MessageJson();

        messageJson.setSubject(messageBase.getSubject());
        messageJson.setPlainTextBody(messageBase.getPlainTextBody());
        messageJson.setHtmlBody(messageBase.getHtmlBody());

        messageJson.setMailingId(messageBase.getMailingId());
        messageJson.setMessageId(messageBase.getMessageId());
        messageJson.setCharSet(messageBase.getCharSet());
        messageJson.setFrom(new AddressJson(messageBase.getFrom().getEmailAddress(), messageBase.getFrom().getFriendlyName()));
        messageJson.setCustomHeaders(populateCustomHeaders(messageBase.getCustomHeaders()));
        messageJson.setAttachments(populateAttachments(messageBase.getAttachments()));

        if (messageBase.getReplyTo() != null) {
            messageJson.setReplyTo(new AddressJson(messageBase.getReplyTo().getEmailAddress(), messageBase.getReplyTo().getFriendlyName()));
        }

        if (messageBase.getApiTemplate() != null) {
            messageJson.setApiTemplate(String.valueOf(messageBase.getApiTemplate()));
        }

        return messageJson;
    }

    /**
     * Converts a List of CustomHeader objects to a List of CustomHeaderJson objects.
     * @param baseCustomHeaders List of CustomHeader objects
     * @return List<CustomHeaderJson>
     */
    private List<CustomHeaderJson> populateCustomHeaders(List<CustomHeader> baseCustomHeaders) {
        if (baseCustomHeaders == null) {
            return null;
        }
        List<CustomHeaderJson> customHeaderJson = new ArrayList<>();

        for (com.socketLabs.injectionApi.message.CustomHeader baseCustomHeader: baseCustomHeaders) {
            customHeaderJson.add(new CustomHeaderJson(baseCustomHeader.getName(), baseCustomHeader.getValue()));
        }
        return customHeaderJson;
    }

    /**
     * Converts a list of Attachment objects to a List of AttachmentJson objects.
     * @param baseAttachments list of Attachment objects
     * @return List<AttachmentJson>
     */
    private List<AttachmentJson> populateAttachments(List<Attachment> baseAttachments) {
        if (baseAttachments == null) {
            return null;
        }
        List<AttachmentJson> attachments = new ArrayList<>();

        for (com.socketLabs.injectionApi.message.Attachment baseAttachment: baseAttachments) {
            AttachmentJson attachment = new AttachmentJson();
            attachment.setContent(baseAttachment.getContent());
            attachment.setContentId(baseAttachment.getContentId());
            attachment.setMimeType(baseAttachment.getMimeType());
            attachment.setName(baseAttachment.getName());
            attachment.setCustomHeaderJsons(populateCustomHeaders(baseAttachment.getCustomHeaders()));
            attachments.add(attachment);
        }

        return attachments;
    }

    /**
     * Converts a List of EmailAddress objects to a List of AddressJson objects.
     * @param baseTo List of EmailAddress objects
     * @return List<AddressJson>
     */
    private List<AddressJson> populateEmailList(List<EmailAddress> baseTo) {
        if (baseTo == null) {
            return null;
        }
        List<AddressJson> addresses = new ArrayList<>();

        for (EmailAddress baseAddress: baseTo) {
            AddressJson address = new AddressJson(baseAddress.getEmailAddress(), baseAddress.getFriendlyName());
            addresses.add(address);
        }

        return addresses;
    }

    /**
     * Loops through a List of BulkRecipient objects,
     * then populates and returns a MergeDataJson object with their merge data.
     * @param global Map<String, String> of global merge data
     * @param recipients List of BulkRecipients
     * @return MergeDataJson
     */
    private MergeDataJson populateMergeData(Map<String, String> global, List<BulkRecipient> recipients) {

        List<List<MergeFieldJson>> perMessageMergeFields = new ArrayList<>();

        for(BulkRecipient recipient : recipients) {
            List<MergeFieldJson> mergeFieldJsonList = generateMergeFieldList(recipient.getMergeData());

            mergeFieldJsonList.add(new MergeFieldJson("DeliveryAddress", recipient.getEmailAddress()));

            if (recipient.getFriendlyName() != null) {
                mergeFieldJsonList.add(new MergeFieldJson("RecipientName", recipient.getFriendlyName()));
            }

            perMessageMergeFields.add(mergeFieldJsonList);
        }

        return new MergeDataJson(perMessageMergeFields, generateMergeFieldList(global));
    }

    /**
     * Converts a HashMap of merge field data into a List of MergeFieldJson objects.
     * @param mergeData Map<String, String> of merge data
     * @return List of MergeFieldJson objects
     */
    private List<MergeFieldJson> generateMergeFieldList(Map<String, String> mergeData) {
        List<MergeFieldJson> mergeFieldJsonList = new ArrayList<>();

        for (Map.Entry<String, String> entry : mergeData.entrySet()) {
            mergeFieldJsonList.add(new MergeFieldJson(entry.getKey(), entry.getValue()));
        }

        return mergeFieldJsonList;
    }
}

