package org.springframework.data.neo4j.events;

import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

/**
 * Created by markangrish on 22/09/2016.
 */
@Component
public class Neo4jModificationEventListener {

	private int preSaveEventCount = 0;
	private int postSaveEventCount = 0;
	private int preDeleteEventCount = 0;
	private int postDeleteEventCount = 0;
	private PreSaveEvent preSaveEvent;
	private PostSaveEvent postSaveEvent;
	private PreDeleteEvent preDeleteEvent;
	private PostDeleteEvent postDeleteEvent;

	@EventListener
	public void onPreSaveEvent(PreSaveEvent event) {
		preSaveEvent = event;
		preSaveEventCount++;
	}

	@EventListener
	public void onPostSaveEvent(PostSaveEvent event) {
		postSaveEventCount++;
		postSaveEvent = event;
	}

	@EventListener
	public void onPreDeleteEvent(PreDeleteEvent event) {
		preDeleteEventCount++;
		preDeleteEvent = event;
	}

	@EventListener
	public void onPostDeleteEvent(PostDeleteEvent event) {
		postDeleteEventCount++;
		postDeleteEvent = event;
	}

	public boolean receivedPreSaveEvent() {
		return preSaveEventCount == 1;
	}

	public boolean receivedPostSaveEvent() {
		return postSaveEventCount == 1;
	}

	public boolean receivedPreDeleteEvent() {
		return preDeleteEventCount == 1;
	}

	public boolean receivedPostDeleteEvent() {
		return postDeleteEventCount == 1;
	}

	public PreSaveEvent getPreSaveEvent() {
		return preSaveEvent;
	}

	public PostSaveEvent getPostSaveEvent() {
		return postSaveEvent;
	}

	public PreDeleteEvent getPreDeleteEvent() {
		return preDeleteEvent;
	}

	public PostDeleteEvent getPostDeleteEvent() {
		return postDeleteEvent;
	}
}

package com.sequenceiq.redbeams.configuration;

import static java.util.concurrent.TimeUnit.MINUTES;
import static java.util.concurrent.TimeUnit.SECONDS;

import java.nio.file.Files;
import java.nio.file.Paths;
import java.sql.SQLException;

import javax.inject.Inject;
import javax.inject.Named;
import javax.persistence.EntityManagerFactory;
import javax.sql.DataSource;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.DependsOn;
import org.springframework.core.env.Environment;
import org.springframework.orm.jpa.JpaTransactionManager;
import org.springframework.orm.jpa.JpaVendorAdapter;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
import org.springframework.orm.jpa.vendor.Database;
import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;

import com.sequenceiq.cloudbreak.common.database.BatchProperties;
import com.sequenceiq.cloudbreak.common.database.JpaPropertiesFacory;
import com.sequenceiq.cloudbreak.common.tx.CircuitBreakerType;
import com.sequenceiq.cloudbreak.util.DatabaseUtil;
import com.sequenceiq.flow.ha.NodeConfig;
import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;

@Configuration
@EnableTransactionManagement
public class DatabaseConfig {

    @Value("${redbeams.db.env.user:}")
    private String dbUser;

    @Value("${redbeams.db.env.pass:}")
    private String dbPassword;

    @Value("${redbeams.db.env.db:}")
    private String dbName;

    @Value("${redbeams.db.env.poolsize:10}")
    private int poolSize;

    @Value("${redbeams.db.env.connectiontimeout:30}")
    private long connectionTimeout;

    @Value("${redbeams.db.env.minidle:2}")
    private int minimumIdle;

    @Value("${redbeams.db.env.idletimeout:10}")
    private long idleTimeout;

    @Value("${redbeams.db.env.schema:" + DatabaseUtil.DEFAULT_SCHEMA_NAME + '}')
    private String dbSchemaName;

    @Value("${redbeams.db.env.ssl:}")
    private boolean ssl;

    @Value("#{'${redbeams.cert.dir:}/${redbeams.db.env.cert.file:}'}")
    private String certFile;

    @Value("${redbeams.hbm2ddl.strategy:validate}")
    private String hbm2ddlStrategy;

    @Value("${redbeams.hibernate.debug:false}")
    private boolean debug;

    @Value("${redbeams.hibernate.circuitbreaker:LOG}")
    private CircuitBreakerType circuitBreakerType;

    @Inject
    @Named("databaseAddress")
    private String databaseAddress;

    @Inject
    private NodeConfig nodeConfig;

    @Inject
    private Environment environment;

    @Bean
    public DataSource dataSource() throws SQLException {
        DatabaseUtil.createSchemaIfNeeded("postgresql", databaseAddress, dbName, dbUser, dbPassword, dbSchemaName);
        HikariConfig config = new HikariConfig();
        if (ssl && Files.exists(Paths.get(certFile))) {
            config.addDataSourceProperty("ssl", "true");
            config.addDataSourceProperty("sslfactory", "org.postgresql.ssl.SingleCertValidatingFactory");
            config.addDataSourceProperty("sslfactoryarg", "file://" + certFile);
        }
        if (nodeConfig.isNodeIdSpecified()) {
            config.addDataSourceProperty("ApplicationName", nodeConfig.getId());
        }
        config.setDriverClassName("io.opentracing.contrib.jdbc.TracingDriver");
        config.setJdbcUrl(String.format("jdbc:tracing:postgresql://%s/%s?currentSchema=%s&traceWithActiveSpanOnly=true", databaseAddress, dbName, dbSchemaName));
        config.setUsername(dbUser);
        config.setPassword(dbPassword);
        config.setMaximumPoolSize(poolSize);
        config.setMinimumIdle(minimumIdle);
        config.setConnectionTimeout(SECONDS.toMillis(connectionTimeout));
        config.setIdleTimeout(MINUTES.toMillis(idleTimeout));
        return new HikariDataSource(config);
    }

    @Bean
    public PlatformTransactionManager transactionManager() throws SQLException {
        JpaTransactionManager jpaTransactionManager = new JpaTransactionManager();
        jpaTransactionManager.setEntityManagerFactory(entityManagerFactory());
        jpaTransactionManager.afterPropertiesSet();
        return jpaTransactionManager;
    }

    @Bean
    @DependsOn("databaseUpMigration")
    public EntityManagerFactory entityManagerFactory() throws SQLException {
        LocalContainerEntityManagerFactoryBean entityManagerFactory = new LocalContainerEntityManagerFactoryBean();

        entityManagerFactory.setPackagesToScan("com.sequenceiq.redbeams", "com.sequenceiq.flow", "com.sequenceiq.cloudbreak.ha");
        entityManagerFactory.setDataSource(dataSource());

        entityManagerFactory.setJpaVendorAdapter(jpaVendorAdapter());
        entityManagerFactory.setJpaProperties(JpaPropertiesFacory.create(hbm2ddlStrategy, debug, dbSchemaName, circuitBreakerType, createBatchProperties()));
        entityManagerFactory.afterPropertiesSet();
        return entityManagerFactory.getObject();
    }

    @Bean
    public JpaVendorAdapter jpaVendorAdapter() {
        HibernateJpaVendorAdapter hibernateJpaVendorAdapter = new HibernateJpaVendorAdapter();
        hibernateJpaVendorAdapter.setShowSql(true);
        hibernateJpaVendorAdapter.setDatabase(Database.POSTGRESQL);
        return hibernateJpaVendorAdapter;
    }

    private BatchProperties createBatchProperties() {
        return new BatchProperties(environment.getProperty("spring.jpa.properties.hibernate.jdbc.batch_size", Integer.class),
                environment.getProperty("spring.jpa.properties.hibernate.order_inserts", Boolean.class),
                environment.getProperty("spring.jpa.properties.hibernate.order_updates", Boolean.class),
                environment.getProperty("spring.jpa.properties.hibernate.jdbc.batch_versioned_data", Boolean.class));
    }
}

package wordhunt;

import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public final class FilePathUtils {
    private FilePathUtils() {}

    /**
     * Build path from directory and file names
     *
     * @param dirName directory name
     * @param fileName file name
     * @return full path to file inside directory
     */
    public static String buildFilePath(String dirName, String fileName) {
        return dirName + File.separator + fileName;
    }

    /**
     * Extract file name from file path
     *
     * @param filePath path to extract file name from
     * @return last part of path
     */
    public static String extractFileName(String filePath) {
        return new File(filePath).getName();
    }

    /**
     * Extract file directory from file path
     *
     * @param filePath
     * @return directory path
     */
    public static String extractFileDir(String filePath) {
        return new File(filePath).getParent();
    }

    /**
     * Build full path from root directory and maybe relative file path
     *
     * @param rootPath
     * @param fileNameRelative
     * @return
     */
    public static String toAbsolutePath(String rootPath, String fileNameRelative) {
        Path path = Paths.get(fileNameRelative);
        Path effectivePath = path;
        if (!path.isAbsolute()) {
            Path base = Paths.get(rootPath);
            effectivePath = base.resolve(path).toAbsolutePath();
        }
        return effectivePath.normalize().toString();
    }

    /**
     * Silent version of getCanonicalPath with path building.
     *
     * @param rootPath
     * @param fileNameRelative
     * @return Canonical file path.
     */
    public static String toCanonicalPath(String rootPath, String fileNameRelative) {
        return toCanonicalPath(toAbsolutePath(rootPath, fileNameRelative));
    }

    /**
     * Silent version of getCanonicalPath with path building.
     *
     * @param filePath
     * @return Canonical file path.
     */
    public static String toCanonicalPath(String filePath) {
        try {
            return new File(filePath).getCanonicalPath();
        } catch (IOException ioe) {
            throw new SearchException("IO error: " + ioe.getMessage(), ioe);
        }
    }

    /**
     * Convert absolute path to relative path
     * @param absolutePath
     * @param rootDir
     * @return
     */
    public static String absoluteToRelativePath(String absolutePath, String rootDir) {
        return new File(rootDir).toURI().relativize(new File(absolutePath).toURI()).getPath();
    }

}

