package chapter07;

import java.util.Scanner;

/*
(Count occurrence of numbers) Write a program that reads the integers between 1
and 100 and counts the occurrences of each. Assume the input ends with 0[SentinelValue]. Here
is a sample run of the program:
Enter the integers between 1 and 100: 2 5 6 5 4 3 23 43 2 0
2 occurs 2 times
3 occurs 1 time
4 occurs 1 time
5 occurs 2 times
6 occurs 1 time
23 occurs 1 time
43 occurs 1 time
*/
public class Exercise07_03 {
    public static void main(String[] args) {

        System.out.println("Enter the integers between 1 and 100: "); // 2 5 6 5 4 3 23 43 2 0
        Scanner input = new Scanner(System.in);
        int[] numbers = new int[100];
        while (true) {
            int count = input.nextInt();
            if (count == 0) break;
            numbers[count - 1]++;
        }
        for (int i = 0; i < numbers.length; i++) {
            if (numbers[i] > 0)
                System.out.println((i + 1) + " occurs " + numbers[i] +
                        " time" + (numbers[i] > 1 ? "s" : ""));
        }
    }
}

public class BubbleSort implements Sort {
    public int[] sort(int arr[]) {
        int len = arr.length;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                int temp;
                if (arr[i] > arr[j]) {
                    temp = arr[j];
                    arr[j] = arr[i];
                    arr[i] = temp;
                }
            }
        }
        System.out.println("ð������");
        return arr;
    }
}

