	public boolean isPrepared() {
		return (user != null);
	}

	@Override
	public int hashCode() {
		final int prime = 1259;
		int result = 432;
		result = prime * result;
		return result;
	}

	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		if (this.userId != ((SelfServiceUsersTabItem)obj).userId)
			return false;

		return true;
	}

	public final static String URL = "service-identities";

