    /**
     * 功能：得到年份月份月底 格式为： (eg: 2016-02-29 23:59:59)<br> 
     * @return String
     * @author pure
     */
    public static String monthEndTime(String year,int month) {
        String strY = null;
        String strZ = null;
        boolean leap = false;
        if (month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 ||month == 12) {
            strZ = "31";
        }else if  (month == 4 ||month == 6 ||month == 9 || month == 11) {
            strZ = "30";
        }else if (month == 2) {
            leap = leapYear(Integer.valueOf(year));
            if (leap) {
                strZ = "29";
            }
            else {
                strZ = "28";
            }
        }
        strY = month >= 10 ? String.valueOf(month) : "0" + month;
        return year + "-" + strY + "-" + strZ+DATE_END;
    }
    /**
     * 功能：判断输入年份是否为闰年<br>
     * 
     * @param year
     * @return 是：true  否：false
     * @author pure
     */
    public static boolean leapYear(int year) {
        boolean leap;
        if (year % 4 == 0) {
            if (year % 100 == 0) {
                if (year % 400 == 0) leap = true;
                else {leap = false;}
            }
            else {leap = true;}
        }
        else {leap = false;}
        return leap;
    }

