            ID: 
             > This class contains the solution for Worksheet2_3a 
             > List Dictionary 
 */


package predictive;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;


/**
 *  ListDictionary class creates a dictionary
 * in a ArrayList with each line containing a WordSig
 * object meaning a word and a signature. Also this class
 * contains the method signatureToWords

 */

public class ListDictionary implements Dictionary{

	private ArrayList<WordSig>dictionary;



	public ListDictionary(String path) {


		Scanner kong = null;


		/**
		 * ArrayList create a new  dictionary that hold all valid words and signature.
		 * 
		 */



		dictionary = new ArrayList<WordSig>();

		try {


			File theFile = new File(path);


			kong = new Scanner(theFile);

			while (kong.hasNext()) {


				String wordTo = kong.next().toLowerCase();


				if (PredictivePrototype.isValidWord(wordTo))


					dictionary.add(new WordSig(wordTo));
			}
		}
		catch (IOException e) {

			System.out.println("We were not able to find the File.");

		} finally {

			kong.close(); 

		}

		Collections.sort(dictionary);
	}

	/**

	 * @param signature is a String
	 * 
	 * @return returns a set of words matching the signature
	 * 
	 */


	public Set<String> signatureToWords(String signature){

		Set<String> suggestion_words = new HashSet<String>();


		WordSig slim = new WordSig("", signature);


		int end = dictionary.size();


		int x= Collections.binarySearch(dictionary, slim);


		int below = x;

		int above = x;


		if (x < 0) {

			return suggestion_words;
		}

		else {




			while (signature.equals(dictionary.get(below).getSignature())) {

				if (!suggestion_words.contains(dictionary.get(below).getWords())) {

					suggestion_words.add(dictionary.get(below).getWords());
				}
				below--;

				if (below<0)

					break;
			}
			while (signature.equals 

					(dictionary.get(above).getSignature())) {

				if (!suggestion_words.contains

						(dictionary.get(above).getWords())) {

					suggestion_words.add(dictionary.get(above).getWords());
				}

				above++;

				if (above>end)

					break;	
			}

		}

		return suggestion_words;
	}

}

package com.uos.uos_mobile.adapter;

import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;

import androidx.appcompat.widget.AppCompatTextView;
import androidx.constraintlayout.widget.ConstraintLayout;
import androidx.recyclerview.widget.RecyclerView;

import com.uos.uos_mobile.item.MovieItem;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;

public class MovieOrderingAdapter extends RecyclerView.Adapter<RecyclerView.ViewHolder> {
    private final ArrayList<MovieItem> movieItemArrayList = new ArrayList<>();  // 예매가능 영화 데이터 목록
    private MovieOrderingAdapter.OnItemClickListener onItemClickListener = null;

    @Override
    public RecyclerView.ViewHolder onCreateViewHolder(ViewGroup parent, int viewType) {
        LayoutInflater layoutInflater = ((LayoutInflater) parent.getContext().getSystemService(Context.LAYOUT_INFLATER_SERVICE));

        return new MovieOrderingAdapter.MovieViewHolder(layoutInflater.inflate(com.uos.uos_mobile.R.layout.item_movieordering, parent, false));
    }

    @Override
    public void onBindViewHolder(RecyclerView.ViewHolder viewHolder, int position) {
        ((MovieViewHolder) viewHolder).tvMovieOrderingMovie.setText(movieItemArrayList.get(position).getMovie());
        ((MovieViewHolder) viewHolder).tvMovieOrderingTime.setText(movieItemArrayList.get(position).getTime());
        ((MovieViewHolder) viewHolder).tvMovieOrderingTheater.setText(movieItemArrayList.get(position).getTheater());
    }

    public void setOnItemClickListener(MovieOrderingAdapter.OnItemClickListener onItemClickListener) {
        this.onItemClickListener = onItemClickListener;
    }

    @Override
    public int getItemCount() {
        return movieItemArrayList.size();
    }

    public MovieItem getItem(int position) {
        return movieItemArrayList.get(position);
    }

    public void setItem(int position, MovieItem movieItem) {
        movieItemArrayList.set(position, movieItem);
    }

    @Override
    public int getItemViewType(int position) {
        return 0;
    }

    public void setJson(JSONArray jsonArray) {
        movieItemArrayList.clear();

        for (int loop = 0; loop < jsonArray.length(); loop++) {
            try {
                JSONObject jsonObject = jsonArray.getJSONObject(loop);

                MovieItem movieItem = new MovieItem();
                movieItem.setSeatListFromJson(jsonObject);

                movieItemArrayList.add(movieItem);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    // 아이템 클릭 리스너 인터페이스
    public interface OnItemClickListener {
        void onItemClick(View view, int position);
    }

    // 영화 뷰 관리자
    public class MovieViewHolder extends RecyclerView.ViewHolder {
        public ConstraintLayout clMovieOrdering;
        public AppCompatTextView tvMovieOrderingMovie;
        public AppCompatTextView tvMovieOrderingTime;
        public AppCompatTextView tvMovieOrderingTheater;

        public MovieViewHolder(View view) {
            super(view);
            clMovieOrdering = view.findViewById(com.uos.uos_mobile.R.id.cl_movieordering);
            tvMovieOrderingMovie = view.findViewById(com.uos.uos_mobile.R.id.tv_movieordering_movie);
            tvMovieOrderingTime = view.findViewById(com.uos.uos_mobile.R.id.tv_movieordering_time);
            tvMovieOrderingTheater = view.findViewById(com.uos.uos_mobile.R.id.tv_movieordering_theater);

            clMovieOrdering.setOnClickListener(view1 -> {
                int position = getAdapterPosition();
                if (position != RecyclerView.NO_POSITION) {
                    if (onItemClickListener != null) {
                        onItemClickListener.onItemClick(view1, position);
                    }
                }
            });
        }
    }
}

