package com.nur1popcorn.irrlicht.engine.mapper;

import com.nur1popcorn.irrlicht.engine.wrappers.Wrapper;
import com.nur1popcorn.irrlicht.engine.wrappers.client.gui.GuiScreen;
import com.nur1popcorn.irrlicht.utils.LoggerFactory;
import javassist.util.proxy.MethodHandler;
import javassist.util.proxy.ProxyFactory;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * The {@link WrapperBridge} is responsible for redirecting method calls to an obfuscated
 * class to the implementation of the {@link Wrapper} it's mapped to.
 *
 * @see ProxyFactory
 * @see Mapper
 * @see Wrapper
 *
 * @author nur1popcorn
 * @since 1.1.0-alpha
 */
public abstract class WrapperBridge implements Wrapper
{
    private Object handle;
    private final Class<? extends Wrapper> clazz;

    public WrapperBridge(Class<? extends Wrapper> clazz)
    {
        this.clazz = clazz;
    }

    @Override
    public final Object getHandle()
    {
        if(handle != null)
            return handle;
        final ProxyFactory proxyFactory = new ProxyFactory();
        final Mapper mapper = Mapper.getInstance();
        proxyFactory.setSuperclass(mapper.getMappedClass(clazz));
        try
        {
            return handle = proxyFactory.create(null, null, new MethodHandler() {
                final Map<Method, Method> methodMap = new HashMap<>();
                {
                    for(Method method : clazz.getDeclaredMethods())
                        methodMap.put(mapper.getMappedMethod(method), method);
                }

                @Override
                public Object invoke(Object proxy, Method thisMethod, Method proceed, Object[] args) throws Throwable
                {
                    final Method method = methodMap.get(thisMethod);
                    if(method != null)
                    {
                        final Class types[] = method.getParameterTypes();
                        final Object handledArgs[] = new Object[args.length];
                        for(int i = 0; i < args.length; i++)
                            handledArgs[i] = Wrapper.class.isAssignableFrom(types[i]) ?
                                    WrapperDelegationHandler.createWrapperProxy((Class<? extends Wrapper>)types[i], args[i]) :
                                    args[i];
                        return method.invoke(this, handledArgs);
                    }
                    return null;
                }
            });
        }
        catch (NoSuchMethodException | InstantiationException | InvocationTargetException | IllegalAccessException e)
        {
            e.printStackTrace();
            throw new RuntimeException("Failed to create WrapperBridge.");
        }
    }
}

package com.github.TKnudsen.timeseries.data.dataGeneration;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Random;

import com.github.TKnudsen.timeseries.data.multivariate.ITimeSeriesMultivariate;
import com.github.TKnudsen.timeseries.data.multivariate.TimeSeriesMultivariate;
import com.github.TKnudsen.timeseries.data.primitives.TimeDuration;
import com.github.TKnudsen.timeseries.data.univariate.ITimeSeriesUnivariate;
import com.github.TKnudsen.timeseries.data.univariate.TimeSeriesUnivariate;

/**
 * <p>
 * Title: SyntheticTimeSeriesGenerator
 * </p>
 * 
 * <p>
 * Description: Generates synthetic time series, e.g., for testing.
 * </p>
 * 
 * <p>
 * Copyright: Copyright (c) 2016
 * </p>
 * 
 * @author Juergen Bernard
 * @version 1.01
 */
public class TimeSeriesGenerator {
	public static ITimeSeriesUnivariate generateSyntheticTimeSeriesUnivariate(long startDate, long endDate,
			TimeDuration quantization, boolean equidistant) {

		List<Long> timeStamps = new ArrayList<>();
		List<Double> values = new ArrayList<>();

		long duration = quantization.getDuration();

		double lastValue = 0.5;
		long l = startDate;
		while (l <= endDate) {
			timeStamps.add(new Long(l));
			values.add(lastValue);

			if (equidistant)
				l += duration;
			else
				l += ((long) (duration * Math.random() * 2));

			lastValue = lastValue + Math.random() * 0.2 - 0.1;
		}

		return new TimeSeriesUnivariate(timeStamps, values, Double.NaN);
	}

	public static ITimeSeriesUnivariate generateSyntheticTimeSeriesUnivariateRandomWalk(double startValue,
			int timeStampCount) {

		List<Long> timeStamps = new ArrayList<>();
		List<Double> values = new ArrayList<>();

		double d = startValue;
		for (long l = 0; l < timeStampCount * 1000; l += 1000) {
			d = Math.min(100, Math.max(0, d + (Math.random() - 0.5) * 10));
			timeStamps.add(l);
			values.add(d);
		}

		return new TimeSeriesUnivariate(timeStamps, values, Double.NaN);
	}

	public static ITimeSeriesUnivariate generateSyntheticTimeSeriesUnivariateRandomWalk(double startValue) {

		List<Long> timeStamps = new ArrayList<>();
		List<Double> values = new ArrayList<>();

		@SuppressWarnings("deprecation")
		Date start = new Date(2016 - 1900, 04, 01);
		@SuppressWarnings("deprecation")
		Date end = new Date(2016 - 1900, 04, 20);
		double d = startValue;
		for (long l = start.getTime(); l < end.getTime(); l += 1000 * 60 * 60) {
			d = Math.min(100, Math.max(0, d + (Math.random() - 0.5) * 10));
			timeStamps.add(l);
			values.add(d);
		}

		return new TimeSeriesUnivariate(timeStamps, values, Double.NaN);
	}

	public static ITimeSeriesMultivariate generateSyntheticTimeSeriesMultivariate(int dimensions, int timeStamps) {
		List<ITimeSeriesUnivariate> bundle = new ArrayList<>();

		for (int i = 0; i < dimensions; i++)
			bundle.add(TimeSeriesGenerator.generateSyntheticTimeSeriesUnivariateRandomWalk(150.0, timeStamps));

		return new TimeSeriesMultivariate(bundle);
	}

	public static ITimeSeriesMultivariate generateSyntheticTimeSeriesMultivariate(long startDate, long endDate,
			int dimensionality, TimeDuration quantization, boolean equidistant) {

		List<Long> timeStamps = new ArrayList<>();
		List<ITimeSeriesUnivariate> timeSeriesUnivariateList = new ArrayList<>();
		List<String> timeSeriesNames = new ArrayList<>();

		long duration = quantization.getDuration();

		long l = startDate;
		while (l <= endDate) {
			timeStamps.add(new Long(l));

			if (equidistant)
				l += duration;
			else
				l += ((long) (duration * Math.random() * 2));
		}

		for (int i = 0; i < dimensionality; i++) {

			List<Long> timeStampsCopy = new ArrayList<>();
			timeStampsCopy.addAll(timeStamps);

			List<Double> values = new ArrayList<>();
			double lastValue = 0.5;

			for (int j = 0; j < timeStampsCopy.size(); j++) {
				values.add(lastValue);
				lastValue = lastValue + Math.random() * 0.2 - 0.1;
			}

			timeSeriesUnivariateList.add(new TimeSeriesUnivariate(timeStampsCopy, values, Double.NaN));
			timeSeriesNames.add("" + i);
		}

		return new TimeSeriesMultivariate(timeSeriesUnivariateList, timeSeriesNames);
	}

	public static ITimeSeriesMultivariate createRandomTSMV(int dim, int timeStamps) {
		List<ITimeSeriesUnivariate> timeSeriesUnivariateList = new ArrayList<>();
		List<Long> timeStampsList;
		List<Double> values;

		for (int i = 0; i < dim; i++) {
			timeStampsList = new ArrayList<>();
			values = new ArrayList<>();
			Random rand = new Random();
			int r = rand.nextInt(10) + 1;
			for (int j = 0; j < timeStamps; j++) {
				double e = rand.nextDouble();
				timeStampsList.add((long) j);
				values.add(Math.sin(r * j * e));
			}

			TimeSeriesUnivariate ts = new TimeSeriesUnivariate(timeStampsList, values);
			timeSeriesUnivariateList.add(ts);
		}

		return new TimeSeriesMultivariate(timeSeriesUnivariateList);
	}

	public static ITimeSeriesMultivariate createSineTSMV(int dim, int timeStamps) {
		List<ITimeSeriesUnivariate> timeSeriesUnivariateList = new ArrayList<>();
		List<Long> timeStampsList;
		List<Double> values;

		for (int i = 0; i < dim; i++) {
			timeStampsList = new ArrayList<>();
			values = new ArrayList<>();
			Random rand = new Random();
			int r = rand.nextInt(10);
			for (int j = 0; j < timeStamps; j++) {
				timeStampsList.add((long) j);
				values.add(Math.sin(r * j));
			}

			TimeSeriesUnivariate ts = new TimeSeriesUnivariate(timeStampsList, values);
			timeSeriesUnivariateList.add(ts);
		}

		return new TimeSeriesMultivariate(timeSeriesUnivariateList);
	}
}

