 *     action.resolve(value + " moge");
 *   });
 *   promise.then((action, value) -> {
 *     response.setContentType("text/html");
 *     response.send(value);
 *   });
 *   promise.error((action, error) -> {
 *     response.sendError(error);
 *   });
 *   promise.start();
 * }
