	 * コンストラクタ.
	 * @param param パラメータを設定します.
	 */
	public Promise(Object param) {
		this.action = new PromiseActionImpl(param);
	}

	/**
	 * コンストラクタ.
	 * @param call 初期実行処理を設定します.
	 */
	public Promise(PromiseFromEndCall call) {
