		checkStartPromiseList(list, len);
		// 新しいPromiseを生成して、そこで登録されたPromise群を実行.
		Promise ret = new Promise((action) -> {
			int i;
			// 既に実行されている場合は例外返却.
			checkStartPromiseList(list, len);
			// 非同期実行.
			for(i = 0; i < len; i ++) {
				list[i].start();
			}
			final PromiseValue[] params = new PromiseValue[len];
			// 実行されたPromise群の待機.
			for(i = 0; i < len; i ++) {
				// 待機結果をリスト取得.
				params[i] = new PromiseValue(
					list[i].getStatus(), list[i].await());
