        for (int i = 0; i < rec.size(); i++) {
            modelL.add(i, rec.get(i));
//            if (rec.get(i).equalsIgnoreCase("default")) {
//                indexOfDefault = i;
//            }
        }
        lst.setModel(modelL);
        //set the default selected
        lst.setSelectedIndex(indexOfDefault);
        lst.repaint();
    }

