package org.cyclops.cyclopscore.ingredient.collection;

import com.google.common.collect.Lists;
import org.cyclops.cyclopscore.ingredient.ComplexStack;
import org.cyclops.cyclopscore.ingredient.IngredientComponentStubs;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;
import java.util.ListIterator;

import static org.hamcrest.CoreMatchers.is;
import static org.hamcrest.CoreMatchers.not;
import static org.hamcrest.MatcherAssert.assertThat;

@RunWith(Parameterized.class)
public class TestIngredientCollectionListComplex {

    private static final ComplexStack CA01_ = new ComplexStack(ComplexStack.Group.A, 0, 1, null);
    private static final ComplexStack CB02_ = new ComplexStack(ComplexStack.Group.B, 0, 2, null);
    private static final ComplexStack CA91B = new ComplexStack(ComplexStack.Group.A, 9, 1, ComplexStack.Tag.B);
    private static final ComplexStack CA01B = new ComplexStack(ComplexStack.Group.A, 0, 1, ComplexStack.Tag.B);

    @Parameterized.Parameters
    public static Collection<Object[]> data() {
        return Arrays.asList(new Object[][] {
                { new IngredientArrayList<>(IngredientComponentStubs.COMPLEX) },
                { new IngredientArrayList<>(IngredientComponentStubs.COMPLEX, 3) },
                { new IngredientArrayList<>(IngredientComponentStubs.COMPLEX, Lists.newArrayList()) },
                { new IngredientArrayList<>(IngredientComponentStubs.COMPLEX, new ComplexStack[0]) },
                { new IngredientLinkedList<>(IngredientComponentStubs.COMPLEX) },
                { new IngredientLinkedList<>(IngredientComponentStubs.COMPLEX, Lists.newArrayList()) },
        });
    }

    @Parameterized.Parameter
    public IngredientList<ComplexStack, Integer> collection;

    @Before
    public void beforeEach() {
        collection.clear();
        collection.add(CA01_);
        collection.add(CB02_);
        collection.add(CA91B);
    }

    @Test
    public void testEquals() {
        assertThat(collection.equals(collection), is(true));
        assertThat(collection.equals("abc"), is(false));
        assertThat(collection.equals(new IngredientCollectionEmpty<>(IngredientComponentStubs.SIMPLE)), is(false));
        assertThat(collection.equals(null), is(false));
        assertThat(collection.equals(new IngredientArrayList<>(IngredientComponentStubs.COMPLEX, CA01_, CB02_, CA91B)), is(true));
        assertThat(collection.equals(new IngredientArrayList<>(IngredientComponentStubs.SIMPLE)), is(false));
        assertThat(collection.equals(new IngredientHashSet<>(IngredientComponentStubs.SIMPLE, Lists.newArrayList(0, 1, 2))), is(false));
    }

    @Test
    public void testHashCode() {
        assertThat(collection.hashCode(), is(collection.hashCode()));
        assertThat(collection.hashCode(), not(is(new IngredientCollectionEmpty<>(IngredientComponentStubs.SIMPLE).hashCode())));
        assertThat(collection.hashCode(), is(new IngredientArrayList<>(IngredientComponentStubs.COMPLEX, CA01_, CB02_, CA91B).hashCode()));
        assertThat(collection.hashCode(), not(is(new IngredientArrayList<>(IngredientComponentStubs.SIMPLE).hashCode())));
    }

    @Test
    public void testGet() {
        assertThat(collection.get(0), is(CA01_));
        assertThat(collection.get(1), is(CB02_));
        assertThat(collection.get(2), is(CA91B));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testGetOutOfBoundsSmall() {
        collection.get(-1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testGetOutOfBoundsLarge() {
        collection.get(3);
    }

    @Test
    public void testSet() {
        assertThat(collection.set(0, CA01B), is(CA01_));

        assertThat(collection.get(0), is(CA01B));
        assertThat(collection.get(1), is(CB02_));
        assertThat(collection.get(2), is(CA91B));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testSetOutOfBoundsSmall() {
        collection.set(-1, CA01B);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testSetOutOfBoundsLarge() {
        collection.set(3, CA01B);
    }

    @Test
    public void testAdd() {
        collection.add(0, CA01B);

        assertThat(collection.get(0), is(CA01B));
        assertThat(collection.get(1), is(CA01_));
        assertThat(collection.get(2), is(CB02_));
        assertThat(collection.get(3), is(CA91B));
    }

    @Test
    public void testAddEnd() {
        collection.add(3, CA01B);

        assertThat(collection.get(0), is(CA01_));
        assertThat(collection.get(1), is(CB02_));
        assertThat(collection.get(2), is(CA91B));
        assertThat(collection.get(3), is(CA01B));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testAddOutOfBoundsSmall() {
        collection.add(-1, CA01B);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testAddOutOfBoundsLarge() {
        collection.add(4, CA01B);
    }

    @Test
    public void testRemove() {
        collection.remove(0);

        assertThat(collection.get(0), is(CB02_));
        assertThat(collection.get(1), is(CA91B));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveOutOfBoundsSmall() {
        collection.remove(-1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveOutOfBoundsLarge() {
        collection.remove(3);
    }

    @Test
    public void testFirstIndexOf() {
        collection.add(CA01_);

        assertThat(collection.firstIndexOf(CA01_), is(0));

        assertThat(collection.firstIndexOf(CA01B), is(-1));
    }

    @Test
    public void testLastIndexOf() {
        collection.add(CA01_);

        assertThat(collection.lastIndexOf(CA01_), is(3));

        assertThat(collection.firstIndexOf(CA01B), is(-1));
    }

    @Test
    public void testListIterator() {
        ListIterator<ComplexStack> it = collection.listIterator();

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(false));
        assertThat(it.nextIndex(), is(0));
        assertThat(it.next(), is(CA01_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.nextIndex(), is(1));
        assertThat(it.next(), is(CB02_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.nextIndex(), is(2));
        assertThat(it.next(), is(CA91B));

        assertThat(it.hasNext(), is(false));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.previousIndex(), is(2));
        assertThat(it.previous(), is(CA91B));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.previousIndex(), is(1));
        assertThat(it.previous(), is(CB02_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.previousIndex(), is(0));
        assertThat(it.previous(), is(CA01_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(false));
    }

    @Test
    public void testListIteratorOffset() {
        ListIterator<ComplexStack> it = collection.listIterator(1);

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.nextIndex(), is(1));
        assertThat(it.next(), is(CB02_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.nextIndex(), is(2));
        assertThat(it.next(), is(CA91B));

        assertThat(it.hasNext(), is(false));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.previousIndex(), is(2));
        assertThat(it.previous(), is(CA91B));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.previousIndex(), is(1));
        assertThat(it.previous(), is(CB02_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(true));
        assertThat(it.previousIndex(), is(0));
        assertThat(it.previous(), is(CA01_));

        assertThat(it.hasNext(), is(true));
        assertThat(it.hasPrevious(), is(false));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testListIteratorOutOfBoundsSmall() {
        collection.listIterator(-1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testListIteratorOutOfBoundsLarge() {
        collection.listIterator(4);
    }

    @Test
    public void testSubList() {
        assertThat(collection.subList(0, 3), is(collection));

        assertThat(collection.subList(2, 3), is(new IngredientArrayList<>(collection.getComponent(), Lists.newArrayList(CA91B))));

        assertThat(collection.subList(1, 2), is(new IngredientArrayList<>(collection.getComponent(), Lists.newArrayList(CB02_))));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testSubListOutOfBoundsSmall() {
        collection.subList(-1, 3);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testSubListOutOfBoundsLarge() {
        collection.subList(0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSubListOutOfBoundsRange() {
        collection.subList(1, 0);
    }

    @Test
    public void testSort() {
        collection.add(CA01B);

        collection.sort(collection.getComponent().getMatcher());

        assertThat(Lists.newArrayList(collection), is(Lists.newArrayList(CA01_, CA01B, CA91B, CB02_)));
    }

    @Test
    public void testSortReverse() {
        collection.sort(collection.getComponent().getMatcher().reversed());

        assertThat(Lists.newArrayList(collection), is(Lists.newArrayList(CB02_, CA91B, CA01_)));
    }

}

package com.batoulapps.QamarDeen.utils;

import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class QamarTime {

    public static Calendar getTodayCalendar() {
        Calendar c = Calendar.getInstance();
        c.set(Calendar.HOUR, 0);
        c.set(Calendar.MINUTE, 0);
        c.set(Calendar.SECOND, 0);
        c.set(Calendar.MILLISECOND, 0);
        c.set(Calendar.AM_PM, Calendar.PM);

        return c;
    }

    public static Calendar getGMTCalendar() {
        Calendar c = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        c.set(Calendar.HOUR, 0);
        c.set(Calendar.MINUTE, 0);
        c.set(Calendar.SECOND, 0);
        c.set(Calendar.MILLISECOND, 0);
        c.set(Calendar.AM_PM, Calendar.PM);

        return c;
    }

    /**
     * given a gmt calendar at 12:00:00, returns the timestamp of a local
     * calendar set at the same date as the gmt calendar at 12:00:00 local
     *
     * @param gmtCal a gmt calendar
     * @return timestamp of 12:00:00 on the same day in the local timezone
     */
    public static long getLocalTimeFromGMT(Calendar gmtCal) {
        return getLocalCalendarFromGMT(gmtCal).getTimeInMillis();
    }

    /**
     * given a gmt calendar at 12:00:00, returns the local calendar
     * set at the same date as the gmt calendar at 12:00:00 local
     *
     * @param gmtCal a gmt calendar
     * @return calendar of 12:00:00 on the same day in the local timezone
     */
    public static Calendar getLocalCalendarFromGMT(Calendar gmtCal) {
        Calendar localTime = getTodayCalendar();
        localTime.set(gmtCal.get(Calendar.YEAR), gmtCal.get(Calendar.MONTH), gmtCal.get(Calendar.DATE));
        return localTime;
    }

    /**
     * given a local calendar at 12:00:00, returns the timestamp of a gmt
     * calendar set at the same date as the local calendar at 12:00:00 gmt
     *
     * @param localCal a local calendar
     * @return timestamp of 12:00:00 on the same day in gmt
     */
    public static long getGMTTimeFromLocal(Calendar localCal) {
        Calendar gmtTime = getGMTCalendar();
        gmtTime.set(localCal.get(Calendar.YEAR), localCal.get(Calendar.MONTH), localCal.get(Calendar.DATE));
        return gmtTime.getTimeInMillis();
    }

    /**
     * given a local date at 12:00:00, returns the timestamp of a gmt
     * calendar set at the same date as the local date at 12:00:00 gmt
     *
     * @param localDate a local date
     * @return timestamp of 12:00:00 on the same day in gmt
     */
    public static long getGMTTimeFromLocalDate(Date localDate) {
        Calendar cal = QamarTime.getTodayCalendar();
        cal.setTime(localDate);
        return QamarTime.getGMTTimeFromLocal(cal);
    }

    public static long getMidnightMillis() {
        Calendar midnight = Calendar.getInstance();
        midnight.set(Calendar.HOUR, 0);
        midnight.set(Calendar.MINUTE, 0);
        midnight.set(Calendar.SECOND, 0);
        midnight.set(Calendar.MILLISECOND, 0);
        midnight.set(Calendar.AM_PM, Calendar.AM);
        midnight.add(Calendar.DATE, 1);

        return midnight.getTimeInMillis();
    }

    public static String getDateFromMillis(long millis) {
        Calendar c = Calendar.getInstance();
        c.setTimeInMillis(millis);
        c.getTime();

        return new SimpleDateFormat("EEE, dd MMM yyyy", Locale.getDefault()).format(c.getTime());
    }
}

package de.robotricker.transportpipes.listener;

import javax.inject.Inject;

import org.bukkit.Chunk;
import org.bukkit.block.Block;
import org.bukkit.block.BlockState;
import org.bukkit.block.BrewingStand;
import org.bukkit.block.DoubleChest;
import org.bukkit.block.Furnace;
import org.bukkit.block.BlastFurnace;
import org.bukkit.block.Smoker;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockExplodeEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.event.world.ChunkLoadEvent;
import org.bukkit.inventory.InventoryHolder;

import de.robotricker.transportpipes.TransportPipes;
import de.robotricker.transportpipes.api.TransportPipesContainer;
import de.robotricker.transportpipes.container.BlockContainer;
import de.robotricker.transportpipes.container.BrewingStandContainer;
import de.robotricker.transportpipes.container.FurnaceContainer;
import de.robotricker.transportpipes.container.SimpleInventoryContainer;
import de.robotricker.transportpipes.duct.Duct;
import de.robotricker.transportpipes.duct.DuctRegister;
import de.robotricker.transportpipes.duct.manager.DuctManager;
import de.robotricker.transportpipes.duct.manager.GlobalDuctManager;
import de.robotricker.transportpipes.duct.manager.PipeManager;
import de.robotricker.transportpipes.duct.pipe.Pipe;
import de.robotricker.transportpipes.location.BlockLocation;
import de.robotricker.transportpipes.location.TPDirection;
import de.robotricker.transportpipes.utils.WorldUtils;

public class TPContainerListener implements Listener {

    @Inject
    private DuctRegister ductRegister;

    @Inject
    private GlobalDuctManager globalDuctManager;

    @Inject
    private TransportPipes transportPipes;

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBlockPlace(BlockPlaceEvent e) {
        notifyBlockUpdate(e.getBlock(), true);
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBlockBreak(BlockBreakEvent e) {
        notifyBlockUpdate(e.getBlock(), false);
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBlockExplode(BlockExplodeEvent e) {
        for (Block b : e.blockList()) {
            notifyBlockUpdate(b, false);
        }
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onEntityExplode(EntityExplodeEvent e) {
        for (Block b : e.blockList()) {
            notifyBlockUpdate(b, false);
        }
    }

    private void notifyBlockUpdate(Block block, boolean place) {
        if (WorldUtils.isContainerBlock(block.getType())) {
            updateContainerBlock(block, place, true);
        }
        if (!place) {
            //undo obfuscation
            Duct duct = globalDuctManager.getDuctAtLoc(block.getLocation());
            if (duct != null) {
                duct.obfuscatedWith(null);
            }
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onChunkLoad(ChunkLoadEvent e) {
        handleChunkLoadSync(e.getChunk(), false);
    }

    public void updateContainerBlock(Block block, boolean add, boolean updateNeighborPipes) {
        PipeManager pipeManager = (PipeManager) (DuctManager<? extends Duct>) ductRegister.baseDuctTypeOf("pipe").getDuctManager();

        BlockLocation blockLoc = new BlockLocation(block.getLocation());
        if (add) {

            if (pipeManager.getContainerAtLoc(block.getLocation()) == null) {
                TransportPipesContainer container = createContainerFromBlock(block);
                pipeManager.getContainers(block.getWorld()).put(blockLoc, container);

                // only update the neighbor pipes if this updateContainerBlock method call is because of a chunk load that was not issued inside the onEnable method
                if (updateNeighborPipes) {
                    for (TPDirection dir : TPDirection.values()) {
                        Duct duct = globalDuctManager.getDuctAtLoc(block.getWorld(), blockLoc.getNeighbor(dir));
                        if (duct instanceof Pipe) {
                            globalDuctManager.updateDuctConnections(duct);
                            globalDuctManager.updateDuctInRenderSystems(duct, true);
                        }
                    }
                }

                transportPipes.runTaskSync(() -> {
                    //checks for double chest neighbor and updates the neighbors TransportPipesContainer if present
                    Block neighborDoubleChestBlock = checkForDoubleChestNeighbor(block);
                    if (neighborDoubleChestBlock != null) {
                        TransportPipesContainer neighborContainer = pipeManager.getContainerAtLoc(neighborDoubleChestBlock.getWorld(), new BlockLocation(neighborDoubleChestBlock.getLocation()));
                        if (neighborContainer instanceof BlockContainer) {
                            ((BlockContainer) neighborContainer).updateBlock();
                        }
                        if (pipeManager.getContainers(block.getWorld()).get(blockLoc) == container) {
                            ((BlockContainer) container).updateBlock();
                        }
                    }
                });

            }

        } else {

            TransportPipesContainer container = pipeManager.getContainerAtLoc(block.getLocation());
            if (container != null) {
                pipeManager.getContainers(block.getWorld()).remove(blockLoc);

                // only update the neighbor pipes if this updateContainerBlock method call is because of a chunk load that was not issued inside the onEnable method
                if (updateNeighborPipes) {
                    for (TPDirection dir : TPDirection.values()) {
                        Duct duct = globalDuctManager.getDuctAtLoc(block.getWorld(), blockLoc.getNeighbor(dir));
                        if (duct instanceof Pipe) {
                            globalDuctManager.updateDuctConnections(duct);
                            globalDuctManager.updateDuctInRenderSystems(duct, true);
                        }
                    }
                }
            }
        }
    }

    public Block checkForDoubleChestNeighbor(Block block) {
        if (block.getState() instanceof InventoryHolder) {
            if (((InventoryHolder) block.getState()).getInventory().getHolder() instanceof DoubleChest) {
                for (TPDirection dir : TPDirection.values()) {
                    if (dir.isSide()) {
                        Block neighborBlock = block.getRelative(dir.getBlockFace());
                        if (neighborBlock.getState() instanceof InventoryHolder) {
                            if (((InventoryHolder) neighborBlock.getState()).getInventory().getHolder() instanceof DoubleChest) {
                                DoubleChest blockChest = (DoubleChest) ((InventoryHolder) block.getState()).getInventory().getHolder();
                                DoubleChest neighborBlockChest = (DoubleChest) ((InventoryHolder) neighborBlock.getState()).getInventory().getHolder();
                                if (blockChest.getLocation().equals(neighborBlockChest.getLocation())) {
                                    return neighborBlock;
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }

    public TransportPipesContainer createContainerFromBlock(Block block) {
        BlockState blockState = block.getState();
        if (blockState instanceof Furnace || blockState instanceof BlastFurnace || blockState instanceof Smoker) {
            return new FurnaceContainer(block);
        } else if (blockState instanceof BrewingStand) {
            return new BrewingStandContainer(block);
        } else if (blockState instanceof InventoryHolder) {
            return new SimpleInventoryContainer(block);
        }
        return null;
    }

    public void handleChunkLoadSync(Chunk loadedChunk, boolean onServerStart) {
        PipeManager pipeManager = (PipeManager) (DuctManager<? extends Duct>) ductRegister.baseDuctTypeOf("pipe").getDuctManager();

        if (loadedChunk.getTileEntities() != null) {
            for (BlockState bs : loadedChunk.getTileEntities()) {
                if (WorldUtils.isContainerBlock(bs.getType())) {

                    //automatically ignores this block if it is already registered as container block
                    updateContainerBlock(bs.getBlock(), true, !onServerStart);

                    //if this block is already registered, update the block, because the blockState object changes after a chunk unload and load
                    TransportPipesContainer container = pipeManager.getContainerAtLoc(bs.getLocation());
                    if (container instanceof BlockContainer) {
                        ((BlockContainer) container).updateBlock();
                    }
                }
            }
        }
    }


}

