package com.android.builder.model;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import java.util.Collection;
import java.util.List;

/**
 * Options for aapt.
 */
public interface AaptOptions {
    enum Namespacing {
        /**
         * Resources are not namespaced.
         *
         * <p>They are merged at the application level, as was the behavior with AAPT1
         */
        DISABLED,
        /**
         * Resources must be namespaced.
         *
         * <p>Each library is compiled in to an AAPT2 static library with its own namespace.
         *
         * <p>Projects using this <em>cannot</em> consume non-namespaced dependencies.
         */
        REQUIRED,
        // TODO: add more modes as implemented.
    }

    /** Returns the value for the --ignore-assets option, or null */
    @Nullable
    String getIgnoreAssets();

    /** Returns the list of values for the -0 (disabled compression) option, or null */
    @Nullable
    Collection<String> getNoCompress();

    /**
     * passes the --error-on-missing-config-entry parameter to the aapt command, by default false.
     */
    boolean getFailOnMissingConfigEntry();

    /** Returns the list of additional parameters to pass. */
    @NonNull
    List<String> getAdditionalParameters();

    /** Returns the resource namespacing strategy for this sub-project */
    @NonNull
    Namespacing getNamespacing();
}

package pl.wavesoftware.utils.stringify.spi.theme;


import org.junit.jupiter.api.Test;
import pl.wavesoftware.utils.stringify.Earth;
import pl.wavesoftware.utils.stringify.Stringify;
import pl.wavesoftware.utils.stringify.TestRepository;
import pl.wavesoftware.utils.stringify.api.Namespace;

import static org.assertj.core.api.Assertions.assertThat;

class ThemeTest {
  private final TestRepository testRepository = new TestRepository();

  @Test
  void prettyPrintTheme() {
    // given
    Earth planet = (Earth) testRepository.createTestPlanet();
    Stringify stringifier = Stringify.of(planet);
    stringifier.theme(new PrettyPrintTheme());
    stringifier.store(Namespace.GLOBAL, store -> store.put("indentation", "  "));
    CharSequence earthHash = hash(planet);
    CharSequence planetSystemHash = hash(planet.getPlanetSystem());
    CharSequence moonHash = hash(planet.getMoon());

    // when
    String result = stringifier.stringify().toString();

    // then
    String expected = format(
      "(Earth#{0}\n" +
        "  name = \"Earth\",\n" +
        "  rocky = true,\n" +
        "  planetSystem = (PlanetSystem#{1}\n" +
        "    planets = ❄️\n" +
        "  ),\n" +
        "  moon = (Moon#{2}\n" +
        "    name = \"Moon\",\n" +
        "    rocky = null,\n" +
        "    planetSystem = (↻️️ PlanetSystem#{1}),\n" +
        "    phase = FULL_MOON,\n" +
        "    visits = {\n" +
        "      \"1969\" => [\"Apollo 11\", \"Apollo 12\"],\n" +
        "      \"1971\" => [\"Apollo 14\", \"Apollo 15\"],\n" +
        "      \"1972\" => [\"Apollo 16\", \"Apollo 17\"]\n" +
        "    }\n" +
        "  ),\n" +
        "  dayOfYear = 14,\n" +
        "  type = 'A'\n" +
        ")",
      earthHash, planetSystemHash, moonHash
    );
    assertThat(result).isEqualTo(expected);
  }

  private String format(String formatStr, Object... args) {
    String work = formatStr;
    for (int i = 0; i < args.length; i++) {
      Object arg = args[i];
      work = work.replace("{" + i + "}", arg.toString());
    }
    assertThat(work).isNotEqualTo(formatStr);
    return work;
  }

  private CharSequence hash(Object object) {
    return Integer.toUnsignedString(System.identityHashCode(object), 36);
  }
}

