package org.apache.flink.runtime.jobmaster.slotpool;

import org.apache.flink.runtime.clusterframework.types.SlotProfile;
import org.apache.flink.runtime.jobmanager.scheduler.Locality;
import org.apache.flink.runtime.jobmaster.SlotInfo;

import javax.annotation.Nonnull;

import java.util.Collection;
import java.util.Optional;

/**
 * Interface for slot selection strategies to be used in the {@link Scheduler}.
 */
public interface SlotSelectionStrategy {

	/**
	 * Selects the best {@link SlotInfo} w.r.t. a certain selection criterion from the provided list of available slots
	 * and considering the given {@link SlotProfile} that describes the requirements.
	 *
	 * @param availableSlots a list of the available slots to select from.
	 * @param slotProfile a slot profile, describing requirements for the slot selection.
	 * @return the selected slot info with the corresponding locality hint.
	 */
	Optional<SlotInfoAndLocality> selectBestSlotForProfile(
		@Nonnull Collection<? extends SlotInfo> availableSlots,
		@Nonnull SlotProfile slotProfile);


	/**
	 * This class is a value type that combines a {@link SlotInfo} with a {@link Locality} hint.
	 */
	final class SlotInfoAndLocality {

		@Nonnull
		private final SlotInfo slotInfo;

		@Nonnull
		private final Locality locality;

		private SlotInfoAndLocality(@Nonnull SlotInfo slotInfo, @Nonnull Locality locality) {
			this.slotInfo = slotInfo;
			this.locality = locality;
		}

		@Nonnull
		public SlotInfo getSlotInfo() {
			return slotInfo;
		}

		@Nonnull
		public Locality getLocality() {
			return locality;
		}

		public static SlotInfoAndLocality of(@Nonnull SlotInfo slotInfo, @Nonnull Locality locality) {
			return new SlotInfoAndLocality(slotInfo, locality);
		}
	}
}

package com.acgist.service;

import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.Objects;

import javax.servlet.http.HttpServletResponse;

import org.springframework.web.multipart.MultipartFile;

import com.acgist.boot.UrlUtils;
import com.acgist.boot.model.MessageCodeException;
import com.acgist.model.entity.BootEntity;
import com.acgist.model.query.FilterQuery;
import com.acgist.service.impl.BootExcelServiceImpl;

/**
 * Web Excel Service
 * 
 * @author acgist
 *
 * @param <T> 类型
 * 
 * @see BootExcelServiceImpl
 */
public interface BootWebExcelService<T extends BootEntity> extends BootExcelService<T> {

	/**
	 * 下载Excel模板
	 * 
	 * @param name 文件名称
	 * @param response 响应
	 */
	default void downloadTemplate(String name, HttpServletResponse response) {
		this.download(name, List.of(), this.header(), response);
	}

	/**
	 * 下载Excel
	 * 
	 * @param name 文件名称
	 * @param query 条件
	 * @param response 响应
	 */
	default void download(String name, FilterQuery query, HttpServletResponse response) {
		this.download(name, query, this.header(), response);
	}

	/**
	 * 下载Excel
	 * 
	 * @param name 文件名称
	 * @param query 条件
	 * @param header 表头
	 * @param response 响应
	 */
	default void download(String name, FilterQuery query, Map<String, ExcelHeaderValue> header, HttpServletResponse response) {
		this.download(name, this.list(query), header, response);
	}

	/**
	 * 下载Excel
	 * 
	 * @param name 文件名称
	 * @param list 数据
	 * @param header 表头
	 * @param response 响应
	 */
	default void download(String name, List<T> list, Map<String, ExcelHeaderValue> header, HttpServletResponse response) {
		try {
			final String downloadName = UrlUtils.encode(Objects.toString(name, this.getEntityClass().getSimpleName()));
			response.setHeader("Content-Type", "application/vnd.ms-excel");
			response.addHeader("Content-Disposition", "attachment;filename=" + downloadName + ".xlsx");
			this.download(list, header, response.getOutputStream());
		} catch (IOException e) {
			throw MessageCodeException.of(e, "下载Excel失败");
		}
	}

	/**
	 * 加载Excel
	 * 
	 * @param file 文件
	 * 
	 * @return 数据
	 */
	default List<List<Object>> load(MultipartFile file) {
		try {
			return this.load(file.getInputStream(), 0);
		} catch (IOException e) {
			throw MessageCodeException.of(e, "读取Excel文件异常");
		}
	}

	/**
	 * 加载Excel
	 * 
	 * @param file 文件
	 * 
	 * @return 数据
	 */
	default List<T> loadEntity(MultipartFile file) {
		return this.load(this.load(file), this.getEntityClass(), this.header());
	}

	/**
	 * 加载Excel
	 * 
	 * @param <K> 类型
	 * 
	 * @param file 文件
	 * @param clazz 返回类型
	 * 
	 * @return 数据
	 */
	default <K> List<K> load(MultipartFile file, Class<K> clazz) {
		return this.load(this.load(file), clazz, this.header());
	}

}

package co.arago.util;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class GetByPathTest {

    private static class ClassData {
        public String classKey = "ClassKeyValue";
        private final String hiddenClassKey = "ClassKeyValue2";
    }

    private final Map<String, Object> data = new HashMap<>();
    private final GetByPath.Flags logFlags = new GetByPath.Flags().setLogErrors(true);
    private final GetByPath.Flags exFlags = new GetByPath.Flags().setThrowExceptions(true).setLogErrors(true);

    @BeforeEach
    void setUp() {
        data.putAll(Map.of("key1", "value1",
                "key2", Map.of("key21", "value21", "key22", "value22", "class", new ClassData()),
                "list", List.of("A", "B", "C", "D"),
                "list2", List.of()));
        data.put("key3", null);
    }

    @Test
    void getWithoutExceptionGood() {
        Object result = GetByPath.newWith("/key2/key22", logFlags).get(data);
        assertEquals(result, "value22");

        result = GetByPath.newWith("/key2/class/classKey", logFlags).get(data);
        assertEquals(result, "ClassKeyValue");

        result = GetByPath.newWith("/list/:last", logFlags).get(data);
        assertEquals(result, "D");

        result = GetByPath.newWith("/list/1", logFlags).get(data);
        assertEquals(result, "B");
    }

    @Test
    void getWithoutExceptionFail() {
        Object result = GetByPath.newWith("/key2/key22/some", logFlags).get(data);
        assertNull(result);

        result = GetByPath.newWith("/key3", logFlags).get(data);
        assertNull(result);

        result = GetByPath.newWith("/key4", logFlags).get(data);
        assertNull(result);

        result = GetByPath.newWith("/key2/class/hiddenClassKey", logFlags).get(data);
        assertNull(result);

        result = GetByPath.newWith("/key2/class/wrongClassKey", logFlags).get(data);
        assertNull(result);

        result = GetByPath.newWith("/list/4", logFlags).get(data);
        assertNull(result);

        result = GetByPath.newWith("/list2/:last", logFlags).get(data);
        assertNull(result);
    }

    @Test
    void getWithException() {
        Assertions.assertThrows(IllegalArgumentException.class,
                () -> GetByPath.newWith("/key2/key22/some", exFlags).get(data));

        Assertions.assertThrows(IllegalArgumentException.class,
                () -> GetByPath.newWith("/key4", exFlags).get(data));

        Assertions.assertThrows(IllegalArgumentException.class,
