import mage.game.events.GameEvent;
import mage.game.events.GameEvent.EventType;
import mage.players.Player;
import mage.target.TargetCard;

/**
 *
 * @author North
 */
public final class PsychicSurgery extends CardImpl {

    public PsychicSurgery(UUID ownerId, CardSetInfo setInfo) {
        super(ownerId, setInfo, new CardType[]{CardType.ENCHANTMENT}, "{1}{U}");

        // Whenever an opponent shuffles their library, you may look at the top two cards of that library.
        // You may exile one of those cards. Then put the rest on top of that library in any order.
        this.addAbility(new PsychicSurgeryTriggeredAbility());
    }

    private PsychicSurgery(final PsychicSurgery card) {
        super(card);
    }

    @Override
    public PsychicSurgery copy() {
        return new PsychicSurgery(this);
    }
}

class PsychicSurgeryTriggeredAbility extends TriggeredAbilityImpl {

    public PsychicSurgeryTriggeredAbility() {
        super(Zone.BATTLEFIELD, new PsychicSurgeryEffect(), true);
    }

    public PsychicSurgeryTriggeredAbility(final PsychicSurgeryTriggeredAbility ability) {
        super(ability);
    }

    @Override
    public PsychicSurgeryTriggeredAbility copy() {
        return new PsychicSurgeryTriggeredAbility(this);
    }

    @Override
    public boolean checkEventType(GameEvent event, Game game) {
        return event.getType() == GameEvent.EventType.LIBRARY_SHUFFLED;
    }

    @Override
    public boolean checkTrigger(GameEvent event, Game game) {
        if (game.getOpponents(controllerId).contains(event.getPlayerId())) {
            this.getEffects().get(0).setValue("PsychicSurgeryOpponent", event.getPlayerId());
            return true;
        }
        return false;
    }

    @Override
    public String getRule() {
        return "Whenever an opponent shuffles their library, " + super.getRule();
    }
}

class PsychicSurgeryEffect extends OneShotEffect {

    public PsychicSurgeryEffect() {
        super(Outcome.Exile);
        this.staticText = "you may look at the top two cards of that library. You may exile one of those cards. Then put the rest on top of that library in any order";
    }

    public PsychicSurgeryEffect(final PsychicSurgeryEffect effect) {
        super(effect);
    }

    @Override
    public PsychicSurgeryEffect copy() {
        return new PsychicSurgeryEffect(this);
    }

    @Override
    public boolean apply(Game game, Ability source) {
        UUID opponentId = (UUID) this.getValue("PsychicSurgeryOpponent");
        Player controller = game.getPlayer(source.getControllerId());
        Player opponent = game.getPlayer(opponentId);

        if (controller != null && opponent != null) {
            Cards cards = new CardsImpl(opponent.getLibrary().getTopCards(game, 2));
            controller.lookAtCards(source, null, cards, game);
            if (!cards.isEmpty() && controller.chooseUse(Outcome.Exile, "Exile a card?", source, game)) {
                TargetCard target = new TargetCard(Zone.LIBRARY, new FilterCard("card to exile"));
                if (controller.choose(Outcome.Exile, cards, target, game)) {
                    Card card = cards.get(target.getFirstTarget(), game);
                    if (card != null) {
                        controller.moveCards(card, Zone.EXILED, source, game);
                        cards.remove(card);
                    }
                }
            }
            controller.putCardsOnTopOfLibrary(cards, game, source, true);
            return true;
        }
        return false;
    }
}

package com.sdu.rocksdb.utils;

import com.sdu.rocksdb.RocksDBMemoryConfiguration;
import com.sdu.rocksdb.RocksDBSharedResources;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import org.rocksdb.Cache;
import org.rocksdb.ColumnFamilyDescriptor;
import org.rocksdb.ColumnFamilyHandle;
import org.rocksdb.ColumnFamilyOptions;
import org.rocksdb.DBOptions;
import org.rocksdb.RocksDB;
import org.rocksdb.RocksDBException;
import org.rocksdb.WriteBufferManager;

/**
 * @author hanhan.zhang
 * */
public class RocksDBOperationUtils {

  /** The name of the merge operator in RocksDB. Do not change except you know exactly what you do. */
  private static final String MERGE_OPERATOR_NAME = "stringappendtest";

  public static RocksDBSharedResources allocateSharedCachesIfConfigured(RocksDBMemoryConfiguration configuration) {
    Cache cache = RocksDBMemoryControllerUtils.createCache(configuration.getTotalMemorySize(),
        configuration.getWriteBufferRatio(), configuration.getHighPriorityPoolRatio());

    WriteBufferManager wbm = RocksDBMemoryControllerUtils.createWriteBufferManager(configuration.getTotalMemorySize(),
        configuration.getWriteBufferRatio(), cache);

    return new RocksDBSharedResources(cache, wbm);
  }


  public static RocksDB openDB(String path,
      List<ColumnFamilyDescriptor> columnFamilyDescriptors,
      List<ColumnFamilyHandle> columnFamilyHandles,
      ColumnFamilyOptions columnFamilyOptions,
      DBOptions dbOptions) throws IOException  {

    List<ColumnFamilyDescriptor> newColumnFamilyDescriptors =
        new ArrayList<>(1 + columnFamilyDescriptors.size());

    // we add the required descriptor for the default CF in FIRST position, see
    // https://github.com/facebook/rocksdb/wiki/RocksJava-Basics#opening-a-database-with-column-families

    newColumnFamilyDescriptors.add(new ColumnFamilyDescriptor(RocksDB.DEFAULT_COLUMN_FAMILY, columnFamilyOptions));
    newColumnFamilyDescriptors.addAll(columnFamilyDescriptors);

    RocksDB dbRef;

    try {
      dbRef = RocksDB.open(dbOptions, path, newColumnFamilyDescriptors, columnFamilyHandles);
    } catch (RocksDBException e) {
      IOUtils.closeQuietly(columnFamilyOptions);
      columnFamilyDescriptors.forEach((cfd) -> IOUtils.closeQuietly(cfd.getOptions()));
      throw new IOException("Error while opening RocksDB instance.", e);
    }

    return dbRef;
  }

  public static ColumnFamilyOptions createColumnFamilyOptions(
      Function<String, ColumnFamilyOptions> columnFamilyOptionsFactory, String stateName) {

    // ensure that we use the right merge operator, because other code relies on this
    return columnFamilyOptionsFactory.apply(stateName).setMergeOperatorName(MERGE_OPERATOR_NAME);
  }

  public static ColumnFamilyHandle createColumnFamily(RocksDB db, String stateName, Function<String, ColumnFamilyOptions> columnFamilyOptionsFactory) {
    /*
     * RocksDB数据存储基于ColumnFamily, 默认数据存储在名为'default'的ColumnFamily列族中
     * */

    // step1: 构建列族描述, ColumnFamilyDescriptor
    ColumnFamilyOptions options = columnFamilyOptionsFactory.apply(stateName).setMergeOperatorName(MERGE_OPERATOR_NAME);
    byte[] nameBytes = stateName.getBytes(StandardCharsets.UTF_8);
    ColumnFamilyDescriptor descriptor = new ColumnFamilyDescriptor(nameBytes, options);

    // step2: 构建列族, ColumnFamilyHandle
    try {
      return db.createColumnFamily(descriptor);
    } catch (RocksDBException e) {
      IOUtils.closeQuietly(descriptor.getOptions());
      throw new RuntimeException("create RocksDb ColumnFamilyHandle failure", e);
    }
  }

}

package com.example.arg_a.moviesapp;

/**
 * Created by arg-a on 24/02/2018.
 */

import android.content.Context;
import android.support.design.widget.BottomNavigationView;
import android.support.design.widget.CoordinatorLayout;
import android.support.v4.view.ViewCompat;
import android.util.AttributeSet;
import android.view.View;
import android.widget.FrameLayout;

public class BottomNavigationBehavior extends CoordinatorLayout.Behavior<BottomNavigationView> {

    public BottomNavigationBehavior() {
        super();
    }

    public BottomNavigationBehavior(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    @Override
    public boolean layoutDependsOn(CoordinatorLayout parent, BottomNavigationView child, View dependency) {
        boolean dependsOn = dependency instanceof FrameLayout;
        return dependsOn;
    }

    @Override
    public boolean onStartNestedScroll(CoordinatorLayout coordinatorLayout, BottomNavigationView child, View directTargetChild, View target, int nestedScrollAxes) {
        return nestedScrollAxes == ViewCompat.SCROLL_AXIS_VERTICAL;
    }

    @Override
    public void onNestedPreScroll(CoordinatorLayout coordinatorLayout, BottomNavigationView child, View target, int dx, int dy, int[] consumed) {
        if (dy < 0) {
            showBottomNavigationView(child);
        } else if (dy > 0) {
            hideBottomNavigationView(child);
        }
    }

    private void hideBottomNavigationView(BottomNavigationView view) {
        view.animate().translationY(view.getHeight());
    }

    private void showBottomNavigationView(BottomNavigationView view) {
        view.animate().translationY(0);
    }
}

package seedu.address.model;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
