            return null;
        }
        return (DConnectMessage) value;
    }

    @Override
    public String toString(final int indent) {
        final StringBuilder builder = new StringBuilder();
        AbstractMessageParser parser = new AbstractMessageParser() {
            private boolean mFirstKey;
            private int mParseInArray;
            private int mFirstArrayValue;
            private int mIndent;

            @Override
            public void startParse() {
            }

            @Override
            public void onKey(final String key) {
                if (!mFirstKey) {
                    builder.append(",");
                }
                appendIndentSpace();

                mFirstKey = false;
                builder.append("\"");
                builder.append(key);
                builder.append("\"");
                builder.append(":");
            }
            @Override
            public void onValue(final Object value) {
                if ((mParseInArray & (1 << mIndent)) != 0) {
                    if ((mFirstArrayValue & (1 << mIndent)) != 0) {
                        builder.append(",");
                    }
                    appendIndentSpace();
                }
                mFirstArrayValue |= (1 << mIndent);
                if (Integer.class.isInstance(value)
                        || Float.class.isInstance(value)
                        || Double.class.isInstance(value)
                        || Long.class.isInstance(value)
                        || Byte.class.isInstance(value)
                        || Short.class.isInstance(value)
                        || Boolean.class.isInstance(value)) {
                    builder.append(value);
                } else if (value == null) {
                    builder.append("null");
                } else {
                    builder.append("\"");
                    builder.append(value);
                    builder.append("\"");
                }
            }
            @Override
            public void startMap() {
                appendIndentSpace();
                builder.append("{");

                mFirstKey = true;
                mIndent++;
            }
            @Override
            public void endMap() {
                mFirstArrayValue &= ~(1 << mIndent);
                mIndent--;
                mFirstArrayValue |= (1 << mIndent);

                appendIndentSpace();
                builder.append("}");
            }
            @Override
            public void startArray() {
                mIndent++;
                if ((mFirstArrayValue & (1 << mIndent)) != 0) {
                    builder.append(",");
                }
                mParseInArray |= (1 << mIndent);
                builder.append("[");
            }
            @Override
            public void endArray() {
                mParseInArray &= ~(1 << mIndent);
                mFirstArrayValue &= ~(1 << mIndent);
                mIndent--;
                mFirstArrayValue |= (1 << mIndent);

                appendIndentSpace();
                builder.append("]");
            }
            @Override
            public void endParse() {
            }

            private void appendIndentSpace() {
                if (indent <= 0) {
                    return;
                }
                if (builder.length() > 0) {
                    appendBreakLine();
                }
                for (int i = 0; i < mIndent * indent; i++) {
                    builder.append(" ");
                }
            }
            private void appendBreakLine() {
                if (indent <= 0) {
                    return;
                }
                builder.append("\n");
            }
        };
        parser.parse(this);

        return builder.toString();
    }

    private static void convertBundleToMap(final Bundle bundle, final DConnectMessage message) throws JSONException {
        if (bundle == null || message == null) {
            return;
        }

        for (String key : bundle.keySet()) {
            Object object = bundle.get(key);
            if (object instanceof Bundle) {
                DConnectMessage m = new BasicDConnectMessage();
                convertBundleToMap((Bundle) object, m);
                message.put(key, m);
            } else if (object instanceof Integer[] || object instanceof Long[] || object instanceof Short[]
                    || object instanceof Byte[] || object instanceof Character[] || object instanceof Float[]
                    || object instanceof Double[] || object instanceof Boolean[] || object instanceof String[]) {
                Object[] bb = (Object[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Integer) {
                message.put(key, ((Integer) object).intValue());
            } else if (object instanceof int[]) {
                int[] bb = (int[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Short) {
                message.put(key, ((Short) object).shortValue());
            } else if (object instanceof short[]) {
                short[] bb = (short[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Character) {
                message.put(key, ((Character) object).charValue());
            } else if (object instanceof char[]) {
                char[] bb = (char[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Byte) {
                message.put(key, ((Byte) object).byteValue());
            } else if (object instanceof byte[]) {
                byte[] bb = (byte[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Long) {
                message.put(key, ((Long) object).longValue());
            } else if (object instanceof long[]) {
                long[] bb = (long[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Float) {
                message.put(key, ((Float) object).floatValue());
            } else if (object instanceof float[]) {
                float[] bb = (float[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Double) {
                message.put(key, ((Double) object).doubleValue());
            } else if (object instanceof double[]) {
                double[] bb = (double[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof Boolean) {
                message.put(key, ((Boolean) object).booleanValue());
            } else if (object instanceof boolean[]) {
                boolean[] bb = (boolean[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    array.add(bb[i]);
                }
                message.put(key, array);
            } else if (object instanceof String) {
                message.put(key, (String) object);
            } else if (object instanceof Bundle) {
                DConnectMessage obj = new BasicDConnectMessage();
                convertBundleToMap((Bundle) object, obj);
                message.put(key, obj);
            } else if (object instanceof Bundle[]) {
                Bundle[] bb = (Bundle[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    DConnectMessage obj = new BasicDConnectMessage();
                    convertBundleToMap(bb[i], obj);
                    array.add(obj);
                }
                message.put(key, array);
            } else if (object instanceof Parcelable[]) {
                Parcelable[] bb = (Parcelable[]) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.length; i++) {
                    DConnectMessage obj = new BasicDConnectMessage();
                    if (bb[i] instanceof Bundle) {
                        convertBundleToMap((Bundle) bb[i], obj);
                    }
                    array.add(obj);
                }
                message.put(key, array);
            } else if (object instanceof Object[]) {
                // プリミティブ型のラッパークラスの配列がObject[]として扱われる場合への対処
                Object[] bb = (Object[]) object;
                if (isPrimitiveWrapperArray(bb)) {
                    List array = new ArrayList();
                    for (int i = 0; i < bb.length; i++) {
                        array.add(bb[i]);
                    }
                    message.put(key, array);
                }
            } else if (object instanceof List<?>) {
                List<?> bb = (List<?>) object;
                List array = new ArrayList();
                for (int i = 0; i < bb.size(); i++) {
                    Object v = bb.get(i);
                    if (v instanceof Bundle) {
                        DConnectMessage obj = new BasicDConnectMessage();
                        convertBundleToMap((Bundle) v, obj);
                        array.add(obj);
                    } else if (v instanceof Parcelable) {
                        DConnectMessage obj = new BasicDConnectMessage();
                        convertBundleToMap((Bundle) v, obj);
                        array.add(obj);
                    } else {
                        array.add(bb.get(i));
                    }
                }
                message.put(key, array);
            }
        }
    }

    private static void convertJSONToMap(final JSONObject root, final DConnectMessage message) throws JSONException {
        if (root == null || message == null) {
            return;
        }

        Iterator it = root.keys();
        while (it.hasNext()) {
            String key = (String) it.next();
            Object object = root.get(key);
            if (object instanceof JSONObject) {
                DConnectMessage m = new BasicDConnectMessage();
                convertJSONToMap((JSONObject) object, m);
                message.put(key, m);
            } else if (object instanceof JSONArray) {
                JSONArray jsonArray = (JSONArray) object;

                int length = jsonArray.length();
                List<Object> array = new ArrayList<>(length);
                for (int i = 0; i < length; i++) {
                    Object obj = jsonArray.get(i);
                    if (obj instanceof JSONObject) {
                        DConnectMessage m = new BasicDConnectMessage();
                        convertJSONToMap((JSONObject) obj, m);
                        array.add(m);
                    } else {
                        array.add(obj);
                    }
                }

                message.put(key, array);
            } else {
                message.put(key, object);
            }
        }
    }
    /**
     * 指定したObject[]がプリミティブ型のラッパークラスの配列であるかどうかをチェックする.
     * <p>
     * なお、配列のすべての要素の型が同一でない場合、falseを返す.
     * 例えば、以下のような場合.
     * </p>
     * <pre>
     * {new Integer(0), new Double(0.0d)} // falseを返す
     * </pre>
     * @param array チェックするオブジェクト配列
     * @return プリミティブ型のラッパークラスの配列である場合はtrue、そうでない場合はfalse
     */
    private static boolean isPrimitiveWrapperArray(final Object[] array) {
        String classNameCache = null;
        for (int i = 0; i < array.length; i++) {
            Object obj = array[i];
            if (obj != null) {
                if (isPrimitiveWrapper(obj)) {
                    String className = obj.getClass().getName();
                    if (classNameCache != null) {
                        if (!classNameCache.equals(className)) {
                            return false;
                        }
                    } else {
                        classNameCache = className;
                    }
                } else {
                    return false;
                }
            }
        }
        return true;
    }


    /**
     * 指定したObjectがプリミティブ型のラッパークラスであるかどうかをチェックする.
     *
     * @param obj チェックするオブジェクト
     * @return プリミティブ型のラッパークラスである場合はtrue、そうでない場合はfalse
     */
    private static boolean isPrimitiveWrapper(final Object obj) {
        return obj instanceof Byte || obj instanceof Short || obj instanceof Integer
                || obj instanceof Long || obj instanceof Float || obj instanceof Double
                || obj instanceof Character || obj instanceof Boolean;
    }
    /**
     * List<Object>へキャストする.
     * @param list リスト
     * @return キャストされたリスト
     */
    @SuppressWarnings("unchecked")
    private List<Object> castListObject(final List<?> list) {
        return (List<Object>) list;
    }
}

package jam.io;

import java.io.File;
import java.io.IOException;

import jam.app.JamLogger;
import jam.lang.JamException;
import jam.util.RegexUtil;

/**
 * Provides utility methods for operating on files and file names.
 *
 * <p>All methods wrap checked exceptions ({@code IOException}s) in
 * runtime exceptions.
 */
public final class FileUtil {
    private FileUtil() {}

    /**
     * Creates a required directory (including all nonexistent parent
     * directories) if it does not already exist.
     *
     * @param dir the required directory.
     *
     * @throws RuntimeException if the input directory does not exist
     * and cannot be created, or if the {@code dir} path does exist
     * but is not a directory.
     */
    public static void ensureDir(File dir) {
	if (!dir.exists()) {
	    boolean success = dir.mkdirs();

	    if (success)
                JamLogger.info("Created directory [%s]...", dir.getAbsolutePath());
            else
		throw JamException.runtime("Failed to create directory [%s].", dir.getAbsolutePath());
	}
        else if (!dir.isDirectory()) {
            throw JamException.runtime("Path [%s] exists but is not a directory.", dir.getAbsolutePath());
        }
    }

    /**
     * Creates a required directory (including all nonexistent parent
     * directories) if it does not already exist.
     *
     * @param dirName the name of the required directory.
     *
     * @throws RuntimeException if the input directory does not exist
     * and cannot be created, or if the {@code dir} path does exist
     * but is not a directory.
     */
    public static void ensureDir(String dirName) {
        ensureDir(new File(dirName));
    }

    /**
     * Creates the parent directories of a file if they do not already
     * exist (e.g., before attempting to open a new file for writing).
     *
     * @param file the file of interest.
     *
     * @throws RuntimeException if the parent directories did not
     * already exist and could not be created.
     */
    public static void ensureParentDirs(File file) {
        ensureDir(FileUtil.getParentFile(file));
    }

    /**
     * Determines whether a file exists.
     *
     * @param fileName the name of the file to check.
     *
     * @return {@code true} iff a file with the specified name exists.
     */
    public static boolean exists(String fileName) {
        File file = new File(fileName);
        return file.exists();
    }

    /**
     * Returns the basename of a file: the last name in the path
     * sequence.
     *
     * @param file the file of interest.
     *
     * @return the basename of the specified file.
     */
    public static String getBaseName(File file) {
        return file.getName();
    }

    /**
     * Returns the prefix of the basename of a file: the substring of
     * the basename before the first dot.
     *
     * @param file the file of interest.
     *
     * @return the basename prefix of the specified file.
     */
    public static String getBaseNamePrefix(File file) {
        return getPrefix(getBaseName(file));
    }

    private static String getPrefix(String fileName) {
        return RegexUtil.DOT.split(fileName)[0];
    }

    /**
     * Returns the canonical form of the specified file but never
     * throws checked exceptions.
     *
     * @param file a file to examine.
     *
     * @return the canonical form of the specified file.
     *
     * @throws RuntimeException if {@code file.getCanonicalPath}
     * throws an {@code IOException}.
     */
    public static File getCanonicalFile(File file) {
        return new File(getCanonicalPath(file));
    }

    /**
     * Returns the canonical path of the specified file but never
     * throws checked exceptions.
     *
     * @param file a file to examine.
     *
     * @return the canonical path of the specified file.
     *
     * @throws RuntimeException if {@code file.getCanonicalPath}
     * throws an {@code IOException}.
     */
    public static String getCanonicalPath(File file) {
        String result = null;

        try {
            result = file.getCanonicalPath();
        }
        catch (IOException ioex) {
            throw JamException.runtime(ioex);
        }

        return result;
    }

    /**
     * Returns the canonical <em>prefix</em> of the specified file
     * (everything before the first dot in the canonical path) but
     * never throws checked exceptions.
     *
     * @param file a file to examine.
     *
     * @return the canonical prefix of the specified file.
     *
     * @throws RuntimeException if {@code file.getCanonicalPath}
     * throws an {@code IOException}.
     */
    public static String getCanonicalPrefix(File file) {
        return getPrefix(getCanonicalPath(file));
    }

    /**
     * Returns the name of the parent directory of a file, or
     * {@code .} (dot) if the file does not specify a parent.
     *
     * <p>Unlike the method {@code java.io.File.getParent}, this
     * method never returns {@code null}.
     *
     * @param file a file to examine.
     *
     * @return the name of the parent directory of the specified file,
     * or {@code .} (dot) if the file does not specify a parent.
     */
    public static String getDirName(File file) {
	String result = file.getParent();

	if (result == null)
	    result = ".";

	return result;
    }

    /**
     * Returns the parent directory of a file, or the "dot" directory
     * if the file does not specify a parent.
     *
     * <p>Unlike the method {@code java.io.File.getParentFile}, this
     * method never returns {@code null}.
     *
     * @param file a file to examine.
     *
     * @return the parent directory of the specified file, or the
     * "dot" directory if the file does not specify a parent.
     */
    public static File getParentFile(File file) {
	return new File(getDirName(file));
    }

    /**
     * Identifies canonical files.
     *
     * @param file a file to examine.
     *
     * @return {@code true} iff the specified file has a canonical
     * path name.
     */
    public static boolean isCanonicalFile(File file) {
        return file.equals(getCanonicalFile(file));
    }

    /**
     * Builds a composite file name by joining components with the
     * system-dependent name separator.
     *
     * @param dirName the first directory in the composite path.
     *
     * @param pathNames the subdirectories and final base name in
     * the composite path.
     *
     * @return the composite file name.
     */
    public static String join(String dirName, String... pathNames) {
        StringBuilder builder = new StringBuilder(dirName);

        for (String pathName : pathNames) {
            builder.append(File.separator);
            builder.append(pathName);
        }

        return builder.toString();
    }

    /**
     * Creates a new file by building a composite file name.
     *
     * @param dirName the first directory in the composite path.
     *
     * @param pathNames the subdirectories and final base name in
     * the composite path.
     *
     * @return a new file with the composite file name.
     */
    public static File newFile(String dirName, String... pathNames) {
        return new File(join(dirName, pathNames));
    }

    /**
     * Asserts that a file exists.
     *
     * @param fileName the name of the required file.
     *
     * @throws RuntimeException if the file does not exist.
     */
    public static void requireFile(String fileName) {
        requireFile(new File(fileName));
    }

    /**
     * Asserts that a file exists.
     *
     * @param file the required file.
     *
     * @throws RuntimeException if the file does not exist.
     */
    public static void requireFile(File file) {
        if (!file.exists())
            throw JamException.runtime("File [%s] does not exist.", getCanonicalPath(file));
    }
}

