package com.buguagaoshu.homework.evaluation.repository.impl;

import com.buguagaoshu.homework.evaluation.config.TokenAuthenticationHelper;
import com.buguagaoshu.homework.common.domain.FileModel;
import com.buguagaoshu.homework.common.domain.VditorFiles;
import com.buguagaoshu.homework.evaluation.repository.FileStorageRepository;
import com.buguagaoshu.homework.common.utils.FileUtil;
import com.buguagaoshu.homework.evaluation.utils.JwtUtil;
import io.jsonwebtoken.Claims;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Repository;
import org.springframework.web.multipart.MultipartFile;

import javax.servlet.http.HttpServletRequest;
import java.io.File;
import java.io.FileNotFoundException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * @author Pu Zhiwei {@literal puzhiweipuzhiwei@foxmail.com}
 * create          2020-06-10 11:38
 * 将文件存储在本地
 */
@Repository
@Slf4j
public class FileSystemFileStorageServiceImpl implements FileStorageRepository {
    private final FileUtil fileUtil;


    public FileSystemFileStorageServiceImpl(FileUtil fileUtil) {
        this.fileUtil = fileUtil;
    }

    @Override
    public Map<String, String> createUploadUrl(String objectName, String userId, Map<String, String> params) {
        return null;
    }

    @Override
    public VditorFiles save(MultipartFile[] files,
                            String userId,
                            Map<String, String> params,
                            HttpServletRequest request) {
        VditorFiles vditorFiles = new VditorFiles();
        vditorFiles.setCode(1);
        List<String> errFiles = new ArrayList<>();
        if (files.length > FileUtil.ONCE_UPLOAD_FILE_NUMBER) {
            for (MultipartFile f : files) {
                errFiles.add(f.getOriginalFilename());
            }
            vditorFiles.setMsg("一次最多上传文件不能超过9个！");
            Map<String, Object> data = new HashMap<>(2);
            data.put("errFiles", errFiles);
            vditorFiles.setData(data);
            return vditorFiles;
        }
        boolean isFlag = false;
        // 检查上传文件大小

        for (MultipartFile f : files) {
            if (f.getSize() > FileUtil.MAX_FILE_SIZE) {
                isFlag = true;
                vditorFiles.setMsg("单个文件大小最大不能超过 20M！");
            }
            errFiles.add(f.getOriginalFilename());
        }
        if (isFlag) {
            Map<String, Object> data = new HashMap<>(2);
            data.put("errFiles", errFiles);
            vditorFiles.setData(data);
            return vditorFiles;
        }
        // 检查文件上传格式
        // TODO 如果时头像，格式必须是图片
        // TODO 检查上传作业时的上传权限
        for (MultipartFile file : files) {
            String fileName = file.getOriginalFilename();
            if (!fileUtil.checkSuffix(fileName)) {
                vditorFiles.setMsg("不支持的文件格式！");
                return vditorFiles;
            }
        }

        // 处理文件保存
        Map<String, Object> succMap = new HashMap<>(2);
        errFiles = new ArrayList<>();
        for (MultipartFile file : files) {
            String fileName = file.getOriginalFilename();
            FileModel fileModel = fileUtil.filePath(fileName, userId, params.get("type"), params.get("homework"));

            String pathName = fileModel.getPath() + "/" + fileModel.getFilename();
            File dest = new File(fileModel.getPath());
            //判断文件父目录是否存在
            if (!dest.exists() && !dest.mkdirs()) {
                vditorFiles.setMsg("上传失败，请重试");
                return vditorFiles;
            }
            try {
                Files.copy(file.getInputStream(), Paths.get(fileModel.getPath(), fileModel.getFilename()));

                // succMap.put(fileName, fileUtil.getWebsite() + "/" + pathName);
                // TODO 有待优化
                succMap.put(fileName, "/api/" + pathName);
            } catch (Exception e) {
                errFiles.add(fileName);
            }
        }
        Map<String, Object> data = new HashMap<>(2);
        vditorFiles.setCode(0);
        vditorFiles.setMsg("上传成功");
        data.put("succMap", succMap);
        data.put("errFiles", errFiles);
        vditorFiles.setData(data);
        return vditorFiles;
    }

    @Override
    public Path load(String path, String filename) throws FileNotFoundException {
        return Paths.get(path, filename);
    }

    @Override
    public Map<String, String> save(MultipartFile file, String course, HttpServletRequest request) {
        Claims user = JwtUtil.getNowLoginUser(request, TokenAuthenticationHelper.SECRET_KEY);
        FileModel fileModel = fileUtil.coursewareFilePath(file.getOriginalFilename(), course, user.getId());
        String pathName = fileModel.getPath() + "/" + fileModel.getFilename();
        File dest = new File(fileModel.getPath());
        HashMap<String, String> map = new HashMap<>(2);
        //判断文件父目录是否存在
        if (!dest.exists() && !dest.mkdirs()) {
            return null;
        }
        try {
            Files.copy(file.getInputStream(), Paths.get(fileModel.getPath(), fileModel.getFilename()));
            map.put("filename", file.getOriginalFilename());
            map.put("path", "/api/" + pathName);
        } catch (Exception e) {
            log.error("教师 {} 上传课件： {} 出现异常: {}", user.getId(), file.getOriginalFilename(), e.getMessage());
            return null;
        }
        return map;
    }
}

package unitTest.electricity;

import java.util.Calendar;


public class ElectricityMeter {

    TariffProvider tp;

    private float kwh = 0;
    private int centsForKwh = 0;

    private boolean tariffOn = false;
    private float kwhTariff = 0;
    private int centsForKwhTariff = 0;

    private int electricityTariffStartHour = 0;
    private int electricityTariffEndHour = 0;

    public ElectricityMeter() {
        tp = new TariffProvider() {
            @Override
            public boolean isTariffNow() {
                Calendar rightNow = Calendar.getInstance();
                int hour = rightNow.get(Calendar.HOUR_OF_DAY);
                return hour > electricityTariffStartHour && hour < electricityTariffEndHour;
            }
        };
    }

    public ElectricityMeter(TariffProvider tp) {
        this.tp = tp;
    }

    public void addKwh(float kwhToAdd) {
        if (isTariffNow()) {
            kwhTariff += kwhToAdd;
        } else {
            kwh += kwhToAdd;
        }
    }

    public boolean isTariffNow() {
        return tp.isTariffNow();
    }

    /**
     * @return how much more expensive is normal price comparing to tariff in percentages
     */

    public int getHowMoreExpensiveNormalIs() {
        return (centsForKwh * 100 / centsForKwhTariff) - 100;
    }

    public float getKwh() {
        return kwh;
    }

    public float getKwhTariff() {
        return kwhTariff;
    }

    void setCentsForKwh(int centsForKwh) {
        this.centsForKwh = centsForKwh;
    }

    void setTariffOn(boolean tariffOn) {
        this.tariffOn = tariffOn;
    }

    void setCentsForKwhTariff(int centsForKwhTariff) {
        this.centsForKwhTariff = centsForKwhTariff;
    }

    void setElectricityTariffStartHour(int electricityTariffStartHour) {
        this.electricityTariffStartHour = electricityTariffStartHour;
    }

    void setElectricityTariffEndHour(int electricityTariffEndHour) {
        this.electricityTariffEndHour = electricityTariffEndHour;
    }

    public void reset() {
        this.kwh = 0;
        this.centsForKwh = 0;
        this.tariffOn = false;
        this.kwhTariff = 0;
        this.centsForKwhTariff = 0;
        this.electricityTariffStartHour = 0;
        this.electricityTariffEndHour = 0;
    }
}

