	@Test
	public void compressionActivatedOnClientAddsHeader() {
		AtomicReference<String> zip = new AtomicReference<>("fail");

		HttpServer server = HttpServer.create()
		                              .port(0)
		                              .compress(true);
		DisposableServer runningServer =
				server.handle((in, out) -> out.sendString(Mono.just("reply")))
				      .wiretap()
				      .bindNow(Duration.ofSeconds(10));
		HttpClient client = HttpClient.create()
				                      .addressSupplier(() -> address(runningServer))
				                      .wiretap()
				                      .compress(true);

		ByteBuf resp =
				client.headers(h -> zip.set(h.get("accept-encoding")))
				      .get()
				      .uri("/test")
				      .responseContent()
				      .blockLast();

		assertThat(zip.get()).isEqualTo("gzip");
		runningServer.dispose();
		runningServer.onDispose()
				.block();
	}

	private InetSocketAddress address(DisposableServer runningServer) {
		return runningServer.address();
	}

	@Test
	public void testIssue282() {
		DisposableServer server =
				HttpServer.create()
				          .compress(2048)
				          .port(0)
				          .handle((req, res) -> res.sendString(Mono.just("testtesttesttesttest")))
				          .bindNow();

		Mono<String> response =
				HttpClient.create()
				          .port(server.address().getPort())
				          .get()
				          .uri("/")
				          .responseContent()
				          .aggregate()
				          .asString();

		StepVerifier.create(response)
		            .expectNextMatches(s -> "testtesttesttesttest".equals(s))
		            .expectComplete()
		            .verify();

		server.dispose();
	}

	@Test
	public void testIssue292() {
		DisposableServer server =
				HttpServer.create()
				          .compress(10)
				          .port(0)
				          .wiretap()
				          .handle((req, res) ->
				                  res.sendHeaders().sendString(Flux.just("test", "test", "test", "test")))
				          .bindNow();

		Mono<String> response =
				HttpClient.create()
				          .port(server.address().getPort())
				          .compress(true)
				          .wiretap()
				          .get()
				          .uri("/")
				          .responseContent()
				          .aggregate()
				          .asString();

		StepVerifier.create(response)
		            .expectNextMatches(s -> "testtesttesttest".equals(s))
		            .expectComplete()
		            .verify();

		response = HttpClient.create()
		                     .port(server.address().getPort())
		                     .wiretap()
		                     .compress(true)
		                     .get()
		                     .uri("/")
		                     .responseContent()
		                     .aggregate()
		                     .asString();

		StepVerifier.create(response)
		            .expectNextMatches(s -> "testtesttesttest".equals(s))
		            .expectComplete()
		            .verify();

		server.dispose();
	}
}

