package joshua.lattice;

import org.testng.Assert;
import org.testng.annotations.Test;

/**
 * Unit tests for Node class.
 * 
 * @author Lane Schwartz
 * @since 2008-07-09
 * @version $LastChangedDate$
 */
@Test(groups = { "lattice_node" })
public class NodeTest {

	private final int id = 12345;

	private Node<String> node;

	@Test
	public void constructNode() {

		node = new Node<String>(id);

		Assert.assertEquals((int) node.id, (int) id);
		Assert.assertTrue(node.outgoingArcs.isEmpty());
		Assert.assertEquals(node.size(), 0);

	}


	@Test(dependsOnMethods = { "constructNode" })
	public void getNumber() {

		Assert.assertEquals(node.getNumber(), id);

	}


	@Test(dependsOnMethods = { "constructNode" })
	public void toStringTest() {

		Assert.assertEquals(node.toString(), "Node-"+id);

	}


	@Test(dependsOnMethods = { "constructNode", "joshua.lattice.ArcTest.constructArc" })
	public void addArc() {

		Node<String> n2 = new Node<String>(2);
		double w2 = 0.123;
		String l2 = "somthing cool";

		Node<String> n3 = new Node<String>(3);
		double w3 = 124.78;
		String l3 = "hurray!";

		Node<String> n4 = new Node<String>(4);
		double w4 = Double.POSITIVE_INFINITY;
		String l4 = "\u0000";

		Assert.assertEquals(node.size(), 0);

		node.addArc(n2, w2, l2);
		Assert.assertEquals(node.size(), 1);
		Arc<String> a2 = node.outgoingArcs.get(0);
		Assert.assertEquals(a2.head, node);
		Assert.assertEquals(a2.tail, n2);
		Assert.assertEquals(a2.cost, w2);
		Assert.assertEquals(a2.label, l2);

		node.addArc(n3, w3, l3);
		Assert.assertEquals(node.size(), 2);
		Arc<String> a3 = node.outgoingArcs.get(1);
		Assert.assertEquals(a3.head, node);
		Assert.assertEquals(a3.tail, n3);
		Assert.assertEquals(a3.cost, w3);
		Assert.assertEquals(a3.label, l3);

		node.addArc(n4, w4, l4);
		Assert.assertEquals(node.size(), 3);
		Arc<String> a4 = node.outgoingArcs.get(2);
		Assert.assertEquals(a4.head, node);
		Assert.assertEquals(a4.tail, n4);
		Assert.assertEquals(a4.cost, w4);
		Assert.assertEquals(a4.label, l4);

	}
}

package com.prismaqf.callblocker.utils;

import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ArrayAdapter;
import android.widget.CheckBox;
import android.widget.CompoundButton;
import android.widget.TextView;

import com.prismaqf.callblocker.EditFilterPatterns;
import com.prismaqf.callblocker.R;
import com.prismaqf.callblocker.rules.FilterRule;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

/**
 * @author ConteDiMonteCristo
 */
public class PatternAdapter extends ArrayAdapter<String> {
    private final FilterRule myRule;
    private final Set<String> myChecked;
    private final EditFilterPatterns myActivity;

    public PatternAdapter(Context context, FilterRule rule, ArrayList<String> checked) {
        super(context, 0, new ArrayList<>(rule.getPatternKeys()));
        myActivity = (EditFilterPatterns)context;
        myRule = rule;
        if (checked != null)
            myChecked = new HashSet<>(checked);
        else
            myChecked = new HashSet<>();
    }

    public void resetChecked() {
        myChecked.clear();
    }

    @Override
    public View getView(final int position, View convertView, ViewGroup parent) {
        final String pattern = getItem(position);
        // Check if an existing view is being reused, otherwise inflate the view
        if (convertView == null) {
            convertView = LayoutInflater.from(getContext()).inflate(R.layout.filter_pattern_record, parent, false);
        }
        // Lookup view for data population
        TextView tv_pattern = (TextView) convertView.findViewById(R.id.text_pattern);
        CheckBox cb_pattern = (CheckBox) convertView.findViewById(R.id.cb_pattern);
        // Populate the data into the template view using the data object
        tv_pattern.setText(pattern);
        if (myChecked.contains(pattern)) cb_pattern.setChecked(true);

        cb_pattern.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener() {

            @Override
            public void onCheckedChanged(CompoundButton buttonView, boolean isChecked) {
                if (buttonView.isChecked())
                    myChecked.add(pattern);
                else
                    myChecked.remove(pattern);
                if (myActivity!= null) myActivity.validateActions();
            }
        });
        return convertView;
    }

    @Override
    public void add(String pattern) {
        myRule.addPattern(pattern);
        super.clear();
        super.addAll(myRule.getPatternKeys());
        if (myActivity!= null) myActivity.validateActions();
    }

    @Override
    public void remove(String pattern) {
        myRule.removePattern(pattern);
        super.clear();
        super.addAll(myRule.getPatternKeys());
        if (myActivity!= null) myActivity.validateActions();
    }

    public void replace(String oldPattern, String newPattern) {
        myRule.removePattern(oldPattern);
        myRule.addPattern(newPattern);
        super.clear();
        super.addAll(myRule.getPatternKeys());
        if (myActivity!= null) myActivity.validateActions();
    }

    public FilterRule getRule() {
        return myRule;
    }

    public ArrayList<String> getMyChecked() {
        return new ArrayList<>(myChecked);
    }
}

