public class DatabaseClient extends Thread {
    private static final LoggerHolder LOG = new LoggerHolder(DatabaseClient.class);
    private static DatabaseClient instance = null;

    private static final String[] sendDatabaseUrls = new String[]
    {
            "api_port/port",
            "api_get_member/kdock",
            "api_get_member/ship2",
            "api_get_member/ship3",
            "api_get_member/slot_item",
            "api_get_member/mapinfo",
            "api_req_hensei/change",
            "api_req_kousyou/createship",
            "api_req_kousyou/getship",
            "api_req_kousyou/createitem",
            "api_req_map/start",
            "api_req_map/next",
            "api_req_map/select_eventmap_rank",
            "api_req_sortie/battle",
            "api_req_battle_midnight/battle",
            "api_req_battle_midnight/sp_midnight",
            "api_req_sortie/night_to_day",
            "api_req_sortie/battleresult",
            "api_req_combined_battle/airbattle",
            "api_req_combined_battle/battle",
            "api_req_combined_battle/midnight_battle",
            "api_req_combined_battle/sp_midnight",
            "api_req_combined_battle/battleresult",
            "api_req_sortie/airbattle",
            "api_req_combined_battle/battle_water",
            "api_req_combined_battle/sp_midnight"
    };

    private static class QueueItem {
        public UndefinedData data;

        public QueueItem(UndefinedData data) {
            this.data = data;
        }
    }

    private static synchronized DatabaseClient getInstance() {
        if (instance == null) {
            instance = new DatabaseClient();
            instance.start();
        }
        return instance;
    }

    public static void send(UndefinedData data) {
        if (AppConfig.get().isSendDatabase() && (AppConfig.get().getAccessKey().length() > 0)) {
            for (String entry : sendDatabaseUrls)
            {
                if (data.getUrl().endsWith(entry))
                {
                    getInstance().dataQueue.offer(new QueueItem(data));
                    break;
                }
            }
        }
    }

    public static synchronized void end() {
        if (instance != null) {
            instance.endRequested = true;
            instance.dataQueue.offer(new QueueItem(null));
            try {
                instance.join();
                instance = null;
            } catch (InterruptedException e) {
                LOG.get().fatal("DatabaseClientスレッド終了時に何かのエラー", e);
            }
        }
    }

    /** この正規表現イミフになりつつある・・・ */
    private final Pattern apiTokenPattern = Pattern
            .compile("&api(_|%5F)token=[0-9a-f]+|api(_|%5F)token=[0-9a-f]+&?");

    private final BlockingQueue<QueueItem> dataQueue = new ArrayBlockingQueue<>(32);

    private HttpClient httpClient = null;

    private boolean endRequested = false;

    private Request createRequest(UndefinedData data) throws UnsupportedEncodingException {
        // api_tokenを取り除く
        String origRequest = new String(data.getRequest(), "UTF-8");
        String sendRequestBody = this.apiTokenPattern.matcher(origRequest).replaceAll("");
        String sendResponseBody = new String(data.getResponse(), "UTF-8");
        UrlEncoded body = new UrlEncoded();
        body.add("token", AppConfig.get().getAccessKey());
        // このクライアントのエージェントキー
        body.add("agent", "6nENnnGzRgSTVeuU652r");
        body.add("url", data.getFullUrl());
        body.add("requestbody", sendRequestBody);
        body.add("responsebody", sendResponseBody); //
        return this.httpClient.POST("http://api.kancolle-db.net/2/")
                .agent("logbook/v" + AppConstants.VERSION)
                .content(new StringContentProvider(body.encode()), "application/x-www-form-urlencoded");
    }

    /* (非 Javadoc)
     * @see java.lang.Thread#run()
     */
    @Override
    public void run() {
        try {
            int skipCount = 0;
            int errorCount = 0;
            this.httpClient = new HttpClient();
            this.httpClient.setExecutor(new QueuedThreadPool(2, 1));
            this.httpClient.setMaxConnectionsPerDestination(2);
            this.httpClient.start();

            while (true) {
                final UndefinedData data = this.dataQueue.take().data;
                if (this.endRequested) {
                    return;
                }
                if (skipCount > 0) {
                    --skipCount;
                    continue;
                }
                for (int retly = 0;; ++retly) {
                    String errorReason = null;
                    try {
                        // 60秒でタイムアウト
                        Request request = this.createRequest(data).timeout(60, TimeUnit.SECONDS);
                        ContentResponse response = request.send();
                        if (this.endRequested) {
                            return;
                        }
                        if (HttpStatus.isSuccess(response.getStatus())) {
                            // 成功したらエラーカウンタをリセット
                            skipCount = errorCount = 0;
                            // ログに出す
                            if (AppConfig.get().isDatabaseSendLog()) {
                                Display.getDefault().asyncExec(new Runnable() {
                                    @Override
                                    public void run() {
                                        try {
                                            if (!ApplicationMain.main.getShell().isDisposed()) {
                                                String url = data.getUrl();
                                                ApplicationMain.main.printMessage("DBへ送信しました("
                                                        + url.substring(url.lastIndexOf('/') + 1) + ")");
                                            }
                                        } catch (Exception e) {
                                            LOG.get().warn("DB送信でエラー", e);
                                        }
                                    }
                                });
                            }
                            break;
                        }
                        else {
                            errorReason = response.getReason();
                        }
                    } catch (Exception e) {
                        errorReason = e.getMessage();
                    }
                    if (errorReason != null) {
                        // 少し時間をおいてリトライ
                        Thread.sleep(1000);
                        if (this.endRequested) {
                            return;
                        }
                        if (retly >= 4) {
                            // リトライが多すぎたらエラーにする
                            skipCount = (errorCount++) * 4;
                            LOG.get().warn("データベースへの送信に失敗しました. " + errorReason);
                            if (skipCount > 0) {
                                LOG.get().warn("以降 " + skipCount + " 個の送信をスキップします.");
                            }
                            break;
                        }
                    }
                }
            }

        } catch (Exception e) {
            if (!this.endRequested) {
                LOG.get().fatal("スレッドが異常終了しました", e);
            }
        } finally {
            if (this.httpClient != null) {
                try {
                    this.httpClient.stop();
                } catch (Exception e) {
                    LOG.get().fatal("HttpClientの終了に失敗", e);
                }
            }
        }
    }
}

package org.webpieces.nio.api;

import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import org.webpieces.util.futures.XFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import org.junit.Assert;
import org.junit.Test;
import org.webpieces.data.api.TwoPools;
import org.webpieces.nio.api.channels.TCPChannel;
import org.webpieces.nio.api.channels.TCPServerChannel;
import org.webpieces.nio.api.mocks.MockConnectionListener;
import org.webpieces.nio.api.mocks.MockMulithreadedSslDataListener;
import org.webpieces.util.threading.NamedThreadFactory;

import io.micrometer.core.instrument.Metrics;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;

public class TestSslOverLocalhost {

	private MockMulithreadedSslDataListener mockSvrDataListener = new MockMulithreadedSslDataListener();
	private MockConnectionListener mockConnListener = new MockConnectionListener(mockSvrDataListener);
	private MockMulithreadedSslDataListener mockClientDataListener = new MockMulithreadedSslDataListener();

	@Test
	public void testBasic() throws InterruptedException, ExecutionException, TimeoutException {
		ChannelManager svrMgr = createSvrChanMgr("server");
		SelfSignedSSLEngineFactory sslFactory = new SelfSignedSSLEngineFactory();
		TCPServerChannel svrChannel = svrMgr.createTCPServerChannel("svrChan", mockConnListener, sslFactory);
		svrChannel.bind(new InetSocketAddress(8444));

		int port = svrChannel.getLocalAddress().getPort();

		//don't really need to use a separate chan mgr but we will here..
		ChannelManager chanMgr = createSvrChanMgr("client");
		TCPChannel channel = chanMgr.createTCPChannel("client", sslFactory.createEngineForClient("cvs.xsoftware.biz", port));
		XFuture<Void> future = channel.connect(new InetSocketAddress("localhost", port), mockClientDataListener);
		future.get();

		byte[] data = new byte[] {0, 2, 4, 6, 8, 10};
		ByteBuffer buf = ByteBuffer.wrap(data);
		channel.write(buf);

		ByteBuffer result = mockSvrDataListener.getFirstBuffer().get(2, TimeUnit.SECONDS);

		byte[] newData = new byte[result.remaining()];
		result.get(newData);

		Assert.assertEquals(data.length, newData.length);
		for(int i = 0; i < data.length; i++) {
			Assert.assertEquals(data[i], newData[i]);
		}

		//verify sniServerName was used in looking up security cert.
		String host = sslFactory.getCachedHost();
		Assert.assertEquals("cvs.xsoftware.biz", host);
	}

	private ChannelManager createSvrChanMgr(String name) {
		ExecutorService executor = Executors.newFixedThreadPool(10, new NamedThreadFactory(name));
		ChannelManagerFactory factory = ChannelManagerFactory.createFactory(Metrics.globalRegistry);
		ChannelManager svrMgr = factory.createMultiThreadedChanMgr(name+"Mgr", new TwoPools("pl", new SimpleMeterRegistry()), new BackpressureConfig(), executor);
		return svrMgr;
	}
}

