                new QueryWrapper<CategoryEntity>()
        );

        return new PageUtils(page);
    }

    @Override
    public List<CategoryEntity> listWithTree() {
        //1、查出所有分类
        List<CategoryEntity> entities = baseMapper.selectList(null);
        //2、组装成父子的树形结构
            //2.1)、找到所有的一级分类。parent_cid=0
//        List<CategoryEntity> level1Menus = entities.stream().filter((categoryEntity) -> {
//            return categoryEntity.getParentCid() == 0;
//        }).collect(Collectors.toList());

            //2.2）、找子分类
         List<CategoryEntity> level1Menus = entities.stream().filter((categoryEntity) -> {
            return categoryEntity.getParentCid() == 0;
         }).map((menu) -> {
             menu.setChildren(getChildrens(menu,entities));
             return menu;
         }).sorted((menu1,menu2) -> {
             return (menu1.getSort() == null?0:menu1.getSort()) - (menu2.getSort() == null?0:menu2.getSort());
         }).collect(Collectors.toList());

         return level1Menus;
    }

    @Override
    public void removeMenuByIds(List<Long> asList) {

        //TODO 1、检查当前删除的菜单，是否被别的地方引用
        //批量删除

        //逻辑删除
        baseMapper.deleteBatchIds(asList);
    }

    //[2/25/225]
    @Override
    public Long[] findCatelogPath(Long catelogId) {
        List<Long> paths = new ArrayList<>();
        List<Long> parentPath = findParentPath(catelogId, paths);

        //逆序转换[225/25/2] => [2/25/225]
        Collections.reverse(parentPath);

        return parentPath.toArray(new Long[parentPath.size()]);
    }

    //查询所有的一级分类
    @Override
    public List<CategoryEntity> getLevel1Categorys() {
        List<CategoryEntity> categoryEntities = baseMapper.selectList(new QueryWrapper<CategoryEntity>().eq("parent_cid", 0));
        return categoryEntities;
    }

    @Override
    public Map<String, List<Catelog2Vo>> getCatelogJson() {

        //1、查出所有1级分类
        List<CategoryEntity> level1Categorys = getLevel1Categorys();

        //2、封装数据
        Map<String, List<Catelog2Vo>> parent_cid = level1Categorys.stream().collect(Collectors.toMap(k -> k.getCatId().toString(), v -> {

            //1、每一个的1级分类，查到这个1级分类的所有2级分类
            List<CategoryEntity> categoryEntities = baseMapper.selectList(new QueryWrapper<CategoryEntity>().eq("parent_cid", v.getCatId()));

            //2、封装上面的结果
            List<Catelog2Vo> catelog2Vos = null;
            //非空判断
            if (categoryEntities != null) {
                //遍历
                catelog2Vos = categoryEntities.stream().map(l2 -> {
                    Catelog2Vo catelog2Vo = new Catelog2Vo(v.getCatId().toString(), null, l2.getCatId().toString(), l2.getName());
                    //1、当前2级分类的3级分类 封装成vo
                    List<CategoryEntity> level3Catelog = baseMapper.selectList(new QueryWrapper<CategoryEntity>().eq("parent_cid", l2.getCatId()));
                    if(level3Catelog!=null){
                        List<Catelog2Vo.Catelog3Vo> collect = level3Catelog.stream().map(l3 -> {
                            //2、3级分类不为空 封装成指定格式
                            Catelog2Vo.Catelog3Vo catelog3Vo = new Catelog2Vo.Catelog3Vo(l2.getCatId().toString(), l3.getCatId().toString(), l3.getName());
                            return catelog3Vo;
                        }).collect(Collectors.toList());
                        catelog2Vo.setCatalog3List(collect);
                    }
                    return catelog2Vo;
                }).collect(Collectors.toList());
            }
            return catelog2Vos;
        }));
        return parent_cid;
    }

    //225 => 225的父亲25 => 25的父亲2
    private List<Long> findParentPath(Long catelogId,List<Long> paths){
        //1、收集当前节点id
        paths.add(catelogId);
        CategoryEntity byId = this.getById(catelogId);
        if(byId.getParentCid()!=0){
            findParentPath(byId.getParentCid(),paths);
        }
        return paths;
    }

    //递归查找所有菜单的子菜单
    private List<CategoryEntity> getChildrens(CategoryEntity root, List<CategoryEntity> all){
        List<CategoryEntity> children = all.stream().filter(categoryEntity->{
            return categoryEntity.getParentCid() == root.getCatId();
        }).map(categoryEntity -> {
            //1、找到子菜单
            categoryEntity.setChildren(getChildrens(categoryEntity,all));
            return categoryEntity;
        }).sorted((menu1,menu2) -> {
            //2、菜单的排序
            return (menu1.getSort() == null?0:menu1.getSort()) - (menu2.getSort() == null?0:menu2.getSort());
        }).collect(Collectors.toList());
    return children;
    }


}

package edu.java.thread;

import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

//video: advance multi thread - 01
public class LockEx {

	/**
	 * @param args
	 */

	public static void showSema(){
		MyPool mypool = new MyPool(20);
		ExecutorService threadPool = Executors.newFixedThreadPool(2);
		MyThread2 t1 = new MyThread2("A", mypool,13);
		MyThread2 t2 = new MyThread2("B", mypool,12);
		threadPool.execute(t1);
		threadPool.execute(t2);

		threadPool.shutdown();

	}

	public static void showSema2(){
		Runnable runner = new Runnable(){
			Random ran = new Random();
			Semaphore signal = new Semaphore(3);
			public void run() {
				int time = ran.nextInt(10);
				try {
					signal.acquire();

					String name = Thread.currentThread().getName();
					System.out.println(name + "running, need to wait:"+time+"");
					Thread.sleep(time*1000);
					System.out.println(name+"finished");
					signal.release();
				} catch(InterruptedException e){
					e.printStackTrace();
				}
			}
		};
		for(int i = 0 ;i<10;i++){
			new Thread(runner).start();
		}
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		showSema2();

	}

}

class MyPool {
	private Semaphore sp;
	// signal sum size
	MyPool(int size) {
		 this.sp = new Semaphore(size);
	}

	public Semaphore getSp() {
		return sp;
	}


}

class MyThread2 extends Thread {
	private String threadname;
	private MyPool pool;
	private int x;

	MyThread2(String threadname, MyPool pool, int x){
		this.threadname = threadname;
		this.pool = pool;
		this.x = x;
	}

	public void run() {
		try{
			pool.getSp().acquire(x);

			System.out.println(threadname + "success" + x +"permission");

			Thread.sleep(300);
		} catch(InterruptedException e){
			e.printStackTrace();
		} finally{
			pool.getSp().release(x);
			System.out.println(threadname +" released"+x+" permission");
		}
	}
}

package com.sjhy.plugin.ui;

import com.intellij.ide.util.PackageChooserDialog;
import com.intellij.openapi.fileChooser.FileChooser;
