package com.intel.cosbench.driver.web;

import static com.intel.cosbench.model.MissionState.*;

import javax.servlet.http.*;

import org.apache.commons.lang.StringUtils;
import org.springframework.web.servlet.ModelAndView;

import com.intel.cosbench.model.MissionInfo;
import com.intel.cosbench.service.DriverService;
import com.intel.cosbench.web.*;

public class WorkersPageController extends AbstractController {

    protected DriverService driver;

    public void setDriver(DriverService driver) {
        this.driver = driver;
    }

    @Override
    protected ModelAndView process(HttpServletRequest req,
            HttpServletResponse res) throws Exception {
        String id = req.getParameter("id");
        if (StringUtils.isEmpty(id))
            throw new BadRequestException();
        MissionInfo info = driver.getMissionInfo(id);
        if (info == null)
            throw new NotFoundException();
        return createResult(info);
    }

    private static ModelAndView createResult(MissionInfo info) {
        ModelAndView result = new ModelAndView("workers");
        result.addObject("info", info);
        result.addObject("isStopped", isStopped(info.getState()));
        result.addObject("isRunning", isRunning(info.getState()));
        return result;
    }

}

package org.qiunet.utils.test.collection.safeCollections;

import org.junit.Assert;
import org.junit.Test;
import org.qiunet.utils.collection.safe.SafeList;

import java.util.Iterator;

/**
 * @author qiunet
 *         Created on 17/3/1 16:47.
 */
public class TestSafeList {
	@Test
	public void testSafeList(){
		SafeList<String> list = new SafeList<>();
		list.add("a");
		list.add("b");
		list.convertToUnmodifiable();
		Assert.assertTrue(list.contains("a"));
		boolean exception = false;
		try {
			list.add("c");
		}catch (Exception e){
			exception = true;
		}
		Assert.assertTrue(exception);

		exception = false;
		try {
			for(Iterator<String> it = list.iterator(); it.hasNext();){
				String po = it.next();
				if("a".equals(po)){
					it.remove();
					continue;
				}

			}
		}catch (Exception e){
			exception = true;
		}
		Assert.assertTrue(exception);

	}
}

