import org.junit.Test;

import cn.itcast.h3.util.H3Util;

public class QBCApp {
	//Criteria基础实例
	@Test
	public void qbc1(){
		Session s = H3Util.getSession();
		//获取Criteria对象
		Criteria c = s.createCriteria(UserModel.class);
		List list = c.list();
		System.out.println(list);
		
		s.close();
	}
	//QBC查询单个属性
	@Test
	public void qbc2(){
		Session s = H3Util.getSession();
		//获取Criteria对象
		Criteria c = s.createCriteria(UserModel.class);
		//只查询单个属性
		Property p = Property.forName("age");
		c.setProjection(p);
		
		List<Integer> list = c.list();
		System.out.println(list);
		
		s.close();
	}
	//QBC查询多个属性
	@Test
	public void qbc3(){
		Session s = H3Util.getSession();
		//获取Criteria对象
		Criteria c = s.createCriteria(UserModel.class);
		//查询多个属性
		//1.将要查询的属性声明
		Property p1 = Property.forName("age");
		Property p2 = Property.forName("userName");
		//2.将这些属性放入到一个属性列表对象中
		ProjectionList plist = Projections.projectionList();
		//3.将属性添加到列表对象中
		plist.add(p1);
		plist.add(p2);
		//4.将属性列表对象设置到查询的模型中
		c.setProjection(plist);
		
		List<Object[]> list = c.list();
		for(Object[] objs:list){
			for(Object obj:objs){
				System.out.print(obj+"\t");
			}
			System.out.println();
