	public CaliType _writeSeek(Environment env, ArrayList<CaliType> args) {
		synchronized(this) {
			int index = (int)((CaliInt)args.get(0)).getValue();
			if((index >= 0)&&(index < buff.length)) {
				this.writeCursor = index;
			} else {
