	public CaliType byteToBinary(Environment env, ArrayList<CaliType> args) {
		int index = (int)((CaliInt)args.get(0)).getValue();
		if((index >= 0)&&(index < buff.length)) {
			String bin = Integer.toBinaryString((this.buff[index] + 256) % 256);
