package org.apache.hadoop.mapreduce.lib.output.committer.manifest;

import java.io.DataOutputStream;
import java.io.IOException;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FSDataOutputStream;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.compress.CompressionCodec;
import org.apache.hadoop.io.compress.GzipCodec;
import org.apache.hadoop.mapreduce.MRJobConfig;
import org.apache.hadoop.mapreduce.OutputFormat;
import org.apache.hadoop.mapreduce.TaskAttemptContext;
import org.apache.hadoop.mapreduce.lib.output.TextOutputFormat;
import org.apache.hadoop.util.ReflectionUtils;

/**
 * A subclass of {@link TextOutputFormat} which logs what is happening, and
 * returns a {@link LoggingLineRecordWriter} which allows the caller
 * to get the destination path.
 * @param <K> key
 * @param <V> value
 */
public class TextOutputForTests<K, V> extends TextOutputFormat<K, V> {

  private static final Logger LOG =
      LoggerFactory.getLogger(TextOutputForTests.class);

  public static final String NAME
      = "org.apache.hadoop.fs.s3a.commit.LoggingTextOutputFormat";

  @Override
  public LoggingLineRecordWriter<K, V> getRecordWriter(TaskAttemptContext job)
      throws IOException, InterruptedException {
    Configuration conf = job.getConfiguration();
    boolean isCompressed = getCompressOutput(job);
    String keyValueSeparator = conf.get(SEPARATOR, "\t");
    CompressionCodec codec = null;
    String extension = "";
    if (isCompressed) {
      Class<? extends CompressionCodec> codecClass =
          getOutputCompressorClass(job, GzipCodec.class);
      codec = ReflectionUtils.newInstance(codecClass, conf);
      extension = codec.getDefaultExtension();
    }
    Path file = getDefaultWorkFile(job, extension);
    FileSystem fs = file.getFileSystem(conf);
    FSDataOutputStream fileOut = fs.create(file, true);
    LOG.debug("Creating LineRecordWriter with destination {}", file);
    if (isCompressed) {
      return new LoggingLineRecordWriter<>(
          file, new DataOutputStream(codec.createOutputStream(fileOut)),
          keyValueSeparator);
    } else {
      return new LoggingLineRecordWriter<>(file, fileOut, keyValueSeparator);
    }
  }

  /**
   * Write a line; counts the number of lines written and logs @ debug in the
   * {@code close()} call.
   * @param <K> key
   * @param <V> value
   */
  public static class LoggingLineRecordWriter<K, V>
      extends LineRecordWriter<K, V> {

    private final Path dest;

    private long lines;

    public LoggingLineRecordWriter(Path dest, DataOutputStream out,
        String keyValueSeparator) {
      super(out, keyValueSeparator);
      this.dest = dest;
    }

    public LoggingLineRecordWriter(DataOutputStream out, Path dest) {
      super(out);
      this.dest = dest;
    }

    @Override
    public synchronized void write(K key, V value) throws IOException {
      super.write(key, value);
      lines++;
    }

    public synchronized void close(TaskAttemptContext context)
        throws IOException {
      LOG.debug("Closing output file {} with {} lines :{}",
          dest, lines, out);
      out.close();
    }

    public Path getDest() {
      return dest;
    }

    public long getLines() {
      return lines;
    }
  }

  /**
   * Bind to a configuration for job submission.
   * @param conf configuration
   */
  public static void bind(Configuration conf) {
    conf.setClass(MRJobConfig.OUTPUT_FORMAT_CLASS_ATTR,
        TextOutputForTests.class,
        OutputFormat.class);
  }
}

package com.akie.java;


/*
* 一、设计类，其实就是设计类的成员
*
* 属性 = 成员变量 = field = 域、字段
* 方法 = 成员方法 = 函数 = method
*
*二、类和对象的使用（面向对象思想落地的实现）
* 1、创建类，设计类的成员
* 2、创建类的对象
* 3、通过“对象.属性” “对象.方法”调用对象的结构
*
* 三、如果创建了一个类的对个对象，则每个对象都独立的拥有一套类的属性（非static的）
*
* 四、对象的内存解析
* */
//测试类
public class PersonTest {
    public static void main(String[] args) {
        //创建Person类的对象
        Person p1 = new Person();
        //Scanner scanner = new Scanner(System.in);

        //调用对象的结构：属性、方法
        //调用属性：“对象.属性”
        p1.name = "Tom";
        p1.isMale = true;
        System.out.println(p1.name);

        //调用方法：“对象.方法”
        p1.eat();
        p1.sleep();
        p1.talk("Chinese");

        //*****************************************
        Person p2 = new Person();
        System.out.println(p2.name);// null
        System.out.println(p2.isMale);// false

        //*****************************************
        //地址赋给p3
        Person p3 = p1;
        System.out.println(p3.name);// Tom

        p3.age = 10;
        System.out.println(p1.age); // 10

    }

}

class Person {

    //属性
    String name;
    int age = 1;
    boolean isMale;

    //方法
    public void eat(){
        System.out.println("人可以吃饭");
    }

    public void sleep() {
        System.out.println("人可以睡觉");
    }

    public void talk(String language){
        System.out.println("人可以说话，使用的是：" + language);
    }
}

package  week4.calculator;

import java.util.*;

public class Lijst 
{
  private Entry header;
  private int size;

  // Constructor voor een lege lijst
  public Lijst() 
  {
    header = new Entry( null, null, null );
    header.next = header;
    header.previous = header;
  }

  // Object vooraan toevoegen
  public void addFirst( Object o ) 
  {
    addBefore( o, header.next );
  }

  // Object vooraan opvragen
  public Object getFirst() 
  {
	  return header.next.element;
  }

  // Object vooraan verwijderen
  public Object removeFirst() 
  {
	  Entry delete = header.next;
	  remove(header.next);
	  return delete.element;	
  }
  
  public void addLast( Object o ) 
  {
    addAfter( o, header.previous );
  }

  // Object vooraan opvragen
  public Object getLast() 
  {
	  return header.previous.element;
  }

  // Object vooraan verwijderen
  public Object removeLast() 
  {
	  Entry delete = header.previous;
	  remove(header.previous);
	  return delete.element;	
  }


  // Aantal objecten in de lijst afleveren
  public int size() 
  {
    return size;
  }

  // De lijst leegmaken
  public void clear() 
  {
	  header.next = header;
	  header.previous = header;
	  size = 0;
  }
  
  public boolean isEmpty() 
  {
	 if(size == 0)
	 {
		 return true;
	 }
	 else
	 {
		 return false;
	 }
  }

  // Lever een iterator voor de lijst
  public Iterator iterator() 
  {
    return new LItr();
  }

  // private methoden

  private void addBefore( Object o, Entry e ) 
  {
    Entry newEntry = new Entry(o, e, e.previous);
    newEntry.previous.next = newEntry;
    newEntry.next.previous = newEntry;
    size++;
  }
  
  private void addAfter( Object o, Entry e ) 
  {
    Entry newEntry = new Entry(o, e.next, e);
    newEntry.previous.next = newEntry;
    newEntry.next.previous = newEntry;
    size++;
  }

  private void remove( Entry e ) 
  {
    if( e == header )
      throw new NoSuchElementException( 
        "Kan Entry niet verwijderen: is header" );

    e.previous.next = e.next;
    e.next.previous = e.previous;
    size--;
  }

  // Inwendige klasse LItr
  private class LItr implements Iterator 
  {
    private Entry pos = header;

    public boolean hasNext() 
    {
      return pos.next != header;
    }

    public Object next() 
    {
      pos = pos.next;
      return pos.element;
    }

    public boolean hasPrevious() 
    {
      return pos.previous != header;
    }

    public Object previous() 
    {
      pos = pos.previous;
      return pos.element;
    }
  } // Einde inwendige klasse LItr


  // Inwendige klasse Entry
  private class Entry 
  {
    Object element;
    Entry next;
    Entry previous;

    Entry( Object element, Entry next, Entry previous ) 
    {
      this.element = element;
      this.next = next;
      this.previous = previous;
    }
  } // Einde inwendige klasse Entry

} // Einde klasse Lijst

package com.momia.service.impl;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Map;

import javax.annotation.Resource;
import javax.servlet.http.HttpServletRequest;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.PreparedStatementCreator;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;

import com.momia.entity.Goods;
import com.momia.entity.TopicGoods;
import com.momia.service.GoodsService;

/**
 * 商品推荐
 * @author duohongzhi
 *
 */
@Service
public class GoodsServiceImpl implements GoodsService{

	@Resource
	private JdbcTemplate jdbcTemplate;

	public JdbcTemplate getJdbcTemplate() {
		return jdbcTemplate;
	}

	public void setJdbcTemplate(JdbcTemplate jdbcTemplate) {
		this.jdbcTemplate = jdbcTemplate;
	}

	public List<Goods> findGoods() {
		String sql = "select id,title,abstracts,addTime,uid,status,updateTime from t_goods where status != 0 ";
		List<Goods> ls = new ArrayList<Goods>();
		List<Map<String, Object>> list = jdbcTemplate.queryForList(sql);
		for (int i = 0; i < list.size(); i++) {
			Goods entity = new Goods();
			entity.setId(Integer.parseInt(list.get(i).get("id").toString()));
			entity.setTitle(list.get(i).get("title").toString());
			entity.setAbstracts(list.get(i).get("abstracts").toString());
			entity.setAddTime(list.get(i).get("addTime").toString());
			entity.setUid(Integer.parseInt(list.get(i).get("uid").toString()));
			entity.setStatus(Integer.parseInt(list.get(i).get("status").toString()));
			entity.setUpdateTime(list.get(i).get("updateTime").toString());
			ls.add(entity);
		}
		return ls;
	}

	public Goods findGoodsById(int id) {
		String sql = "select id,title,abstracts,addTime,uid,status,updateTime from t_goods where id = ?";	
		final Goods entity = new Goods();
		final Object[] params = new Object[] {id};	
		jdbcTemplate.query(sql,params, new RowCallbackHandler(){
			public void processRow(ResultSet rs) throws SQLException {
				goodsForm(rs, entity);
			}
		});
		return entity;
	}

	public Goods goodsForm(ResultSet rs,Goods goods){
		try {
			//向对象中添加各个属性值
			goods.setId(rs.getInt("id"));
			goods.setTitle(rs.getString("title"));
			goods.setAbstracts(rs.getString("abstracts"));
			goods.setAddTime(rs.getString("addTime"));
			goods.setUid(rs.getInt("uid"));
			goods.setStatus(rs.getInt("status"));
			goods.setUpdateTime(rs.getString("updateTime"));
		} catch (SQLException e) {
			e.printStackTrace();
		}
		return goods;
	}

	public int update(Goods goods) {
		String sql = "update t_goods set title = ?, abstracts = ?, addTime = ?, uid = ?, status = ?, updateTime = ? where id = ?";

		Object[] params = new Object[] {goods.getTitle(), goods.getAbstracts(),goods.getAddTime(), goods.getUid(), goods.getStatus(),goods.getUpdateTime(),goods.getId()};
		int flag = jdbcTemplate.update(sql,params);	
		return flag;
	}

	public int insert(final Goods goods) {
		final String sql = "insert into t_goods (title, abstracts, addTime, uid, status, updateTime) values (?, ?, ?, ?, ?, ?)";
		KeyHolder keyHolder = new GeneratedKeyHolder();
		int flag = jdbcTemplate.update( new PreparedStatementCreator(){
            public java.sql.PreparedStatement createPreparedStatement(Connection conn) throws SQLException{

            	int i = 0;
                java.sql.PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
                ps.setString(++i, goods.getTitle());
                ps.setString(++i, goods.getAbstracts());
                ps.setString(++i, goods.getAddTime());
                ps.setInt(++i, goods.getUid());
                ps.setInt(++i, goods.getStatus());
                ps.setString(++i, goods.getUpdateTime());

                return ps;
            }
        },keyHolder);
		if (flag > 0) {
			flag = keyHolder.getKey().intValue();
		}
		return flag;
	}

	public int delete(int id) {
		String sql = "update t_goods set status = ?, updateTime = ? where id = ?";
		Object[] params = new Object[] {0, (new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")).format(new Date()) , id};					
		int flag = jdbcTemplate.update(sql,params);			
		return flag;
	}

	public Goods formGoods(HttpServletRequest req, int falg) {
		Goods entity = new Goods();
		if(falg == 0){
			entity.setId(Integer.parseInt(req.getParameter("id")));
		}
		entity.setTitle(req.getParameter("title"));
		entity.setAbstracts(req.getParameter("abstracts"));
		entity.setAddTime((new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")).format(new Date()));
		entity.setUid(Integer.parseInt(req.getParameter("uid")));
		entity.setStatus(1);
		entity.setUpdateTime((new SimpleDateFormat("yyyy-MM-dd HH:mm:ss")).format(new Date()));

		return entity;
	}

	public List<Goods> findgoods(List<Goods> lGoods,
			List<TopicGoods> tGoods) {
		List<Goods> ls = new ArrayList<Goods>();
		if(lGoods.size() > 0 && tGoods.size() > 0){
			for (int i = 0; i < lGoods.size(); i++) {
				int r = 0;
				for (int j = 0; j < tGoods.size(); j++) {
					int id =  lGoods.get(i).getId();
					int gid = tGoods.get(j).getGid();
					if( id == gid){
						r = 1;
						break;
					}
				}
				if(r == 0){
					ls.add(lGoods.get(i));
				}
			}
		}
		if(tGoods.size() == 0){
			ls.addAll(lGoods);
		}
		return ls;
	}

	public List<Goods> findgoods(List<TopicGoods> tGoods) {
		List<Goods> ls = new ArrayList<Goods>();

		if(tGoods.size() > 0){
			for (int i = 0; i < tGoods.size(); i++) {
				ls.add(findGoodsById(tGoods.get(i).getGid()));
			}
		}
		return ls;
	}

}

