package org.apache.jmeter.report.processor;

/**
 * A Job that can be used to execute an operation that produce a result that we
 * want to get in the future when it is ready.
 * 
 * 
 * @param <T>
 *            The result type
 * @since 3.0
 */
abstract class Job<T> implements Runnable {

    private volatile boolean resultReady = false;

    private final Object lock = new Object();

    private volatile T result;

    @Override
    public final void run() {
        resultReady = false;
        result = exec();
        synchronized (lock) {
            resultReady = true;
            lock.notify();
        }
    }

    protected abstract T exec();

    public T getResult() throws InterruptedException {
        synchronized (lock) {
            while (!resultReady) {
                lock.wait();
            }
        }
        return result;
    }
}

package leetcode;

import java.util.HashMap;
import java.util.Map;

/**
 * Given a string, find the length of the longest substring without repeating characters.
 * <p>
 * Examples:
 * <p>
 * Given "abcabcbb", the answer is "abc", which the length is 3.
 * <p>
 * Given "bbbbb", the answer is "b", with the length of 1.
 * <p>
 * Given "pwwkew", the answer is "wke", with the length of 3. Note that the answer must be a substring, "pwke" is a
 * subsequence and not a substring.
 */
public class LongestSubstring {

    public int logestSubstring(String text) {

        int longest = 0;
        Map<Character, Integer> counterMap = new HashMap<>();

        int i = 0;
        int j = 0;

        while (i < text.length() && j < text.length()) {
            char currentChar = text.charAt(j);

            counterMap.compute(currentChar, (ch, counter) -> counter == null ? 1 : ++counter);

            if (counterMap.get( currentChar) == 1) {
                if (longest < (j - i + 1)) {
                    longest = (j - i + 1);
                }
            } else {
                while (i <= j) {

                    if (counterMap.get(text.charAt(i)) > 1) {
                        counterMap.compute(text.charAt(i), (ch, counter) -> --counter);
                        i++;
                        break;
                    }
                    counterMap.compute(text.charAt(i), (ch, counter) -> --counter);
                    i++;
                }
            }

            j++;
        }


        return longest;
    }
}

public class Solution {
    public ListNode mergeTwoLists(ListNode l1, ListNode l2) {
        ListNode head, tail;
        head = new ListNode(Integer.MIN_VALUE);
        tail = head;
        while (l1 != null && l2 != null) {
            if (l1.val < l2.val) {
                tail.next = l1;
                tail = tail.next;
                l1 = l1.next;
            } else {
                tail.next = l2;
                tail = tail.next;
                l2 = l2.next;
            }
        }
        if (l1 != null) {
            tail.next = l1;
        } else {
            tail.next = l2;
        }
        return head.next;
    }
}

package edu.yctc.common.constant;

import java.util.List;

import com.google.common.collect.ImmutableList;

/**
 * 学生上课状态得分
 * 
 * @author 15272
 */
public class StateScore {

    /** 认真听课 */
    public static final int LISTENING_SCORE = 10;
    /** 玩手机 */
    public static final int PLAY_MOBILE_PHONE_SCORE = 6;
    /** 发呆 */
    public static final int DAZE_SCORE = 8;
    /** 睡觉 */
    public static final int SLEEP_SCORE = 7;

    public static final List<Integer> ALL_STATE_SCORE = ImmutableList.of(LISTENING_SCORE,
        PLAY_MOBILE_PHONE_SCORE, DAZE_SCORE,
        SLEEP_SCORE);

    public static boolean isLegal(int stateScore) {
        for (Integer integer : ALL_STATE_SCORE) {
            if (integer == stateScore) {
                return true;
            }
        }
        return false;
    }
}

