@Configuration
public class SentinelConfig {

    @Bean
    public ZuulFilter sentinelZuulPreFilter() {
        return new SentinelZuulPreFilter(FilterOrderConstants.PRE_FILTER_ORDER);
    }

    @Bean
    public ZuulFilter sentinelZuulPostFilter() {
        return new SentinelZuulPostFilter(FilterOrderConstants.POST_FILTER_ORDER);
    }

    @Bean
    public ZuulFilter sentinelZuulErrorFilter() {
        return new SentinelZuulErrorFilter(FilterOrderConstants.ERROR_FILTER_ORDER);
    }

    @PostConstruct
    public void doInit() {
        initFallback();
        initGatewayRules();
    }

    /**
     * 初始化限流规则（或在 dashboard 中配置）
     */
    private void initGatewayRules() {
        Set<GatewayFlowRule> rules = new HashSet<>();
        rules.add(new GatewayFlowRule("auth")
                // 限流阈值QPS
                .setCount(2)
                // 统计时间窗口，单位是秒，默认是 1 秒
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("upms")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("id")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("bigdata")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("blockchain")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("demo/provider")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("demo/consumer")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("demo/sample")
                .setCount(2)
                .setIntervalSec(1)
        );
        rules.add(new GatewayFlowRule("demo/ribbon")
                .setCount(2)
                .setIntervalSec(1)
        );
        GatewayRuleManager.loadRules(rules);
    }

    /**
     * 自定义错误回滚提示内容
     */
    private void initFallback() {
        ZuulBlockFallbackManager.registerProvider(new CustomBlockFallbackProvider());
    }

}

