        assertThat(putQueryParamLine("BucketId", "bucketId"),
                is("this.getQueryParams().put(\"bucket_id\", bucketId);"));

        assertThat(putQueryParamLine("BucketName", "bucketName"),
                is("this.getQueryParams().put(\"bucket_id\", bucketName);"));
