import static uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.callback.PreSubmitCallbackStage.ABOUT_TO_START;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.jupiter.MockitoExtension;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.AsylumCase;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.CaseDetails;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.Event;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.callback.Callback;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.callback.PreSubmitCallbackResponse;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.callback.PreSubmitCallbackStage;
import uk.gov.hmcts.reform.iacaseapi.domain.entities.ccd.field.YesOrNo;


@ExtendWith(MockitoExtension.class)
@SuppressWarnings("unchecked")
class HomeOfficeCaseValidatePreparerTest {

    private HomeOfficeCaseValidatePreparer homeOfficeCaseValidatePreparer;

    @Mock
    private Callback<AsylumCase> callback;
    @Mock
    private CaseDetails<AsylumCase> caseDetails;
    @Mock
    private AsylumCase asylumCase;

    @BeforeEach
    public void setUp() {
        homeOfficeCaseValidatePreparer = new HomeOfficeCaseValidatePreparer(true);
    }

    @Test
    void handler_checks_home_office_integration_enabled_returns_yes() {

        when(callback.getEvent()).thenReturn(SUBMIT_APPEAL);
        when(callback.getCaseDetails()).thenReturn(caseDetails);
        when(caseDetails.getCaseData()).thenReturn(asylumCase);

        PreSubmitCallbackResponse<AsylumCase> response =
            homeOfficeCaseValidatePreparer.handle(ABOUT_TO_START, callback);

        assertThat(response).isNotNull();
        assertThat(response.getData()).isNotEmpty();
        assertThat(response.getData()).isEqualTo(asylumCase);
        assertThat(response.getErrors()).isEmpty();
        Mockito.verify(asylumCase, times(1)).write(
            IS_HOME_OFFICE_INTEGRATION_ENABLED, YesOrNo.YES);

    }

    @Test
    void handler_checks_home_office_integration_disabled_returns_no() {

        homeOfficeCaseValidatePreparer = new HomeOfficeCaseValidatePreparer(false);

        when(callback.getEvent()).thenReturn(PAY_AND_SUBMIT_APPEAL);
        when(callback.getCaseDetails()).thenReturn(caseDetails);
        when(caseDetails.getCaseData()).thenReturn(asylumCase);

        PreSubmitCallbackResponse<AsylumCase> response =
            homeOfficeCaseValidatePreparer.handle(ABOUT_TO_START, callback);

        assertThat(response).isNotNull();
        assertThat(response.getData()).isNotEmpty();
        assertThat(response.getData()).isEqualTo(asylumCase);
        assertThat(response.getErrors()).isEmpty();
        Mockito.verify(asylumCase, times(1)).write(
            IS_HOME_OFFICE_INTEGRATION_ENABLED, YesOrNo.NO);
    }

    @Test
    void it_can_handle_callback() {

        for (Event event : Event.values()) {

            when(callback.getEvent()).thenReturn(event);

            for (PreSubmitCallbackStage callbackStage : PreSubmitCallbackStage.values()) {

                boolean canHandle = homeOfficeCaseValidatePreparer.canHandle(callbackStage, callback);

                if (callbackStage == ABOUT_TO_START
                    && (callback.getEvent() == SUBMIT_APPEAL
                    || callback.getEvent() == PAY_AND_SUBMIT_APPEAL
                    || callback.getEvent() == MARK_APPEAL_PAID
                    || callback.getEvent() == REQUEST_HOME_OFFICE_DATA)
                ) {
                    assertTrue(canHandle);
                } else {
                    assertFalse(canHandle);
                }
            }

            reset(callback);
        }
    }

    @Test
    void should_not_allow_null_arguments() {

        assertThatThrownBy(() -> homeOfficeCaseValidatePreparer.canHandle(null, callback))
            .hasMessage("callbackStage must not be null")
            .isExactlyInstanceOf(NullPointerException.class);

        assertThatThrownBy(() -> homeOfficeCaseValidatePreparer.canHandle(ABOUT_TO_START, null))
            .hasMessage("callback must not be null")
            .isExactlyInstanceOf(NullPointerException.class);

        assertThatThrownBy(() -> homeOfficeCaseValidatePreparer.handle(null, callback))
            .hasMessage("callbackStage must not be null")
            .isExactlyInstanceOf(NullPointerException.class);

        assertThatThrownBy(() -> homeOfficeCaseValidatePreparer.handle(ABOUT_TO_START, null))
            .hasMessage("callback must not be null")
            .isExactlyInstanceOf(NullPointerException.class);
    }

    @Test
    void handler_throws_error_if_cannot_actually_handle() {

        assertThatThrownBy(() -> homeOfficeCaseValidatePreparer.handle(ABOUT_TO_START, callback))
            .hasMessage("Cannot handle callback")
            .isExactlyInstanceOf(IllegalStateException.class);

        when(callback.getEvent()).thenReturn(START_APPEAL);
        assertThatThrownBy(() -> homeOfficeCaseValidatePreparer.handle(ABOUT_TO_START, callback))
            .hasMessage("Cannot handle callback")
            .isExactlyInstanceOf(IllegalStateException.class);

    }

}

package com.fabercode.prelude.core.functionals;

import java.util.function.Function;
import java.util.function.Supplier;

public class Result<R> {
    public final R value;
    public final Throwable error;

    private Result(R value, Throwable error) {
        this.value = error == null ? value : null;
        this.error = value == null ? error : null;
    }

    public static <R> Result<R> empty() {
        return new Result<>(null, null);
    }

    public static <R> Result<R> withValue(R value) {
        return new Result<>(value, null);
    }

    public static <R> Result<R> withError(Throwable cause) {
        return new Result<>(null, cause);
    }

    public R yield(Function<Throwable, R> exceptionHandler, Supplier<R> nullHandler) {
        if (isValid()) return value;
        if (isError()) return exceptionHandler.apply(error);
        if (isEmpty()) return nullHandler.get();
        return null;
    }

    public boolean isEmpty() {
        return value == null && error == null;
    }

    public boolean isValid() {
        return value != null;
    }

    public boolean isError() {
        return error != null;
    }
}

package io.github.splotycode.spellchecker.check.defaults;

import io.github.splotycode.mosaik.util.AlmostBoolean;
import io.github.splotycode.mosaik.util.collection.CollectionUtil;
import io.github.splotycode.spellchecker.check.Check;
import io.github.splotycode.spellchecker.check.ProblemCollector;
import io.github.splotycode.spellchecker.check.visitor.ElementVisitor;
import io.github.splotycode.spellchecker.check.visitor.Visitor;
import io.github.splotycode.spellchecker.element.Word;
import lombok.AllArgsConstructor;

import java.util.Set;

@AllArgsConstructor
public class DoubleWordCheck extends Check {

    private final Set<String> exceptions;

    public DoubleWordCheck(String... exceptions) {
        this.exceptions = CollectionUtil.newHashSet(exceptions);
    }

    @Override
    public Visitor visitor() {
        return new ElementVisitor() {
            @Override
            public void visitWord(ProblemCollector collector, Word word) {
                if (word.nextWord() != null &&
                        word.asString().equalsIgnoreCase(word.nextWord().asString()) &&
                        !exceptions.contains(word.asString(AlmostBoolean.NO))) {
                    collector.addProblem(word, word.nextWord(), "Same word after each other");
                }
            }
        };
    }
}

