package jenkins.model;

import static org.junit.Assert.assertTrue;

import hudson.model.Node.Mode;

import org.junit.Rule;
import org.junit.Test;
import org.jvnet.hudson.test.Issue;
import org.jvnet.hudson.test.JenkinsRule;

public class MasterBuildConfigurationTest {

    @Rule public JenkinsRule j = new JenkinsRule();

    @Test
    @Issue("JENKINS-23966")
    public void retainMasterLabelWhenNoSlaveDefined() throws Exception {
        Jenkins jenkins = j.getInstance();

        assertTrue("Test is for master with no slave", jenkins.getComputers().length == 1);

        // set our own label & mode
        final String myTestLabel = "TestLabelx0123";
        jenkins.setLabelString(myTestLabel);
        jenkins.setMode(Mode.EXCLUSIVE);

        // call global config page
        j.configRoundtrip();

        // make sure settings were not lost
        assertTrue("Master's label is lost", myTestLabel.equals(jenkins.getLabelString()));
        assertTrue("Master's mode is lost", Mode.EXCLUSIVE.equals(jenkins.getMode()));
    }
}

package DataStructures.Caches;

import java.util.HashMap;
import java.util.Map;

/**
 * Most recently used (MRU)
 * <p>
 * In contrast to Least Recently Used (LRU), MRU discards the most recently used items first.
 * https://en.wikipedia.org/wiki/Cache_replacement_policies#Most_recently_used_(MRU)
 *
 * @param <K> key type
 * @param <V> value type
 */
public class MRUCache<K, V> {
    private final Map<K, Entry<K, V>> data = new HashMap<>();
    private Entry<K, V> head;
    private Entry<K, V> tail;
    private int cap;
    private static final int DEFAULT_CAP = 100;

    public MRUCache() {
        setCapacity(DEFAULT_CAP);
    }

    private void setCapacity(int newCapacity) {
        checkCapacity(newCapacity);
        for (int i = data.size(); i > newCapacity; i--) {
            Entry<K, V> evicted = evict();
            data.remove(evicted.getKey());
        }
        this.cap = newCapacity;
    }


    private void checkCapacity(int capacity) {
        if (capacity <= 0) {
            throw new RuntimeException("capacity must greater than 0!");
        }
    }

    private Entry<K, V> evict() {
        if (head == null) {
            throw new RuntimeException("cache cannot be empty!");
        }
        final Entry<K, V> evicted = this.tail;
        tail = evicted.getPreEntry();
        tail.setNextEntry(null);
        evicted.setNextEntry(null);
        return evicted;
    }

    public MRUCache(int cap) {
        setCapacity(cap);
    }

    public V get(K key) {
        if (!data.containsKey(key)) {
            return null;
        }
        final Entry<K, V> entry = data.get(key);
        moveEntryToLast(entry);
        return entry.getValue();
    }

    public void put(K key, V value) {
        if (data.containsKey(key)) {
            final Entry<K, V> exitingEntry = data.get(key);
            exitingEntry.setValue(value);
            moveEntryToLast(exitingEntry);
            return;
        }
        Entry<K, V> newEntry;
        if (data.size() == cap) {
            newEntry = evict();
            data.remove(newEntry.getKey());
        } else {
            newEntry = new Entry<>();
        }
        newEntry.setKey(key);
        newEntry.setValue(value);
        addNewEntry(newEntry);
        data.put(key, newEntry);
    }

    private void addNewEntry(Entry<K, V> newEntry) {
        if (data.isEmpty()) {
            head = newEntry;
            tail = newEntry;
            return;
        }
        tail.setNextEntry(newEntry);
        newEntry.setPreEntry(tail);
        newEntry.setNextEntry(null);
        tail = newEntry;
    }

    private void moveEntryToLast(Entry<K, V> entry) {
        if (tail == entry) {
            return;
        }
        final Entry<K, V> preEntry = entry.getPreEntry();
        final Entry<K, V> nextEntry = entry.getNextEntry();
        if (preEntry != null) {
            preEntry.setNextEntry(nextEntry);
        }
        if (nextEntry != null) {
            nextEntry.setPreEntry(preEntry);
        }
        if (head == entry) {
            head = nextEntry;
        }
        tail.setNextEntry(entry);
        entry.setPreEntry(tail);
        entry.setNextEntry(null);
        tail = entry;
    }

    static final class Entry<I, J> {
        private Entry<I, J> preEntry;
        private Entry<I, J> nextEntry;
        private I key;
        private J value;

        public Entry() {
        }

        public Entry(Entry<I, J> preEntry, Entry<I, J> nextEntry, I key, J value) {
            this.preEntry = preEntry;
            this.nextEntry = nextEntry;
            this.key = key;
            this.value = value;
        }

        public Entry<I, J> getPreEntry() {
            return preEntry;
        }

        public void setPreEntry(Entry<I, J> preEntry) {
            this.preEntry = preEntry;
        }

        public Entry<I, J> getNextEntry() {
            return nextEntry;
        }

        public void setNextEntry(Entry<I, J> nextEntry) {
            this.nextEntry = nextEntry;
        }

        public I getKey() {
            return key;
        }

        public void setKey(I key) {
            this.key = key;
        }

        public J getValue() {
            return value;
        }

        public void setValue(J value) {
            this.value = value;
        }
    }

    public static void main(String[] args) {
        final MRUCache<String, Integer> cache = new MRUCache<>(2);
        cache.put("Key1", 1);
        cache.put("Key2", 2);
        cache.put("Key3", 3);
        cache.put("Key4", 4);
        System.out.println("getValue(Key1): " + cache.get("Key1"));
        System.out.println("getValue(Key2): " + cache.get("Key2"));
        System.out.println("getValue(Key3): " + cache.get("Key3"));
        System.out.println("getValue(Key4): " + cache.get("Key4"));
    }
}

public class Pascal {

    public static void main(String[] args) {
        pascal(20);
    }

    public static void pascal(int n) {
        int[][] t = new int[n+1][];
        for(int i=0; i<=n; i++) {
            t[i] = new int[i+1];
            t[i][0] = 1;
            t[i][i] = 1;
        }
        for (int i=2; i<=n; i++)
            for(int j=1; j<i; j++)
                t[i][j] = t[i-1][j-1] + t[i-1][j];
        for (int i=0; i<=n; i++) {
            for(int j=0; j<=i; j++)
                System.out.print(t[i][j]+" ");
            System.out.println();
        }
    }

}

package net.openid.conformance.condition.rs;

import java.net.InetAddress;

import com.google.common.base.Strings;
import com.google.common.net.InetAddresses;

import net.openid.conformance.condition.AbstractCondition;
import net.openid.conformance.condition.PostEnvironment;
import net.openid.conformance.condition.PreEnvironment;
import net.openid.conformance.testmodule.Environment;

public class ExtractFapiIpAddressHeader extends AbstractCondition {

	@Override
	@PreEnvironment(required = "incoming_request")
	@PostEnvironment(strings = "fapi_customer_ip_address")
	public Environment evaluate(Environment env) {

		String header = env.getString("incoming_request", "headers.x-fapi-customer-ip-address");
		if (Strings.isNullOrEmpty(header)) {
			throw error("Couldn't find FAPI ip address header");
		} else {

			// try to parse it to make sure it's in the right format
			try {

				InetAddress addr = InetAddresses.forString(header);

				env.putString("fapi_customer_ip_address", header);
				logSuccess("Found a FAPI ip address header", args("fapi_customer_ip_address", header, "addr", addr.getHostAddress()));

				return env;

			} catch (IllegalArgumentException e) {
				throw error("Could not parse FAPI ip address header", args("fapi_customer_ip_address", header));
			}

		}

	}

}

package crazypants.enderio.machines.machine.spawner;

import javax.annotation.Nonnull;

import com.enderio.core.client.render.ManagedTESR;
import com.enderio.core.client.render.RenderUtil;
import com.enderio.core.common.vecmath.Vector3f;

import crazypants.enderio.machines.config.config.SpawnerConfig;
import crazypants.enderio.machines.init.MachineObject;
import net.minecraft.block.state.IBlockState;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.GlStateManager;
import net.minecraft.entity.Entity;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

@SideOnly(Side.CLIENT)
public class PoweredSpawnerSpecialRenderer extends ManagedTESR<TilePoweredSpawner> {

  public PoweredSpawnerSpecialRenderer() {
    super(MachineObject.block_powered_spawner.getBlock());
  }

  @Override
  protected boolean shouldRender(@Nonnull TilePoweredSpawner te, @Nonnull IBlockState blockState, int renderPass) {
    return te.isActive();
  }

  @Override
  protected void renderTileEntity(@Nonnull TilePoweredSpawner te, @Nonnull IBlockState blockState, float partialTicks, int destroyStage) {
    renderMob(te, partialTicks);
    if (!te.getNotification().isEmpty() && !SpawnerConfig.disableNotification.get()) {
      float offset = 0;
      GlStateManager.disableDepth();
      for (SpawnerNotification note : te.getNotification()) {
        RenderUtil.drawBillboardedText(new Vector3f(0.5, 1.5 + offset, 0.5), note.getDisplayString(), 0.25f);
        offset += 0.375f;
      }
      GlStateManager.enableDepth();
    }
  }

  private void renderMob(TilePoweredSpawner te, float partialTicks) {
    Entity entity = te.getCachedEntity();

    if (entity != null) {
      float f = 0.53125F;
      float f1 = Math.max(entity.width, entity.height);

      if (f1 > 1.0D) {
        f /= f1;
      }

      GlStateManager.pushMatrix();
      GlStateManager.translate(0.5F, 0.4F, 0.5F);
      GlStateManager.rotate((float) (te.getPrevMobRotation() + (te.getMobRotation() - te.getPrevMobRotation()) * partialTicks) * 10.0F, 0.0F, 1.0F, 0.0F);
      GlStateManager.translate(0.0F, -0.2F, 0.0F);
      GlStateManager.rotate(-30.0F, 1.0F, 0.0F, 0.0F);
      GlStateManager.scale(f, f, f);
      Minecraft.getMinecraft().getRenderManager().renderEntity(entity, 0.0D, 0.0D, 0.0D, 0.0F, partialTicks, false);
      GlStateManager.popMatrix();
    }
  }

}

