package com.SH.planner.common;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.multipart.MultipartFile;

public class FileManagerService {

	public final static String FILE_UPLOAD_PATH = "/Users/sohyun/Documents/Spring/upload/plannerImage/";

	private static Logger logger = LoggerFactory.getLogger(FileManagerService.class);

	// 파일 저장
	public static String saveFile(int userId, MultipartFile file) {

		if(file == null) {
			logger.error("FileManagerService::saveFile - 업로드 파일 없음");
			return null;
		}

		// 파일경로 
		// 사용자 별로 구분할 수 있도록 사용자가 파일을 올린 시간으로 구분(ms 단위의 시간)

		String directoryName = userId + "_" + System.currentTimeMillis() + "/";

		String filePath = FILE_UPLOAD_PATH + directoryName;

		// 디렉토리 생성
		File directory = new File(filePath);
		if(directory.mkdir() == false) {
			// 디렉토리 생성 에러
			logger.error("FileManagerService::saveFile - 디렉토리 생성 에러");
			return null;
		}

		try {
			 byte[] bytes = file.getBytes();
			// 파일 저장 경로 + 파일 이름 경로 객체
			Path path = Paths.get(filePath + file.getOriginalFilename());
			// 파일 저장
			Files.write(path, bytes);

		} catch (IOException e) {
			logger.error("FileManagerService::saveFile - 파일 저장 에러");
			e.printStackTrace();
			return null;
		}

		// 파일 접근 가능한 주소를 return 
		return "/images/" + directoryName + file.getOriginalFilename();

	}

	// 파일 삭제
	public static void removeFile(String filePath) {

		// 삭제할 파일 경로
		// filePath : /images/~~~/~~.png
		// 실제 파일 경로 : /Users/sohyun/Document/Spring/upload/plannerImage/ 

		String realFilePath = FILE_UPLOAD_PATH + filePath.replace("/images/", "");

		// 파일 지우기
		Path path = Paths.get(realFilePath);
		// 파일이 있는지 확인
		if(Files.exists(path)) {
			try {
				Files.delete(path);
			} catch (IOException e) {
				logger.error("fileManagerService::removeFile - 파일 삭제 실패");
				e.printStackTrace();
			}
		}

		// 디렉토리 삭제
		// 실제 디렉토리 경로 : /Users/sohyun/Document/Spring/upload/plannerImage/~~~
		path = path.getParent();

		if(Files.exists(path)) {
			try {
				Files.delete(path);
			} catch (IOException e) {
				logger.error("fileManagerService::removeFile - 디렉토리 삭제 실패");
				e.printStackTrace();
			}
		}
	}








}

package es.tid.bgp.bgp4.update.fields.pathAttributes;

import es.tid.bgp.bgp4.update.fields.PathAttribute;


/**
 * ORIGIN is a well-known mandatory attribute.  The ORIGIN attribute is
   generated by the speaker that originates the associated routing
   information.  Its value SHOULD NOT be changed by any other speaker.
   
 *   a) ORIGIN (Type Code 1):

            ORIGIN is a well-known mandatory attribute that defines the
            origin of the path information.  The data octet can assume
            the following values:

               Value      Meaning

               0         IGP - Network Layer Reachability Information
                            is interior to the originating AS

               1         EGP - Network Layer Reachability Information
                            learned via the EGP protocol [RFC904]

               2         INCOMPLETE - Network Layer Reachability
                            Information learned by some other means
                            
 * @author mcs
 *
 */
public class OriginAttribute extends PathAttribute{

	int value;
	
	public OriginAttribute(){		
		super();
		//Poner los flags. 		
		this.typeCode = PathAttributesTypeCode.PATH_ATTRIBUTE_TYPECODE_ORIGIN;

	}
	public OriginAttribute(byte []bytes, int offset){
		super(bytes, offset);
		decode(bytes,offset+mandatoryLength);		
	}
	@Override
	public void encode() {
		pathAttributeLength = 1;
		this.length=pathAttributeLength+mandatoryLength;

		this.bytes=new byte[this.length];
		encodeHeader();		
		bytes[3]=(byte)(value & 0xFF);		
		
	}
	public void decode(byte []bytes, int offset){
		value = bytes[offset];
	}
	public int getValue() {
		return value;
	}
	public void setValue(int value) {
		this.value = value;
	}
	
	@Override
	public String toString() {
		//String sb = super.toString();
		return "Origin [Value=" + value+ "]";
	}
	

}

package com.itsmeyaw.werewolfbot.command;

import discord4j.common.util.Snowflake;
import discord4j.core.object.VoiceState;
import discord4j.core.object.entity.Guild;
import discord4j.core.object.entity.Member;
import discord4j.core.object.entity.Message;
import discord4j.core.object.entity.channel.VoiceChannel;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import reactor.core.publisher.Flux;

import java.util.Optional;

@Component
public class Mute implements Command{

    private final Logger LOGGER = LoggerFactory.getLogger(Mute.class);

    @Override
    public String getCommand() {
        return "mute";
    }

    @Override
    public void execute(Message m) {
        m.getAuthorAsMember().map(Member::getDisplayName).subscribe(name -> LOGGER.info(String.format("Mute received! [From:%s]", name)));

        Optional<Snowflake> channel = m.getAuthorAsMember()
                .flatMap(Member::getVoiceState)
                .map(VoiceState::getChannelId)
                .block();

        if (channel != null) {
            long snowflake = channel.get().asLong();
            Flux.from(m.getGuild())
                    .flatMap(Guild::getMembers)
                    .filter(me -> me.getVoiceState()
                            .flatMap(VoiceState::getChannel)
                            .map(VoiceChannel::getId)
                            .map(e -> e.asLong() == snowflake)
                            .blockOptional()
                            .orElse(false))
                    .flatMap(me -> me.edit(g -> g.setMute(true)))
                    .subscribe();
        } else {
            m.getChannel()
                    .flatMap(c -> c.createMessage("You have to be connected to a voice channel!"))
                    .subscribe();
        }
    }
}

