@Entity
@Table(name = "cat_incidencias")
@XmlRootElement

public class Incidencia implements Serializable {

    private static final long serialVersionUID = 1L;
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Basic(optional = false)
    @Column(name = "id")
    private Integer id;
    @Column(name = "fecha_incidencia")
    @Temporal(TemporalType.TIMESTAMP)
    private Date fechaIncidencia;
    @Size(max = 2147483647)
    @Column(name = "observacion_incidencia")
    private String observacionIncidencia;

    ///Relacion entre incidencia a Predio by Fsan
    @JsonBackReference(value = "predioIncidencia")
    @JoinColumn(name = "id_predio", referencedColumnName = "id")
    @ManyToOne(optional = false)
    private Predio predio;
    //
    ///Relacion entre incidencia a integrante by Fsan
    @JsonBackReference(value = "predioIntegrantes")
    @JoinColumn(name = "id_integrante", referencedColumnName = "id")
    @ManyToOne(optional = false)
    private Integrante integrante;
    //

    //Fsan
    @OneToMany(cascade = CascadeType.ALL, mappedBy = "incidencia")
    private List<IncidenciaImagen> incidenciaImagen;
    //

    public Incidencia() {
    }

    public Incidencia(Integer id) {
        this.id = id;
    }

    public Integer getId() {
        return id;
    }

    public void setId(Integer id) {
        this.id = id;
    }

    public Date getFechaIncidencia() {
        return fechaIncidencia;
    }

    public void setFechaIncidencia(Date fechaIncidencia) {
        this.fechaIncidencia = fechaIncidencia;
    }

    public String getObservacionIncidencia() {
        return observacionIncidencia;
    }

    public void setObservacionIncidencia(String observacionIncidencia) {
        this.observacionIncidencia = observacionIncidencia;
    }

    @JsonIgnore
    public Predio getPredio() {
        return predio;
    }

    public void setPredio(Predio predio) {
        this.predio = predio;
    }

    public Integrante getIntegrante() {
        return integrante;
    }

    public void setIntegrante(Integrante integrante) {
        this.integrante = integrante;
    }

    public List<IncidenciaImagen> getIncidenciaImagen() {
        return incidenciaImagen;
    }

    public void setIncidenciaImagen(List<IncidenciaImagen> incidenciaImagen) {
        this.incidenciaImagen = incidenciaImagen;
    }

    @Override
    public int hashCode() {
        int hash = 0;
        hash += (id != null ? id.hashCode() : 0);
        return hash;
    }

    @Override
    public boolean equals(Object object) {
        // TODO: Warning - this method won't work in the case the id fields are not set
        if (!(object instanceof Incidencia)) {
            return false;
        }
        Incidencia other = (Incidencia) object;
        if ((this.id == null && other.id != null) || (this.id != null && !this.id.equals(other.id))) {
            return false;
        }
        return true;
    }

    @Override
    public String toString() {
        return "com.dadoco.cat.model.Incidencia[ id=" + id + " ]";
    }

}

package me.idra.multiblocksystem.commands;



import java.util.List;
import java.util.ArrayList;

import org.bukkit.ChatColor;
import org.bukkit.Location;
import org.bukkit.block.Block;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;

import me.idra.multiblocksystem.bases.BaseCommand;
import me.idra.multiblocksystem.helpers.ItemStackHelper;
import me.idra.multiblocksystem.objects.ItemGroup;



public class CommandEditorCreate extends BaseCommand{


	public CommandEditorCreate() {
		super();

		name = new String[] {"editor", "create"};
		description = ChatColor.DARK_AQUA + "Creates a new structure file from an in-world structure";
		arguments = new String[] {"filename", "y", "x", "z"};
		hidden = false;
		console = true;

		addPermission();
		addName();
	}

	@Override
	public boolean commandFunction(CommandSender sender, Command command, String label, String[] args) {

		// Get dimensions
		int dimension_y = Integer.parseInt(args[3]);
		int dimension_x = Integer.parseInt(args[4]);
		int dimension_z = Integer.parseInt(args[5]);

		// TODO finish this

		// Get corner position
		Location player_location = ((Player) sender).getLocation();
		Location corner = player_location.add(1, 0, 1);

		// Build block array
		List<List<List<ItemGroup>>> stack_list = new ArrayList<> ();

		for (int y = 0; y < dimension_y; y++) {
			List<List<ItemGroup>> stack_y = new ArrayList<> ();

			for (int x = 0; x < dimension_x; x++) {
				List<ItemGroup> stack_x = new ArrayList<> ();

				for (int z = 0; z < dimension_z; z++) {

					Location location = corner.clone().add(x, y, z);
					Block block = location.getBlock();
					stack_x.add(ItemStackHelper.groupFromBlock(block));
				}

				stack_y.add(stack_x);
			}

			stack_list.add(stack_y);
		}

		// Successful execution
		return true;
	}
}

package ru.job4j.array;

import org.junit.Test;

import java.util.Arrays;

import static org.hamcrest.Matchers.containsInAnyOrder;
import static org.junit.Assert.*;
import static org.hamcrest.core.Is.is;

/**
 * Test for ArrayDuplicate.java
 * @author Galanov Sergey
 * @since 23.07.2018
 * @version 1.0
 */
public class ArrayDuplicateTest {

    /**
     * Test for func "remove"
     */
    @Test
    public void whenArrayWithDuplicatesThenArrayWithoutDuplicates() {
        ArrayDuplicate arrayDuplicate = new ArrayDuplicate();
        String[] array = {"Привет", "Мир", "Привет", "Супер", "asd", "Привет", "Мир", "qwe"};
        String[] result = arrayDuplicate.removing(array);
        String[] expect = {"Привет", "Мир", "Супер", "asd", "qwe"};
        assertThat(Arrays.asList(result), containsInAnyOrder(expect));
    }

    @Test
    public void whenArrayWithTwoDuplicatesThenArrayWithoutDuplicates() {
        ArrayDuplicate arrayDuplicate = new ArrayDuplicate();
        String[] array = {"Привет", "Мир", "Супер", "Привет", "asd", "Привет", "Привет"};
        String[] result = arrayDuplicate.removing(array);
        String[] expect = {"Привет", "Мир", "Супер", "asd"};
        assertThat(result, is(expect));
    }

    @Test
    public void whenArrayAllOneThenOneItem() {
        ArrayDuplicate arrayDuplicate = new ArrayDuplicate();
        String[] array = {"Привет", "Привет", "Привет", "Привет", "Привет"};
        String[] result = arrayDuplicate.removing(array);
        String[] expect = {"Привет"};
        assertThat(result, is(expect));
    }
}

