package com.google.publicalerts.cap.edxl.types;

import java.util.ArrayList;
import java.util.List;

/**
 * Generic bean to hold XML parsed entries of the form:
 * <p>
 * <fooElement>
 *   <valueListUrn>valueListUrn</valueListUrn>
 *   <value>value</value>
 * </fooElement>
 * <p>
 * where the content of <valueListUrn> is the Uniform Resource
 * Name of a published list of values and definitions, and the content of
 * <value> is a string (which may represent a number) denoting the value itself.
 * Multiple instances of the <value> may occur with a single <valueListUrn>
 * within the <fooElement> container.
 *
 * @author anshul@google.com (Anshul Kundani)
 */
public class ValueList {
  private String specifier;
  private List<String> values;

  public ValueList() {
    values = new ArrayList<String>();
  }

  public ValueList(String specifier, List<String> values) {
    this.specifier = specifier;
    this.values = values;
  }

  public void setSpecifier(String specifier) {
    this.specifier = specifier;
  }

  public String getSpecifier() {
    return specifier;
  }

  public void addValue(String value) {
    values.add(value);
  }

  public List<String> getValues() {
    return values;
  }
}

package appmanager;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.firefox.FirefoxDriver;
import org.openqa.selenium.ie.InternetExplorerDriver;
import org.openqa.selenium.remote.DesiredCapabilities;
import org.openqa.selenium.remote.RemoteWebDriver;

import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.net.URL;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class ApplicationManager {
    private static final Properties properties = new Properties();
    private WebDriver wd;
    private String browser;

    private ContactHelper contactHelper;
    private GroupHelper groupHelper;
    private NavigationHelper navigationHelper;
    private SessionHelper sessionHelper;
    private DbHelper dbHelper;

    public void init() throws IOException {
        String propertyFile = System.getProperty("config", "web");
        properties.load(new FileReader(new File(String.format("src/test/resources/%s.properties", propertyFile))));
        this.browser = properties.getProperty("test.browser");

        dbHelper = new DbHelper();

        if (properties.getProperty("test.selenium.driver").equals("")) {
            if (browser.equals("firefox")) wd = new FirefoxDriver();
            else if (browser.equals("chrome")) wd = new ChromeDriver();
            else if (browser.equals("ie")) wd = new InternetExplorerDriver();
        } else {
            DesiredCapabilities capabilities = new DesiredCapabilities();
            capabilities.setBrowserName(browser);
            wd = new RemoteWebDriver(new URL(properties.getProperty("test.selenium.driver")), capabilities);
        }
        wd.manage().timeouts().implicitlyWait(3, TimeUnit.SECONDS);

        wd.get(properties.getProperty("test.baseURL"));

        contactHelper = new ContactHelper(wd);
        groupHelper = new GroupHelper(wd);
        navigationHelper = new NavigationHelper(wd);
        sessionHelper = new SessionHelper(wd);

        sessionHelper.login(properties.getProperty("test.adminLogin"), properties.getProperty("test.adminPassword"));
    }

    public void stop() {
        wd.quit();
    }

    public GroupHelper group() {
        return groupHelper;
    }

    public ContactHelper contact() {
        return contactHelper;
    }

    public NavigationHelper goTo() {
        return navigationHelper;
    }

    public DbHelper db() {
        return dbHelper;
    }
}

package com.aliyuncs.kms.secretsmanager.client.utils;

import java.util.Arrays;

public class ArrayUtils {

    private ArrayUtils() {
        // do nothing
    }

    public static <T> byte[] concatAll(byte[] first, byte[]... rest) {
        int totalLength = first.length;
        for (byte[] array : rest) {
            totalLength += array.length;
        }
        byte[] result = Arrays.copyOf(first, totalLength);
        int offset = first.length;
        for (byte[] array : rest) {
            System.arraycopy(array, 0, result, offset, array.length);
            offset += array.length;
        }
        return result;
    }

}

