package com.wutong.backmanage.core.intercept;

import org.apache.shiro.session.InvalidSessionException;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Pointcut;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

import com.wutong.backmanage.core.controller.BaseController;
import com.wutong.backmanage.core.support.HttpKit;
import com.wutong.backmanage.core.shiro.ShiroKit;

/**
 * 验证session超时的拦截器
 *
 */
@Aspect
@Component
@ConditionalOnProperty(prefix = "wutong", name = "session-open", havingValue = "true")
public class SessionTimeoutInterceptor extends BaseController {

    @Pointcut("execution(* com.wutong.backmanage.*..controller.*.*(..))")
    public void cutService() {
    }

    @Around("cutService()")
    public Object sessionTimeoutValidate(ProceedingJoinPoint point) throws Throwable {

        String servletPath = HttpKit.getRequest().getServletPath();

        if (servletPath.equals("/kaptcha") || servletPath.equals("/login") || servletPath.equals("/global/sessionError")) {
            return point.proceed();
        }else{
            if(ShiroKit.getSession().getAttribute("sessionFlag") == null){
                ShiroKit.getSubject().logout();
                throw new InvalidSessionException();
            }else{
                return point.proceed();
            }
        }
    }
}

package com.intellif.consumer.web;

import com.google.common.collect.Maps;
import com.intellif.utils.ApplicationContextHolder;
import com.netflix.loadbalancer.ServerList;
import com.netflix.niws.loadbalancer.DiscoveryEnabledServer;
import feign.Response;
import io.prometheus.client.Counter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

@RestController
public class HelloController {

    private static final Counter requestTotal = Counter.build()
            .name("my_sample_counter")
            .labelNames("status")
            .help("A simple Counter to illustrate custom Counters in Spring Boot and Prometheus").register();

    @Autowired
    private RemoteService remoteService;


    @GetMapping("/batch/test")
    public Map<String, Object> batchTest() throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2000);
        List<Long> execTimes = Collections.synchronizedList(new ArrayList<>());
        int testCount = 1000 * 10;
        CountDownLatch startLatch = new CountDownLatch(1);
        CountDownLatch endLatch = new CountDownLatch(testCount);
        AtomicInteger errCount = new AtomicInteger();
        for (int i = 0; i < testCount; i++) {
            executor.execute(() -> {
                try {
                    startLatch.await();
                } catch (InterruptedException e) {
                    //doing nothing...
                }
                try {
                    Date startTime = new Date();
                    postJson();
                    execTimes.add(new Date().getTime() - startTime.getTime());
                } catch (Throwable t) {
                    System.out.println(t);
                    errCount.incrementAndGet();
                } finally {
                    endLatch.countDown();
                }
            });
        }
        startLatch.countDown();
        endLatch.await();
        long sumTime = 0;
        for (Long execTime : execTimes) {
            sumTime += execTime;
            System.out.println("execute time: " + execTime);
        }
        System.out.println("avgTime : " + sumTime / execTimes.size());
        System.out.println("errCount: " + errCount.get());
        System.out.println("totalCount: " + execTimes.size());
        Map<String, Object> map = new HashMap<>();
        map.put("time", execTimes);
        map.put("err", errCount);
        map.put("avgTime", sumTime / execTimes.size());
        return map;
    }


    @GetMapping("/test/simple")
    public String simple() throws InterruptedException {
        Thread.sleep(new Random().nextInt(1000 * 10));
        return "hello world";
    }

    @GetMapping("/test/hello")
    public User hello() {
        User user = remoteService.user();
        ApplicationContext applicationContext = ApplicationContextHolder.getApplicationContext();
        ServerList serverList = applicationContext.getBean(ServerList.class);
        List<DiscoveryEnabledServer> updatedListOfServers = serverList.getUpdatedListOfServers();
        for (DiscoveryEnabledServer updatedListOfServer : updatedListOfServers) {
            System.out.printf("id[%s] host:port[%s] \n", updatedListOfServer.getId(), updatedListOfServer.getHostPort());
        }
        System.out.println("--------- initial ---------");
        List<DiscoveryEnabledServer> initialListOfServers = serverList.getInitialListOfServers();
        for (DiscoveryEnabledServer initialListOfServer : initialListOfServers) {
            System.out.printf("id[%s] host:port[%s] \n", initialListOfServer.getId(), initialListOfServer.getHostPort());
        }


        return user;
    }

    @GetMapping("/remote/hello")
    public String remoteHello() {
        Map<String, String> param = Maps.newHashMap();
        param.put("age", "18");
        param.put("sex", "女");
        param.put("name", "张珊");
        return remoteService.hello(param);
    }

    @GetMapping(value = "/remote/form/data")
    public String remoteFormData(String name) {
        return remoteService.formData("张三");
    }

    @GetMapping(value = "/remote/post/json")
    public String postJson() {
        Date start = new Date();
        String name = "xiao熊";
        User user = new User("王华", "男", 18);
        String s = remoteService.postJson(name, user);
        System.out.printf("the controller get result: ==> %d\n", new Date().getTime() - start.getTime());
        return s;
    }

    @RequestMapping(value = "/download", method = RequestMethod.GET)
    public ResponseEntity<byte[]> downFile() {
        ResponseEntity<byte[]> result = null;
        InputStream inputStream = null;
        try {
            // feign文件下载
            Response response = remoteService.downloadFile();
            Response.Body body = response.body();
            inputStream = body.asInputStream();
            byte[] b = new byte[inputStream.available()];
            inputStream.read(b);
            HttpHeaders heads = new HttpHeaders();
            heads.add(HttpHeaders.CONTENT_DISPOSITION, "attachment;filename=123.txt");
            heads.add(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE);

            result = new ResponseEntity<byte[]>(b, heads, HttpStatus.OK);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            if (inputStream != null) {
                try {
                    inputStream.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
        return result;
    }


}

package com.thomaskioko.podadddict.musicplayerlib.model;

import android.os.Parcel;
import android.os.Parcelable;

import java.util.Date;

/**
 * Encapsulate Track track data.
 *
 * @author kioko
 */
public class Track implements Parcelable {

    /**
     * Parcelable.
     */
    public static final Parcelable.Creator<Track> CREATOR = new Parcelable.Creator<Track>() {
        public Track createFromParcel(Parcel source) {
            return new Track(source);
        }

        public Track[] newArray(int size) {
            return new Track[size];
        }
    };


    private long mDurationInMilli;
    private Date mCreationDate;
    private boolean mPublicSharing;
    private boolean mStreamable;
    private boolean mDownloadable;
    private String mArtworkUrl;
    private String mStreamUrl;
    private String mGenre;
    private String mTitle;
    private String mArtist;
    private String mDescription;

    /**
     * Default constructor.
     */
    public Track() {
    }

    private Track(Parcel in) {
        this.mDurationInMilli = in.readLong();
        long tmpMCreatationDate = in.readLong();
        this.mCreationDate = tmpMCreatationDate == -1 ? null : new Date(tmpMCreatationDate);
        this.mPublicSharing = in.readByte() != 0;
        this.mStreamable = in.readByte() != 0;
        this.mDownloadable = in.readByte() != 0;
        this.mArtworkUrl = in.readString();
        this.mStreamUrl = in.readString();
        this.mGenre = in.readString();
        this.mTitle = in.readString();
        this.mArtist = in.readString();
        this.mDescription = in.readString();
    }

    @Override
    public int describeContents() {
        return 0;
    }

    @Override
    public void writeToParcel(Parcel dest, int flags) {

        dest.writeLong(this.mDurationInMilli);
        dest.writeLong(mCreationDate != null ? mCreationDate.getTime() : -1);
        dest.writeByte(mPublicSharing ? (byte) 1 : (byte) 0);
        dest.writeByte(mStreamable ? (byte) 1 : (byte) 0);
        dest.writeByte(mDownloadable ? (byte) 1 : (byte) 0);
        dest.writeString(this.mArtworkUrl);
        dest.writeString(this.mStreamUrl);
        dest.writeString(this.mGenre);
        dest.writeString(this.mTitle);
        dest.writeString(this.mArtist);
        dest.writeString(this.mDescription);

    }

    @Override
    public String toString() {
        return "Track{"
                + "mDurationInMilli=" + mDurationInMilli
                + ", mCreationDate=" + mCreationDate
                + ", mPublicSharing=" + mPublicSharing
                + ", mStreamable=" + mStreamable
                + ", mDownloadable=" + mDownloadable
                + ", mArtworkUrl='" + mArtworkUrl + '\''
                + ", mStreamUrl='" + mStreamUrl + '\''
                + ", mGenre='" + mGenre + '\''
                + ", mTitle='" + mTitle + '\''
                + ", mDescription='" + mDescription + '\''
                + '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }


        return true;
    }

    @Override
    public int hashCode() {
        return 0;
    }

    /**
     * Integer Id.
     *
     * @return Integer Id.
     */
    public int getId() {
        return 0;
    }

    /**
     * duration in milliseconds
     *
     * @return duration in milliseconds
     */
