package io.cryptolens.models;

import com.google.gson.Gson;
import io.cryptolens.internal.ActivateResult;
import io.cryptolens.legacy.JavaSecuritySignatureVerifier;
import io.cryptolens.legacy.Shared;
import io.cryptolens.methods.Helpers;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.List;

/**
 * Represents a license returned by Key.Activate.
 */
public class LicenseKey {
    public int ProductId;
    public long Id;
    public String Key;
    public long Created;
    public long Expires;
    public int Period;
    public boolean F1;
    public boolean F2;
    public boolean F3;
    public boolean F4;
    public boolean F5;
    public boolean F6;
    public boolean F7;
    public boolean F8;
    public String Notes;
    public boolean Block;
    public long GlobalId;
    public Customer Customer;
    public List<ActivatedMachine> ActivatedMachines;
    public boolean TrialActivation;
    public int MaxNoOfMachines;
    //  private int AllowedMachines;
    public List<DataObject> DataObjects;
    public long SignDate;

    /**
     * Internal variable used to store the response.
     */
    protected String RawResponse;

    /**
     * Save the current license object as a string. You can load it again using @see LoadFromString.
     * @return A string representing this license object object.
     */
    public String SaveAsString() {
        return RawResponse;
    }


    /**
     * Load a license string (created with @see SaveAsString) into a license object.
     * Note, signature verification will be performed under the hood.
     * @param RSAPubKey Your RSA Public Key, which can be found <a href="https://app.cryptolens.io/docs/api/v3/QuickStart">here</a>.
     * @param licenseString The license key object stored as a string.
     * @return A license key object from the 'licenseString'.
     */
    public static LicenseKey LoadFromString(String RSAPubKey, String licenseString) {
        return LoadFromString(RSAPubKey, licenseString, -1);
    }

    /**
     * Load a license string (created with @see SaveAsString) into a license object.
     * Note, signature verification will be performed under the hood.
     * @param RSAPubKey Your RSA Public Key, which can be found <a href="https://app.cryptolens.io/docs/api/v3/QuickStart">here</a>.
     * @param licenseString The license key object stored as a string.
     * @param signatureExpirationInterval If the license key was signed, this method
     *                                    will check so that no more than "signatureExpirationInterval"
     *                                    days have passed since the last activation.
     * @return A new license key object or null (if an error has occurred).
     */
    public static LicenseKey LoadFromString(String RSAPubKey, String licenseString, int signatureExpirationInterval) {

        ActivateResult result = null;
        byte[] licenseKey;
        byte[] signature;
        try{
            result = new Gson().fromJson(licenseString, ActivateResult.class);
            licenseKey = Shared.defaultBase64Decoder(result.licenseKey);
            signature = Shared.defaultBase64Decoder(result.signature);
        } catch (Exception ex) {
            System.err.println(ex.getStackTrace()); return null;
        }

        try {

            JavaSecuritySignatureVerifier signatureVerifier = new JavaSecuritySignatureVerifier();
            int mstart = RSAPubKey.indexOf("<Modulus>");
            int mend = RSAPubKey.indexOf("</Modulus>");
            int estart = RSAPubKey.indexOf("<Exponent>");
            int eend = RSAPubKey.indexOf("</Exponent>");
            signatureVerifier.setModulusBase64(RSAPubKey.substring(mstart + 9, mend));
            signatureVerifier.setExponentBase64(RSAPubKey.substring(estart + 10, eend));

            if (!signatureVerifier.verify(licenseKey, signature)) {
                System.err.println("Signature check failed");
                return null;
            }
        } catch(Exception ex) {System.err.println(ex.getStackTrace()); return null;}

        String s = new String(licenseKey, StandardCharsets.UTF_8);
        LicenseKey license = new Gson().fromJson(s, LicenseKey.class);
        license.RawResponse = licenseString;

        if(signatureExpirationInterval > 0) {
            long unixTime = System.currentTimeMillis() / 1000L;

            if(license.SignDate + 0x15180*signatureExpirationInterval < unixTime) {
                // the license file has expired.
                System.err.println("The license file has expired.");
                return  null;
            }
        }

        return license;
    }

    /**
     * Check if the current license has expired.
     * @return True if it has expired and false otherwise.
     */
    public boolean HasExpired() {
        return Helpers.HasExpired(this);
    }

    /**
     * Check if the current license has not expired.
     * @return True if it has not expired and false otherwise.
     */
    public boolean HasNotExpired() {
        return Helpers.HasNotExpired(this);
    }

    /**
     * Check if this license has a certain feature enabled (i.e. set to true).
     * @param feature The feature, eg 1 to 8.
     * @return If the feature is set to true, true is returned and false otherwise.
     */
    public boolean HasFeature(int feature) {
        return Helpers.HasFeature(this, feature);
    }

}

package org.infinispan.persistence.leveldb.config;

import static org.testng.AssertJUnit.assertEquals;
import static org.testng.AssertJUnit.assertFalse;
import static org.testng.AssertJUnit.assertTrue;

import java.io.IOException;
import java.io.InputStream;

import org.infinispan.Cache;
import org.infinispan.commons.test.skip.OS;
import org.infinispan.commons.test.skip.SkipTestNG;
import org.infinispan.commons.util.Util;
import org.infinispan.configuration.cache.Configuration;
import org.infinispan.configuration.cache.ConfigurationBuilder;
import org.infinispan.configuration.cache.StoreConfiguration;
import org.infinispan.configuration.global.GlobalConfiguration;
import org.infinispan.configuration.global.GlobalConfigurationBuilder;
import org.infinispan.configuration.parsing.ConfigurationBuilderHolder;
import org.infinispan.configuration.parsing.ParserRegistry;
import org.infinispan.manager.DefaultCacheManager;
import org.infinispan.manager.EmbeddedCacheManager;
import org.infinispan.persistence.leveldb.configuration.LevelDBStoreConfiguration;
import org.infinispan.persistence.leveldb.configuration.LevelDBStoreConfigurationBuilder;
import org.infinispan.test.AbstractInfinispanTest;
import org.infinispan.test.TestingUtil;
import org.testng.annotations.AfterClass;
import org.testng.annotations.BeforeClass;
import org.testng.annotations.Test;

/**
 *
 * @author <a href="mailto:rtsang@redhat.com">Ray Tsang</a>
 *
 */
@Test(groups = "unit", testName = "persistence.leveldb.configuration.ConfigurationTest")
public class ConfigurationTest extends AbstractInfinispanTest {
   private String tmpDirectory = TestingUtil.tmpDirectory(this.getClass());
   private String tmpDataDirectory = tmpDirectory + "/data";
   private String tmpExpiredDirectory = tmpDirectory + "/expired";

   @BeforeClass
   public void skipOnOS() {
      SkipTestNG.skipOnOS(OS.SOLARIS, OS.WINDOWS);
   }

   @AfterClass(alwaysRun = true)
   protected void clearTempDir() {
      Util.recursiveFileRemove(tmpDirectory);
   }

   public void testConfigBuilder() {
      GlobalConfiguration globalConfig = new GlobalConfigurationBuilder()
            .transport().defaultTransport()
            .build();

      Configuration cacheConfig = new ConfigurationBuilder().persistence().addStore(LevelDBStoreConfigurationBuilder.class).location(tmpDataDirectory)
            .expiredLocation(tmpExpiredDirectory).implementationType(LevelDBStoreConfiguration.ImplementationType.AUTO).build();

      StoreConfiguration cacheLoaderConfig = cacheConfig.persistence().stores().get(0);
      assertTrue(cacheLoaderConfig instanceof LevelDBStoreConfiguration);
      LevelDBStoreConfiguration leveldbConfig = (LevelDBStoreConfiguration) cacheLoaderConfig;
      assertEquals(tmpDataDirectory, leveldbConfig.location());
      assertEquals(tmpExpiredDirectory, leveldbConfig.expiredLocation());

      EmbeddedCacheManager cacheManager = new DefaultCacheManager(globalConfig);

      cacheManager.defineConfiguration("testCache", cacheConfig);

      cacheManager.start();
      Cache<String, String> cache = cacheManager.getCache("testCache");

      cache.put("hello", "there");
      cache.stop();
      cacheManager.stop();
   }

   public void testXmlConfig() throws IOException {
      InputStream configSTream = ConfigurationTest.class.getResourceAsStream("/config/leveldb-config-auto.xml");
      ConfigurationBuilderHolder configHolder = new ParserRegistry().parse(configSTream);

      // check persistence attributes
      Configuration cacheConfig = configHolder.getNamedConfigurationBuilders().get("testCache").build();
      assertFalse(cacheConfig.persistence().passivation());
      assertEquals(cacheConfig.persistence().stores().size(), 1);

      // check generic store attributes
      StoreConfiguration cacheLoaderConfig = cacheConfig.persistence().stores().get(0);
      assertFalse(cacheLoaderConfig.shared());
      assertTrue(cacheLoaderConfig.preload());
      assertTrue(cacheLoaderConfig instanceof LevelDBStoreConfiguration);

      // check LevelDB store attributes
      LevelDBStoreConfiguration leveldbConfig = (LevelDBStoreConfiguration) cacheLoaderConfig;
      assertEquals("/tmp/leveldb/52/data", leveldbConfig.location());
      assertEquals("/tmp/leveldb/52/expired", leveldbConfig.expiredLocation());
      assertEquals(LevelDBStoreConfiguration.ImplementationType.AUTO, leveldbConfig.implementationType());
   }
}

