            throw new UnExpectedRequestException("rule_id: [" + request.getMultiRuleId() + "]) {&IS_NOT_A_MULTI_TEMPLATE_RULE}");
        }
        // Delete rule
        return deleteMultiRuleReal(ruleInDb);
    }

    @Override
    @Transactional(rollbackFor = {Exception.class})
