package cn.torna.manager.doc.postman;

import lombok.Getter;
import lombok.Setter;
import org.springframework.util.CollectionUtils;
import org.springframework.util.StringUtils;

import java.util.List;
import java.util.stream.Collectors;

/**
 * @author tanghc
 */
@Getter
@Setter
public class Url {

    private String protocol;
    private List<String> host;
    private String raw;
    private String port;
    private List<String> path;
    /** path 参数 */
    private List<Param> variable;
    private List<Param> query;

    public String getFullUrl() {
        if (!CollectionUtils.isEmpty(path)) {
            return "/" + path.stream()
                    .map(p -> {
                        // :id
                        if (p.startsWith(":")) {
                            return "{" + p.substring(1) + "}";
                        }
                        return p;
                    })
                    .collect(Collectors.joining("/"));
        }
        if (StringUtils.hasText(raw)) {
            return raw;
        }
        return "";
    }

}

package ch.pontius.nio.smb;

public final class SMBPathUtil {
    /**
     * Private constructor; this class cannot be instantiated.
     */
    private SMBPathUtil() {}

    /**
     * Checks if the provided path string points to a folder (i.e. ends with an /).
     *
     * @param path Path that should be checked.
     * @return True if provided path points to a folder and false otherwise.
     */
    public static boolean isFolder(String path) {
        return path.endsWith(SMBFileSystem.PATH_SEPARATOR);
    }

    /**
     *  Checks if provided path string is an absolute path (i.e. starts with an /).
     *
     * @param path Path that should be checked.
     * @return True if provided path is a relative path and false otherwise.
     */
    public static boolean isAbsolutePath(String path) {
        return path.startsWith(SMBFileSystem.PATH_SEPARATOR);
    }

    /**
     *  Checks if provided path string is a relative path (i.e. does not start with an /).
     *
     * @param path Path that should be checked.
     * @return True if provided path is a relative path and false otherwise.
     */
    public static boolean isRelativePath(String path) {
        return !path.startsWith(SMBFileSystem.PATH_SEPARATOR);
    }

    /**
     * Splits the provided path string into its path components.
     *
     * @param path Path string that should be split.
     * @return Array of path components.
     */
    public static String[] splitPath(String path) {
        String[] split = path.split(SMBFileSystem.PATH_SEPARATOR);
        if (split.length > 0 && split[0].equals("")) {
            String[] truncated = new String[split.length-1];
            System.arraycopy(split, 1,truncated, 0, split.length-1);
            return truncated;
        } else {
            return split;
        }
    }

    /**
     * Merges the provided path components into a single pat string.
     *
     * @param components Array of path components.
     * @param start Index of the first item in the list that should be considered; inclusive.
     * @param end Index of the last item in the list that should be considered; exclusive.
     * @param absolute Boolean indicating whether resulting path should be treated as absolute path.
     * @param folder Boolean indicating whether resulting path should point to a folder.
     * @return Resulting path string
     */
    public static String mergePath(String[] components, int start, int end, boolean absolute, boolean folder) {
        if (components.length == 0) return "";

        StringBuilder builder = new StringBuilder();
        if (absolute) builder.append(SMBFileSystem.PATH_SEPARATOR);
        for (int i = start; i<end; i++) {
            String component = components[i];
            builder.append(component);
            if (!component.endsWith("/")) {
                builder.append(SMBFileSystem.PATH_SEPARATOR);
            }
        }
        if (!folder) {
            return builder.substring(0, Math.max(0,builder.length()-1));
        } else {
            return builder.toString();
        }
    }
}

import models.Event;
import java.util.List;
import java.util.ArrayList;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;


public class App {
    public static void main(String[] args) {


        ArrayList<Event> allEvents = new ArrayList<Event>();

        boolean programRunning = true;
        while (programRunning) {

            try {
                Event event = new Event();
                System.out.println("Welcome to Java Event Planning. Please type one of the following options: all events, custom event, or exit");

                BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));
                String navigationChoice = bufferedReader.readLine().toLowerCase();

                if (navigationChoice.equals("all events")) {
                    for (Event individualEvent : allEvents) {
                        System.out.println("----------------");
                        System.out.println(individualEvent.getPerson() + " people,");
                        System.out.println("Having " + individualEvent.getMeal());
                        System.out.println("And " + individualEvent.getDrink());
                        System.out.println("While enjoying the " + individualEvent.getShow());
                        System.out.println("----------------");
                    }

                } else if (navigationChoice.equals("custom event")) {

                    System.out.println("Great, Let's get started on your Event! First, how many people will be attending?");
                    Integer userEventPerson = Integer.parseInt(bufferedReader.readLine());
                    event.setPerson(userEventPerson);

                    System.out.println("OK, and what type of food should there be: Steak or Seafood");
                    boolean selectFood = true;
                    while (selectFood) {
                        String userEventMeal = bufferedReader.readLine().toLowerCase();
                        if (userEventMeal.equals("steak") || userEventMeal.equals("seafood")) {
                            event.setMeal(userEventMeal);
                            event.setPriceOfMeal();
                            selectFood = false;

                        } else {
                            System.out.println("Please type one of the items listed.");
                        }

                    }
                    System.out.println("Awesome! What type of drinks should there be: Beer or Wine");
                    boolean selectDrink = true;
                    while (selectDrink) {
                        String userEventDrink = bufferedReader.readLine().toLowerCase();
                        if (userEventDrink.equals("beer") || userEventDrink.equals("wine")) {
                            event.setDrink(userEventDrink);
                            event.setPriceOfDrink();
                            selectDrink = false;

                        } else {
                            System.out.println("Please type one of the items listed.");
                        }
                    }

                    System.out.println("And what type of entertainment should there be: DJ or Concert");
                    boolean selectShow = true;
                    while (selectShow) {
                        String userEventShow = bufferedReader.readLine().toLowerCase();
                        if (userEventShow.equals("dj") || userEventShow.equals("concert")) {
                            event.setShow(userEventShow);
                            event.setPriceOfShow();
                            selectShow = false;

                        } else  {
                            System.out.println("Please type one of the items listed.");

                        }
                    }

                    System.out.println("Holiday Discount: Enter SUMMERFUN to take $50 off your purchase! Or PARTYDJ to receive a free DJ show with your purchase! Or DECLINE to skip this step.");
                    boolean selectCoupon = true;
                    while (selectCoupon) {

                        String deal = bufferedReader.readLine().toLowerCase();

                        if (deal.equals("summerfun")) {
                            System.out.println("----------------");
                            System.out.println("All Right! Your purchase has been adjusted!");
                            int eventDeal = (event.priceTotal() - 50);
                            System.out.println("Your new total is $" + eventDeal);
                            System.out.println("----------------");
                            selectCoupon = false;

                        } else if (deal.equals("partydj")) {
                            System.out.println("----------------");
                            System.out.println("All Right! Your purchase has been adjusted!");
                            int eventDeal = (event.priceTotal() - (event.getPriceOfShow()));
                            System.out.println("Your new total is $" + eventDeal);
                            System.out.println("----------------");
                            selectCoupon = false;

                        } else if (deal.equals("decline")) {
                            System.out.println("----------------");
                            System.out.println("What, you don't like savings?");
                            System.out.println("Your total is: " + event.priceTotal());
                            System.out.println("----------------");
                            selectCoupon = false;
                        }
                    }
                    allEvents.add(event);

                } else if (navigationChoice.equals("exit")){
                    System.out.println("Goodbye!");
                    programRunning = false;
                } else {
                    System.out.println("I'm sorry, we don't recognize your input");
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

