        this.inline("th", "運", null);
        this.inline("th", "速力", null);
        this.inline("th", "射程", null);

        this.end(); // tr

        int totalNowHp = 0;
        int totalMaxHp = 0;

        for (int i = 0; i < ships.size(); ++i) {
            SHIP ship = ships.get(i);
