                int[] maxeq = ship.getShipInfo().getMaxeq2(); // 艦載機最大搭載数
                if (c < items.size()) {
                    ItemDto item = items.get(c);
                    if (item != null) {
                        if (item.isPlane()) {
                            String max = (maxeq == null) ? "?" : String.valueOf(maxeq[c]);
                            String cur = (onSlots == null) ? "?" : String.valueOf(onSlots[c]);
                            onSlot = cur + "/" + max;
