package org.jdbi.v3.sqlobject.config;

import java.lang.reflect.Method;
import java.util.Optional;
import java.util.stream.Stream;

import org.jdbi.v3.core.Handle;
import org.jdbi.v3.core.Jdbi;
import org.jdbi.v3.core.Something;
import org.jdbi.v3.core.mapper.SomethingMapper;
import org.jdbi.v3.core.rule.H2DatabaseRule;
import org.jdbi.v3.sqlobject.Handler;
import org.jdbi.v3.sqlobject.HandlerFactory;
import org.jdbi.v3.sqlobject.Handlers;
import org.jdbi.v3.sqlobject.SqlObjectPlugin;
import org.jdbi.v3.sqlobject.customizer.Bind;
import org.jdbi.v3.sqlobject.customizer.BindBean;
import org.jdbi.v3.sqlobject.statement.SqlQuery;
import org.jdbi.v3.sqlobject.statement.SqlUpdate;
import org.jdbi.v3.sqlobject.transaction.Transaction;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

import static org.assertj.core.api.Assertions.assertThat;

public class TestUseCustomHandlerFactory {
    @Rule
    public H2DatabaseRule dbRule = new H2DatabaseRule().withSomething().withPlugin(new SqlObjectPlugin());

    private Handle handle;

    @Before
    public void setUp() {
        Jdbi db = dbRule.getJdbi();

        HandlerFactory defaultHandlerFactory = new HandlerFactory() {

            @Override
            public Optional<Handler> buildHandler(Class<?> sqlObjectType, Method method) {
                return getImplementation(sqlObjectType, method).map(m ->
                        (Handler) (target, args, handle) -> m.invoke(null, Stream.concat(Stream.of(target), Stream.of(args)).toArray())
               );
            }

            private Optional<Method> getImplementation(Class<?> type, Method method) {
                return Stream.of(type.getClasses())
                        .filter(c -> c.getSimpleName().equals("DefaultImpls"))
                        .flatMap(c -> Stream.of(c.getMethods()).filter(m -> m.getName().equals(method.getName())))
                        .findAny();
            }
        };

        db.configure(Handlers.class, c -> c.register(defaultHandlerFactory));
        handle = db.open();
    }

    @Test
    public void shouldUseConfiguredDefaultHandler() {
        SomethingDao h = handle.attach(SomethingDao.class);
        Something s = h.insertAndFind(new Something(1, "Joy"));
        assertThat(s.getName()).isEqualTo("Joy");
    }

    @RegisterRowMapper(SomethingMapper.class)
    public interface SomethingDao {
        @SqlUpdate("insert into something (id, name) values (:id, :name)")
        void insert(@BindBean Something s);

        @SqlQuery("select id, name from something where id = :id")
        Something findById(@Bind("id") int id);

        @Transaction
        Something insertAndFind(Something s);

        @SuppressWarnings("unused")
        class DefaultImpls {
            private DefaultImpls() {}

            public static Something insertAndFind(SomethingDao dao, Something s) {
                dao.insert(s);
                return dao.findById(s.getId());
            }
        }
    }

}

package org.zstack.compute.allocator;

import org.springframework.beans.factory.annotation.Autowire;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Configurable;
import org.zstack.core.db.DatabaseFacade;
import org.zstack.core.db.SimpleQuery;
import org.zstack.core.db.SimpleQuery.Op;
import org.zstack.core.errorcode.ErrorFacade;
import org.zstack.header.allocator.*;
import org.zstack.header.exception.CloudRuntimeException;
import org.zstack.header.host.HostVO;
import org.zstack.header.storage.primary.PrimaryStorageClusterRefVO;
import org.zstack.header.storage.primary.PrimaryStorageClusterRefVO_;
import org.zstack.header.vm.VmInstanceConstant.VmOperation;
import org.zstack.header.vm.VmInstanceInventory;
import org.zstack.header.volume.VolumeInventory;
import org.zstack.utils.CollectionUtils;
import org.zstack.utils.function.Function;

import java.util.*;

/**
 */
@Configurable(preConstruction = true, autowire = Autowire.BY_TYPE)
public class AttachedVolumePrimaryStorageAllocatorFlow extends AbstractHostAllocatorFlow {
    @Autowired
    private DatabaseFacade dbf;

    @Override
    public void allocate() {
        throwExceptionIfIAmTheFirstFlow();

        if (VmOperation.NewCreate.toString().equals(spec.getVmOperation())) {
            throw new CloudRuntimeException("AttachedVolumePrimaryStorageAllocatorFlow can not be used for creating new vm. It's for starting/migrating vm");
        }

        VmInstanceInventory vm = spec.getVmInstance();
        List<String> requiredPsUuids = CollectionUtils.transformToList(vm.getAllVolumes(), new Function<String, VolumeInventory>() {
            @Override
            public String call(VolumeInventory arg) {
                return arg.getPrimaryStorageUuid();
            }
        });

        // find out cluster that have all required primary storage attached
        SimpleQuery<PrimaryStorageClusterRefVO> q = dbf.createQuery(PrimaryStorageClusterRefVO.class);
        q.add(PrimaryStorageClusterRefVO_.primaryStorageUuid, Op.IN, requiredPsUuids);
        List<PrimaryStorageClusterRefVO> refs = q.list();
        Map<String, Set<String>> clusterPs = new HashMap<String, Set<String>>();
        for (PrimaryStorageClusterRefVO ref : refs) {
            Set<String> pss = clusterPs.get(ref.getClusterUuid());
            if (pss == null) {
                pss = new HashSet<String>();
                clusterPs.put(ref.getClusterUuid(), pss);
            }
            pss.add(ref.getPrimaryStorageUuid());
        }

        List<String> clusterHavingAllPs = new ArrayList<String>();
        for (Map.Entry<String, Set<String>> e : clusterPs.entrySet()) {
            if (e.getValue().containsAll(requiredPsUuids)) {
                clusterHavingAllPs.add(e.getKey());
            }
        }

        // find out host in above result clusters
        List<HostVO> tmp = candidates;
        candidates = new ArrayList<HostVO>();
        if (!clusterHavingAllPs.isEmpty()) {
            for (HostVO h : tmp) {
                if (clusterHavingAllPs.contains(h.getClusterUuid())) {
                    candidates.add(h);
                }
            }
        }

        if (candidates.isEmpty()) {
            fail(String.format("no host found in clusters which have attached to all primary storage%s where vm[uuid:%s]'s volumes locate",
                    requiredPsUuids, vm.getUuid()));
        } else {
            next(candidates);
        }
    }
}

