import com.google.common.base.MoreObjects;
import com.hederahashgraph.api.proto.java.Timestamp;
import com.swirlds.common.io.SerializableDataInputStream;
import com.swirlds.common.io.SerializableDataOutputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class RichInstant {
	private static final Logger log = LogManager.getLogger(RichInstant.class);

	public static final RichInstant MISSING_INSTANT = new RichInstant(0L, 0);
	public static final RichInstant.Provider LEGACY_PROVIDER = new Provider();

	private int nanos;
	private long seconds;

	@Deprecated
	public static class Provider {
		public RichInstant deserialize(DataInputStream in) throws IOException {
			in.readLong();
			in.readLong();

			return new RichInstant(in.readLong(), in.readInt());
		}
	}

	public RichInstant() { }

	public RichInstant(long seconds, int nanos) {
		this.seconds = seconds;
		this.nanos = nanos;
	}

	public static RichInstant from(SerializableDataInputStream in) throws IOException {
		return new RichInstant(in.readLong(), in.readInt());
	}

	public void serialize(SerializableDataOutputStream out) throws IOException {
		out.writeLong(seconds);
		out.writeInt(nanos);
	}

	/* --- Object --- */

	@Override
	public String toString() {
		return MoreObjects.toStringHelper(this)
				.add("seconds", seconds)
				.add("nanos", nanos)
				.toString();
	}

	@Override
	public boolean equals(Object o) {
		if (this == o) {
			return true;
		}
		if (o == null || RichInstant.class != o.getClass()) {
			return false;
		}
		var that = (RichInstant)o;
		return seconds == that.seconds && nanos == that.nanos;
	}

	@Override
	public int hashCode() {
		return Objects.hash(seconds, nanos);
	}

	/* --- Bean --- */

	public long getSeconds() {
		return seconds;
	}

	public int getNanos() {
		return nanos;
	}


	/* --- Helpers --- */

	public static RichInstant fromGrpc(Timestamp grpc) {
		return grpc.equals(Timestamp.getDefaultInstance())
				? MISSING_INSTANT
				: new RichInstant(grpc.getSeconds(), grpc.getNanos());
	}

	public Timestamp toGrpc() {
		return isMissing()
				? Timestamp.getDefaultInstance() :
				Timestamp.newBuilder().setSeconds(seconds).setNanos(nanos) .build();
	}
	public boolean isAfter(RichInstant other) {
		return (seconds > other.seconds) || (seconds == other.seconds && (nanos > other.nanos));
	}

	public Instant toJava() {
		return Instant.ofEpochSecond(seconds, nanos);
	}

	public static RichInstant fromJava(Instant when) {
		return Optional.ofNullable(when)
				.map(at -> new RichInstant(at.getEpochSecond(), at.getNano()))
				.orElse(null);
	}

	public boolean isMissing() {
		return this == MISSING_INSTANT;
	}
}

package com.github.tkurz.media.fragments.temporal;

/**
 * Represents a temporal fragment in 'Normal Play Time' (npt) like specified in RFC 2326.
 * By default, start time is 0.0 and end time is infinite.
 * <p/>
 * Author: Thomas Kurz (tkurz@apache.org)
 */
public class NPTFragment extends TemporalFragment<NPTFragment> {

    private Clocktime start;
    private Clocktime end;

    public NPTFragment() {
        this.start = Clocktime.ZERO;
        this.end = Clocktime.INFINIT;
    }

    public NPTFragment(Clocktime start, Clocktime end) {
        this.start = start != null ? start : Clocktime.ZERO;
        this.end = end != null ? end : Clocktime.INFINIT;
    }

    @Override
    public Unit getUnit() {
        return Unit.NPT;
    }

    public Clocktime getStart() {
        return start;
    }

    public void setStart(Clocktime start) {
        this.start = start != null ? start : Clocktime.ZERO;
    }

    public Clocktime getEnd() {
        return end != null ? end : Clocktime.INFINIT;
    }

    public void setEnd(Clocktime end) {
        this.end = end != null ? end : Clocktime.INFINIT;
    }

    public String stringValue() {
        if(end == Clocktime.INFINIT) return "t="+start;
        if(start == Clocktime.ZERO) return "t=,"+end;
        return "t="+start+","+end;
    }

}

