import org.eclipse.emf.edit.ui.action.CollapseAllAction;
import org.eclipse.emf.edit.ui.action.ControlAction;
import org.eclipse.emf.edit.ui.action.CreateChildAction;
import org.eclipse.emf.edit.ui.action.CreateSiblingAction;
import org.eclipse.emf.edit.ui.action.EditingDomainActionBarContributor;
import org.eclipse.emf.edit.ui.action.ExpandAllAction;
import org.eclipse.emf.edit.ui.action.FindAction;
import org.eclipse.emf.edit.ui.action.LoadResourceAction;
import org.eclipse.emf.edit.ui.action.RevertAction;
import org.eclipse.emf.edit.ui.action.ValidateAction;
import org.eclipse.jface.action.Action;
import org.eclipse.jface.action.ActionContributionItem;
import org.eclipse.jface.action.IAction;
import org.eclipse.jface.action.IContributionItem;
import org.eclipse.jface.action.IContributionManager;
import org.eclipse.jface.action.IMenuManager;
import org.eclipse.jface.action.IToolBarManager;
import org.eclipse.jface.action.MenuManager;
import org.eclipse.jface.action.Separator;
import org.eclipse.jface.action.SubContributionItem;
import org.eclipse.jface.viewers.ISelection;
import org.eclipse.jface.viewers.ISelectionChangedListener;
import org.eclipse.jface.viewers.ISelectionProvider;
import org.eclipse.jface.viewers.IStructuredSelection;
import org.eclipse.jface.viewers.SelectionChangedEvent;
import org.eclipse.jface.viewers.Viewer;
import org.eclipse.ui.IEditorPart;

import ru.arsysop.loft.rgm.internal.base.workbench.Messages;

public abstract class EmfActionBarContributor extends EditingDomainActionBarContributor
		implements ISelectionChangedListener {

	private final IAction properties = new ShowPropertiesViewAction(this::getPage);

	private final IAction refresh = new Action(Messages.BaseActionBarContributor_refresh_text) {
		@Override
		public boolean isEnabled() {
			return editor instanceof IViewerProvider;
		}

		@Override
		public void run() {
			if (editor instanceof IViewerProvider) {
				Viewer viewer = ((IViewerProvider) editor).getViewer();
				if (viewer != null) {
					viewer.refresh();
				}
			}
		}
	};

	protected IEditorPart editor;
	protected ISelectionProvider selections;

	protected Collection<IAction> createChildActions;

	protected IMenuManager createChildMenuManager;

	protected Collection<IAction> createSiblingActions;

	protected IMenuManager createSiblingMenuManager;

	public EmfActionBarContributor() {
		super(ADDITIONS_LAST_STYLE);
		loadResourceAction = new LoadResourceAction();
		validateAction = new ValidateAction();
		controlAction = new ControlAction();
		findAction = FindAction.create();
		revertAction = new RevertAction();
		expandAllAction = new ExpandAllAction();
		collapseAllAction = new CollapseAllAction();
	}

	@Override
	public final void contributeToToolBar(IToolBarManager toolBarManager) {
		super.contributeToToolBar(toolBarManager);
		completeToolbar(toolBarManager);
	}

	protected abstract void completeToolbar(IToolBarManager toolBarManager);

	@Override
	public final void contributeToMenu(IMenuManager menuManager) {
		super.contributeToMenu(menuManager);
		IMenuManager submenuManager = createSubMenu();
		menuManager.insertAfter("additions", submenuManager); //$NON-NLS-1$
		submenuManager.add(new Separator("settings")); //$NON-NLS-1$
		submenuManager.add(new Separator("actions")); //$NON-NLS-1$
		submenuManager.add(new Separator("additions")); //$NON-NLS-1$
		submenuManager.add(new Separator("additions-end")); //$NON-NLS-1$
		createChildMenuManager = new MenuManager(Messages.BaseActionBarContributor_menu_new_child);
		submenuManager.insertBefore("additions", createChildMenuManager); //$NON-NLS-1$
		createSiblingMenuManager = new MenuManager(Messages.BaseActionBarContributor_menu_new_sibling);
		submenuManager.insertBefore("additions", createSiblingMenuManager); //$NON-NLS-1$
		// Force an update because Eclipse hides empty menus now.
		submenuManager.addMenuListener(m -> m.updateAll(true));
		addGlobalActions(submenuManager);
	}

	protected abstract IMenuManager createSubMenu();

	protected Optional<IEditorPart> activeEditor() {
		return Optional.ofNullable(editor);
	}

	@Override
	public final void setActiveEditor(IEditorPart part) {
		super.setActiveEditor(part);
		editor = part;
		if (selections != null) {
			selections.removeSelectionChangedListener(this);
		}
		if (part == null) {
			selections = null;
		} else {
			selections = part.getSite().getSelectionProvider();
			if (selections != null) {
				selections.addSelectionChangedListener(this);
				if (selections.getSelection() != null) {
					selectionChanged(new SelectionChangedEvent(selections, selections.getSelection()));
				}
			}
		}
	}

	@Override
	public final void selectionChanged(SelectionChangedEvent event) {
		if (createChildMenuManager != null) {
			depopulateManager(createChildMenuManager, createChildActions);
		}
		if (createSiblingMenuManager != null) {
			depopulateManager(createSiblingMenuManager, createSiblingActions);
		}
		Collection<?> newChildDescriptors = null;
		Collection<?> newSiblingDescriptors = null;

		ISelection selection = event.getSelection();
		if (selection instanceof IStructuredSelection && ((IStructuredSelection) selection).size() == 1) {
			Object object = ((IStructuredSelection) selection).getFirstElement();

			EditingDomain domain = ((IEditingDomainProvider) editor).getEditingDomain();

			newChildDescriptors = domain.getNewChildDescriptors(object, null);
			newSiblingDescriptors = domain.getNewChildDescriptors(null, object);
		}
		createChildActions = generateCreateChildActions(newChildDescriptors, selection);
		createSiblingActions = generateCreateSiblingActions(newSiblingDescriptors, selection);

		if (createChildMenuManager != null) {
			populateManager(createChildMenuManager, createChildActions, null);
			createChildMenuManager.update(true);
		}
		if (createSiblingMenuManager != null) {
			populateManager(createSiblingMenuManager, createSiblingActions, null);
			createSiblingMenuManager.update(true);
		}
	}

	private Collection<IAction> generateCreateChildActions(Collection<?> descriptors, ISelection selection) {
		Collection<IAction> actions = new ArrayList<IAction>();
		if (descriptors != null) {
			for (Object descriptor : descriptors) {
				actions.add(new CreateChildAction(editor, selection, descriptor));
			}
		}
		return actions;
	}

	private Collection<IAction> generateCreateSiblingActions(Collection<?> descriptors, ISelection selection) {
		Collection<IAction> actions = new ArrayList<IAction>();
		if (descriptors != null) {
			for (Object descriptor : descriptors) {
				actions.add(new CreateSiblingAction(editor, selection, descriptor));
			}
		}
		return actions;
	}

	private void populateManager(IContributionManager manager, Collection<? extends IAction> actions,
			String contributionID) {
		if (actions != null) {
			for (IAction action : actions) {
				if (contributionID != null) {
					manager.insertBefore(contributionID, action);
				} else {
					manager.add(action);
				}
			}
		}
	}

	private void depopulateManager(IContributionManager manager, Collection<? extends IAction> actions) {
		if (actions != null) {
			IContributionItem[] items = manager.getItems();
			for (int i = 0; i < items.length; i++) {
				IContributionItem contributionItem = items[i];
				while (contributionItem instanceof SubContributionItem) {
					contributionItem = ((SubContributionItem) contributionItem).getInnerItem();
				}
				if (contributionItem instanceof ActionContributionItem) {
					IAction action = ((ActionContributionItem) contributionItem).getAction();
					if (actions.contains(action)) {
						manager.remove(contributionItem);
					}
				}
			}
		}
	}

	@Override
	public final void menuAboutToShow(IMenuManager menuManager) {
		super.menuAboutToShow(menuManager);
		MenuManager children = new MenuManager(Messages.BaseActionBarContributor_menu_new_child);
		populateManager(children, createChildActions, null);
		menuManager.insertBefore("edit", children); //$NON-NLS-1$
		MenuManager sibling = new MenuManager(Messages.BaseActionBarContributor_menu_new_sibling);
		// $NON-NLS-1$
		populateManager(sibling, createSiblingActions, null);
		menuManager.insertBefore("edit", sibling); //$NON-NLS-1$
	}

	@Override
	protected final void addGlobalActions(IMenuManager menuManager) {
		menuManager.insertAfter("additions-end", new Separator("ui-actions")); //$NON-NLS-1$ //$NON-NLS-2$
		menuManager.insertAfter("ui-actions", properties); //$NON-NLS-1$
		refresh.setEnabled(refresh.isEnabled());
		menuManager.insertAfter("ui-actions", refresh); //$NON-NLS-1$
		super.addGlobalActions(menuManager);
	}

	@Override
	protected final boolean removeAllReferencesOnDelete() {
		return true;
	}

}

package eu.modernmt.context.lucene;

import eu.modernmt.config.AnalyzerConfig;
import eu.modernmt.context.ContextAnalyzer;
import eu.modernmt.context.ContextAnalyzerException;
import eu.modernmt.context.lucene.analysis.ContextAnalyzerIndex;
import eu.modernmt.context.lucene.analysis.DocumentBuilder;
import eu.modernmt.context.lucene.storage.Bucket;
import eu.modernmt.context.lucene.storage.CorporaStorage;
import eu.modernmt.data.LogDataListener;
import eu.modernmt.data.DataListenerProvider;
import eu.modernmt.io.UTF8Charset;
import eu.modernmt.lang.LanguageDirection;
import eu.modernmt.model.ContextVector;
import eu.modernmt.model.corpus.Corpus;
import eu.modernmt.model.corpus.impl.StringCorpus;
import eu.modernmt.model.corpus.impl.parallel.FileCorpus;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.apache.lucene.document.Document;

import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.*;
import java.util.concurrent.*;

/**
 * Created by davide on 09/05/16.
 */
public class LuceneAnalyzer implements ContextAnalyzer, DataListenerProvider {

    private final Logger logger = LogManager.getLogger(LuceneAnalyzer.class);

    private final ContextAnalyzerIndex index;
    private final CorporaStorage storage;
    private final AnalysisThread analysis;

    public LuceneAnalyzer(File indexPath, AnalyzerConfig config) throws IOException {
        this(new ContextAnalyzerIndex(new File(indexPath, "index")), new CorporaStorage(new File(indexPath, "storage")), config);
    }

    protected LuceneAnalyzer(ContextAnalyzerIndex index, CorporaStorage storage, AnalyzerConfig config) {
        this.index = index;
        this.storage = storage;

        if (config.analyze()) {
            this.analysis = new AnalysisThread(config);
            this.analysis.start();
        } else {
            this.analysis = null;
        }
    }

    public ContextAnalyzerIndex getIndex() {
        return index;
    }

    public CorporaStorage getStorage() {
        return storage;
    }

    @Override
    public ContextVector getContextVector(UUID user, LanguageDirection direction, String query, int limit) throws ContextAnalyzerException {
        return getContextVector(user, direction, new StringCorpus(null, direction.source, query), limit);
    }

    @Override
    public ContextVector getContextVector(UUID user, LanguageDirection direction, File source, int limit) throws ContextAnalyzerException {
        return getContextVector(user, direction, new FileCorpus(source, null, direction.source), limit);
    }

    @Override
    public ContextVector getContextVector(UUID user, LanguageDirection direction, Corpus query, int limit) throws ContextAnalyzerException {
        try {
            return this.index.getContextVector(user, direction, query, limit);
        } catch (IOException e) {
            throw new ContextAnalyzerException("Failed to calculate context-vector due an internal error", e);
        }
    }

    @Override
    public synchronized void optimize() throws ContextAnalyzerException {
        logger.info("Starting memory forced merge");
        long begin = System.currentTimeMillis();
        try {
            this.index.forceMerge();
        } catch (IOException e) {
            throw new ContextAnalyzerException(e);
        }
        long elapsed = System.currentTimeMillis() - begin;
        logger.info("Memory forced merge completed in " + (elapsed / 1000.) + "s");
    }

    public void analyze(Bucket bucket) throws IOException {
        long size = bucket.getSize();

        if (size == 0) {
            // Deleted
            index.delete(bucket.getId());
        } else {
            Reader reader = new InputStreamReader(bucket.getContentStream(), UTF8Charset.get());
            Document document = DocumentBuilder.newInstance(bucket.getOwner(), bucket.getId(), bucket.getLanguage(), reader);
            index.update(document);
        }
    }

    @Override
    public void close() throws IOException {
        try {
            this.storage.close();
        } finally {
            try {
                this.index.close();
            } finally {
                if (this.analysis != null)
                    this.analysis.shutdown();
            }
        }
    }

    protected void runAnalysis(ExecutorService executor, long maxToleratedMisalignment, int batchSize) throws IOException {
        Set<Bucket> buckets = storage.getUpdatedBuckets(maxToleratedMisalignment, batchSize);
        List<AnalysisTask> tasks = new ArrayList<>(buckets.size());

        for (Bucket bucket : buckets)
            tasks.add(new AnalysisTask(bucket));

        if (executor == null) {
            for (AnalysisTask task : tasks)
                task.run();
        } else {
            List<Future<Void>> results = new ArrayList<>(tasks.size());
            for (AnalysisTask task : tasks)
                results.add(executor.submit(task, null));

            for (Future<Void> future : results) {
                try {
                    future.get();
                } catch (InterruptedException e) {
                    // Ignore it
                } catch (ExecutionException e) {
                    Throwable cause = e.getCause();
                    if (cause instanceof RuntimeException)
                        throw (RuntimeException) cause;
                    else
                        throw new Error("Unexpected exception", cause);
                }
            }
        }

        // Commit

        index.flush();

        for (AnalysisTask task : tasks) {
            try {
                storage.markUpdate(task.getBucket(), task.getSize());
            } catch (IOException e) {
                logger.error("Failed to mark update for bucket " + task.getBucket());
            }
        }
    }

    @Override
    public Collection<LogDataListener> getDataListeners() {
        return Collections.singleton(storage);
    }

    private class AnalysisThread extends Thread {

        private final int timeout;
        private final int batchSize;
        private final long maxToleratedMisalignment;

        private final ExecutorService executor;
        private final SynchronousQueue<Object> handoff;
        private boolean active = true;

        public AnalysisThread(AnalyzerConfig config) {
            this.timeout = config.getTimeout();
            this.batchSize = config.getBatchSize();
            this.maxToleratedMisalignment = config.getMaxToleratedMisalignment();

            int threads = config.getThreads();
            this.executor = Executors.newFixedThreadPool(config.getThreads());
            this.handoff = new SynchronousQueue<>();

            if (logger.isDebugEnabled()) {
                logger.debug("AnalysisThread started with: timeout=" + timeout + ", batchSize=" + batchSize +
                        ", maxToleratedMisalignment=" + maxToleratedMisalignment + ", threads=" + threads);
            }
        }

        public void run() {
            while (active) {
                try {
                    handoff.poll(timeout, TimeUnit.SECONDS);
                } catch (InterruptedException e) {
                    // Ignore it
                }

                if (!active)
                    break;

                try {
                    runAnalysis(executor, maxToleratedMisalignment, batchSize);
                } catch (Exception e) {
                    logger.error("Failed to retrieve run analysis", e);
                }
            }
        }

        public void shutdown() {
            this.active = false;
            handoff.offer(new Object());

            try {
                executor.shutdownNow();
                executor.awaitTermination(timeout, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                // ignore it
            }
        }
    }

    private class AnalysisTask implements Runnable {

        private final Bucket bucket;
        private long size = -1;

        public AnalysisTask(Bucket bucket) {
            this.bucket = bucket;
        }

        public long getSize() {
            return size < 0 ? bucket.getSize() : size;
        }

        public Bucket getBucket() {
            return bucket;
        }

        @Override
        public void run() {
            try {
                long start = System.currentTimeMillis();
                this.size = bucket.getSize();

                LuceneAnalyzer.this.analyze(bucket);

                long elapsed = (long) ((System.currentTimeMillis() - start) / 100.);
                if (logger.isDebugEnabled())
                    logger.debug("Index of bucket " + bucket + " completed in " + (elapsed / 10.) + "s");
            } catch (Exception e) {
                logger.error("Failed to index bucket: " + bucket, e);
            }
        }
    }

}

