package org.spica.fx;

import com.sun.nio.file.SensitivityWatchEventModifier;
import java.io.IOException;
import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.nio.file.StandardWatchEventKinds;
import java.nio.file.WatchEvent;
import java.nio.file.WatchKey;
import java.nio.file.WatchService;
import javafx.beans.value.ChangeListener;
import javafx.beans.value.ObservableValue;
import javafx.scene.Scene;
import lombok.extern.slf4j.Slf4j;
import org.spica.fx.controllers.MainController;
import org.spica.javaclient.services.Services;

@Slf4j
public class ConfigfileWatcherThread extends Thread{

  private Services services;

  private boolean mouseInFxApplication = true;
  private MainController mainController;

  public ConfigfileWatcherThread (final Mask<MainController> mainControllerMask) {
    this.mainController = mainControllerMask.getController();
    this.services = mainController.getServices();
    Scene scene = mainControllerMask.getScene();

    mainControllerMask.getStage().focusedProperty().addListener(new ChangeListener<Boolean>() {
      @Override
      public void changed(ObservableValue<? extends Boolean> observable, Boolean oldValue, Boolean newValue) {
        mouseInFxApplication = newValue;
        log.info("set mouseInFxApplication to " + mouseInFxApplication + " on focus");

      }
    });
    // Notice if we are in or outside of the fx app because we always reload the model if the configfile changes
    // AND we are outside of the fx app
    /**scene.setOnMouseEntered(event -> {
      mouseInFxApplication = true;
      log.info("set mouseInFxApplication to " + mouseInFxApplication);
    });
    scene.setOnMouseExited(event -> {
      mouseInFxApplication = false;
      log.info("set mouseInFxApplication to " + mouseInFxApplication);
    });**/
  }
  @Override
  public void run() {
    try {
      WatchService watchService = FileSystems.getDefault().newWatchService();

      Path path = services.getModelCacheService().getConfigFile().getParentFile().toPath();
      log.info("Register watchService on file " + path);

      path.register(watchService, new WatchEvent.Kind[]{StandardWatchEventKinds.ENTRY_MODIFY, StandardWatchEventKinds.ENTRY_CREATE}, SensitivityWatchEventModifier.HIGH);

      WatchKey key;
      while ((key = watchService.take()) != null) {
        for (WatchEvent<?> event : key.pollEvents()) {
          Path eventPath = (Path) event.context();

          log.info("Event kind:" + event.kind() + ". File affected: " + eventPath.toString() + "<->" + services.getModelCacheService().getConfigFile().getName() + ", FX-App focused: " + mainController.getStage().isFocused());

          if (eventPath.toString().equals(services.getModelCacheService().getConfigFile().getName()) &&
              ! mainController.getStage().isFocused()) {
            log.info("Reload config model");
            mainController.getServices().getModelCacheService().reload();

            for (Mask next: mainController.getRegisteredMasks().values()) {
              next.getController().refreshData();
            }
          }

        }
        key.reset();
      }
    } catch (IOException | InterruptedException e) {
      log.error(e.getLocalizedMessage(), e);
    }
  }

}

package net.justincredible;

import android.util.Log;
import android.app.Activity;
import android.content.Intent;

import org.apache.cordova.CallbackContext;
import org.apache.cordova.CordovaPlugin;
import org.apache.cordova.PluginResult;
import org.json.JSONArray;
