package io.strimzi.operator.topic;

import io.vertx.core.AsyncResult;
import io.vertx.core.Future;
import io.vertx.core.Handler;
import io.vertx.ext.unit.TestContext;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

public class MockTopicStore implements TopicStore {

    private Map<TopicName, Topic> topics = new HashMap<>();
    private Function<TopicName, AsyncResult<Void>> createTopicResponse = t -> Future.failedFuture("Unexpected. Your test's MockTopicStore probably needs a createTopicResponse configured.");
    private Function<TopicName, AsyncResult<Void>> deleteTopicResponse = t -> Future.failedFuture("Unexpected. Your test's MockTopicStore probably needs a deleteTopicResponse configured.");
    private Function<TopicName, AsyncResult<Void>> updateTopicResponse = t -> Future.failedFuture("Unexpected. Your test's MockTopicStore probably needs a updateTopicResponse configured.");
    private Function<TopicName, AsyncResult<Topic>> getTopicResponse = t -> null;

    @Override
    public void read(TopicName name, Handler<AsyncResult<Topic>> handler) {
        AsyncResult<Topic> result1 = getTopicResponse.apply(name);
        if (result1 == null) {
            Topic result = topics.get(name);
            handler.handle(Future.succeededFuture(result));
        } else {
            handler.handle(result1);
        }
    }

    @Override
    public void create(Topic topic, Handler<AsyncResult<Void>> handler) {
        AsyncResult<Void> response = createTopicResponse.apply(topic.getTopicName());
        if (response.succeeded()) {
            Topic old = topics.put(topic.getTopicName(), topic);
            if (old != null) {
                handler.handle(Future.failedFuture(new TopicStore.EntityExistsException()));
            }
        }
        handler.handle(response);
    }

    @Override
    public void update(Topic topic, Handler<AsyncResult<Void>> handler) {
        Topic old = topics.put(topic.getTopicName(), topic);
        if (old != null) {
            handler.handle(Future.succeededFuture());
        } else {
            handler.handle(Future.failedFuture(new TopicStore.NoSuchEntityExistsException()));
        }
    }

    @Override
    public void delete(TopicName topicName, Handler<AsyncResult<Void>> handler) {
        AsyncResult<Void> response = deleteTopicResponse.apply(topicName);
        if (response.succeeded()) {
            Topic topic = topics.remove(topicName);
            if (topic == null) {
                handler.handle(Future.failedFuture(new TopicStore.NoSuchEntityExistsException()));
            }
        }
        handler.handle(response);
    }

    public void assertExists(TestContext context, TopicName topicName) {
        context.assertTrue(topics.containsKey(topicName));
    }

    public void assertNotExists(TestContext context, TopicName topicName) {
        context.assertFalse(topics.containsKey(topicName));
    }

    public void assertContains(TestContext context, Topic topic) {
        context.assertEquals(topic, topics.get(topic.getTopicName()));
    }

    public MockTopicStore setCreateTopicResponse(TopicName createTopic, Exception exception) {
        Function<TopicName, AsyncResult<Void>> old = this.createTopicResponse;
        this.createTopicResponse = t -> {
            if (t.equals(createTopic)) {
                if (exception != null) {
                    return Future.failedFuture(exception);
                } else {
                    return Future.succeededFuture();
                }
            } else {
                return old.apply(t);
            }
        };
        return this;
    }

    public MockTopicStore setDeleteTopicResponse(TopicName createTopic, Exception exception) {
        Function<TopicName, AsyncResult<Void>> old = this.deleteTopicResponse;
        this.deleteTopicResponse = t -> {
            if (t.equals(createTopic)) {
                if (exception != null) {
                    return Future.failedFuture(exception);
                } else {
                    return Future.succeededFuture();
                }
            } else {
                return old.apply(t);
            }
        };
        return this;
    }

    public MockTopicStore setUpdateTopicResponse(TopicName updateTopic, Exception exception) {
        Function<TopicName, AsyncResult<Void>> old = this.updateTopicResponse;
        this.updateTopicResponse = t -> {
            if (t.equals(updateTopic)) {
                if (exception != null) {
                    return Future.failedFuture(exception);
                } else {
                    return Future.succeededFuture();
                }
            } else {
                return old.apply(t);
            }
        };
        return this;
    }

    public MockTopicStore setGetTopicResponse(TopicName topic, Future<Topic> f) {
        Function<TopicName, AsyncResult<Topic>> old = this.getTopicResponse;
        this.getTopicResponse = t -> {
            if (t.equals(topic)) {
                return f;
            } else {
                return old.apply(t);
            }
        };
        return this;
    }

    public void assertEmpty(TestContext context) {
        context.assertTrue(this.topics.isEmpty());
    }

}

package de.triology.cas.services;

import de.triology.cas.services.attributes.ReturnMappedAttributesPolicy;
import org.apereo.cas.services.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * An abstract class that encapsulates the stages {@link CesServicesManager} operates in.
 * It provides it's registered services via {@link #getRegisteredServices()}.
 * <p>
 * Implementations must initialize their registered services by implementing the template method
 * {@link #initRegisteredServices()}.
 */
abstract class CesServicesManagerStage {
    protected final Logger log = LoggerFactory.getLogger(getClass());

    private final CesServiceManagerConfiguration managerConfig;

    /**
     * Map to store all registeredServices.
     */
    protected final Map<Long, RegisteredService> registeredServices = new ConcurrentHashMap<>();

    CesServicesManagerStage(CesServiceManagerConfiguration managerConfig) {
        this.managerConfig = managerConfig;
    }


    /**
     * @return the services registered in this stage.
     */
    public Map<Long, RegisteredService> getRegisteredServices() {
        if (this.registeredServices.isEmpty()) {
            initRegisteredServices();
        }
        return this.registeredServices;
    }

    /**
     * Template method that add the stage-specific services to the <code>registeredServices</code>.
     */
    protected abstract void initRegisteredServices();


    protected abstract void updateRegisteredServices();

    /**
     * Registers a new service
     *
     * @param service service object to register
     */
    protected void addNewService(RegexRegisteredService service) {
        service.setProxyPolicy(new RegexMatchingRegisteredServiceProxyPolicy("^https?://.*"));
        service.setEvaluationOrder((int) service.getId());
        service.setAttributeReleasePolicy(new ReturnMappedAttributesPolicy(managerConfig.getAllowedAttributes(), managerConfig.getAttributesMappingRules()));
        if (managerConfig.isOidcAuthenticationDelegationEnabled()) {
            configureOidcDelegationService(service);
        }
        registeredServices.put(service.getId(), service);
    }

    /**
     * Applies basic configuration to all services when the OIDC delegation authentication is enabled.
     *
     * @param service The service that should be configured
     */
    private void configureOidcDelegationService(RegexRegisteredService service) {
        if (managerConfig.getOidcPrincipalsAttribute() != null && !managerConfig.getOidcPrincipalsAttribute().isEmpty()) {
            var principalProvider = new PrincipalAttributeRegisteredServiceUsernameProvider();
            principalProvider.setUsernameAttribute(managerConfig.getOidcPrincipalsAttribute());
            service.setUsernameAttributeProvider(principalProvider);
        }

        List<String> allowedProviders = new ArrayList<>();
        allowedProviders.add(managerConfig.getOidcClientDisplayName());
        var delegatedAuthenticationPolicy = new DefaultRegisteredServiceDelegatedAuthenticationPolicy();
        delegatedAuthenticationPolicy.setAllowedProviders(allowedProviders);
        var accessStrategy = new DefaultRegisteredServiceAccessStrategy();
        accessStrategy.setDelegatedAuthenticationPolicy(delegatedAuthenticationPolicy);
        service.setAccessStrategy(accessStrategy);
    }

    /**
     * @return a new numeric ID for a registered service
     */
    protected long createId() {
        return findHighestId(registeredServices) + 1;
    }

    /**
     * @return the highest number within the keyset of <code>map</code>
     */
    private static long findHighestId(Map<Long, RegisteredService> map) {
        long id = 0;

        for (Map.Entry<Long, RegisteredService> entry : map.entrySet()) {
            if (entry.getKey() > id) {
                id = entry.getKey();
            }
        }
        return id;
    }

}

