package io.github.code13.javastack.libs.protostuff;

import io.protostuff.LinkedBuffer;
import io.protostuff.ProtostuffIOUtil;
import io.protostuff.Schema;
import io.protostuff.runtime.RuntimeSchema;
import org.objenesis.Objenesis;
import org.objenesis.ObjenesisStd;

/**
 * ProtostuffUtils.
 *
 * @author <a href="https://github.com/Code-13/">code13</a>
 * @date 2021/10/15 13:58
 */
public final class ProtostuffUtils {

  private static Objenesis objenesis = new ObjenesisStd();

  @SuppressWarnings("unchecked")
  public static <T> byte[] serialize(T obj) {
    Class<T> objClass = (Class<T>) obj.getClass();
    Schema<T> schema = getSchema(objClass);
    byte[] data;
    LinkedBuffer buffer = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE);
    try {
      data = ProtostuffIOUtil.toByteArray(obj, schema, buffer);
    } finally {
      buffer.clear();
    }
    return data;
  }

  public static <T> T deserialize(byte[] data, Class<T> clazz) {
    T obj = objenesis.newInstance(clazz);
    Schema<T> schema = getSchema(clazz);
    ProtostuffIOUtil.mergeFrom(data, obj, schema);
    return obj;
  }

  private static <T> Schema<T> getSchema(Class<T> objClass) {
    return RuntimeSchema.getSchema(objClass);
  }

  private ProtostuffUtils() {
    throw new UnsupportedOperationException(String.format("%s is Utils", getClass().getName()));
  }
}

package amai.org.conventions.navigation;

import android.app.Activity;
import android.graphics.drawable.Drawable;

public class NavigationItem {
	private final Class<? extends Activity> activity;
	private final String text;
	private final Drawable icon;
	private final Drawable selectedIcon;

	public NavigationItem(Class<? extends Activity> activity, String text, Drawable icon) {
		this(activity, text, icon, null);
	}

	public NavigationItem(Class<? extends Activity> activity, String text, Drawable icon, Drawable selectedIcon) {
		this.activity = activity;
		this.text = text;
		this.icon = icon;
		this.selectedIcon = selectedIcon;
	}

	public Class<? extends Activity> getActivity() {
		return activity;
	}

	public String getText() {
		return text;
	}

	public Drawable getIcon() {
		return icon;
	}

	public Drawable getSelectedIcon() {
		return selectedIcon;
	}
}

package com.ss.editor.scene;

import static com.ss.editor.util.GeomUtils.getDirection;

import com.jme3.light.DirectionalLight;
import com.jme3.light.Light;
import com.jme3.light.PointLight;
import com.jme3.light.SpotLight;
import com.jme3.math.Quaternion;
import com.jme3.math.Vector3f;
import com.jme3.renderer.Camera;
import com.jme3.scene.Node;
import com.ss.editor.Editor;
import com.ss.editor.util.LocalObjects;

import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

/**
 * The node to present and edit lights.
 *
 * @author JavaSaBr
 */
public class EditorLightNode extends Node {

    @NotNull
    private static final Editor EDITOR = Editor.getInstance();

    /**
     * The light.
     */
    @Nullable
    private Light light;

    /**
     * The model.
     */
    @Nullable
    private Node model;

    /**
     * Set a light.
     *
     * @param light the light.
     */
    public void setLight(@Nullable final Light light) {
        this.light = light;
    }

    /**
     * Get a light.
     *
     * @return the light.
     */
    @Nullable
    public Light getLight() {
        return light;
    }

    /**
     * Get a model.
     *
     * @return the model.
     */
    @Nullable
    public Node getModel() {
        return model;
    }

    /**
     * Set a model.
     *
     * @param model the model.
     */
    public void setModel(@Nullable final Node model) {
        this.model = model;
    }

    @Override
    public void updateGeometricState() {

        final Light light = getLight();

        if (light instanceof PointLight) {
            final PointLight pointLight = (PointLight) light;
            pointLight.setPosition(getLocalTranslation());
        } else if (light instanceof DirectionalLight) {
            final DirectionalLight directionalLight = (DirectionalLight) light;
            final Quaternion rotation = getLocalRotation();
            directionalLight.setDirection(getDirection(rotation, directionalLight.getDirection()));
        } else if (light instanceof SpotLight) {
            final SpotLight spotLight = (SpotLight) light;
            final Quaternion rotation = getLocalRotation();
            final Vector3f direction = getDirection(rotation, spotLight.getDirection());
            spotLight.setDirection(direction);
            spotLight.setPosition(getLocalTranslation());
        }

        super.updateGeometricState();
    }

    /**
     * Update position and rotation of a model.
     */
    public void updateModel() {

        final Node model = getModel();
        if (model == null) return;

        final Camera camera = EDITOR.getCamera();
        final LocalObjects local = LocalObjects.get();
        final Vector3f positionOnCamera = local.getNextVector();
        positionOnCamera.set(getLocalTranslation()).subtractLocal(camera.getLocation());
        positionOnCamera.normalizeLocal();
        positionOnCamera.multLocal(camera.getFrustumNear() + 0.4f);
        positionOnCamera.addLocal(camera.getLocation());

        model.setLocalTranslation(positionOnCamera);
        model.setLocalRotation(getLocalRotation());
    }
}

